// Gerado por scripts/extract-phb.py a partir do Livro D&D.pdf local.
(function(root){const data=[{"id":"amizade","name":"Amizade","level":0,"school":"encantamento","ritual":false,"classes":["bardo","bruxo","feiticeiro","mago"],"pdfPage":214,"time":"1 ação","range":"Pessoal","components":"S, M (uma pequena quantidade de maquiagem aplicada ao rosto durante a conjuração da magia)","duration":"Concentração, até 1 minuto","concentration":true,"text":"Truque de encantamento\nTempo de Conjuração: 1 ação\nAlcance: Pessoal\nComponentes: S, M (uma pequena quantidade de\n   maquiagem aplicada ao rosto durante a conjuração da\n   magia)\nDuração: Concentração, até 1 minuto\nPela duração, você terá vantagem em todos os testes de\nCarisma direcionados a uma criatura, à sua escolha, que\nnão seja hostil a você. Quando a magia acabar, a criatura\nperceberá que você usou maia para influenciar o humor\ndela, e ficará hostil a você. Uma criatura propensa a\nviolência irá atacar você. Outra criatura pode buscar\noutras formas de retaliação (a critério do Mestre),\ndependendo da natureza da sua interação com ela."},{"id":"ataque-certeiro","name":"Ataque Certeiro","level":0,"school":"adivinhação","ritual":false,"classes":["bardo","bruxo","feiticeiro","mago"],"pdfPage":219,"time":"1 ação","range":"9 metros","components":"S","duration":"Concentração, até 1 rodada","concentration":true,"text":"Truque de adivinhação\nTempo de Conjuração: 1 ação\nAlcance: 9 metros\nComponentes: S\nDuração: Concentração, até 1 rodada\nVocê estende sua mão e aponta o dedo para um alvo no\nalcance. Sua magia garante a você uma breve intuição\nsobre as defesas do alvo. No seu próximo turno, você terá\nvantagem na primeira jogada de ataque contra o alvo,\nconsiderando que essa magia não tenha acabado."},{"id":"bordao-mistico","name":"Bordão Místico","level":0,"school":"transmutação","ritual":false,"classes":["druida"],"pdfPage":222,"time":"1 ação bônus","range":"Toque","components":"V, S, M (visco, uma folha de trevo e uma clava ou bordão)","duration":"1 minuto","concentration":false,"text":"Truque de transmutação\nTempo de Conjuração: 1 ação bônus\nAlcance: Toque\nComponentes: V, S, M (visco, uma folha de trevo e uma\n   clava ou bordão)\nDuração: 1 minuto\nA madeira de uma clava ou bordão, que você esteja\nsegurando, é imbuída com o poder da natureza. Pela\nduração, você pode usar sua habilidade de conjuração ao\ninvés da sua Força para as jogadas de ataque e dano\ncorpo-a-corpo usando essa arma, e o dado de dano da\narma se torna um d8. A arma também se torna mágica, se\nela já não for. A magia acaba se você conjura-la\nnovamente ou se você soltar a arma."},{"id":"chama-sagrada","name":"Chama Sagrada","level":0,"school":"evocação","ritual":false,"classes":["clerigo"],"pdfPage":224,"time":"1 ação","range":"18 metros","components":"V, S","duration":"Instantânea","concentration":false,"text":"Truque de evocação\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, S\nDuração: Instantânea\nRadiação similar a uma chama desce sobre uma criatura\nque você possa ver, dentro do alcance. O alvo deve ser\nbem sucedido num teste de resistência de Destreza ou\nsofrerá 1d8 de dano radiante. O alvo não recebe qualquer\nbenefício de cobertura contra esse teste de resistência.\n   O dano da magia aumenta em 1d8 quando você\nalcança o 5° nível (2d8), 11° nível (3d8) e 17° nível (4d8)."},{"id":"chicote-de-espinhos","name":"Chicote de Espinhos","level":0,"school":"transmutação","ritual":false,"classes":["druida"],"pdfPage":224,"time":"1 ação","range":"9 metros","components":"V, S, M (um muda de uma planta com espinhos)","duration":"Instantânea","concentration":false,"text":"Truque de transmutação\nTempo de Conjuração: 1 ação\nAlcance: 9 metros\nComponentes: V, S, M (um muda de uma planta com\n   espinhos)\nDuração: Instantânea\nVocê cria um longo chicote de vinhas coberto por espinhos\nque chicoteia, ao seu comando, em direção de uma\ncriatura dentro do alcance. Realize um ataque corpo-a-\ncorpo com magia contra o alvo. Se o ataque atingir, a\ncriatura sofrerá 1d6 de dano perfurante e, se a criatura\nfor Grande ou menor, você a puxa até 3 metros para perto\nde você.\n    O dano dessa magia aumenta em 1d6 quando você\nalcança o 5° nível (2d6), 11° nível (3d6) e 17° nível (4d6)."},{"id":"consertar","name":"Consertar","level":0,"school":"transmutação","ritual":false,"classes":["bardo","clerigo","druida","feiticeiro","mago"],"pdfPage":230,"time":"1 minuto","range":"Toque","components":"V, S, M (dois ímãs)","duration":"Instantânea","concentration":false,"text":"Truque de transmutação\nTempo de Conjuração: 1 minuto\nAlcance: Toque\nComponentes: V, S, M (dois ímãs)\nDuração: Instantânea\nEssa magia repara um única quebra ou fissura em um\nobjeto que você tocar, como um elo quebrado de uma\ncorrente, duas metades de uma chave partida, um manto\nrasgado ou o vazamento em um odre. Contanto que a\nquebra ou fissura não tenha mais de 30 centímetros em\nqualquer dimensão, você pode remenda-la, não deixando\nqualquer vestígio do dano anterior.\n    Essa magia pode reparar fisicamente um item mágico\nou constructo, mas a magia não irá restaurar a magia em\ntais objetos."},{"id":"criar-chamas","name":"Criar Chamas","level":0,"school":"conjuração","ritual":false,"classes":["druida"],"pdfPage":233,"time":"1 ação","range":"Pessoal","components":"V, S","duration":"10 minutos","concentration":false,"text":"Truque de conjuração\nTempo de Conjuração: 1 ação\nAlcance: Pessoal\nComponentes: V, S\nDuração: 10 minutos\nUma chama tremulante aparece na sua mão. A chama\npermanece ai pela duração e não machuca nem você nem\nseu equipamento. A chama emite luz plena num raio de 3\nmetros e penumbra por 3 metros adicionais. A magia\nacaba se você dissipa-la usando uma ação ou se conjura-la\nnovamente.\n   Você pode, também, atacar com a chama, no entanto,\nfazer isso acaba com a magia. Quando você conjura essa\nmagia ou com uma ação em um turno posterior, você pode\narremessar a chama numa criatura a até 9 metros de\nvocê. Faça um ataque à distância com magia. Se atingir, o\nalvo sofre 1d8 de dano de fogo.\n   O dano dessa magia aumenta em 1d8 quando você\nalcança o 5° nível (2d8), 11° nível (3d8) e 17° nível (4d8)."},{"id":"druidismo","name":"Druidismo","level":0,"school":"transmutação","ritual":false,"classes":["druida"],"pdfPage":240,"time":"1 ação","range":"9 metros","components":"V, S","duration":"Instantânea","concentration":false,"text":"Truque de transmutação\nTempo de Conjuração: 1 ação\nAlcance: 9 metros\nComponentes: V, S\nDuração: Instantânea\nSussurrando para os espíritos da natureza, você cria um\ndos seguintes efeitos, dentro do alcance:\n   Você cria um efeito sensorial minúsculo e inofensivo\n    que prevê como será o clima na sua localização pelas\n    próximas 24 horas. O efeito deve se manifestar como\n    um globo dourado para céu claro, uma nuvem para\n    chuva, flocos de neve para nevasca e assim por diante.\n    Esse efeito persiste por 1 rodada.\n   Você faz uma flor florescer, uma semente brotar ou um\n    folha amadurecer, instantaneamente.\n   Você cria um efeito sensorial inofensivo instantâneo,\n    como folhas caindo, um sopro de vento, o som de um\n    pequeno animal ou o suave odor de um repolho. O\n    efeito deve caber num cubo de 1,5 metro.\n   Você, instantaneamente, acende ou apaga uma vela,\n    tocha ou fogueira pequena."},{"id":"espirro-acido","name":"Espirro Ácido","level":0,"school":"conjuração","ritual":false,"classes":["feiticeiro","mago"],"pdfPage":243,"time":"1 ação","range":"18 metros","components":"V, S","duration":"Instantânea","concentration":false,"text":"Truque de conjuração\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, S\nDuração: Instantânea\nVocê arremessa uma bolha de ácido. Escolha uma\ncriatura dentro do alcance, ou escolha duas criaturas\ndentro do alcance que estejam a 1,5 metro uma da outra.\nUm alvo deve ser bem sucedido num teste de resistência\nde Destreza ou sofrerá 1d6 de dano ácido.\n   O dano dessa magia aumenta em 1d6 quando você\nalcança o 5° nível (2d6), 11° nível (3d6) e 17° nível (4d6)."},{"id":"estabilizar","name":"Estabilizar","level":0,"school":"necromancia","ritual":false,"classes":["clerigo"],"pdfPage":244,"time":"1 ação","range":"Toque","components":"V, S","duration":"Instantânea","concentration":false,"text":"Truque de necromancia\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S\nDuração: Instantânea\nVocê toca uma criatura viva que esteja com 0 pontos de\nvida. A criatura é estabilizada. Essa magia não afeta\nmortos-vivos ou constructos."},{"id":"globos-de-luz","name":"Globos de Luz","level":0,"school":"evocação","ritual":false,"classes":["bardo","feiticeiro","mago"],"pdfPage":247,"time":"1 ação","range":"36 metros","components":"V, S, M (um pouco de fósforo ou wychwood ou um inseto luminoso)","duration":"Concentração, até 1 minuto","concentration":true,"text":"Truque de evocação\nTempo de Conjuração: 1 ação\nAlcance: 36 metros\nComponentes: V, S, M (um pouco de fósforo ou\n   wychwood ou um inseto luminoso)\nDuração: Concentração, até 1 minuto\nVocê cria até quatro luzes do tamanho de tochas dentro\ndo alcance, fazendo-as parecerem tochas, lanternas ou\nesferas luminosas que flutuam no ar pela duração. Você\ntambém pode combinar as quatro luzes em uma forma\nluminosa, vagamente humanoide, de tamanho Médio.\nQualquer que seja a forma que você escolher, cada luz\nproduz penumbra num raio de 3 metros.\n    Com uma ação bônus, no seu turno, você pode mover\nas luzes, até 18 metros, para um novo local dentro do\nalcance. Uma luz deve estar a, pelo menos, 6 metros de\noutra luz criada por essa magia e uma luz some se\nexceder o alcance da magia."},{"id":"ilusao-menor","name":"Ilusão Menor","level":0,"school":"ilusão","ritual":false,"classes":["bardo","bruxo","feiticeiro","mago"],"pdfPage":248,"time":"1 ação","range":"9 metros","components":"V, M (um pouco de lã)","duration":"1 minuto","concentration":false,"text":"Truque de ilusão\nTempo de Conjuração: 1 ação\nAlcance: 9 metros\nComponentes: V, M (um pouco de lã)\nDuração: 1 minuto\nVocê cria um som ou uma imagem de um objeto, dentro\ndo alcance, que permanece pela duração. A ilusão também\ntermina se você dissipa-la usando uma ação ou conjurar\nessa magia novamente.\n    Se você criar um som, seu volume pode variar entre\num sussurro até um grito. Pode ser a sua voz, a voz de\noutrem, o rugido de um leão, batidas de tambor ou\nqualquer outro som que você quiser. O som permanece no\nmesmo volume durante toda duração ou você pode fazer\nsons distintos em momentos diferentes, antes da magia\nacabar.\n    Se você criar uma imagem de um objeto – como uma\ncadeira, pegadas de lama ou um pequeno baú – ela não\npode ter mais de 1,5 metro cúbico. A imagem não pode\nproduzir som, luz, cheiro ou qualquer outro efeito\nsensorial. Interação física com a imagem revelará que ela\né uma ilusão, já que as coisas podem atravessa-la.\n    Se uma criatura usar sua ação para examinar a\nimagem, ela pode determinar que ela é uma ilusão se\nobtiver sucesso num teste de Inteligência (Investigação)\ncontra a CD da magia. Se uma criatura discernir a ilusão\ncomo sendo isso, a ilusão se tornará suave para a\ncriatura."},{"id":"luz","name":"Luz","level":0,"school":"evocação","ritual":false,"classes":["bardo","clerigo","feiticeiro","mago"],"pdfPage":253,"time":"1 ação","range":"Toque","components":"V, M (um vaga-lume ou musgo fosforescente)","duration":"1 hora","concentration":false,"text":"Truque de evocação\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, M (um vaga-lume ou musgo\n   fosforescente)\nDuração: 1 hora\nVocê toca um objeto que não tenha mais 3 metros em\nqualquer dimensão. Até a magia acabar, o objeto emite\nluz plena num raio de 6 metros e penumbra por 6 metros\nadicionais. Cobrir o objeto completamente com alguma\ncoisa opaca bloqueará a luz. A magia termina se você\nconjura-la novamente ou dissipa-la com uma ação.\n   Se você tentar afetar um objeto segurado ou vestido\npor uma criatura hostil, a criatura deve ser bem sucedida\nnum teste de Destreza para evitar a magia."},{"id":"mensagem","name":"Mensagem","level":0,"school":"transmutação","ritual":false,"classes":["bardo","feiticeiro","mago"],"pdfPage":256,"time":"1 ação","range":"36 metros","components":"V, S, M (um pedaço curto de fio de cobre)","duration":"1 rodada","concentration":false,"text":"Truque de transmutação\nTempo de Conjuração: 1 ação\nAlcance: 36 metros\nComponentes: V, S, M (um pedaço curto de fio de cobre)\nDuração: 1 rodada\nVocê aponta seu dedo para uma criatura dentro do\nalcance e sussurra uma mensagem. O alvo (e apenas ele)\nouvi a mensagem e pode responder com um sussurro que\napenas você pode ouvir.\n    Você pode conjurar essa magia através de objetos\nsólidos se você tiver familiaridade com o alvo. Silêncio\nmágico, 30 centímetros de rocha, 2,5 centímetros de metal\ncomum, uma fina camada de chumbo, ou 90 centímetros\nde madeira ou terra bloqueiam a magia. A magia não\nprecisa seguir uma linha reta e pode viajar livremente,\ndobrando esquinas ou através de aberturas."},{"id":"maos-magicas","name":"Mãos Mágicas","level":0,"school":"conjuração","ritual":false,"classes":["bardo","bruxo","feiticeiro","mago"],"pdfPage":255,"time":"1 ação","range":"9 metros","components":"V, S","duration":"1 minuto","concentration":false,"text":"Truque de conjuração\nTempo de Conjuração: 1 ação\nAlcance: 9 metros\nComponentes: V, S\nDuração: 1 minuto\nUma mão espectral flutuante aparece num ponto, à sua\nescolha, dentro do alcance. A mão permanece pela\nduração ou até você dissipa-la com uma ação. A mão some\nse estiver a mais de 9 metros de você ou se você conjurar\nessa magia novamente.\n   Você pode usar sua ação para controlar a mão. Você\npode usar a mão para manipular um objeto, abrir uma\nporta ou recipiente destrancado, guardar ou pegar um\nitem de um recipiente aberto ou derramar o conteúdo de\num frasco. Você pode mover a mão até 9 metros a cada\nvez que a usa.\n   A mão não pode atacar, ativar itens mágicos ou\ncarregar mais de 5 quilos."},{"id":"orientacao","name":"Orientação","level":0,"school":"adivinhação","ritual":false,"classes":["clerigo","druida"],"pdfPage":264,"time":"1 ação","range":"Toque","components":"V, S","duration":"Concentração, até 1 minuto","concentration":true,"text":"Truque de adivinhação\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S\nDuração: Concentração, até 1 minuto\nVocê toca uma criatura voluntária. Uma vez, antes da\nmagia acabar, o alvo pode rolar um d4 e adicionar o\nnúmero rolado a um teste de habilidade a escolha dele.\nEle pode rolar o dado antes ou depois de realizar o teste\nde habilidade. Após isso, a magia termina."},{"id":"prestidigitacao","name":"Prestidigitação","level":0,"school":"transmutação","ritual":false,"classes":["bardo","bruxo","feiticeiro","mago"],"pdfPage":269,"time":"1 ação","range":"3 metros","components":"V, S","duration":"Até 1 hora","concentration":false,"text":"Truque de transmutação\nTempo de Conjuração: 1 ação\nAlcance: 3 metros\nComponentes: V, S\nDuração: Até 1 hora\nEssa magia é um truque mágico simples que conjuradores\niniciantes usam para praticar. Você cria um dos seguintes\nefeitos mágicos dentro do alcance:\n   Você cria, instantaneamente, um efeito sensorial\n    inofensivo, como uma chuva de faíscas, um sopro de\n    vento, notas musicais suaves ou um odor estranho.\n   Você, instantaneamente, acende ou apaga uma vela,\n    uma tocha ou uma pequena fogueira.\n   Você, instantaneamente, limpa ou suja um objeto de\n    até 1 metro cúbico.\n   Você esfria, esquenta ou melhora o sabor de até 1\n    metro cubico de matéria inorgânica por 1 hora.\n   Você faz uma cor, uma pequena marca ou um símbolo\n    aparecer em um objeto ou superfície por 1 hora.\n   Você cria uma bugiganga não-mágica ou uma imagem\n    ilusória que caiba na sua mão e que dura até o final do\n    seu próximo turno.\n    Se você conjurar essa magia diversas vezes, você pode\nter até três dos seus efeitos não-instantâneos ativos, ao\nmesmo tempo, e você pode dissipar um desses efeitos com\numa ação."},{"id":"protecao-contra-laminas","name":"Proteção contra Lâminas","level":0,"school":"abjuração","ritual":false,"classes":["bardo","bruxo","feiticeiro","mago"],"pdfPage":270,"time":"1 ação","range":"Pessoal","components":"V, S","duration":"1 rodada","concentration":false,"text":"Truque de abjuração\nTempo de Conjuração: 1 ação\nAlcance: Pessoal\nComponentes: V, S\nDuração: 1 rodada\n\nVocê estende suas mãos e desenha um símbolo de\nproteção no ar. Até o final do seu próximo turno, você terá\nresistência contra dano de concussão, cortante e\nperfurante causado por ataques com armas."},{"id":"raio-de-fogo","name":"Raio de Fogo","level":0,"school":"evocação","ritual":false,"classes":["feiticeiro","mago"],"pdfPage":272,"time":"1 ação","range":"36 metros","components":"V, S","duration":"Instantânea","concentration":false,"text":"Truque de evocação\nTempo de Conjuração: 1 ação\nAlcance: 36 metros\nComponentes: V, S\nDuração: Instantânea\nVocê arremessa um cisco de fogo em uma criatura ou\nobjeto dentro do alcance. Faça um ataque à distância com\nmagia contra o alvo. Se atingir, o alvo sofre 1d10 de dano\nde fogo. Um objeto inflamável atingido por essa magia,\nincendeia se não estiver sendo vestido ou carregado.\n   O dano dessa magia aumenta em 1d10 quando você\nalcança o 5° nível (2d10), 11° nível (3d10) e 17° nível\n(4d10)."},{"id":"raio-de-gelo","name":"Raio de Gelo","level":0,"school":"evocação","ritual":false,"classes":["feiticeiro","mago"],"pdfPage":272,"time":"1 ação","range":"18 metros","components":"V, S","duration":"Instantânea","concentration":false,"text":"Truque de evocação\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, S\nDuração: Instantânea\nUm raio frigido de luz azul clara parte em direção de uma\ncriatura, dentro do alcance. Realize um ataque à\ndistância com magia contra o alvo. Se atingir, ele sofre\n1d8 de dano de frio e seu deslocamento é reduzido em 3\nmetros até o começo do seu próximo turno.\n    O dano da magia aumenta em 1d8 quando você\nalcança o 5° nível (2d8), 11° nível (3d8) e 17° nível (4d8)."},{"id":"rajada-mistica","name":"Rajada Mística","level":0,"school":"evocação","ritual":false,"classes":["bruxo"],"pdfPage":273,"time":"1 ação","range":"36 metros","components":"V, S","duration":"Instantânea","concentration":false,"text":"Truque de evocação\nTempo de Conjuração: 1 ação\nAlcance: 36 metros\nComponentes: V, S\nDuração: Instantânea\nUm feixe de energia crepitante vai em direção a uma\ncriatura dentro do alcance. Realize uma jogada de ataque\nà distância com magia contra o alvo. Se atingir, o alvo\nsofre 1d10 de dano de energia.\n    A magia cria mais de um feixe quando você alcança\nníveis elevados: dois feixes no 5° nível, três feixes no 11°\nnível e quatro feixes no 17° nível. Você pode direcionar os\nfeixes para o mesmo alvo ou para alvos diferentes. Realize\njogadas de ataque separadas para cada feixe."},{"id":"rajada-de-veneno","name":"Rajada de Veneno","level":0,"school":"conjuração","ritual":false,"classes":["bruxo","druida","feiticeiro","mago"],"pdfPage":273,"time":"1 ação","range":"3 metros","components":"V, S","duration":"Instantânea","concentration":false,"text":"Truque de conjuração\nTempo de Conjuração: 1 ação\nAlcance: 3 metros\nComponentes: V, S\nDuração: Instantânea\nVocê ergue sua mão em direção de uma criatura que você\npossa ver, dentro do alcance e projeta um sopro de gás\ntóxico da sua palma. A criatura deve ser bem sucedida\nnum teste de resistência de Constituição ou sofrerá 1d12\nde dano de veneno.\n   O dano dessa magia aumenta em 1d12 quando você\nalcança o 5° nível (2d12), 11° nível (3d12) e 17° nível\n(4d12)."},{"id":"resistencia","name":"Resistência","level":0,"school":"abjuração","ritual":false,"classes":["clerigo","druida"],"pdfPage":276,"time":"1 ação","range":"Toque","components":"V, S, M (um manto em miniatura)","duration":"Concentração, até 1 minuto","concentration":true,"text":"Truque de abjuração\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S, M (um manto em miniatura)\nDuração: Concentração, até 1 minuto\nVocê toca uma criatura voluntária. Uma vez, antes da\nmagia acabar, o alvo pode rolar um d4 e adicionar o valor\njogado a um teste de resistência de sua escolha. Ele pode\nrolar o dado antes ou depois de realizar o teste de\nresistência. Então, a magia termina."},{"id":"taumaturgia","name":"Taumaturgia","level":0,"school":"transmutação","ritual":false,"classes":["clerigo"],"pdfPage":282,"time":"1 ação","range":"9 metros","components":"V","duration":"Até 1 minuto","concentration":false,"text":"Truque de transmutação\nTempo de Conjuração: 1 ação\nAlcance: 9 metros\nComponentes: V\nDuração: Até 1 minuto\nVocê manifesta pequenas maravilhas, um sinal de poder\nsobrenatural, dentro do alcance. Você cria um dos\nseguintes efeitos mágicos dentro do alcance:\n   Sua voz ressoa com o triplo do volume normal por 1\n    minuto.\n   Você provoca tremores inofensivos no solo por 1\n    minuto.\n   Você cria, instantaneamente, um som que se origina\n    de um ponto, à sua escolha, dentro do alcance, como o\n    barulho de um trovão, o gralhar de um corvo ou\n    sussurros sinistros.\n   Você, instantaneamente, faz uma porta ou janela\n    destrancada se abrir ou se fechar.\n   Você altera a aparência dos seus olhos por 1 minuto.\n\n    Se você conjurar essa magia diversas vezes, você pode\nter até três dos efeitos de 1 minuto ativos por vez, e você\npode dissipar um desses efeitos com uma ação."},{"id":"toque-arrepiante","name":"Toque Arrepiante","level":0,"school":"necromancia","ritual":false,"classes":["bruxo","feiticeiro","mago"],"pdfPage":286,"time":"1 ação","range":"36 metros","components":"V, S","duration":"1 rodada","concentration":false,"text":"Truque de necromancia\nTempo de Conjuração: 1 ação\nAlcance: 36 metros\nComponentes: V, S\nDuração: 1 rodada\nVocê cria uma mão esquelética fantasmagórica no espaço\nde uma criatura, dentro do alcance. Realize um ataque à\ndistância com magia contra a criatura para afeta-la com o\nfrio sepulcral. Se atingir, a criatura sofre 1d8 de dano\nnecrótico e não poderá recuperar pontos de vida até o\ninício do seu próximo turno. Até lá, a mão ficará presa ao\nalvo.\n    Se você atingir um alvo morto-vivo, ele terá\ndesvantagem nas jogadas de ataque contra você até o\nfinal do seu próximo turno.\n    O dano dessa magia aumenta em 1d8 quando você\nalcança o 5° nível (2d8), 11° nível (3d8) e 17° nível (4d8)."},{"id":"toque-chocante","name":"Toque Chocante","level":0,"school":"evocação","ritual":false,"classes":["feiticeiro","mago"],"pdfPage":286,"time":"1 ação","range":"Toque","components":"V, S","duration":"Instantânea","concentration":false,"text":"Truque de evocação\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S\nDuração: Instantânea\nEletricidade surge da sua mão para transmitir um choque\nem uma criatura que você tentar tocar. Faça um ataque\ncorpo-a-corpo com magia contra o alvo. Você tem\nvantagem na jogada de ataque se o alvo estiver vestindo\nqualquer armadura de metal. Se atingir, o alvo sofre 1d8\nde dano elétrico e não pode usar reações até o início do\npróximo turno dele.\n   O dano da magia aumenta em 1d8 quando você\nalcança o 5° nível (2d8), 11° nível (3d8) e 17° nível (4d8)."},{"id":"zombaria-viciosa","name":"Zombaria Viciosa","level":0,"school":"encantamento","ritual":false,"classes":["bardo"],"pdfPage":288,"time":"1 ação","range":"18 metros","components":"V","duration":"Instantânea","concentration":false,"text":"Truque de encantamento\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V\nDuração: Instantânea\nVocê libera uma série de insultos atados com\nencantamentos sutis numa criatura que você possa ver,\ndentro do alcance. Se o alvo puder ouvir você (apesar de\nnão precisar compreende-lo), ele deve ser bem sucedido\nnum teste de resistência de Sabedoria ou sofrerá 1d4 de\ndano psíquico e terá desvantagem na próxima jogada de\nataque que ele fizer antes do final do próximo turno dele.\n   O dano dessa magia aumenta em 1d4 quando você\nalcança o 5° nível (2d4), 11° nível (3d4) e 17° nível (4d4)."},{"id":"alarme","name":"Alarme","level":1,"school":"abjuração","ritual":true,"classes":["mago","patrulheiro"],"pdfPage":213,"time":"1 minuto","range":"9 metros","components":"V, S, M (um pequeno sino e um pequeno fio de prata)","duration":"8 horas","concentration":false,"text":"1° nível de abjuração (ritual)\nTempo de Conjuração: 1 minuto\nAlcance: 9 metros\nComponentes: V, S, M (um pequeno sino e um pequeno\n   fio de prata)\nDuração: 8 horas\nVocê coloca um alarme para intrusos desavisados.\nEscolha uma porta, uma janela ou uma área dentro do\nalcance que não seja maior que 6 metros cúbicos. Até a\nmagia acabar, um alarme alerta você sempre que uma\ncriatura Miúda ou maior tocarem ou entrarem na área\nprotegida. Quando você conjura a magia, você pode\ndesignar as criaturas que não ativarão o alarme. Você\ntambém escolhe se o alarme será mental ou audível.\n    Um alarme mental alerta você com um silvo na sua\nmente, se você estiver a até de 1,5 quilômetro da área\nprotegida. Esse silvo acordará você se você estiver\ndormindo.\n    Um alarme audível produz o som de um sino de mão\npor 10 minutos num raio de 18 metros."},{"id":"amizade-animal","name":"Amizade animal","level":1,"school":"encantamento","ritual":false,"classes":["bardo","druida","patrulheiro"],"pdfPage":215,"time":"1 ação","range":"9 metros","components":"V, S, M (um punhado de comida)","duration":"24 horas","concentration":false,"text":"1° nível de encantamento\nTempo de Conjuração: 1 ação\nAlcance: 9 metros\nComponentes: V, S, M (um punhado de comida)\nDuração: 24 horas\nEssa magia deixa você convencer uma besta que você não\nquer prejudicar. Escolha uma besta que você possa ver\ndentro do alcance. Ela deve ver e ouvir você. Se a\nInteligência da besta for 4 ou maior, a magia falha. Do\ncontrário, a besta deve ser bem sucedida num teste de\nresistência de Sabedoria ou ficará enfeitiçada por você\npela duração da magia. Se você ou um dos seus\ncompanheiros ferir o alvo, a magia termina.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 2° nível ou\nsuperior, você pode afetar uma besta adicional para cada\nnível do espaço acima do 1°."},{"id":"armadura-arcana","name":"Armadura Arcana","level":1,"school":"abjuração","ritual":false,"classes":["feiticeiro","mago"],"pdfPage":218,"time":"1 ação","range":"Toque","components":"V, S, M (um pedaço de couro curado)","duration":"8 horas","concentration":false,"text":"1° nível de abjuração\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S, M (um pedaço de couro curado)\nDuração: 8 horas\nVocê toca uma criatura voluntária que não esteja vestindo\narmadura e uma energia mágica protetora a envolve até a\nmagia acabar. A CA base do alvo se torna 13 + o\nmodificador de Destreza dele. A magia acaba se o alvo\ncolocar uma armadura ou se você dissipa-la usando uma\nação."},{"id":"armadura-de-agathys","name":"Armadura de Agathys","level":1,"school":"abjuração","ritual":false,"classes":["bruxo"],"pdfPage":218,"time":"1 ação","range":"Pessoal","components":"V, S, M (um copo de água)","duration":"1 hora","concentration":false,"text":"1° nível de abjuração\nTempo de Conjuração: 1 ação\nAlcance: Pessoal\nComponentes: V, S, M (um copo de água)\nDuração: 1 hora\nUma força magica protetora envolve você, manifestando-\nse como um frio espectral que cobre você e seu\nequipamento. Você ganha 5 pontos de vida temporários\npela duração. Se uma criatura atingir você com um\nataque corpo-a-corpo enquanto estiver com esses pontos\nde vida, a criatura sofrerá 5 de dano de frio.\n    Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 2° nível ou\nsuperior, tanto os pontos de vida temporários quanto o\ndano de frio aumentam em 5 para cada nível do espaço\nacima do 1°."},{"id":"auxilio-divino","name":"Auxílio Divino","level":1,"school":"evocação","ritual":false,"classes":["paladino"],"pdfPage":220,"time":"1 ação bônus","range":"Pessoal","components":"V, S","duration":"Concentração, até 1 minuto","concentration":true,"text":"1° nível de evocação\nTempo de Conjuração: 1 ação bônus\nAlcance: Pessoal\nComponentes: V, S\nDuração: Concentração, até 1 minuto\nSua oração fortalece você com radiação divina. Até o fim\nda magia, seus ataques com arma causam 1d4 de dano\nradiante extra ao atingirem."},{"id":"bom-fruto","name":"Bom Fruto","level":1,"school":"transmutação","ritual":false,"classes":["druida","patrulheiro"],"pdfPage":222,"time":"1 ação","range":"Toque","components":"V, S, M (um raminho de visco)","duration":"Instantânea","concentration":false,"text":"1° nível de transmutação\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S, M (um raminho de visco)\nDuração: Instantânea\nAté dez frutos aparecem na sua mão e são infundidos com\nmagia pela duração. Uma criatura pode usar sua ação\npara comer um fruto. Comer um fruto restaura 1 ponto de\nvida e um fruto produz nutrientes suficientes para\nsustentar uma criatura por um dia.\n   Os frutos perdem seu potencial se não forem\nconsumidos dentro de 24 horas da conjuração dessa\nmagia."},{"id":"bracos-de-hadar","name":"Braços de Hadar","level":1,"school":"conjuração","ritual":false,"classes":["bruxo"],"pdfPage":222,"time":"1 ação","range":"Pessoal (3 metros de raio)","components":"V, S","duration":"Instantânea","concentration":false,"text":"1° nível de conjuração\nTempo de Conjuração: 1 ação\nAlcance: Pessoal (3 metros de raio)\nComponentes: V, S\nDuração: Instantânea\nVocê invoca o poder de Hadar, o Faminto Sombrio.\nTentáculos de energia negra brotam de você e golpeiam\ntodas as criaturas a até 3 metros de você. Cada criatura\nna área deve realizar um teste de resistência de Força. Se\nfalhar, o alvo sofre 2d6 de dano necrótico e não pode fazer\nreações até o próximo turno dela. Em um sucesso, uma\ncriatura sofre metade do dano e não sofre qualquer outro\nefeito.\n    Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 2° nível ou\nsuperior, o dano aumenta em 1d6 para cada nível do\nespaço acima do 1°."},{"id":"bruxaria","name":"Bruxaria","level":1,"school":"encantamento","ritual":false,"classes":["bruxo"],"pdfPage":223,"time":"1 ação bônus","range":"18 metros","components":"V, S, M (o olho petrificado de um tritão)","duration":"Concentração, até 1 hora","concentration":true,"text":"1° nível de encantamento\nTempo de Conjuração: 1 ação bônus\nAlcance: 18 metros\nComponentes: V, S, M (o olho petrificado de um tritão)\nDuração: Concentração, até 1 hora\nVocê coloca uma maldição em uma criatura que você\npossa ver, dentro do alcance. Até a magia acabar, você\ncausa 1d6 de dano necrótico extra no alvo sempre que\natingi-lo com um ataque. Além disso, escolha uma\nhabilidade quando você conjurar a magia. O alvo tem\ndesvantagem em testes de habilidade feitos com a\nhabilidade escolhida.\n   Se o alvo cair a 0 pontos de vida antes da magia\nacabar, você pode usar uma ação bônus, em um turno\nsubsequente, para amaldiçoar outra criatura.\n   Uma magia remover maldição conjurada no alvo acaba\ncom a magia prematuramente.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 3° ou 4° nível, você\npoderá manter sua concentração na magia por até 8\nhoras. Quando você usar um espaço de magia de 5° nível\nou superior, você poderá manter sua concentração na\nmagia por até 24 horas."},{"id":"bencao","name":"Bênção","level":1,"school":"encantamento","ritual":false,"classes":["clerigo","paladino"],"pdfPage":221,"time":"1 ação","range":"9 metros","components":"V, S, M (um borrifo de água benta)","duration":"Concentração, até 1 minuto","concentration":true,"text":"1° nível de encantamento\nTempo de Conjuração: 1 ação\nAlcance: 9 metros\nComponentes: V, S, M (um borrifo de água benta)\nDuração: Concentração, até 1 minuto\nVocê abençoa até três criaturas, à sua escolha, dentro do\nalcance. Sempre que um alvo realizar uma jogada de\nataque ou teste de resistência antes da magia acabar, o\nalvo pode jogar um d4 e adicionar o valor jogado ao\nataque ou teste de resistência.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 2° nível ou\nsuperior, você pode afetar uma criatura adicional para\ncada nível do espaço acima do 1°."},{"id":"comando","name":"Comando","level":1,"school":"encantamento","ritual":false,"classes":["clerigo","paladino"],"pdfPage":226,"time":"1 ação","range":"18 metros","components":"V","duration":"1 rodada","concentration":false,"text":"1° nível de encantamento\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V\nDuração: 1 rodada\nVocê pronuncia uma palavra de comando para uma\ncriatura que você possa ver dentro do alcance. O alvo deve\nser bem sucedido num teste de resistência de Sabedoria\nou seguirá seu comando no próximo turno dele. A magia\nnão tem efeito se o alvo for um morto-vivo, se ele não\nentender seu idioma ou se o comando for diretamente\nnocivo a ele.\n    Alguns comandos típicos e seus efeitos a seguir. Você\npode proferir um comando diferente dos descritos aqui. Se\no fizer, o Mestre descreve como o alvo reage. Se o alvo não\npuder cumprir o comando, a magia termina.\n    Aproxime-se. O alvo se move para próximo de você o\nmáximo que puder na rota mais direta, terminando seu\nturno, se ele se mover a até 1,5 metro de você.\n    Largue. O alvo larga o que quer que ele esteja\nsegurando, e termina seu turno.\n    Fuja. O alvo gasta seu turno se movendo para longe\nde você da forma mais rápida que puder.\n    Deite-se. O alvo deita-se no chão e então, termina seu\nturno.\n    Parado. O alvo não se move e não realiza nenhuma\nação. Uma criatura voadora continua no alto,\nconsiderando que ela seja capaz de fazê-lo. Se ela tiver\nque se mover para continuar no alto, ela voa a mínima\ndistância necessária para permanecer no ar.\n    Em Níveis Superiores. Se você conjurar essa magia\nusando um espaço de magia de 2° nível ou superior, você\npode afetar uma criatura adicional para cada nível do\nespaço acima do 1°. As criaturas devem estar a 9 metros\nentre si para serem afetadas."},{"id":"compreender-idiomas","name":"Compreender Idiomas","level":1,"school":"adivinhação","ritual":true,"classes":["bardo","bruxo","feiticeiro","mago"],"pdfPage":226,"time":"1 ação","range":"Pessoal","components":"V, S, M (um pitada de fuligem e sal)","duration":"1 hora","concentration":false,"text":"1° nível de adivinhação (ritual)\nTempo de Conjuração: 1 ação\nAlcance: Pessoal\nComponentes: V, S, M (um pitada de fuligem e sal)\nDuração: 1 hora\nPela duração, você compreende o significado literal de\nqualquer idioma falado que você ouvir. Você também\ncompreende qualquer idioma escrito que vir, mas você\ndeve tocar a superfície onde as palavras estão escritas.\nLeva, aproximadamente, 1 minuto para ler uma página\nde texto.\n    Essa magia não decifra mensagens secretas em textos\nou glifos, como um selo arcano, que não seja parte de um\nidioma escrito."},{"id":"constricao","name":"Constrição","level":1,"school":"conjuração","ritual":false,"classes":["druida"],"pdfPage":230,"time":"1 ação","range":"27 metros","components":"V, S","duration":"Concentração, até 1 minuto","concentration":true,"text":"1° nível de conjuração\nTempo de Conjuração: 1 ação\nAlcance: 27 metros\nComponentes: V, S\nDuração: Concentração, até 1 minuto\nErvas e vinhas poderosas brotam do solo num quadrado\nde 6 metros a partir de um ponto dentro do alcance. Pela\nduração, essas plantas transformam o solo na área em\nterreno difícil.\n   Uma criatura na área quando você conjurar a magia\ndeve ser bem sucedida num teste de resistência de Força\nou ficará impedida pelo emaranhado de plantas, até a\nmagia acabar. Uma criatura impedida pelas plantas pode\nusar sua ação para realizar um teste de Força, contra a\nCD da magia. Se for bem sucedido, irá se libertar.\n   Quando a magia termina, as plantas conjuradas\nmurcharão."},{"id":"convocar-familiar","name":"Convocar Familiar","level":1,"school":"conjuração","ritual":true,"classes":["mago"],"pdfPage":231,"time":"1 hora","range":"3 metros","components":"V, S, M (carvão, incenso e ervas no valor de 10 po, que devem ser consumidos pelo fogo em um braseiro de bronze)","duration":"Instantânea","concentration":false,"text":"1° nível de conjuração (ritual)\n Tempo de Conjuração: 1 hora\n Alcance: 3 metros\n Componentes: V, S, M (carvão, incenso e ervas no valor\n    de 10 po, que devem ser consumidos pelo fogo em um\n    braseiro de bronze)\n Duração: Instantânea\n Você adquire os serviços de uma familiar, um espírito que\n toma a forma de um animal, à sua escolha: aranha,\n caranguejo, cavalo marinho, coruja, corvo, doninha, gato,\n falcão, lagarto, morcego, peixe (arenque), polvo, rato, rã\n (sapo) ou serpente venenosa. Aparecendo em um espaço\n desocupado dentro do alcance, o familiar tem as mesmas\n estatísticas da forma escolhida, no entanto, ele é um\n celestial, corruptor ou fada (à sua escolha) ao invés de\n uma besta.\n     Seu familiar age independentemente de você, mas ele\n sempre obedece aos seus comandos. Em combate, ele rola\n sua a própria iniciativa e age no seu próprio turno. Um\n familiar não pode atacar, mas ele pode realizar outras\n ações, como de costume.\n   Quando um familiar cai a 0 pontos de vida, ele\ndesaparece, não deixando qualquer corpo físico para trás.\nEle reaparece depois de você conjurar essa magia\nnovamente.\n   Enquanto seu familiar estiver a até 30 metros de você,\nvocê pode se comunicar telepaticamente com ele. Além\ndisso, com uma ação, você pode ver através dos olhos do\nfamiliar e ouvir através dos ouvidos dele, até o início do\nseu próximo turno, adquirindo os benefícios de qualquer\nsentido especial que o familiar possua. Durante esse\nperíodo, você estará cego e surdo em relação aos seus\npróprios sentidos.\n   Com uma ação, você pode, temporariamente,\ndispensar seu familiar. Ele desaparece dentro de uma\nbolsa dimensional onde ele aguarda sua convocação.\nAlternativamente, você pode dispensa-lo para sempre.\nCom uma ação, enquanto ele estiver temporariamente\ndispensado, você pode fazê-lo reaparecer em qualquer\nespaço desocupado a até 9 metros de você.\n   Você não pode ter mais de um familiar por vez. Se você\nconjurar essa magia enquanto já tiver um familiar, ao\ninvés disso, você faz seu familiar existente adotar uma\nnova forma. Escolha uma das formas da lista acima. Seu\nfamiliar se transforma na criatura escolhida.\n   Finalmente, quando você conjura uma magia com\nalcance de toque, seu familiar pode transmitir a magia,\ncomo se ele tivesse conjurado ela. Seu familiar precisa\nestar a até 30 metros de você e deve usar a reação dele\npara transmitir a magia quando você a conjurar. Se a\nmagia necessitar de uma jogada de ataque, você usa seu\nmodificador de ataque para essa jogada."},{"id":"criar-ou-destruir-agua","name":"Criar ou Destruir Água","level":1,"school":"transmutação","ritual":false,"classes":["clerigo","druida"],"pdfPage":234,"time":"1 ação","range":"9 metros","components":"V, S, M (uma gota de água se estiver criando ou alguns grãos de areia se estiver destruindo)","duration":"Instantânea","concentration":false,"text":"1° nível de transmutação\nTempo de Conjuração: 1 ação\nAlcance: 9 metros\nComponentes: V, S, M (uma gota de água se estiver\n   criando ou alguns grãos de areia se estiver destruindo)\nDuração: Instantânea\nVocê pode tanto criar quanto destruir água.\n   Criar Água. Você cria 30 litros de água limpa dentro\ndo alcance, em um recipiente aberto. Alternativamente, a\nágua pode cair como chuva em um cubo de 9 metros\ndentro do alcance, extinguindo chamas expostas na área.\n   Destruir Água. Você destrói até 30 litros de água de\num     recipiente     aberto     dentro      do     alcance.\nAlternativamente, você pode destruir um nevoeiro em um\ncubo de 9 metros dentro do alcance.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 2° nível ou\nsuperior, você pode criar ou destruir 30 litros de água\nadicionais, ou o tamanho do cubo aumenta em 1,5 metro,\npara cada nível do espaço acima do 1°."},{"id":"curar-ferimentos","name":"Curar Ferimentos","level":1,"school":"evocação","ritual":false,"classes":["bardo","clerigo","druida","paladino","patrulheiro"],"pdfPage":234,"time":"1 ação","range":"Toque","components":"V, S","duration":"Instantânea","concentration":false,"text":"1° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S\nDuração: Instantânea\nUma criatura que você tocar recupera uma quantidade de\npontos de vida igual a 1d8 + seu modificador de\nhabilidade de conjuração. Essa magia não produz efeito\nem mortos-vivos ou constructos.\n    Em Níveis Superiores. Se você conjurar essa magia\nusando um espaço de magia de 2° nível ou superior, a\ncura aumenta em 1d8 para cada nível do espaço acima do\n1°."},{"id":"destruicao-colerica","name":"Destruição Colérica","level":1,"school":"evocação","ritual":false,"classes":["paladino"],"pdfPage":237,"time":"1 ação bônus","range":"Pessoal","components":"V","duration":"Concentração, até 1 minuto","concentration":true,"text":"1° nível de evocação\nTempo de Conjuração: 1 ação bônus\nAlcance: Pessoal\nComponentes: V\nDuração: Concentração, até 1 minuto\nDa próxima vez que você atingir com um ataque corpo-a-\ncorpo com arma enquanto essa magia durar, seu ataque\ncausará 1d6 de dano psíquico extra. Além disso, se o alvo\nfor uma criatura, ele deve realizar um teste de resistência\nde Sabedoria ou ficará amedrontado por você até a magia\nacabar. Com uma ação, a criatura pode realizar um teste\nde resistência de Sabedoria contra a CD da magia para se\nmanter resoluto e terminar a magia."},{"id":"destruicao-lancinante","name":"Destruição Lancinante","level":1,"school":"evocação","ritual":false,"classes":["paladino"],"pdfPage":237,"time":"1 ação bônus","range":"Pessoal","components":"V","duration":"Concentração, até 1 minuto","concentration":true,"text":"1° nível de evocação\nTempo de Conjuração: 1 ação bônus\nAlcance: Pessoal\nComponentes: V\nDuração: Concentração, até 1 minuto\nDa próxima vez que você atingir uma criatura com um\nataque corpo-a-corpo com arma enquanto essa magia\ndurar, sua arma flameja com intensas chamas brancas e o\nataque causa 1d6 de dano de fogo extra ao alvo, fazendo-o\nincendiar pelas chamas. No início de cada turno dele, até\na arma acabar, o alvo deve realizar um teste de\nresistência de Constituição. Se falhar na resistência, ele\nsofre 1d6 de dano de fogo. Se passar na resistência, a\nmagia acaba. Se o alvo ou uma criatura a 1,5 metro dele\nusar uma ação para apagar as chamas ou se algum outro\nefeito extinguir as chamas (como submergir o alvo em\nágua), a magia acaba.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 2° nível ou\nsuperior, o dano extra inicial causado por esse ataque\naumenta em 1d6 para cada nível do espaço acima do 1°."},{"id":"destruicao-trovejante","name":"Destruição Trovejante","level":1,"school":"evocação","ritual":false,"classes":["paladino"],"pdfPage":237,"time":"1 ação bônus","range":"Pessoal","components":"V","duration":"Concentração, até 1 minuto","concentration":true,"text":"1° nível de evocação\nTempo de Conjuração: 1 ação bônus\nAlcance: Pessoal\nComponentes: V\nDuração: Concentração, até 1 minuto\nDa primeira vez que você atingir um ataque corpo-a-corpo\ncom arma enquanto essa magia durar, sua arma é\nrodeada por trovões que são audíveis a até 90 metros de\nvocê e o ataque causa 2d6 de dano trovejante extra no\nalvo. Além disso, se o alvo for uma criatura, ele deve ser\nbem sucedido num teste de resistência de Força ou será\nempurrado 3 metros para longe de você e cairá no chão."},{"id":"detectar-magia","name":"Detectar Magia","level":1,"school":"adivinhação","ritual":true,"classes":["bardo","clerigo","druida","feiticeiro","mago","paladino","patrulheiro"],"pdfPage":237,"time":"1 ação","range":"Pessoal","components":"V, S","duration":"Concentração, até 10 minutos","concentration":true,"text":"1° nível de adivinhação (ritual)\nTempo de Conjuração: 1 ação\nAlcance: Pessoal\nComponentes: V, S\nDuração: Concentração, até 10 minutos\nPela duração, você sente a presença de magia a até 9\nmetros de você. Se você sentir magia dessa forma, você\npode usar sua ação para ver uma aura suave em volta de\nqualquer criatura ou objeto visível, na área que carrega\nmagia, e você descobre a escolha de magia, se houver\numa.\n   A magia pode penetrar a maioria das barreiras, mas é\nbloqueada por 30 centímetros de rocha, 2,5 centímetros de\nmetal comum, uma fina camada de chumbo, ou 90\ncentímetros de madeira ou terra."},{"id":"detectar-veneno-e-doenca","name":"Detectar Veneno e Doença","level":1,"school":"adivinhação","ritual":true,"classes":["clerigo","druida","paladino","patrulheiro"],"pdfPage":238,"time":"1 ação","range":"Pessoal","components":"V, S, M (uma folha de teixo)","duration":"Concentração, até 10 minutos","concentration":true,"text":"1° nível de adivinhação (ritual)\nTempo de Conjuração: 1 ação\nAlcance: Pessoal\nComponentes: V, S, M (uma folha de teixo)\nDuração: Concentração, até 10 minutos\nPela duração, você sente a presença e localização de\nvenenos, criaturas venenosas e doenças a até 9 metros de\nvocê. Você também identifica o tipo de veneno, criatura\nvenenosa ou doença em cada caso.\n   A magia pode penetrar a maioria das barreiras, mas é\nbloqueada por 30 centímetros de rocha, 2,5 centímetros de\nmetal comum, uma fina camada de chumbo, ou 90\ncentímetros de madeira ou terra."},{"id":"detectar-o-bem-e-mal","name":"Detectar o Bem e Mal","level":1,"school":"adivinhação","ritual":false,"classes":["clerigo","paladino"],"pdfPage":237,"time":"1 ação","range":"Pessoal","components":"V, S","duration":"Concentração, até 10 minutos","concentration":true,"text":"1° nível de adivinhação\nTempo de Conjuração: 1 ação\nAlcance: Pessoal\nComponentes: V, S\nDuração: Concentração, até 10 minutos\nPela duração, você sabe se existe uma aberração,\ncelestial, corruptor, elemental, fada ou morto-vivo, a até 9\nmetros de você, assim como onde a criatura está\nlocalizada. Similarmente, você sabe se existe um local ou\nobjeto, a até 9 metros de você, que tenha sido consagrado\nou profanado magicamente.\n   A magia pode penetrar a maioria das barreiras, mas é\nbloqueada por 30 centímetros de rocha, 2,5 centímetros de\nmetal comum, uma fina camada de chumbo, ou 90\ncentímetros de madeira ou terra."},{"id":"disco-flutuante-de-tenser","name":"Disco Flutuante de Tenser","level":1,"school":"conjuração","ritual":true,"classes":["mago"],"pdfPage":238,"time":"1 ação","range":"9 metros","components":"V, S, M (uma gota de mercúrio)","duration":"1 hora","concentration":false,"text":"1° nível de conjuração (ritual)\nTempo de Conjuração: 1 ação\nAlcance: 9 metros\nComponentes: V, S, M (uma gota de mercúrio)\nDuração: 1 hora\nEssa magia cria um plano horizontal, circular de energia\nde 90 cm de diâmetro por 2,5 cm de espessura, que flutua\n90 centímetros acima do chão em um espaço desocupado,\nà sua escolha, que você possa ver dentro do alcance. O\ndisco permanece pela duração e pode suportar até 250\nquilos. Se mais peso for colocado nele, a magia termina, e\ntudo em cima do disco cai no chão.\n    O disco é imóvel enquanto você estiver a até 6 metros\ndele. Se você se afastar a mais de 6 metros dele, o disco\nseguirá você, mantendo-se a 6 metros de você. Ele pode\natravessar terreno irregular, subir ou descer escadas,\nencostas e similares, mas ele não pode atravessar\nmudanças de elevação de 3 metros ou mais. Por exemplo,\no disco não pode atravessar um fosso de 3 metros de\nprofundidade nem poderia sair de tal fosso se tivesse sido\ncriado no fundo dele.\n    Se você se afastar mais de 30 metros do disco\n(tipicamente por ele não poder rodear um obstáculo para\nseguir você), a magia acaba."},{"id":"disfarcar-se","name":"Disfarçar-se","level":1,"school":"ilusão","ritual":false,"classes":["bardo","feiticeiro","mago"],"pdfPage":238,"time":"1 ação","range":"Pessoal","components":"V, S","duration":"1 hora","concentration":false,"text":"1° nível de ilusão\nTempo de Conjuração: 1 ação\nAlcance: Pessoal\nComponentes: V, S\nDuração: 1 hora\nVocê faz com que você mesmo – incluindo suas roupas,\narmadura, armas e outros pertences no seu personagem –\npareça diferente até a magia acabar ou até você usar sua\nação para dispensa-la. Você pode se parecer 30\ncentímetros mais baixo ou mais alto, e pode parecer\nmagro, gordo ou entre ambos. Você não pode mudar o tipo\ndo seu corpo, portanto, você deve adotar uma forma que\ntenha a mesma disposição básica de membros. No mais, a\nextensão da sua ilusão cabe a você.\n    As mudanças criadas por essa magia não conseguem\nse sustentar perante uma inspeção física. Por exemplo, se\nvocê usar essa magia para adicionar um chapéu ao seu\nvisual, objetos que passarem pelo chapéu e qualquer um\nque tocá-lo não sentirá nada ou sentirá sua cabeça e\ncabelo. Se você usar essa magia para aparentar ser mais\nmagro do que é, a mão de alguém que a erguer para tocar\nem você, irá esbarrar em você enquanto ainda está,\naparentemente, está no ar.\n    Para perceber que você está disfarçado, uma criatura\npode usar a ação dela para inspecionar sua aparência e\ndeve ser bem sucedida em um teste de Inteligência\n(Investigação) contra a CD da sua magia."},{"id":"duelo-compelido","name":"Duelo Compelido","level":1,"school":"encantamento","ritual":false,"classes":["paladino"],"pdfPage":240,"time":"1 ação bônus","range":"9 metros","components":"V","duration":"Concentração, até 1 minuto","concentration":true,"text":"1° nível de encantamento\nTempo de Conjuração: 1 ação bônus\nAlcance: 9 metros\nComponentes: V\nDuração: Concentração, até 1 minuto\nVocê tenta compelir uma criatura a duelar com você. Uma\ncriatura que você possa ver, dentro do alcance, deve\nrealizar um teste de resistência de Sabedoria. Se falhar, a\ncriatura é atraída por você, compelida pela sua exigência\ndivina. Pela duração, ela tem desvantagem nas jogadas\nde ataque contra criaturas diferentes de você e deve\nrealizar um teste de resistência de Sabedoria cada vez\nque tentar se mover para um espaço que esteja a mais de\n9 metros de você; se ela passar no teste de resistência,\nessa magia não restringirá o movimento do alvo nesse\nturno.\n    A magia termina se você atacar qualquer outra\ncriatura, se você conjurar uma magia que afete uma\ncriatura hostil diferente do alvo, se uma criatura\namigável a você causar dano ou conjurar uma magia\nnociva nele ou se você terminar seu turno a mais de 9\nmetros do alvo."},{"id":"enfeiticar-pessoa","name":"Enfeitiçar Pessoa","level":1,"school":"encantamento","ritual":false,"classes":["bardo","bruxo","druida","feiticeiro","mago"],"pdfPage":241,"time":"1 ação","range":"9 metros","components":"V, S","duration":"1 hora","concentration":false,"text":"1° nível de encantamento\nTempo de Conjuração: 1 ação\nAlcance: 9 metros\nComponentes: V, S\nDuração: 1 hora\nVocê tenta enfeitiçar um humanoide que você possa ver\ndentro do alcance. Ele deve realizar um teste de\nresistência de Sabedoria, e recebe vantagem nesse teste\nse você ou seus companheiros estiverem lutando com ele.\nSe ele falhar, ficará enfeitiçado por você até a magia\nacabar ou até você ou seus companheiros fizerem\nqualquer coisa nociva contra ele. A criatura enfeitiçada\nreconhece você como um conhecido amigável. Quando a\nmagia acabar, a criatura saberá que foi enfeitiçada por\nvocê.\n   Em Níveis Superiores. Se você conjurar essa magia\nusando um espaço de magia de 2° nível ou superior, você\npode afetar uma criatura adicional para cada nível do\nespaço acima do 1°. As criaturas devem estar a até 9\nmetros umas das outras quando você for afeta-las."},{"id":"escrita-ilusoria","name":"Escrita Ilusória","level":1,"school":"ilusão","ritual":true,"classes":["bardo","bruxo","mago"],"pdfPage":241,"time":"1 minuto","range":"Toque","components":"S, M (uma tinta à base de chumbo valendo, no mínimo, 10 po, que é consumida pela magia)","duration":"10 dias","concentration":false,"text":"1° nível de ilusão (ritual)\nTempo de Conjuração: 1 minuto\nAlcance: Toque\nComponentes: S, M (uma tinta à base de chumbo\n   valendo, no mínimo, 10 po, que é consumida pela\n   magia)\nDuração: 10 dias\nVocê escreve em um pergaminho, papel ou qualquer outro\nmaterial adequado e tinge ele com uma poderosa ilusão\nque permanece pela duração.\n    Para você e para qualquer criatura que você designar\nquando você conjura essa magia, a escrita parece normal,\nescrita com a sua caligrafia e transmite qualquer que seja\na mensagem que você desejava quando escreveu o texto.\nPara todos os outros, a escrita aparece como se tivesse\nsido escrita com uma caligrafia desconhecida ou mágica\nque é inteligível. Alternativamente, você pode fazer a\nescrita parecer uma mensagem totalmente diferente,\nescrita com uma caligrafia e idioma diferentes, apesar de\no idioma precisar ser um que você conheça.\n    No caso da magia ser dissipada, tanto a escrita\noriginal quanto a ilusória desaparecem.\n    Uma criatura com visão verdadeira pode ler a\nmensagem escondida."},{"id":"escudo-arcano","name":"Escudo Arcano","level":1,"school":"abjuração","ritual":false,"classes":["feiticeiro","mago"],"pdfPage":241,"time":"1 reação, que você faz quando é atingido por um ataque ou alvo da magia mísseis mágicos","range":"Pessoal","components":"V, S","duration":"1 rodada","concentration":false,"text":"1° nível de abjuração\nTempo de Conjuração: 1 reação, que você faz quando é\n   atingido por um ataque ou alvo da magia mísseis\n   mágicos\nAlcance: Pessoal\nComponentes: V, S\nDuração: 1 rodada\nUma barreira de energia invisível aparece e protege você.\nAté o início do seu próximo turno, você recebe +5 de bônus\nna CA, incluindo contra o ataque que desencadeou a\nmagia, e você não sofre dano de mísseis mágicos."},{"id":"escudo-da-fe","name":"Escudo da Fé","level":1,"school":"abjuração","ritual":false,"classes":["clerigo","paladino"],"pdfPage":241,"time":"1 ação bônus","range":"18 metros","components":"V, S, M (um pequeno pergaminho com alguns textos sagrados escritos nele)","duration":"Concentração, até 10 minutos","concentration":true,"text":"1° nível de abjuração\nTempo de Conjuração: 1 ação bônus\nAlcance: 18 metros\nComponentes: V, S, M (um pequeno pergaminho com\n   alguns textos sagrados escritos nele)\nDuração: Concentração, até 10 minutos\nUm campo cintilante aparece ao redor de uma criatura, à\nsua escolha, dentro do alcance, concedendo +2 de bônus\nna CA pela duração."},{"id":"falar-com-animais","name":"Falar com Animais","level":1,"school":"adivinhação","ritual":true,"classes":["bardo","druida","patrulheiro"],"pdfPage":244,"time":"1 ação","range":"Pessoal","components":"V, S","duration":"10 minutos","concentration":false,"text":"1° nível de adivinhação (ritual)\nTempo de Conjuração: 1 ação\nAlcance: Pessoal\nComponentes: V, S\nDuração: 10 minutos\nVocê adquire a habilidade de compreender e se comunicar\nverbalmente com bestas, pela duração. O conhecimento e\nconsciência de muitas bestas é limitado pela inteligência\ndelas mas, no mínimo, as bestas poderão dar informações\na você sobre os locais e monstros próximos, incluindo tudo\nque eles possam perceber ou tenham percebido no dia\nanterior. Você pode tentar persuadir uma besta a lhe\nprestar um favor, à critério do Mestre."},{"id":"fogo-das-fadas","name":"Fogo das Fadas","level":1,"school":"evocação","ritual":false,"classes":["bardo","druida"],"pdfPage":245,"time":"1 ação","range":"18 metros","components":"V","duration":"Concentração, até 1 minuto","concentration":true,"text":"1° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V\nDuração: Concentração, até 1 minuto\nCada objeto num cubo de 6 metros dentro do alcance fica\ndelineado com luz azul, verde ou violeta (à sua escolha).\nQualquer criatura na área, quando a magia é conjurada,\ntambém fica delineada com luz, se falhar num teste de\nresistência de Destreza. Pela duração, os objetos e\ncriaturas afetadas emitem penumbra num raio de 3\nmetros.\n    Qualquer jogada de ataque contra uma criatura\nafetada ou objeto tem vantagem, se o atacante puder ver\no alvo e, a criatura afetada ou objeto não recebe benefício\npor estar invisível."},{"id":"golpe-constritor","name":"Golpe Constritor","level":1,"school":"conjuração","ritual":false,"classes":["patrulheiro"],"pdfPage":247,"time":"1 ação bônus","range":"Pessoal","components":"V","duration":"Concentração, até 1 minuto","concentration":true,"text":"1° nível de conjuração\nTempo de Conjuração: 1 ação bônus\nAlcance: Pessoal\nComponentes: V\nDuração: Concentração, até 1 minuto\nDa próxima vez que você atingir uma criatura com um\nataque com arma, antes do final da magia, um\nemaranhado maciço de vinhas espinhentas aparecem no\nlocal do impacto e o alvo deve ser bem sucedido num teste\nde resistência de Força ou ficará impedido pelas vinhas\nmágicas, até o fim da magia. Uma criatura Grande ou\nmaior tem vantagem no seu teste de resistência. Se o alvo\nfor bem sucedido na resistência, as vinhas murcharão.\n    Enquanto estiver impedido pela magia, um alvo sofre\n1d6 de dano perfurante no início de cada um dos turnos\ndele. Uma criatura impedida pelas vinhas ou uma que\npossa tocar a criatura, pode usar sua ação para realizar\num teste de Força contra a CD da magia. Num sucesso, o\nalvo é libertado.\n    Em Níveis Superiores. Se você conjurar essa magia\nusando um espaço de magia de 2° nível ou superior, o\ndano aumenta em 1d6 para cada nível do espaço acima do\n1°."},{"id":"heroismo","name":"Heroísmo","level":1,"school":"encantamento","ritual":false,"classes":["bardo","paladino"],"pdfPage":248,"time":"1 ação","range":"Toque","components":"V, S","duration":"Concentração, até 1 minuto","concentration":true,"text":"1° nível de encantamento\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S\nDuração: Concentração, até 1 minuto\nUma criatura voluntária que você tocar é imbuída com\nbravura. Até a magia acabar, a criatura é imune a ser\namedrontada e ganha pontos de vida temporários igual ao\nseu modificador de habilidade de conjuração, no início de\ncada turno dela. Quando a magia acabar, o alvo perde\nqualquer ponto de vida temporário restante dessa magia.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 2° nível ou\nsuperior, você pode afetar uma criatura adicional para\ncada nível do espaço acima do 1°."},{"id":"identificacao","name":"Identificação","level":1,"school":"adivinhação","ritual":true,"classes":["bardo","mago"],"pdfPage":248,"time":"1 minuto","range":"Toque","components":"V, S, M (uma perola valendo, no mínimo, 100 po e uma pena de coruja)","duration":"Instantânea","concentration":false,"text":"1° nível de adivinhação (ritual)\nTempo de Conjuração: 1 minuto\nAlcance: Toque\nComponentes: V, S, M (uma perola valendo, no mínimo,\n   100 po e uma pena de coruja)\nDuração: Instantânea\nVocê escolhe um objeto que você deve tocar durante toda\na conjuração da magia. Se ele for um item mágico ou\nalgum outro objeto imbuído por magia, você descobre suas\npropriedades e como usá-lo, se exige sintonia para ser\nusado e quantas cargas ele tem, se aplicável. Você\ndescobre se quaisquer magias estão afetando o item e\nquais eles são. Se o item foi criado por magia, você\ndescobre que magia o criou.\n   Se você, ao invés, tocar uma criatura durante toda a\nconjuração, você descobre quais magias, se houver\nalguma, estão afetando-a atualmente."},{"id":"imagem-silenciosa","name":"Imagem Silenciosa","level":1,"school":"ilusão","ritual":false,"classes":["bardo","feiticeiro","mago"],"pdfPage":250,"time":"1 ação","range":"18 metros","components":"V, S, M (um pouco de lã)","duration":"Concentração, até 10 minutos","concentration":true,"text":"1° nível de ilusão\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, S, M (um pouco de lã)\nDuração: Concentração, até 10 minutos\nVocê cria a imagem de um objeto, criatura ou outro\nfenômeno visual que não tenha mais de 4,5 metros\ncúbicos. A imagem aparece num ponto, dentro do alcança,\ne permanece pela duração. A imagem é puramente visual;\nnão é acompanhada por som, cheiro ou outros efeitos\nsensoriais.\n    Você pode usar sua ação para fazer a imagem se\nmover para qualquer ponto, dentro do alcance. À medida\nque a imagem muda de lugar, você pode alterar a\naparência dela para que seu movimento pareça ser o\nnatural para a imagem. Por exemplo, se você criar uma\nimagem de uma criatura e move-la, você pode alterar a\nimagem para que ela pareça estar andando.\n    Interação física com a imagem, revelará que ela é uma\nilusão, já que as coisas podem passar através dela. Uma\ncriatura que usar sua ação para examinar a imagem,\npode determinar que ela é uma ilusão com um teste de\nInteligência (Investigação) bem sucedido contra a CD da\nmagia. Se uma criatura discernir a ilusão como sendo\nisso, a criatura poderá ver através da imagem."},{"id":"infligir-ferimentos","name":"Infringir Ferimentos","level":1,"school":"necromancia","ritual":false,"classes":["clerigo"],"pdfPage":250,"time":"1 ação","range":"Toque","components":"V, S","duration":"Instantânea","concentration":false,"text":"1° nível de necromancia\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S\nDuração: Instantânea\nFaça um ataque corpo-a-corpo com magia contra uma\ncriatura dentro do alcance. Se atingir, o alvo sofre 3d10\nde dano necrótico.\n    Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 2° nível ou\nsuperior, o dano aumenta em 1d10 para cada nível acima\ndo 1°."},{"id":"leque-cromatico","name":"Leque Cromático","level":1,"school":"ilusão","ritual":false,"classes":["feiticeiro","mago"],"pdfPage":252,"time":"1 ação","range":"Pessoal (cone de 4,5 metros)","components":"V, S, M (um punhado de pó ou areia nas cores vermelha, amarela e azul)","duration":"1 rodada","concentration":false,"text":"1° nível de ilusão\nTempo de Conjuração: 1 ação\nAlcance: Pessoal (cone de 4,5 metros)\nComponentes: V, S, M (um punhado de pó ou areia nas\n   cores vermelha, amarela e azul)\nDuração: 1 rodada\nUm feixe ofuscante de luzes coloridas ordenadas, surge da\nsua mão. Role 6d10; o total é a quantidade de pontos de\nvida de criaturas que essa magia pode afetar. As\ncriaturas num cone de 4,5 metros, originado de você, são\nafetadas em ordem ascendente dos seus pontos de vida\n(ignorando criaturas inconsciente e que não podem ver).\n    Começando com as criaturas que tiverem menos\npontos de vida, cada criatura afetada por essa magia\nficará cega até o fim da magia. Subtraia os pontos de vida\nde cada criatura do total antes de considerar os pontos de\nvida da próxima criatura. Os pontos de vida de uma\ncriatura devem ser iguais ou menores que o total restante\npara que essa criatura seja afetada\n    Em Níveis Superiores. Se você conjurar essa magia\nusando um espaço de magia de 2° nível ou superior, jogue\n2d10 adicionais para cada nível do espaço acima do 1°."},{"id":"marca-do-cacador","name":"Marca do Caçador","level":1,"school":"adivinhação","ritual":false,"classes":["patrulheiro"],"pdfPage":255,"time":"1 ação bônus","range":"27 metros","components":"V","duration":"Concentração, até 1 hora","concentration":true,"text":"1° nível de adivinhação\nTempo de Conjuração: 1 ação bônus\nAlcance: 27 metros\nComponentes: V\nDuração: Concentração, até 1 hora\nVocê escolhe uma criatura que possa ver, dentro do\nalcance e a marca misticamente como sua presa. Até a\nmagia acabar, você causa 1d6 de dano extra ao alvo\nsempre que você o atingir com um ataque com arma e\nvocê tem vantagem em quaisquer testes de Sabedoria\n(Percepção) ou Sabedoria (Sobrevivência) feitos para\nencontrá-la. Se o alvo cair a 0 pontos de vida antes da\nmagia acabar, você pode usar uma ação bônus, no seu\nturno subsequente para marcar uma nova criatura.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 3° ou 4° nível, você\npoderá manter sua concentração na magia por até 8\nhoras. Quando você usar um espaço de magia de 5° nível\nou superior, você poderá manter sua concentração na\nmagia por até 24 horas."},{"id":"maos-flamejantes","name":"Mãos Flamejantes","level":1,"school":"evocação","ritual":false,"classes":["feiticeiro","mago"],"pdfPage":254,"time":"1 ação","range":"Pessoal (cone de 4,5 metros)","components":"V, S","duration":"Instantânea","concentration":false,"text":"1° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: Pessoal (cone de 4,5 metros)\nComponentes: V, S\nDuração: Instantânea\nEnquanto você mantiver suas mãos com os polegares\njuntos e os dedos abertos, uma fino leque de chamas\nemerge das pontas dos seus dedos erguidos. Cada criatura\nnum cone de 4,5 metros deve realizar um teste de\nresistência de Destreza. Uma criatura sofre 3d6 de dano\nde fogo se falhar no teste, ou metade desse dano se\nobtiver sucesso.\n    O fogo incendeia qualquer objeto inflamável na área\nque não esteja sendo vestido ou carregado.\n    Em Níveis Superiores. Se você conjurar essa magia\nusando um espaço de magia de 2° nível ou superior, o\ndano aumenta em 1d6 para cada nível do espaço acima do\n1°."},{"id":"misseis-magicos","name":"Mísseis Mágicos","level":1,"school":"evocação","ritual":false,"classes":["feiticeiro","mago"],"pdfPage":257,"time":"1 ação","range":"36 metros","components":"V, S","duration":"Instantânea","concentration":false,"text":"1° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: 36 metros\nComponentes: V, S\nDuração: Instantânea\nVocê cria três dardos brilhantes de energia mística. Cada\ndardo atinge uma criatura, à sua escolha, que você possa\nver, dentro do alcance. Um dardo causa 1d4 + 1 de dano\nde energia ao alvo. Todos os dardos atingem\nsimultaneamente e você pode direciona-los para atingir\numa criatura ou várias.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 2° nível ou\nsuperior, a magia cria um dardo adicional para cada nível\ndo espaço acima do 1°."},{"id":"nevoa-obscurecente","name":"Névoa Obscurecente","level":1,"school":"conjuração","ritual":false,"classes":["druida","feiticeiro","mago","patrulheiro"],"pdfPage":262,"time":"1 ação","range":"36 metros","components":"V, S","duration":"Concentração, até 1 hora","concentration":true,"text":"1° nível de conjuração\nTempo de Conjuração: 1 ação\nAlcance: 36 metros\nComponentes: V, S\nDuração: Concentração, até 1 hora\nVocê cria uma esfera de 6 metros de raio de névoa,\ncentrada num ponto, dentro do alcance. A esfera se\nespalha, dobrando esquinas, e a área dela é de escuridão\ndensa. Ela permanece pela duração ou até um vento\nmoderado ou mais rápido (pelo menos 15 quilômetros por\nhora) dispersa-la.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 2° nível ou\nsuperior, o raio da névoa aumenta em 6 metros para cada\nnível do espaço acima do 1°."},{"id":"onda-trovejante","name":"Onda Trovejante","level":1,"school":"evocação","ritual":false,"classes":["bardo","druida","feiticeiro","mago"],"pdfPage":264,"time":"1 ação","range":"Pessoal (cubo de 4,5 metros)","components":"V, S","duration":"Instantânea","concentration":false,"text":"1° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: Pessoal (cubo de 4,5 metros)\nComponentes: V, S\nDuração: Instantânea\nUma onda de força trovejante varre tudo a partir de você.\nCada criatura num cubo de 4,5 metros originado em você,\ndeve realizar um teste de resistência de Constituição. Se\nfalhar na resistência, uma criatura sofrerá 2d8 de dano\ntrovejante e será empurrada 3 metros para longe de você.\nSe obtive sucesso na resistência, a criatura sofrerá\nmetade desse dano e não será empurrada.\n   Além disso, objetos soltos que estiverem\ncompletamente dentro da área de efeito serão\nautomaticamente empurrados 3 metros para longe de\nvocê pelo efeito da magia e a magia emitirá um\nressonante barulho de trovão audível a até 90 metros.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 2° nível ou\nsuperior, o dano aumenta em 1d8 para cada nível acima\ndo 1°."},{"id":"orbe-cromatica","name":"Orbe Cromática","level":1,"school":"evocação","ritual":false,"classes":["feiticeiro","mago"],"pdfPage":264,"time":"1 ação","range":"27 metros","components":"V, S, M (um diamante valendo, no mínimo, 50 po)","duration":"Instantânea","concentration":false,"text":"1° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: 27 metros\nComponentes: V, S, M (um diamante valendo, no\n   mínimo, 50 po)\nDuração: Instantânea\nVocê arremessa uma esfera de energia de 12 centímetros\nde diâmetro numa criatura que você possa ver dentro do\nalcance. Você escolhe ácido, frio, fogo, elétrico, veneno ou\ntrovejante para o tipo de orbe que você cria e, então,\nrealiza um ataque à distância com magia. Se o ataque\natingir, a criatura sofre 3d8 de dano do tipo escolhido.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 2° nível ou\nsuperior, o dano aumenta em 1d8 para cada nível do\nespaço acima do 1°."},{"id":"palavra-curativa","name":"Palavra Curativa","level":1,"school":"evocação","ritual":false,"classes":["bardo","clerigo","druida"],"pdfPage":264,"time":"1 ação bônus","range":"18 metros","components":"V","duration":"Instantânea","concentration":false,"text":"1° nível de evocação\nTempo de Conjuração: 1 ação bônus\nAlcance: 18 metros\nComponentes: V\nDuração: Instantânea\nUma criatura, à sua escolha, que você possa ver dentro do\nalcance recupera uma quantidade de pontos de vida igual\na 1d4 + seu modificador de habilidade de conjuração. Essa\nmagia não tem efeito em mortos-vivos ou constructos\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 2° nível ou\nsuperior, a cura aumenta em 1d4 para cada nível do\nespaço acima do 1°."},{"id":"passos-longos","name":"Passos Longos","level":1,"school":"transmutação","ritual":false,"classes":["bardo","druida","mago","patrulheiro"],"pdfPage":265,"time":"1 ação","range":"Toque","components":"V, S, M (um pouco de barro)","duration":"1 hora","concentration":false,"text":"1° nível de transmutação\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S, M (um pouco de barro)\nDuração: 1 hora\nVocê toca uma criatura. O deslocamento do alvo aumenta\nem 3 metros, até a magia acabar.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 2° nível ou\nsuperior, você pode afetar uma criatura adicional para\ncada nível do espaço acima do 1°."},{"id":"perdicao","name":"Perdição","level":1,"school":"encantamento","ritual":false,"classes":["bardo","clerigo"],"pdfPage":267,"time":"1 ação","range":"9 metros","components":"V, S, M (uma gota de sangue)","duration":"Concentração, até 1 minuto","concentration":true,"text":"1° nível de encantamento\nTempo de Conjuração: 1 ação\nAlcance: 9 metros\nComponentes: V, S, M (uma gota de sangue)\nDuração: Concentração, até 1 minuto\nAté três criaturas, à sua escolha, que você possa ver\ndentro do alcance, devem realizar um teste de resistência\nde Carisma. Sempre que um alvo que falhou nessa\nresistência realizar uma jogada de ataque ou um teste de\nresistência antes da magia acabar, o alvo deve rolar um\nd4 e subtrair o valor rolado da jogada de ataque ou teste\nde resistência.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 2° nível ou\nsuperior, você pode afetar uma criatura adicional para\ncada nível do espaço acima do 1°."},{"id":"protecao-contra-o-bem-e-mal","name":"Proteção contra o Bem e Mal","level":1,"school":"abjuração","ritual":false,"classes":["bruxo","clerigo","mago","paladino"],"pdfPage":270,"time":"1 ação","range":"Toque","components":"V, S, M (água benta ou pó de prata e ferro, consumidos pela magia)","duration":"Concentração, até 10 minutos","concentration":true,"text":"1° nível de abjuração\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S, M (água benta ou pó de prata e\n   ferro, consumidos pela magia)\nDuração: Concentração, até 10 minutos\nAté a magia acabar, uma criatura voluntária que você\ntocar estará protegida contra certos tipos de criaturas:\naberrações, celestiais, corruptores, elementais, fadas e\nmortos-vivos.\n   A proteção garante diversos benefícios. As criaturas\ndesse tipo tem desvantagem nas jogadas de ataque contra\no alvo. O alvo não pode ser enfeitiçado, amedrontado ou\npossuído por elas. Se o alvo já estiver enfeitiçado,\namedrontado ou possuído por uma dessas criaturas, o\nalvo terá vantagem em qualquer novo teste de resistência\ncontra o efeito relevante."},{"id":"purificar-alimentos","name":"Purificar Alimentos","level":1,"school":"transmutação","ritual":true,"classes":["clerigo","druida","paladino"],"pdfPage":271,"time":"1 ação","range":"3 metros","components":"V, S","duration":"Instantânea","concentration":false,"text":"1° nível de transmutação (ritual)\nTempo de Conjuração: 1 ação\nAlcance: 3 metros\nComponentes: V, S\nDuração: Instantânea\nToda comida e bebida não-mágica dentro de uma esfera\nde 1,5 metro de raio centrada num ponto, à sua escolha,\ndentro do alcance é purificada e se livrada de venenos ou\ndoenças."},{"id":"queda-suave","name":"Queda Suave","level":1,"school":"transmutação","ritual":false,"classes":["bardo","feiticeiro","mago"],"pdfPage":271,"time":"1 reação, que você realiza quando você ou uma criatura a até 18 metros cair","range":"18 metros","components":"V, M (uma pequena pena ou penugem similar)","duration":"1 minuto","concentration":false,"text":"1° nível de transmutação\nTempo de Conjuração: 1 reação, que você realiza\n   quando você ou uma criatura a até 18 metros cair\nAlcance: 18 metros\nComponentes: V, M (uma pequena pena ou penugem\n   similar)\nDuração: 1 minuto\nEscolha até cinco criaturas caindo, dentro do alcance. A\ntaxa de descendência de uma criatura caindo é reduzida\npara 18 metros por rodada, até o fim da magia. Se a\ncriatura aterrissar antes da magia acabar, ela não sofre\nnenhum dano de queda, pode aterrissar em pé e a magia\ntermina para essa criatura."},{"id":"raio-adoecente","name":"Raio Adoecente","level":1,"school":"necromancia","ritual":false,"classes":["feiticeiro","mago"],"pdfPage":271,"time":"1 ação","range":"18 metros","components":"V, S","duration":"Instantânea","concentration":false,"text":"1° nível de necromancia\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, S\nDuração: Instantânea\nUm raio adoecente de energia esverdeada chicoteia na\ndireção de uma criatura dentro do alcance. Faça um\nataque à distância com magia contra o alvo. Se atingir, o\nalvo sofrerá 2d8 de dano de veneno e deve realizar um\nteste de resistência de Constituição. Se falhar na\nresistência, ele também ficará envenenado até o final do\nseu próximo turno.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 2° nível ou\nsuperior, o dano da magia aumenta em 1d8 para cada\nnível do espaço acima do 1°."},{"id":"raio-guiador","name":"Raio Guiador","level":1,"school":"evocação","ritual":false,"classes":["clerigo"],"pdfPage":272,"time":"1 ação","range":"36 metros","components":"V, S","duration":"1 rodada","concentration":false,"text":"1° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: 36 metros\nComponentes: V, S\nDuração: 1 rodada\nUm lampejo de luz se lança em direção de uma criatura, à\nsua escolha, dentro do alcance. Realize um ataque à\ndistância com magia contra o alvo. Se atingir, o alvo sofre\n4d6 de dano radiante e, a próxima jogada de ataque\ncontra esse alvo, antes do final do seu próximo turno, terá\nvantagem, graças a penumbra mística cintilando no alvo,\naté então.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 2° nível ou\nsuperior, o dano aumenta em 1d6 para cada nível do\nespaço acima do 1°."},{"id":"raio-de-bruxa","name":"Raio de Bruxa","level":1,"school":"evocação","ritual":false,"classes":["bruxo","feiticeiro","mago"],"pdfPage":271,"time":"1 ação","range":"9 metros","components":"V, S, M (um galho de uma árvore que tenha sido atingida por um relâmpago)","duration":"Concentração, até 1 minuto","concentration":true,"text":"1° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: 9 metros\nComponentes: V, S, M (um galho de uma árvore que\n   tenha sido atingida por um relâmpago)\nDuração: Concentração, até 1 minuto\nUm raio crepitante de energia azul é arremessado em\numa criatura dentro do alcance, formando um arco\nelétrico contínuo entre você e o alvo. Faça um ataque à\ndistância com magia contra a criatura. Se atingir, o alvo\nsofrerá 1d12 de dano elétrico e, em cada um dos seus\nturnos, pela duração, você pode usar sua ação para causar\n1d12 de dano elétrico ao alvo, automaticamente. A magia\nacaba se você usar sua ação para fazer qualquer outra\ncoisa. A magia também acaba se o alvo estiver fora do\nalcance da magia ou se você tiver cobertura total para ele.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 2° nível ou\nsuperior, o dano inicial aumenta em 1d12 para cada nível\ndo espaço acima do 1°."},{"id":"recuo-acelerado","name":"Recuo Acelerado","level":1,"school":"transmutação","ritual":false,"classes":["bruxo","feiticeiro","mago"],"pdfPage":275,"time":"1 ação bônus","range":"Pessoal","components":"V, S","duration":"Concentração, até 10 minutos","concentration":true,"text":"1° nível de transmutação\nTempo de Conjuração: 1 ação bônus\nAlcance: Pessoal\nComponentes: V, S\nDuração: Concentração, até 10 minutos\nEssa magia permite que você se mova a um ritmo\nincrível. Quando você conjura essa magia e, a partir de\nentão, com uma ação bônus em cada um dos seus turnos,\naté a magia acabar, você pode realizar a ação de\nDisparada."},{"id":"repreensao-infernal","name":"Repreensão Infernal","level":1,"school":"evocação","ritual":false,"classes":["bruxo"],"pdfPage":276,"time":"1 reação, que você faz em resposta ao sofre dano de uma criatura a até 18 metros de você e que você possa ver","range":"18 metros","components":"V, S","duration":"Instantânea","concentration":false,"text":"1° nível de evocação\nTempo de Conjuração: 1 reação, que você faz em\n   resposta ao sofre dano de uma criatura a até 18\n   metros de você e que você possa ver\nAlcance: 18 metros\nComponentes: V, S\nDuração: Instantânea\nVocê aponta seu dedo e a criatura que causou dano a você\né, momentaneamente, envolta por chamas infernais. A\ncriatura deve realizar um teste de resistência de\nDestreza. Ela sofre 2d10 de dano de fogo se falhar na\nresistência ou metade desse dano se obtiver sucesso.\n    Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 2° nível ou\nsuperior, o dano aumenta em 1d10 para cada nível do\nespaço acima do 1°."},{"id":"riso-histerico-de-tasha","name":"Riso Histérico de Tasha","level":1,"school":"encantamento","ritual":false,"classes":["bardo","mago"],"pdfPage":277,"time":"1 ação","range":"9 metros","components":"V, S, M (pequenas tortas e uma pena que é balançada no ar)","duration":"Concentração, até 1 minuto","concentration":true,"text":"1° nível de encantamento\nTempo de Conjuração: 1 ação\nAlcance: 9 metros\nComponentes: V, S, M (pequenas tortas e uma pena que\n   é balançada no ar)\nDuração: Concentração, até 1 minuto\nUma criatura, à sua escolha, que você possa ver, dentro\ndo alcance, acha tudo hilariantemente engraçado e cai na\ngargalhada, se essa magia afeta-la. O alvo deve ser bem\nsucedido em um teste de resistência de Sabedoria ou cairá\nno chão, ficando incapacitado e incapaz de se levantar\npela duração. Uma criatura com valor de Inteligência 4 ou\ninferior não é afetada.\n   Ao final de cada um dos turnos dela e, toda vez que\nsofrer dano, o alvo pode realizar outro teste de resistência\nde Sabedoria. O alvo terá vantagem no teste de\nresistência se ele for garantido por ele ter sofrido dano. Se\nobtiver sucesso, a magia acaba."},{"id":"salto","name":"Salto","level":1,"school":"transmutação","ritual":false,"classes":["druida","feiticeiro","mago","patrulheiro"],"pdfPage":278,"time":"1 ação","range":"Toque","components":"V, S, M (uma perna de gafanhoto)","duration":"1 minuto","concentration":false,"text":"1° nível de transmutação\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S, M (uma perna de gafanhoto)\nDuração: 1 minuto\nVocê toca uma criatura. A distância de salto da criatura é\ntriplicada até a magia acabar."},{"id":"santuario","name":"Santuário","level":1,"school":"abjuração","ritual":false,"classes":["clerigo"],"pdfPage":278,"time":"1 ação bônus","range":"9 metros","components":"V, S, M (um pequeno espelho de prata)","duration":"1 minuto","concentration":false,"text":"1° nível de abjuração\nTempo de Conjuração: 1 ação bônus\nAlcance: 9 metros\nComponentes: V, S, M (um pequeno espelho de prata)\nDuração: 1 minuto\nVocê protege uma criatura, dentro do alcance, contra\nataques. Até a magia acabar, qualquer criatura que\ntentar atacar ou usar magias que causem dano contra\ncriatura protegida deve, primeiro, realizar um teste de\nresistência de Sabedoria. Se falhar na resistência, a\ncriatura deve escolher um novo alvo ou perderá o ataque\nou magia. Essa magia não protege a criatura contra\nefeitos de área, como a explosão de uma bola de fogo.\n    Se a criatura protegida realizar um ataque ou conjurar\numa magia que afete uma criatura inimiga, essa magia\nacaba."},{"id":"saraivada-de-espinhos","name":"Saraivada de Espinhos","level":1,"school":"conjuração","ritual":false,"classes":["patrulheiro"],"pdfPage":278,"time":"1 ação bônus","range":"Pessoal","components":"V","duration":"Concentração, até 1 minuto","concentration":true,"text":"1° nível de conjuração\nTempo de Conjuração: 1 ação bônus\nAlcance: Pessoal\nComponentes: V\nDuração: Concentração, até 1 minuto\nDa próxima vez que você atingir uma criatura com um\nataque à distância com arma, antes da magia acabar,\nessa magia cria uma chuva de espinhos que brota da sua\narma à distância ou munição. Além do efeito normal do\nataque, o alvo do ataque e cada criatura a até 1,5 metro\ndele, devem realizar um teste de resistência de Destreza.\nUma criatura sofre 1d10 de dano perfurante se falhar na\nresistência ou metade desse dano se obtiver sucesso.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 2° nível ou\nsuperior, o dano aumenta em 1d10 para cada nível do\nespaço acima do 1° (até o máximo de 6d10)."},{"id":"servo-invisivel","name":"Servo Invisível","level":1,"school":"conjuração","ritual":true,"classes":["bardo","bruxo","mago"],"pdfPage":279,"time":"1 ação","range":"18 metros","components":"V, S, M (um pedaço de barbante e um pouco de madeira)","duration":"1 hora","concentration":false,"text":"1° nível de conjuração (ritual)\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, S, M (um pedaço de barbante e um\n   pouco de madeira)\nDuração: 1 hora\nEssa magia cria uma força invisível, sem mente e sem\nforma que realiza tarefas simples, ao seu comando, até a\nmagia acabar. O servo aparece do nada em um espaço\ndesocupado no chão, dentro do alcance. Ele tem CA 10, 1\nponto de vida, Força 2 e não pode atacar. Se ele cair a 0\npontos de vida, a magia acaba.\n    Uma vez em cada um dos seus turnos, com uma ação\nbônus, você pode comandar, mentalmente, o servo para se\nmover até 4,5 metros e interagir com um objeto. O servo\npode realizar tarefas simples que um serviçal humano\nfaria, como buscar coisas, limpar, consertar, dobrar\nroupas, acender chamas, servir comida ou derramar\nvinho. Uma vez que um comando seja dado, o servo\nrealiza a tarefa da melhor forma possível, até completar a\ntarefa, então esperará o seu próximo comando.\n    Se você comandar o servo a realizar uma tarefa que\npoderia afasta-lo a mais de 18 metros de você, a magia\ntermina."},{"id":"sono","name":"Sono","level":1,"school":"encantamento","ritual":false,"classes":["bardo","feiticeiro","mago"],"pdfPage":281,"time":"1 ação","range":"36 metros","components":"V, S, M (um punhado de areia fina, pétalas de rosas ou um grilo)","duration":"1 minuto","concentration":false,"text":"1° nível de encantamento\nTempo de Conjuração: 1 ação\nAlcance: 36 metros\nComponentes: V, S, M (um punhado de areia fina,\n   pétalas de rosas ou um grilo)\nDuração: 1 minuto\nEssa magia põem as criaturas num entorpecimento\nmágico. Jogue 5d8; o total é a quantidade de pontos de\nvida de criaturas afetados pela magia. As criaturas numa\nárea de 6 metros de raio, centrada no ponto escolhido,\ndentro do alcance, são afetadas em ordem ascendente dos\npontos de vida atuais delas (ignorando criaturas\ninconscientes).\n    Começando com as criaturas com menos pontos de\nvida atuais, cada criatura afetada por essa magia cai\ninconsciente até a magia acabar, sofrer dano ou alguém\nusar sua ação para sacudi-la ou esbofeteá-la até acordar.\nSubtraia os pontos de vida de cada criatura do total antes\nde seguir para a próxima criatura com menos pontos de\nvida atuais. Os pontos de vida atuais da criatura devem\nser iguais ou menores que o valor restante para que a\ncriatura possa ser afetada.\n    Mortos-vivos e criaturas imunes a serem enfeitiçadas\nnão são afetadas por essa magia.\n    Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 2º nível ou\nsuperior, jogue 2d8 adicionais para cada nível do espaço\nacima do 1°."},{"id":"sussurros-dissonantes","name":"Sussurros Dissonantes","level":1,"school":"encantamento","ritual":false,"classes":["bardo"],"pdfPage":281,"time":"1 ação","range":"18 metros","components":"V","duration":"Instantânea","concentration":false,"text":"1° nível de encantamento\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V\nDuração: Instantânea\nVocê sussurra uma melodia dissonante que apenas uma\ncriatura, à sua escolha, dentro do alcance pode ouvir,\ncausando-lhe uma terrível dor. O alvo deve realizar um\nteste de resistência de Sabedoria. Se falhar na\nresistência, ele sofrerá 3d6 de dano psíquico e deve,\nimediatamente, usar sua reação, se disponível, para se\nmover para o mais longe possível de você. A criatura não\nse moverá para um terreno obviamente perigoso, como\numa fogueira ou abismo. Se obtiver sucesso na\nresistência, o alvo sofre metade do dano e não precisa se\nafastar de você. Uma criatura surda obtém sucesso\nautomaticamente na sua resistência.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 2° nível ou\nsuperior, o dano aumenta em 1d6 para cada nível do\nespaço acima do 1°."},{"id":"vitalidade-falsa","name":"Vitalidade Falsa","level":1,"school":"necromancia","ritual":false,"classes":["feiticeiro","mago"],"pdfPage":288,"time":"1 ação","range":"Pessoal","components":"V, S, M (uma pequena quantidade de álcool ou bebidas destiladas)","duration":"1 hora","concentration":false,"text":"1° nível de necromancia\nTempo de Conjuração: 1 ação\nAlcance: Pessoal\nComponentes: V, S, M (uma pequena quantidade de\n   álcool ou bebidas destiladas)\nDuração: 1 hora\nReforçando-se com uma vitalidade necromântica ilusória,\nvocê ganha 1d4 + 4 pontos de vida temporários pela\nduração.\n    Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 2° nível ou\nsuperior, você ganha 5 pontos de vida temporários\nadicionais para cada nível do espaço de magia acima do\n1°."},{"id":"area-escorregadia","name":"Área Escorregadia","level":1,"school":"conjuração","ritual":false,"classes":["mago"],"pdfPage":218,"time":"1 ação","range":"18 metros","components":"V, S, M (um pouco de pele de porco ou manteiga)","duration":"1 minuto","concentration":false,"text":"1° nível de conjuração\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, S, M (um pouco de pele de porco ou\n   manteiga)\nDuração: 1 minuto\nGraxa escorregadia cobre o solo em um quadrado de 3\nmetros centrado em um ponto, dentro do alcance,\ntornando essa área em terreno difícil pela duração.\n   Quando a graxa aparece, cada criatura de pé na área\ndeve ser bem sucedida num teste de resistência de\nDestreza ou cairá no chão. Uma criatura que entre na\nárea ou termine seu turno nela, deve ser bem sucedido\nnum teste de resistência de Destreza ou cairá no chão."},{"id":"acalmar-emocoes","name":"Acalmar Emoções","level":2,"school":"encantamento","ritual":false,"classes":["bardo","clerigo"],"pdfPage":213,"time":"1 ação","range":"18 metros","components":"V, S","duration":"Concentração, até 1 minuto","concentration":true,"text":"2° nível de encantamento\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, S\nDuração: Concentração, até 1 minuto\nVocê tenta suprimir emoções fortes em um grupo de\npessoas. Cada humanoide em uma esfera de 6 metros de\nraio, centrada em um ponto que você escolher dentro do\nalcance, deve realizar um teste de resistência de Carisma;\numa criatura pode escolher falhar nesse teste, se desejar.\nSe uma criatura falhar na resistência, escolha um dentre\nos dois efeitos a seguir.\n   Você pode suprimir qualquer efeito que esteja\ndeixando a criatura enfeitiçada ou amedrontada. Quando\nessa magia terminar, qualquer efeito suprimido volta a\nfuncionar, considerando que sua duração não tenha\nacabado nesse meio tempo.\n   Alternativamente, você pode tornar um alvo\nindiferente às criaturas que você escolher que forem\nhostis a ele. Essa indiferença acaba se o alvo for atacado\nou ferido por uma magia ou se ele testemunhar qualquer\ndos seus amigos sendo ferido. Quando a magia terminar,\na criatura se tornará hostil novamente, a não ser que o\nMestre diga o contrário."},{"id":"ajuda","name":"Ajuda","level":2,"school":"abjuração","ritual":false,"classes":["clerigo","paladino"],"pdfPage":213,"time":"1 ação","range":"9 metros","components":"V, S, M (uma pequena fita de tecido branco)","duration":"8 horas","concentration":false,"text":"2° nível de abjuração\nTempo de Conjuração: 1 ação\nAlcance: 9 metros\nComponentes: V, S, M (uma pequena fita de tecido\n   branco)\nDuração: 8 horas\nSua magia inspira seus aliados com vigor e determinação.\nEscolha até três criaturas dentro do alcance. O máximo\nde pontos de vida e os pontos de vida atuais de cada alvo\naumentam em 5, pela duração.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 3° nível ou\nsuperior, os pontos de vida dos alvos aumentam em 5\npontos adicionais para cada nível do espaço acima do o 2°."},{"id":"alterar-se","name":"Alterar-se","level":2,"school":"transmutação","ritual":false,"classes":["feiticeiro","mago"],"pdfPage":214,"time":"1 ação","range":"Pessoal","components":"V, S","duration":"Concentração, até 1 hora","concentration":true,"text":"2° nível de transmutação\nTempo de Conjuração: 1 ação\nAlcance: Pessoal\nComponentes: V, S\nDuração: Concentração, até 1 hora\nVocê assume uma forma diferente. Quando conjurar essa\nmagia, escolha uma das seguintes opções, o efeito durará\npela duração da magia. Enquanto a magia durar, você\npode terminar uma opção com uma ação para ganhar os\nbenefícios de uma diferente.\n    Adaptação Aquática. Você adapta seu corpo para\num ambiente aquático, brotando guelras e crescendo\nmembranas entre seus dedos. Você pode respirar embaixo\nd’água e ganha deslocamento de natação igual a seu\ndeslocamento terrestre.\n    Mudar Aparência. Você transforam sua aparência.\nVocê decide com o que você parece, incluindo altura, peso,\ntraços faciais, timbre da sua voz, comprimento do cabelo,\ncoloração e características distintas, se tiverem. Você\npode ficar parecido com um membro de outra raça, apesar\nde nenhuma de suas estatísticas mudar. Você também\nnão pode parecer com uma criatura de um tamanho\ndiferente do seu, e seu formado básico permanece o\nmesmo; se você for bípede, você não pode usar essa magia\npara se tornar quadrupede, por exemplo. A qualquer\nmomento, pela duração da magia, você pode usar sua ação\npara mudar sua aparência dessa forma, novamente.\n    Armas Naturais. Você faz crescerem garras, presas,\nespinhos, chifres ou armas naturais diferentes, à sua\nescolha. Seus ataques desarmados causam 1d6 de dano de\nconcussão, perfurante ou cortante, como apropriado para\na arma natural que você escolheu, e você é proficiente\ncom seus ataques desarmados. Finalmente, a arma\nnatural é mágica e você tem +1 de bônus nas jogadas de\nataque e dano que você fizer com ela."},{"id":"aprimorar-habilidade","name":"Aprimorar Habilidade","level":2,"school":"transmutação","ritual":false,"classes":["bardo","clerigo","druida","feiticeiro"],"pdfPage":217,"time":"1 ação","range":"Toque","components":"V, S, M (pelo ou penas de uma besta)","duration":"Concentração, até 1 hora","concentration":true,"text":"2° nível de transmutação\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S, M (pelo ou penas de uma besta)\nDuração: Concentração, até 1 hora\nVocê toca uma criatura e a agracia com aprimoramento\nmágico. Escolha um dos efeitos a seguir; o alvo ganha esse\nefeito até o fim da magia.\n   Agilidade do Gato. O alvo tem vantagem em testes\nde Destreza. Ele também não sofre dano ao cair de 6\nmetros ou menos, se não estiver incapacitado.\n   Esperteza da Raposa. O alvo tem vantagem em\ntestes de Inteligência.\n   Esplendor da Águia. O alvo tem vantagem em testes\nde Carisma.\n   Força do Touro. O alvo tem vantagem em testes de\nForça e sua capacidade de carga é dobrada.\n   Sabedoria da Coruja. O alvo tem vantagem em\ntestes de Sabedoria.\n   Vigor do Urso. O alvo tem vantagem em testes de\nConstituição. Ele também recebe 2d6 pontos de vida\ntemporários, que são perdidos quando a magia termina.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 3° nível ou\nsuperior, você pode afetar uma criatura adicional para\ncada nível do espaço acima do 2°."},{"id":"arma-espiritual","name":"Arma Espiritual","level":2,"school":"evocação","ritual":false,"classes":["clerigo"],"pdfPage":218,"time":"1 ação bônus","range":"18 metros","components":"V, S","duration":"1 minuto","concentration":false,"text":"2° nível de evocação\nTempo de Conjuração: 1 ação bônus\nAlcance: 18 metros\nComponentes: V, S\nDuração: 1 minuto\nVocê cria uma arma espectral flutuante, dentro do\nalcance, que permanece pela duração ou até você conjurar\nessa magia novamente. Quando você conjura essa magia,\nvocê pode realizar um ataque corpo-a-corpo com magia\ncontra uma criatura a 1,5 metro da arma. Se atingir, o\nalvo sofre dano de energia igual a 1d8 + seu modificador\nde habilidade de conjuração.\n   Com uma ação bônus, no seu turno, você pode mover a\narma até 6 metros e repetir o ataque contra uma criatura\na 1,5 metro dela.\n   A arma pode ter a forma que você desejar. Clérigos de\ndivindades associadas com uma arma em particular\n(como St. Cuthbert é conhecido por sua maça ou Thor por\nseu martelo) fazem o efeito dessa magia se assemelhar a\nessa arma.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 4° nível ou\nsuperior, o dano aumenta em 1d8 para cada dois níveis do\nespaço acima do 2°."},{"id":"arma-magica","name":"Arma Mágica","level":2,"school":"transmutação","ritual":false,"classes":["mago","paladino"],"pdfPage":218,"time":"1 ação bônus","range":"Toque","components":"V, S","duration":"Concentração, até 1 hora","concentration":true,"text":"2° nível de transmutação\nTempo de Conjuração: 1 ação bônus\nAlcance: Toque\nComponentes: V, S\nDuração: Concentração, até 1 hora\nVocê toca uma arma não-mágica. Até a magia acabar, a\narma se torna uma arma mágica com +1 de bônus nas\njogadas de ataque e jogadas de dano.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 4° nível ou\nsuperior, o bônus aumenta para +2. Quando você usar um\nespaço de magia de 6° nível ou superior, o bônus aumenta\npara +3."},{"id":"arrombar","name":"Arrombar","level":2,"school":"transmutação","ritual":false,"classes":["bardo","feiticeiro","mago"],"pdfPage":218,"time":"1 ação","range":"18 metros","components":"V","duration":"Instantânea","concentration":false,"text":"2° nível de transmutação\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V\nDuração: Instantânea\nEscolha um objeto que você possa ver, dentro do alcance.\nO objeto pode ser uma porta, uma caixa, um baú ou um\npar de algemas, um cadeado ou outro objeto que contenha\num meio mundano ou mágico que previne o acesso.\n   Um alvo que esteja fechado por uma fechadura\nmundana ou preso ou barrado torna-se destrancado,\ndestravado ou desbloqueado. Se o objeto tiver múltiplas\nfechaduras, apenas uma delas é destrancada.\n   Se você escolher um alvo que esteja travado pela\nmagia tranca arcana, essa magia será suprimida por 10\nminutos, durante esse período o alvo pode ser aberto e\nfechado normalmente.\n   Quando você conjurar essa magia, uma batida forte,\naudível a até 90 metros de distância, emana do objeto\nalvo."},{"id":"augurio","name":"Augúrio","level":2,"school":"adivinhação","ritual":true,"classes":["clerigo"],"pdfPage":219,"time":"1 minuto","range":"Pessoal","components":"V, S, M (varetas, ossos ou objetos similarmente marcados valendo, no mínimo, 25 po)","duration":"Instantânea","concentration":false,"text":"2° nível de adivinhação (ritual)\nTempo de Conjuração: 1 minuto\nAlcance: Pessoal\nComponentes: V, S, M (varetas, ossos ou objetos\n   similarmente marcados valendo, no mínimo, 25 po)\nDuração: Instantânea\nAo lançar varetas cravejados com gemas, rolar ossos de\ndragão, puxar cartas ornamentadas ou usar outro tipo de\nferramenta de adivinhação, você recebe um pressagio de\numa entidade de outro mundo, sobre os resultados de\ncursos de ação específicos que você planeja tomar nos\npróximos 30 minutos. O Mestre escolhe dentre os\npossíveis presságios a seguir:\n•   Êxito, para resultados bons\n•   Fracasso, para resultados maus\n•   Êxito e fracasso, para resultados bons e maus\n•   Nada, para resultados que não são especialmente bons\n    ou ruins\nA magia não leva em conta qualquer possível\ncircunstancia que possa mudar o resultado, como a\nconjuração de magias adicionais ou a perda ou ganho de\num companheiro.\n    Se você conjurar a magia duas ou mais vezes antes de\ncompletar seu próximo descanso longo, existe uma chance\ncumulativa de 25 por cento de cada conjuração, depois da\nprimeira que você fez, ter um resultado aleatório. O\nMestre faz essa jogada secretamente."},{"id":"aumentar-reduzir","name":"Aumentar/Reduzir","level":2,"school":"transmutação","ritual":false,"classes":["feiticeiro","mago"],"pdfPage":219,"time":"1 ação","range":"9 metros","components":"V, S, M (um pouco de pó de ferro)","duration":"Concentração, até 1 minuto","concentration":true,"text":"2° nível de transmutação\nTempo de Conjuração: 1 ação\nAlcance: 9 metros\nComponentes: V, S, M (um pouco de pó de ferro)\nDuração: Concentração, até 1 minuto\nVocê faz com que uma criatura ou um objeto que você\npossa ver dentro do alcance, fique maior ou menor, pela\nduração. Escolha entre uma criatura ou um objeto que\nnão esteja sendo carregado nem vestido. Se o alvo for\ninvoluntário, ele deve realizar um teste de resistência de\nConstituição. Se for bem sucedido, a magia não surte\nefeito.\n    Se o alvo for uma criatura, tudo que ele esteja vestindo\nou carregando muda e tamanho com ela. Qualquer item\nlargado por uma criatura afetada, retorna ao seu\ntamanho natural.\n    Aumentar. O tamanho do alvo dobra em todas as\ndimensões e seu peso é multiplicado por oito. Esse\naumento eleva seu tamanho em uma categoria – de Médio\npara Grande, por exemplo. Se não houver espaço\nsuficiente para que o alvo dobre de tamanho, a criatura\nou objeto alcança o tamanho máximo possível no espaço\ndisponível. Até o fim da magia, o alvo também tem\nvantagem em testes de Força e testes de resistência de\nForça. O tamanho das armas do alvo crescem para se\nadequar ao seu novo tamanho. Quando essas armas são\nampliadas, os ataques do alvo com elas causam 1d4 de\ndano extra.\n    Reduzir. O tamanho do alvo é reduzido à metade em\ntodas as dimensões e seu peso é reduzido a um oitavo do\nnormal. Essa redução diminui o tamanho do alvo em uma\ncategoria – de Médio para Pequeno, por exemplo. Até o\nfim da magia, o alvo tem desvantagem em testes de Força\ne testes de resistência de Força. O tamanho das armas do\nalvo diminuem para se adequar ao seu novo tamanho.\nQuando essas armas são reduzidas, os ataques do alvo\ncom elas causam 1d4 de dano a menos (isso não pode\nreduzir o dano a menos de 1)."},{"id":"aura-magica-de-nystul","name":"Aura Mágica de Nystul","level":2,"school":"ilusão","ritual":false,"classes":["mago"],"pdfPage":220,"time":"1 ação","range":"Toque","components":"V, S, M (um pequeno quadrado de seda)","duration":"24 horas","concentration":false,"text":"2° nível de ilusão\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S, M (um pequeno quadrado de seda)\nDuração: 24 horas\nVocê coloca uma ilusão em uma criatura ou objeto que\nvocê tocar, então magias de adivinhação revelarão\ninformações falsas sobre ele. O alvo pode ser uma criatura\nvoluntária ou um objeto que não esteja sendo carregado\nou vestido por outra criatura.\n   Quando você conjura essa magia, escolha um ou\nambos os efeitos seguintes. O efeito permanece pela\nduração. Se você conjurar essa magia na mesma criatura\nou objeto a cada dia por 30 dias, colocando o mesmo efeito\nnele todas as vezes, a ilusão durará até ser dissipada.\n   Aura Falsa. Você modifica a forma como o alvo\naparece para magias e efeitos mágicos, como detectar\nmagia, que detectam auras mágicas. Você pode fazer um\nobjeto não-mágico parecer mágico ou mudar a aura\nmágica de um objeto para que ela pareça pertencer a\noutra escola de magia a sua escolha. Quando você usar\nesse efeito num objeto, você pode fazer a aura falsa\naparente a qualquer criatura que manusear o item.\n   Máscara. Você modifica a forma como o alvo aparece\npara magias e efeitos que detectam tipos de criaturas,\ncomo o Sentido Divino do paladino ou o gatilho de um\nmagia símbolo. Você escolhe o tipo de criatura e outras\nmagias e efeitos mágicos consideram o alvo como se ele\nfosse uma criatura desse tipo ou tendência."},{"id":"boca-encantada","name":"Boca Encantada","level":2,"school":"ilusão","ritual":true,"classes":["bardo","mago"],"pdfPage":221,"time":"1 minuto","range":"9 metros","components":"V, S, M (um pedaço de favo de mel e pó de jade valendo, no mínimo, 10 po, consumidos pela magia)","duration":"Até ser dissipada","concentration":false,"text":"2° nível de ilusão (ritual)\nTempo de Conjuração: 1 minuto\nAlcance: 9 metros\nComponentes: V, S, M (um pedaço de favo de mel e pó\n   de jade valendo, no mínimo, 10 po, consumidos pela\n   magia)\nDuração: Até ser dissipada\nVocê implanta uma mensagem em um objeto dentro do\nalcance, uma mensagem que é pronunciada quando uma\ncondição de ativação é satisfeita. Escolha um objeto que\nvocê possa ver e não esteja sendo vestido ou carregado por\noutra criatura. Então, fale a mensagem, que deve conter\n25 palavras ou menos, apesar de ela poder ser entregue\ndurante um período de até 10 minutos. Finalmente,\ndetermine a circunstância que irá ativar a magia para\nque sua mensagem seja entregue.\n    Quando essa circunstância ocorrer, a boca encantada\naparecerá no objeto e recitará a mensagem com sua voz e\ncom o mesmo volume que você falou. Se o objeto que você\nescolheu tiver uma boca ou algo semelhante a uma boca\n(por exemplo, a boca de uma estátua), a boca mágica\naparece ai, então, as palavras parecerão vir da boca do\nobjeto. Quando você conjura essa magia, você pode fazer a\nmagia acabar depois de enviar sua mensagem ou ela pode\npermanecer e repetir a mensagem sempre que a\ncircunstância de ativação ocorrer.\n    A circunstância de ativação pode ser tão genérica ou\ntão detalhada quando você quiser, apesar de ela precisar\nser baseada em condições visuais ou audíveis que ocorram\na até 9 metros do objeto. Por exemplo, você pode instruir\na boca a falar quando uma criatura se aproximar a menos\nde 9 metros do objeto ou quando um sino de prata tocar a\nmenos de 9 metros dela."},{"id":"cativar","name":"Cativar","level":2,"school":"encantamento","ritual":false,"classes":["bardo","bruxo"],"pdfPage":224,"time":"1 ação","range":"18 metros","components":"V, S","duration":"1 minuto","concentration":false,"text":"2° nível de encantamento\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, S\nDuração: 1 minuto\nVocê tece um cordão de palavras distrativas, fazendo as\ncriaturas, à sua escolha, que você puder ver dentro do\nalcance e que puderem ouvir você, realizarem um teste de\nresistência de Sabedoria. Qualquer criatura que não\npuder ser enfeitiçada, passa automaticamente nesse teste\nde resistência e, se você ou seus companheiros estiverem\nlutando com a criatura, ela terá vantagem na resistência.\nSe falhar na resistência, a criatura terá desvantagem em\ntestes de Sabedoria (Percepção) feitos para notar\nqualquer criatura além de você, até a magia acabar ou até\no alvo não poder mais ouvir você. A magia acaba se você\nestiver incapacitado ou incapaz de falar."},{"id":"cegueira-surdez","name":"Cegueira/Surdez","level":2,"school":"necromancia","ritual":false,"classes":["bardo","clerigo","feiticeiro","mago"],"pdfPage":224,"time":"1 ação","range":"9 metros","components":"V","duration":"1 minuto","concentration":false,"text":"2° nível de necromancia\nTempo de Conjuração: 1 ação\nAlcance: 9 metros\nComponentes: V\nDuração: 1 minuto\nVocê pode cegar ou ensurdecer um oponente. Escolha uma\ncriatura que você possa ver dentro do alcance para fazer\num teste de resistência de Constituição. Se ela falhar,\nficará ou cega ou surda (à sua escolha) pela duração. No\nfinal de cada um dos turnos dele, o alvo pode realizar um\nteste de resistência de Constituição. Se obtiver sucesso, a\nmagia termina.\n    Em Níveis Superiores. Se você conjurar essa magia\nusando um espaço de magia de 3° nível ou superior, você\npode afetar uma criatura adicional para cada nível de\nespaço acima do 2°."},{"id":"chama-continua","name":"Chama Continua","level":2,"school":"evocação","ritual":false,"classes":["clerigo","mago"],"pdfPage":224,"time":"1 ação","range":"Toque","components":"V, S, M (pó de rubi no valor de 50 po, consumido pela magia)","duration":"Até ser dissipada","concentration":false,"text":"2° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S, M (pó de rubi no valor de 50 po,\n   consumido pela magia)\nDuração: Até ser dissipada\nUma chama, que produz iluminação equivalente a uma\ntocha, surge de um objeto que você tocar. O efeito é\nparecido com o de uma chama normal, mas ele não\nproduz calor e não consome oxigênio. Uma chama\ncontinua pode ser coberta ou escondida, mas não sufocada\nou extinta."},{"id":"convocar-montaria","name":"Convocar Montaria","level":2,"school":"conjuração","ritual":false,"classes":["paladino"],"pdfPage":232,"time":"10 minutos","range":"9 metros","components":"V, S","duration":"Instantânea","concentration":false,"text":"2° nível de conjuração\nTempo de Conjuração: 10 minutos\nAlcance: 9 metros\nComponentes: V, S\nDuração: Instantânea\nVocê convoca um espírito que assume a forma de uma\nmontaria excepcionalmente inteligente, forte e leal,\ncriando uma ligação duradoura com ela. Aparecendo em\num espaço desocupado dentro do alcance, a montaria\nadquire a forma que você escolher, como um cavalo de\nguerra, um pônei, um camelo, um alce ou um mastim.\n(Seu Mestre pode permitir outros animais para serem\nconvocados como montarias.) A montaria tem as\nestatísticas da forma escolhida, no entanto, ele é um\ncelestial, corruptor ou fada (à sua escolha) ao invés do seu\ntipo normal. Além disso, se sua montaria tiver\nInteligência 5 ou menor, a Inteligência dela se torna 6 e\nela ganha a capacidade de compreender um idioma, à sua\nescolha, que você fala.\n    Sua montaria serve tanto para cavalgar quando para o\ncombate e você tem uma ligação instintiva com ela que\npermite a vocês lutarem como uma unidade singular.\nEnquanto estiver montado na sua montaria, você pode\nfazer com que qualquer magia que você conjure que tenha\nalcance pessoal, também afete a sua montaria.\n    Quando a montaria cair a 0 pontos de vida, ela\ndesaparece, não deixando qualquer corpo físico para trás.\nVocê também pode dispensar sua montaria a qualquer\nmomento, com uma ação, fazendo-a desaparecer. Em\nambos os casos, conjurar essa magia novamente\nconvocará a mesma montaria, restaurando-a ao seu\nmáximo de pontos de vida.\n    Enquanto sua montaria estiver a até 1,5 quilômetro de\nvocê, você pode se comunicar telepaticamente com ela.\n    Você não pode ter mais de uma montaria ligado por\nessa magia por vez. Com uma ação, você pode liberar a\nmontaria da ligação a qualquer momento, fazendo-a\ndesaparecer."},{"id":"cordao-de-flechas","name":"Cordão de Flechas","level":2,"school":"transmutação","ritual":false,"classes":["patrulheiro"],"pdfPage":232,"time":"1 ação","range":"1,5 metro","components":"V, S, M (quatro ou mais flechas ou virotes)","duration":"8 horas","concentration":false,"text":"2° nível de transmutação\nTempo de Conjuração: 1 ação\nAlcance: 1,5 metro\nComponentes: V, S, M (quatro ou mais flechas ou\n   virotes)\nDuração: 8 horas\nVocê enfinca quatro munições não-mágicas – flechas ou\nvirotes de besta – no solo dentro do alcance e conjura\nmagia neles para proteger uma área. Até a magia acabar,\nsempre que uma criatura diferente de você se aproximar\na 9 metros das munições pela primeira vez em um turno\nou terminar seu turno na área, uma das munições voa\npara atingi-la. A criatura deve ser bem sucedida num\nteste de resistência de Destreza ou sofrerá 1d6 de dano\nperfurante. A munição, então, é destruída. A magia\ntermina quando não restar nenhuma munição.\n   Quando você conjurar essa magia, você pode designar\nquaisquer criaturas, à sua escolha, e a magia ignora-as.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 3° nível ou\nsuperior, a quantidade de munições que você pode afetar\naumenta em dois para cada nível do espaço acima do 2°."},{"id":"coroa-da-loucura","name":"Coroa da Loucura","level":2,"school":"encantamento","ritual":false,"classes":["bardo","bruxo","feiticeiro","mago"],"pdfPage":232,"time":"1 ação","range":"36 metros","components":"V, S","duration":"Concentração, até 1 minuto","concentration":true,"text":"2° nível de encantamento\nTempo de Conjuração: 1 ação\nAlcance: 36 metros\nComponentes: V, S\nDuração: Concentração, até 1 minuto\nUm humanoide, à sua escolha, que você possa ver dentro\ndo alcance, deve ser bem sucedido num teste de\nresistência de Sabedoria ou ficará enfeitiçado por você\npela duração. Enquanto o alvo estiver enfeitiçado dessa\nforma, uma coroa retorcida de ferro denteado aparece na\ncabeça dele e a loucura brilha em seus olhos.\n   A criatura enfeitiçada deve usar sua ação antes de se\nmover, em cada um dos turnos dela, para realizar um\nataque corpo-a-corpo contra uma criatura, diferente de si\nmesma, que você escolher mentalmente.\n   O alvo pode agir normalmente no turno dele se você\nnão escolher uma criatura ou se você não estiver dentro\ndo alcance.\n   Nos seus turnos subsequentes, você deve usar sua\nação para manter o controle sobre o alvo, ou a magia\ntermina. Igualmente, o alvo pode realizar um teste de\nresistência de Sabedoria no final de cada um dos turnos\ndele. Se obtiver sucesso, a magia termina."},{"id":"crescer-espinhos","name":"Crescer Espinhos","level":2,"school":"transmutação","ritual":false,"classes":["druida","patrulheiro"],"pdfPage":233,"time":"1 ação","range":"45 metros","components":"V, S, M (sete espinhos afiados ou sete gravetos, todos com uma ponta afiada)","duration":"Concentração, até 10 minutos","concentration":true,"text":"2° nível de transmutação\nTempo de Conjuração: 1 ação\nAlcance: 45 metros\nComponentes: V, S, M (sete espinhos afiados ou sete\n   gravetos, todos com uma ponta afiada)\nDuração: Concentração, até 10 minutos\nO solo num raio de 6 metros, centrado num ponto dentro\ndo alcance, se retorce e brotam cavilhas rígidas e\nespinhos. A área se torna terreno difícil pela duração.\nQuando uma criatura entrar ou se mover dentro da área,\nela sofrerá 2d4 de dano perfurante para cada 1,5 metro\nque ela atravessar.\n   A transformação do terreno é camuflada para parecer\nnatural. Qualquer criatura que não puder ver a área no\nmomento que a magia for conjurada, deve realizar um\nteste de Sabedoria (Percepção) contra a CD da magia para\nreconhecer o terreno como perigoso, antes de adentra-lo."},{"id":"despedacar","name":"Despedaçar","level":2,"school":"evocação","ritual":false,"classes":["bardo","bruxo","feiticeiro","mago"],"pdfPage":236,"time":"1 ação","range":"18 metros","components":"V, S, M (uma lasca de mica)","duration":"Instantânea","concentration":false,"text":"2° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, S, M (uma lasca de mica)\nDuração: Instantânea\nUm alto som estridente, dolorosamente intenso, emerge\nde um ponto, à sua escolha, dentro do alcance. Cada\ncriatura, numa esfera de 3 metros de raio, centrada no\nponto deve fazer um teste de resistência de Constituição.\nUma criatura sofre 3d8 de dano trovejante se falhar na\nresistência ou metade desse dano se obtiver sucesso. Uma\ncriatura feita de material inorgânico como pedra, cristal\nou metal, tem desvantagem nesse teste de resistência.\n    Um objeto não-mágico que não esteja sendo vestido ou\ncarregado, também sofre o dano, se estiver na área da\nmagia.\n    Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 3° nível ou\nsuperior, o dano aumenta em 1d8 para cada nível do\nespaço acima do 2°."},{"id":"detectar-pensamentos","name":"Detectar Pensamentos","level":2,"school":"adivinhação","ritual":false,"classes":["bardo","feiticeiro","mago"],"pdfPage":237,"time":"1 ação","range":"Pessoal","components":"V, S, M (um pedaço de cobre)","duration":"Concentração, até 1 minuto","concentration":true,"text":"2° nível de adivinhação\nTempo de Conjuração: 1 ação\nAlcance: Pessoal\nComponentes: V, S, M (um pedaço de cobre)\nDuração: Concentração, até 1 minuto\nPela duração, você pode ler os pensamentos de certas\ncriaturas. Quando você conjura essa magia e, com sua\nação a cada turno até o fim da magia, você pode focar sua\nmente em qualquer criatura que você puder ver a até 9\nmetros de você. Se a criatura escolhida possuir\nInteligência 3 ou inferior ou não falar nenhum tipo de\nidioma, a criatura não poderá ser afetada.\n    Você, inicialmente, descobre os pensamentos\nsuperficiais da criatura – o que está mais presente na sua\nmente no momento. Com uma ação, você pode tanto\nmudar sua atenção para os pensamentos de outra\ncriatura, como tentar sondar mais profundamente na\nmente da mesma criatura. Se você resolver sondar\nprofundamente, a criatura deve realizar um teste de\nresistência de Sabedoria. Se falhar, você ganha ciência do\nseu raciocínio (se possuir), seu estado emocional e algo\nque tome grande parte da sua mente (como algo que ele se\npreocupe, amores ou ódios). Se ele for bem sucedido, a\nmagia termina. Em ambas situações, o alvo saberá que\nvocê está sondando a mente dele e, a não ser que você\nmude sua atenção para os pensamentos de outra criatura,\na criatura pode usar a ação dela, no turno dela, para\nrealizar um teste de Inteligência resistido por seu teste de\nInteligência; se ela for bem sucedida, a magia termina.\n    Perguntas feitas diretamente para a criatura alvo,\nnormalmente moldarão o curso dos seus pensamentos,\nportanto, essa magia é particularmente eficiente como\nparte de um interrogatório.\n    Você pode, também, usar essa magia para detectar a\npresença que criaturas pensantes que você não possa ver.\nQuando você conjura essa magia ou, com sua ação\nenquanto ela durar, você pode procurar por pensamentos\na até 9 metros de você. A magia pode penetrar a maioria\ndas barreiras, mas é bloqueada por 30 centímetros de\nrocha, 2,5 centímetros de metal comum, uma fina camada\nde chumbo, ou 90 centímetros de madeira ou terra. Você\nnão pode detectar uma criatura com Inteligência 3 ou\ninferior ou uma que não fale qualquer idioma.\n    Uma vez que você tenha detectado a presença de uma\ncriatura dessa forma, você pode ler os pensamentos dela\npelo resto da duração, como descrito acima, mesmo que\nvocê não possa vê-la, mas ela ainda precisa estar dentro\ndo alcance."},{"id":"encontrar-armadilhas","name":"Encontrar Armadilhas","level":2,"school":"adivinhação","ritual":false,"classes":["clerigo","druida","patrulheiro"],"pdfPage":240,"time":"1 ação","range":"36 metros","components":"V, S","duration":"Instantânea","concentration":false,"text":"2° nível de adivinhação\nTempo de Conjuração: 1 ação\nAlcance: 36 metros\nComponentes: V, S\nDuração: Instantânea\nVocê sente a presença de qualquer armadilha dentro do\nalcance a qual você tenha linha de visão. Uma armadilha,\npara os propósitos dessa magia, inclui qualquer coisa que\npossa causar um efeito repentino ou inesperado em você,\nconsiderado nocivo ou indesejável, que foi especificamente\nplanejado para ser por seu criador. Portanto, a magia\nsentirá a área afetada pela magia alarme, um glifo de\nvigilância ou uma armadilha mecânica de fosso, mas ela\nnão revelará uma fragilidade natural no piso, um teto\ninstável ou um sumidouro escondido.\n   Essa magia apenas revela que existe uma magia\npresente. Você não descobre a localização de cada\narmadilha, mas você também descobre a natureza\ngenérica do perigo representando pela armadilha que\nvocê sentiu."},{"id":"escuridao","name":"Escuridão","level":2,"school":"evocação","ritual":false,"classes":["bruxo","feiticeiro","mago"],"pdfPage":242,"time":"1 ação","range":"18 metros","components":"V, M (pelo de morcego e uma gota de piche ou pedaço de carvão)","duration":"Concentração, até 10 minutos","concentration":true,"text":"2° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, M (pelo de morcego e uma gota de\n   piche ou pedaço de carvão)\nDuração: Concentração, até 10 minutos\nEscuridão mágica se espalha a partir de um ponto, à sua\nescolha, dentro do alcance e preenche uma esfera de 4,5\nmetros de raio pela duração. A escuridão se estende,\ndobrando esquinas. Uma criatura com visão no escuro não\npode ver através dessa escuridão e luz não-mágica não\npode iluminar dentro dela.\n    Se o ponto que você escolheu for um objeto que você\nesteja segurando, ou um que não esteja sendo vestido ou\ncarregado, a escuridão emanará do objeto e se moverá\ncom ele. Cobrir completamente a fonte da escuridão com\num objeto opaco, como uma vasilha ou um elmo,\nbloqueará a escuridão.\n    Se qualquer área dessa magia sobrepor uma área de\nluz criada por uma magia de 2° ou inferior, a magia que\ncriou a luz será dissipada."},{"id":"esfera-flamejante","name":"Esfera Flamejante","level":2,"school":"conjuração","ritual":false,"classes":["druida","mago"],"pdfPage":242,"time":"1 ação","range":"18 metros","components":"V, S, M (um pouco de seco, uma pitada de enxofre e uma camada de pó de ferro)","duration":"Concentração, até 1 minuto","concentration":true,"text":"2° nível de conjuração\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, S, M (um pouco de seco, uma pitada de\n   enxofre e uma camada de pó de ferro)\nDuração: Concentração, até 1 minuto\nUma esfera de fogo, com 1,5 metro de diâmetro, aparece\nem um espaço desocupado, à sua escolha, dentro do\nalcance e permanece pela duração. Qualquer criatura que\nterminar seu turno a até 1,5 metro da esfera, deve\nrealizar um teste de resistência de Destreza. A criatura\nsofre 2d6 de dano de fogo se falhar na resistência, ou\nmetade desse dano se obtiver sucesso.\n   Com uma ação bônus, você pode mover a esfera até 9\nmetros. Se você arremessar a esfera contra uma criatura,\nessa criatura deve realizar o teste de resistência contra o\ndano da esfera e a esfera para de se mover esse turno.\n   Quando você move a esfera, você pode direciona-la\npara barreira de até 1,5 metro de altura e ela salta sobre\nfossos de até 3 metros de distância. A esfera incendeia\nobjetos inflamáveis que não estejam sendo vestidos ou\ncarregados e emite luz plena a 6 metros de raio e\npenumbra por mais 6 metros adicionais.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 3° nível ou\nsuperior, o dano aumenta em 1d6 para cada nível do\nespaço acima do 2°."},{"id":"esquentar-metal","name":"Esquentar Metal","level":2,"school":"transmutação","ritual":false,"classes":["bardo","druida"],"pdfPage":244,"time":"1 ação","range":"18 metros","components":"V, S, M (um pedaço de ferro e uma chama)","duration":"Concentração, até 1 minuto","concentration":true,"text":"2° nível de transmutação\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, S, M (um pedaço de ferro e uma\n   chama)\nDuração: Concentração, até 1 minuto\nEscolha uma objeto manufaturado de metal, como uma\narma de metal ou uma armadura pesada ou média de\nmetal, que você possa ver dentro do alcance. Você faz com\nque o objeto brilhe vermelho-incandescente. Qualquer\ncriatura em contato físico com o objeto sofrerá 2d8 de\ndano de fogo quando você conjurar a magia. Até a magia\nacabar, você pode usar uma ação bônus, em cada um dos\nseus turnos subsequentes, para causar esse dano\nnovamente.\n    Se uma criatura estiver segurando ou vestindo o objeto\ne sofrer o dano dele, a criatura deve ser bem sucedida\nnum teste de resistência de Constituição ou largará o\nobjeto se ela puder. Se ela não largar o objeto, ela terá\ndesvantagem em jogadas de ataque e testes de habilidade\naté o início do seu próximo turno.\n    Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 3° nível ou\nsuperior, o dano aumenta em 1d8 para cada nível do\nespaço acima do 2°."},{"id":"flecha-acida-de-melf","name":"Flecha Ácida de Melf","level":2,"school":"evocação","ritual":false,"classes":["mago"],"pdfPage":245,"time":"1 ação","range":"36 metros","components":"V, S, M (folha de ruibarbo em pó e o estômago de uma víbora)","duration":"Instantânea","concentration":false,"text":"2° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: 36 metros\nComponentes: V, S, M (folha de ruibarbo em pó e o\n   estômago de uma víbora)\nDuração: Instantânea\nUma flecha esverdeada cintilante voa em direção de um\nalvo dentro do alcance e explode em um jato de ácido.\nFaça um ataque à distância com magia contra o alvo. Se\natingir, o alvo sofre 4d4 de dano de ácido imediatamente e\n2d4 de dano de ácido no final do próximo turno dele. Se\nerrar, a flecha salpica o alvo com ácido, causando metade\ndo dano inicial e nenhum dano no final do próximo turno\ndele.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 3° nível ou\nsuperior, o dano (tanto inicial quanto posterior) aumenta\nem 1d4 para cada nível do espaço acima do 2°."},{"id":"forca-fantasmagorica","name":"Força Fantasmagórica","level":2,"school":"ilusão","ritual":false,"classes":["bardo","feiticeiro","mago"],"pdfPage":245,"time":"1 ação","range":"18 metros","components":"V, S, M (um pouco de lã)","duration":"Concentração, até 1 minuto","concentration":true,"text":"2° nível de ilusão\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, S, M (um pouco de lã)\nDuração: Concentração, até 1 minuto\nVocê constrói uma ilusão que se enraíza na mente de uma\ncriatura que você possa ver, dentro do alcance. O alvo\ndeve realizar um teste de resistência de Inteligência. Se\nfalhar na resistência, você cria um objeto, criatura ou\noutro fenômeno visível – porém, fantasmagórico – à sua\nescolha, com não mais de 3 metros cúbicos e que será\npercebido apenas pelo alvo, pela duração. Essa magia não\nafeta mortos-vivos ou constructos.\n    O fantasma inclui som, temperatura e outros\nestímulos, também evidentes apenas para o alvo.\n    O alvo pode usar sua ação para examinar o fantasma\ncom um teste de Inteligência (Investigação) contra a CD\nda as magia. Se for bem sucedido, o alvo percebe que o\nfantasma é uma ilusão e a magia acaba.\n    Enquanto o alvo estiver sob efeito dessa magia, ele\nconsiderará o fantasma como sendo real. O alvo\nracionalizará quaisquer resultados ilógicos ao interagir\ncom o fantasma. Por exemplo, um alvo tentado atravessar\numa ponte fantasmagórica que atravesse um abismo,\ncairá quando pisar na ponte. Se o alvo sobreviver a queda,\nele ainda acreditará que a ponte existe e procurará outra\nexplicação para a sua queda – ele foi puxado, ele\nescorregou ou um vento forte pode ter o jogado pra fora.\n    Um alvo afetado está tão convencido da realidade do\nfantasma que pode até mesmo sofrer dano da ilusão. Um\nfantasma criado para se parecer com uma criatura pode\natacar o alvo. Similarmente, um fantasma criado para se\nparecer com fogo, um poço de ácido ou lava, podem\nqueimar o alvo. A cada rodada, no seu turno, o fantasma\npode causar 1d6 de dano psíquico no alvo, se ele estiver\nna área do fantasma ou a 1,5 metro dele, considerando\nque a ilusão é de uma criatura ou perigo que,\nlogicamente, possa causar dano, como por atacar. O alvo\nentende o dano como sendo de um tipo apropriado para a\nilusão."},{"id":"imobilizar-pessoa","name":"Imobilizar Pessoa","level":2,"school":"encantamento","ritual":false,"classes":["bardo","bruxo","clerigo","druida","feiticeiro","mago"],"pdfPage":250,"time":"1 ação","range":"18 metros","components":"V, S, M (uma pequena peça de ferro reta)","duration":"Concentração, até 1 minuto","concentration":true,"text":"2° nível de encantamento\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, S, M (uma pequena peça de ferro reta)\nDuração: Concentração, até 1 minuto\nEscolha um humanoide que você possa ver, dentro do\nalcance. O alvo deve ser bem sucedido num teste de\nresistência de Sabedoria ou ficará paralisado pela\nduração. Essa magia não tem efeito em mortos-vivos. No\nfinal de cada um dos turnos dele, o alvo pode realizar\noutro teste de resistência de Sabedoria. Se obtiver\nsucesso, a magia termina no alvo.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 3° nível ou\nsuperior, você pode afetar um humanoide adicional para\ncada nível de magia acima do 2°. Os humanoides devem\nestar a 9 metros entre si para serem afetados."},{"id":"invisibilidade","name":"Invisibilidade","level":2,"school":"ilusão","ritual":false,"classes":["bardo","bruxo","feiticeiro","mago"],"pdfPage":251,"time":"1 ação","range":"Toque","components":"V, S, M (uma pestana envolta em goma- arábica)","duration":"Concentração, até 1 hora","concentration":true,"text":"2° nível de ilusão\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S, M (uma pestana envolta em goma-\n   arábica)\nDuração: Concentração, até 1 hora\nUma criatura que você tocar, se torna invisível até a\nmagia acabar. Qualquer coisa que o alvo esteja vestindo\nou carregando fica invisível enquanto estiver de posse do\nalvo. A magia termina para o alvo caso ele ataque ou\nconjure uma magia.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 3° nível ou\nsuperior, você pode afetar um alvo adicional para cada\nnível do espaço acima do 2°."},{"id":"levitacao","name":"Levitação","level":2,"school":"transmutação","ritual":false,"classes":["feiticeiro","mago"],"pdfPage":252,"time":"1 ação","range":"18 metros","components":"V, S, M (uma pequena presilha de couro ou um pedaço de fio dourado dobrado em forma de copo com uma haste longa em uma extremidade)","duration":"Concentração, até 10 minutos","concentration":true,"text":"2° nível de transmutação\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, S, M (uma pequena presilha de couro\n   ou um pedaço de fio dourado dobrado em forma de\n   copo com uma haste longa em uma extremidade)\nDuração: Concentração, até 10 minutos\nUma criatura ou objeto, à sua escolha, que você possa ver,\ndentro do alcance, ergue-se verticalmente, até 6 metros e\npermanece suspenso lá pela duração. A magia pode\nlevitar um alvo pesando até 250 quilos. Uma criatura\ninvoluntária que for bem sucedida num teste de\nresistência de Constituição não é afetada\n   O alvo pode se mover apenas ao puxar ou empurrar\num objeto fixo ou superfície ao seu alcance (como um\nmuro ou teto), permitindo que ele se mova como se\nestivesse escalando. Você pode mudar a altitude do alvo\nem até 6 metros em ambas as direções no seu turno. Se\nvocê for o alvo, você pode se mover para cima ou para\nbaixo como parte do seu movimento. Do contrário, você\nprecisa usar sua ação para mover o alvo, que deve\npermanecer dentro do alcance da magia.\n   Quando a magia acaba, o alvo flutua suavemente até o\nchão, se ele ainda estiver no ar."},{"id":"localizar-animais-ou-plantas","name":"Localizar Animais ou Plantas","level":2,"school":"adivinhação","ritual":true,"classes":["bardo","druida","patrulheiro"],"pdfPage":252,"time":"1 ação","range":"Pessoal","components":"V, S, M (um pouco de pelo de um cão de caça)","duration":"Instantânea","concentration":false,"text":"2° nível de adivinhação (ritual)\nTempo de Conjuração: 1 ação\nAlcance: Pessoal\nComponentes: V, S, M (um pouco de pelo de um cão de\n   caça)\nDuração: Instantânea\nDescreva ou nomeie um tipo especifico de besta ou planta.\nConcentre-se na voz da natureza ao seu redor, você\ndescobre a direção e distância da criatura ou planta mais\npróxima desse tipo dentro de 7,5 quilômetros, se houver\nalguma presente."},{"id":"localizar-objeto","name":"Localizar Objeto","level":2,"school":"adivinhação","ritual":false,"classes":["bardo","clerigo","druida","mago","paladino","patrulheiro"],"pdfPage":253,"time":"1 ação","range":"Pessoal","components":"V, S, M (um galho bifurcado)","duration":"Concentração, até 10 minutos","concentration":true,"text":"2° nível de adivinhação\nTempo de Conjuração: 1 ação\nAlcance: Pessoal\nComponentes: V, S, M (um galho bifurcado)\nDuração: Concentração, até 10 minutos\nDescreva ou nomeie um objeto que seja familiar a você.\nVocê sente a direção da localização do objeto, contanto\nque o objeto esteja a até 300 metros de você. Se o objeto\nestiver em movimento, você saberá a direção do\nmovimento dele.\n   A magia pode localizar um objeto especifico que você,\ndesde que você já tenha o visto de perto – a até 9 metros –\npelo menos uma vez. Alternativamente, a magia pode\nlocalizar o objeto de um tipo em particular mais próximo,\ncomo certo tipo de vestuário, joia, móvel, ferramenta ou\narma.\n   Essa magia não pode localizar um objeto se qualquer\nespessura de chumbo, até mesmo uma folha fina,\nbloquear o caminho direto entre você e o objeto."},{"id":"lufada-de-vento","name":"Lufada de Vento","level":2,"school":"evocação","ritual":false,"classes":["druida","feiticeiro","mago"],"pdfPage":253,"time":"1 ação","range":"Pessoal (linha de 18 metros)","components":"V, S, M (uma semente de legume)","duration":"Concentração, até 1 minuto","concentration":true,"text":"2° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: Pessoal (linha de 18 metros)\nComponentes: V, S, M (uma semente de legume)\nDuração: Concentração, até 1 minuto\nUma linha de vento forte, com 18 metros de comprimento\ne 3 metros de largura, é soprada de você em uma direção,\nà sua escolha, pela duração da magia. Cada criatura que\ncomeçar seu turno na linha, deve ser bem sucedida num\nteste de resistência de Força ou será empurrada 4,5\nmetros para trás, na direção seguida pela linha. Qualquer\ncriatura na linha deve gastar 3 metros de movimentação\npara cada 1,5 metro que ela se mover enquanto se\naproxima de você.\n    As lufadas dispersam gases ou vapores e apagam\nvelas, tochas e chamas similares desprotegidas na área.\nElas fazem com que chamas protegidas, como as de\nlanternas, vibrem descontroladamente e tenham 50 por\ncento de chance de serem extintas.\n    Com uma ação bônus, em cada um dos seus turnos,\nantes da magia acabar, você pode mudar a direção à qual\na linha é soprada de você."},{"id":"lamina-flamejante","name":"Lâmina Flamejante","level":2,"school":"evocação","ritual":false,"classes":["druida"],"pdfPage":251,"time":"1 ação bônus","range":"Pessoal","components":"V, S, M (folha de sumagre)","duration":"Concentração, até 10 minutos","concentration":true,"text":"2° nível de evocação\nTempo de Conjuração: 1 ação bônus\nAlcance: Pessoal\nComponentes: V, S, M (folha de sumagre)\nDuração: Concentração, até 10 minutos\nVocê evoca uma lâmina ardente em sua mão livre. A\nlâmina é similar em tamanho e formato a uma cimitarra\ne ela permanece pela duração. Se você soltar a lâmina, ela\ndesaparece, mas você pode evocar a lâmina novamente\ncom uma ação bônus.\n    Você pode usar sua ação para realizar ataques corpo-a-\ncorpo com magia com a lâmina ardente. Se atingir, o alvo\nsofrerá 3d6 de dano de fogo.\n    A lâmina flamejante emite luz plena a 3 metros de\nraio e penumbra por mais 3 metros adicionais.\n    Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 4° nível ou\nsuperior, o dano aumenta em 1d6 para cada dois níveis do\nespaço acima do 2°."},{"id":"marca-da-punicao","name":"Marca da Punição","level":2,"school":"evocação","ritual":false,"classes":["paladino"],"pdfPage":255,"time":"1 ação bônus","range":"Pessoal","components":"V","duration":"Concentração, até 1 minuto","concentration":true,"text":"2° nível de evocação\nTempo de Conjuração: 1 ação bônus\nAlcance: Pessoal\nComponentes: V\nDuração: Concentração, até 1 minuto\nDa próxima vez que você atingir uma criatura com um\nataque com arma, antes do fim da magia, a arma cintilará\ncom radiação astral quando você golpear. O ataque causa\n2d6 de dano radiante extra ao alvo, que se torna visível,\nse estava invisível, e o alvo emite penumbra em um raio\nde 1,5 metro e não pode ficar invisível até a magia acabar.\n   Em Níveis Superiores. Se você conjurar essa magia\nusando um espaço de magia de 3° nível ou superior, o\ndano extra aumenta em 1d6 para cada nível do espaço\nacima do 2°."},{"id":"mensageiro-animal","name":"Mensageiro Animal","level":2,"school":"encantamento","ritual":true,"classes":["bardo","druida","patrulheiro"],"pdfPage":256,"time":"1 ação","range":"9 metros","components":"V, S, M (um punhado de comida)","duration":"24 horas","concentration":false,"text":"2° nível de encantamento (ritual)\nTempo de Conjuração: 1 ação\nAlcance: 9 metros\nComponentes: V, S, M (um punhado de comida)\nDuração: 24 horas\nAtravés dessa magia, você usa um animal para entregar\numa mensagem. Escolha uma besta Miúda que você possa\nver dentro do alcance, como um esquilo, um gaio-azul ou\num morcego. Você especifica um local, que você já deve ter\nvisitado, e um remetente com uma descrição geral, como\n“um homem ou mulher vestido em um uniforme da\nguarda da cidade” ou “um anão ruivo vestindo um chapéu\npontudo”. Você também fala uma mensagem com até\nvinte e cindo palavras. A besta alvo viaja pela duração da\nmagia para o local especifico, cobrindo 75 quilômetros em\n24 horas para um mensageiro voador ou 37,5 quilômetros\npara outros animais.\n    Quando o mensageiro chegar, ele entrega sua\nmensagem para a criatura que você descreveu, repetindo\no som da sua voz. O mensageiro fala apenas para uma\ncriatura que tenha uma descrição compatível com a que\nele recebeu. Se o mensageiro não alcançar o destino antes\ndo fim da magia, a mensagem é perdida e a besta faz seu\ncaminho de volta para onde você conjurou a magia.\n    Em Níveis Superiores. Se você conjurar essa magia\nusando um espaço de magia de 3° nível ou superior, a\nduração da magia aumenta em 48 horas para cada nível\ndo espaço acima do 2°."},{"id":"nublar","name":"Nublar","level":2,"school":"ilusão","ritual":false,"classes":["feiticeiro","mago"],"pdfPage":262,"time":"1 ação","range":"Pessoal","components":"V","duration":"Concentração, até 1 minuto","concentration":true,"text":"2° nível de ilusão\nTempo de Conjuração: 1 ação\nAlcance: Pessoal\nComponentes: V\nDuração: Concentração, até 1 minuto\nSeu corpo se torna turvo, mudando e oscilando para todos\nque puderem ver você. Pela duração, qualquer criatura\nterá desvantagem nas jogadas de ataque contra você. Um\natacante é imune a esse efeito se não depender de visão,\ncomo os que tenham percepção às cegas ou os que\npuderem ver através de ilusões, como os com visão\nverdadeira."},{"id":"nuvem-de-adagas","name":"Nuvem de Adagas","level":2,"school":"conjuração","ritual":false,"classes":["bardo","bruxo","feiticeiro","mago"],"pdfPage":263,"time":"1 ação","range":"18 metros","components":"V, S, M (uma lasca de vidro)","duration":"Concentração, até 1 minuto","concentration":true,"text":"2° nível de conjuração\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, S, M (uma lasca de vidro)\nDuração: Concentração, até 1 minuto\nVocê preenche o ar com adagas giratórias num cubo de\n1,5 metro quadrado, centrado em m ponto, à sua escolha,\ndentro do alcance. Uma criatura sofre 4d4 de dano\ncortante quando entra na área da magia pela primeira\nvez no turno dela ou começa seu turno na área.\n    Em Níveis Superiores. Se você conjurar essa magia\nusando um espaço de magia de 3° nível ou superior, o\ndano aumenta em 2d4 para cada nível do espaço acima do\n2°."},{"id":"oracao-curativa","name":"Oração Curativa","level":2,"school":"evocação","ritual":false,"classes":["clerigo"],"pdfPage":264,"time":"10 minutos","range":"9 metros","components":"V","duration":"Instantânea","concentration":false,"text":"2° nível de evocação\nTempo de Conjuração: 10 minutos\nAlcance: 9 metros\nComponentes: V\nDuração: Instantânea\nAté seis criaturas, à sua escolha, que você possa ver,\ndentro do alcance, recuperam uma quantidade de pontos\nde vida igual a 2d8 + seu modificador de habilidade de\nconjuração, cada uma. Essa magia não afeta mortos-vivos\nou constructos.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 3° nível ou\nsuperior, a cura aumenta em 1d8 para cada nível do\nespaço acima do 2°."},{"id":"passo-nebuloso","name":"Passo Nebuloso","level":2,"school":"conjuração","ritual":false,"classes":["bruxo","feiticeiro","mago"],"pdfPage":265,"time":"1 ação bônus","range":"Pessoal","components":"V","duration":"Instantânea","concentration":false,"text":"2° nível de conjuração\nTempo de Conjuração: 1 ação bônus\nAlcance: Pessoal\nComponentes: V\nDuração: Instantânea\nBrevemente envolto por uma neblina prateada, você se\nteletransporta a até 9 metros para um espaço desocupado\nque você possa ver."},{"id":"passos-sem-pegadas","name":"Passos sem Pegadas","level":2,"school":"abjuração","ritual":false,"classes":["druida","patrulheiro"],"pdfPage":266,"time":"1 ação","range":"Pessoal","components":"V, S, M (cinzas de uma folha de visco queimada e um ramo de pinheiro)","duration":"Concentração, até 1 hora","concentration":true,"text":"2° nível de abjuração\nTempo de Conjuração: 1 ação\nAlcance: Pessoal\nComponentes: V, S, M (cinzas de uma folha de visco\n   queimada e um ramo de pinheiro)\nDuração: Concentração, até 1 hora\nUm véu de sombras e silencia irradia de você, encobrindo\nvocê e seus companheiros contra detecção. Pela duração,\ncada criatura, à sua escolha, a até 9 metros de você\n(incluindo você) recebe +10 de bônus em testes de\nDestreza (Furtividade) e não pode ser rastreada, exceto\npor meio mágicos. Uma criatura que receber esse bônus\nnão deixa quaisquer pegadas ou outros vestígios da sua\npassagem."},{"id":"patas-de-aranha","name":"Patas de Aranha","level":2,"school":"transmutação","ritual":false,"classes":["bruxo","feiticeiro","mago"],"pdfPage":266,"time":"1 ação","range":"Toque","components":"V, S, M (uma gota de betume e uma aranha)","duration":"Concentração, até 1 hora","concentration":true,"text":"2° nível de transmutação\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S, M (uma gota de betume e uma\n   aranha)\nDuração: Concentração, até 1 hora\nAté a magia acabar, uma criatura voluntária que você\ntocar, recebe a habilidade de se mover para cima, para\nbaixo e através de superfícies verticais e de cabeça para\nbaixo pelos tetos, enquanto deixa suas mãos livres. O alvo\ntambém ganha deslocamento de escalada igual a seu\ndeslocamento de caminhada."},{"id":"pele-de-arvore","name":"Pele de Árvore","level":2,"school":"transmutação","ritual":false,"classes":["druida","patrulheiro"],"pdfPage":266,"time":"1 ação","range":"Toque","components":"V, S, M (um pedaço de casca de carvalho)","duration":"Concentração, até 1 hora","concentration":true,"text":"2° nível de transmutação\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S, M (um pedaço de casca de carvalho)\nDuração: Concentração, até 1 hora\nVocê toca uma criatura voluntária. Até o fim da magia, a\npele da criatura fica rígida, similar a casca de um\ncarvalho, e a CA do alvo não pode ser inferior a 16,\nindependentemente do tipo de armadura que ela esteja\nvestindo."},{"id":"protecao-contra-veneno","name":"Proteção contra Veneno","level":2,"school":"abjuração","ritual":false,"classes":["clerigo","druida","paladino","patrulheiro"],"pdfPage":270,"time":"1 ação","range":"Toque","components":"V, S","duration":"1 hora","concentration":false,"text":"2° nível de abjuração\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S\nDuração: 1 hora\n\nVocê toca uma criatura. Se ela estiver envenenada, você\nneutraliza o veneno. Se mais de um veneno estiver\nafligindo o alvo, você neutraliza um veneno, que você\nsaiba estar presente, ou neutraliza um aleatório.\n   Pela duração, o alvo terá vantagem em testes de\nresistência para não envenenado e terá resistência a dano\nde veneno."},{"id":"raio-ardente","name":"Raio Ardente","level":2,"school":"evocação","ritual":false,"classes":["feiticeiro","mago"],"pdfPage":271,"time":"1 ação","range":"36 metros","components":"V, S","duration":"Instantânea","concentration":false,"text":"2° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: 36 metros\nComponentes: V, S\nDuração: Instantânea\nVocê cria três raios de fogo e os arremessa em alvos\ndentro do alcance. Você pode arremessa-los em um alvo\nou em vários.\n   Realize um ataque à distância com magia para cada\nraio. Se atingir, o alvo sofrerá 2d6 de dano de fogo.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 3° nível ou\nsuperior, você cria um raio adicional para cada nível do\nespaço acima do 2°."},{"id":"raio-lunar","name":"Raio Lunar","level":2,"school":"evocação","ritual":false,"classes":["druida"],"pdfPage":273,"time":"1 ação","range":"36 metros","components":"V, S, M (várias sementes de qualquer planta lunar e um pedaço de feldspato opalescente)","duration":"Concentração, até 1 minuto","concentration":true,"text":"2° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: 36 metros\nComponentes: V, S, M (várias sementes de qualquer\n   planta lunar e um pedaço de feldspato opalescente)\nDuração: Concentração, até 1 minuto\nUm raio prateado de luz pálida brilha para baixo em um\ncilindro com 1,5 metro de raio e 12 metros de altura,\ncentrado num ponto dentro do alcance. Até a magia\nacabar, penumbra preenche o cilindro.\n    Quando uma criatura entrar na área da magia pela\nprimeira vez em um turno, ou começar seu turno lá, ela é\nengolfada por chamas fantasmagóricas que causam dores\nlancinantes e ela deve realizar um teste de resistência de\nConstituição. Ela sofre 2d10 de dano radiante se falhar\nna resistência ou metade desse dano se passar.\n    Um metamorfo faz seu teste de resistência com\ndesvantagem. Se ele falhar, ele, também, reverte\ninstantaneamente para sua forma original e não pode\nassumir uma forma diferente até deixar a luz da magia.\n    Em cada um dos seus turnos após conjurar essa\nmagia, você pode usar uma ação para mover o raio 18\nmetros em qualquer direção.\n    Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 3° nível ou\nsuperior, o dano aumenta em 1d10 para cada nível do\nespaço acima do 2°."},{"id":"raio-do-enfraquecimento","name":"Raio do Enfraquecimento","level":2,"school":"necromancia","ritual":false,"classes":["bruxo","mago"],"pdfPage":272,"time":"1 ação","range":"18 metros","components":"V, S","duration":"Concentração, até 1 minuto","concentration":true,"text":"2° nível de necromancia\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, S\nDuração: Concentração, até 1 minuto\nUm raio negro de energia enervante parte do seu dedo em\ndireção de uma criatura, dentro do alcance. Faça um\nataque à distância com magia contra o alvo. Se atingir, o\nalvo causará metade do dano com ataques com armas que\nusem Força, até a magia acabar.\n   No final de cada um dos turnos do alvo, ele pode\nrealizar um teste de resistência de Constituição contra a\nmagia. Se obtiver sucesso, a magia acaba."},{"id":"reflexos","name":"Reflexos","level":2,"school":"ilusão","ritual":false,"classes":["bruxo","feiticeiro","mago"],"pdfPage":275,"time":"1 ação","range":"Pessoal","components":"V, S","duration":"1 minuto","concentration":false,"text":"2° nível de ilusão\nTempo de Conjuração: 1 ação\nAlcance: Pessoal\nComponentes: V, S\nDuração: 1 minuto\nTrês duplicatas ilusórias de você aparecem no seu espaço.\nAté a magia acabar, as duplicatas se movem com você e\ncopiam as suas ações, trocando de posição, tornando\nimpossível rastrear qual imagem é real. Você pode usar\nsua ação para dissipar as duplicatas ilusórias.\n   Cada vez que uma criatura mirar você com um ataque\nenquanto a magia durar, role um d20 para determinar se\no ataque, em vez de você, mira uma das suas duplicatas.\n   Se você tiver três duplicatas, você deve rolar um 6 ou\nmaior para mudar o alvo do ataque para uma duplicata.\nCom duas duplicatas, você deve rolar um 8 ou maior. Com\numa duplicata, você deve rolar um 11 ou maior.\n   A CA de uma duplicata é igual a 10 + seu modificador\nde Destreza. Se um ataque atingir uma duplicata, ela é\ndestruída. Uma duplicata só pode ser destruída por um\nataque que a atinja. Ela ignora todos os outros danos e\nefeitos. A magia acaba quando todas as três duplicatas\nforem destruídas.\n   Uma criatura não pode ser afetada por essa magia se\nnão puder enxergar, se ela contar com outros sentidos\nalém da visão, como percepção às cegas, ou se ela puder\nperceber ilusões como falsas, como com visão verdadeira."},{"id":"repouso-tranquilo","name":"Repouso Tranquilo","level":2,"school":"necromancia","ritual":true,"classes":["clerigo","mago"],"pdfPage":276,"time":"1 ação","range":"Toque","components":"V, S, M (uma pitada de sal e uma peça de cobre colocada em cada um dos olhos do corpo, que devem permanecer ai pela duração)","duration":"10 dias","concentration":false,"text":"2° nível de necromancia (ritual)\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S, M (uma pitada de sal e uma peça de\n   cobre colocada em cada um dos olhos do corpo, que\n   devem permanecer ai pela duração)\nDuração: 10 dias\nVocê toca um corpo ou outros restos mortais. Pela\nduração, o alvo estará protegido de decomposição e não\npode se tornar um morto-vivo.\n   A magia também estende, efetivamente, o limite de\ntempo para que o alvo seja trazido de volta a vida, já que\nos dias passados sob a influência dessa magia não contam\nno tempo limite de tais magias, como reviver os mortos."},{"id":"restauracao-menor","name":"Restauração Menor","level":2,"school":"abjuração","ritual":false,"classes":["bardo","clerigo","druida","paladino","patrulheiro"],"pdfPage":277,"time":"1 ação","range":"Toque","components":"V, S","duration":"Instantânea","concentration":false,"text":"2° nível de abjuração\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S\nDuração: Instantânea\nVocê toca uma criatura e pode, ou acabar com uma\ndoença ou uma condição que a esteja afligindo. A condição\npode ser cega, surda, paralisada ou envenenada."},{"id":"sentido-bestial","name":"Sentido Bestial","level":2,"school":"adivinhação","ritual":true,"classes":["druida","patrulheiro"],"pdfPage":279,"time":"1 ação","range":"Toque","components":"S","duration":"Concentração, até 1 hora","concentration":true,"text":"2° nível de adivinhação (ritual)\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: S\nDuração: Concentração, até 1 hora\nVocê toca uma besta voluntária. Pela duração da magia,\nvocê pode usar sua ação para ver através dos olhos e ouvir\natravés dos ouvidos da besta e continua a fazê-lo até você\nusar sua ação para retornar aos seus sentidos normais.\n   Enquanto estiver utilizando os sentidos da besta, você\nganha os benefícios de qualquer sentido especial possuído\npela criatura, no entanto, você estará cego e surdo em\nrelação aos seus próprios sentidos."},{"id":"silencio","name":"Silêncio","level":2,"school":"ilusão","ritual":true,"classes":["bardo","clerigo","patrulheiro"],"pdfPage":279,"time":"1 ação","range":"36 metros","components":"V, S","duration":"Concentração, até 10 minutos","concentration":true,"text":"2° nível de ilusão (ritual)\nTempo de Conjuração: 1 ação\nAlcance: 36 metros\nComponentes: V, S\nDuração: Concentração, até 10 minutos\nPela duração, nenhum som pode ser criado dentro ou\natravessar uma esfera de 6 metros de raio centrada num\nponto, à sua escolha, dentro do alcance. Qualquer criatura\nou objeto totalmente dentro da esfera é imune a dano\ntrovejante e as criaturas estarão surdas enquanto\nestiverem completamente dentro dela. Conjurar magias\nque inclua a componente verbal é impossível ai."},{"id":"sugestao","name":"Sugestão","level":2,"school":"encantamento","ritual":false,"classes":["bardo","bruxo","feiticeiro","mago"],"pdfPage":281,"time":"1 ação","range":"9 metros","components":"V, M (uma língua de cobra e, ou um pedaço de favo de mel ou uma gota de azeite doce)","duration":"Concentração, até 8 horas","concentration":true,"text":"2° nível de encantamento\nTempo de Conjuração: 1 ação\nAlcance: 9 metros\nComponentes: V, M (uma língua de cobra e, ou um\n   pedaço de favo de mel ou uma gota de azeite doce)\nDuração: Concentração, até 8 horas\nVocê sugere um curso de atividade (limitado a uma ou\nduas sentenças) e, magicamente, influencia um criatura\nque você possa ver, dentro do alcance, e que possa ouvir e\ncompreender você. Criaturas que não podem ser\nenfeitiçadas são imunes a esse efeito. A sugestão deve ser\nformulada de modo que o curso de ação soe razoável.\nDizer para a criatura se esfaquear, se arremessar em\numa lança, tocar fogo em si mesma ou fazer algum outro\nato obviamente nocivo anulará o efeito da magia.\n   O alvo deve realizar um teste de resistência de\nSabedoria. Se falhar na resistência, ele seguirá o curso de\nação que você descreveu, da melhor forma possível. O\ncurso de ação sugerido pode continuar por toda a duração.\nSe a atividade sugerida puder ser completada em um\ntempo menor, a magia termina quando o alvo completar o\nque lhe foi dito para que fizesse.\n   Você pode, também, especificar condições que irão\nativar uma atividade especial pela duração. Por exemplo,\nvocê poderia sugerir a um cavaleiro que entregasse seu\ncavalo de guerra ao primeiro mendigo que ele encontrar.\nSe a condição não for satisfeita antes da magia expirar, a\natividade não será concluída.\nSe você ou um dos seus companheiros causar dano a uma\n   criatura afetada por essa magia, a magia termina."},{"id":"teia","name":"Teia","level":2,"school":"conjuração","ritual":false,"classes":["feiticeiro","mago"],"pdfPage":282,"time":"1 ação","range":"18 metros","components":"V, S, M (um pedaço de teia de aranha)","duration":"Concentração, até 1 hora","concentration":true,"text":"2° nível de conjuração\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, S, M (um pedaço de teia de aranha)\nDuração: Concentração, até 1 hora\nVocê conjura uma massa de teias espessas e pegajosas\nnum ponto, à sua escolha, dentro do alcance. As teias\npreenchem um cubo de 6 metros naquele ponto, pela\nduração. As teias são terreno difícil e causam escuridão\nleve na área delas.\n    Se as teias não estiverem sendo suportadas por duas\nmassas sólidas (como duas paredes ou árvores) ou em\ncamadas sobre um chão, parede ou teto, a teia conjurada\ndesaba sobre si mesma e a magia termina no início do seu\npróximo turno. As teias em camadas sobre uma superfície\nplana terão 1,5 metro de profundidade.\n    Cada criatura que começar seu turno nas teias ou\nentrar nelas durante seu turno, deve realizar um teste de\nresistência de Destreza. Se falhar na resistência, a\ncriatura estará impedida enquanto permanecer nas teias\nou até se libertar.\n    Uma criatura impedida pelas teias pode usar sua ação\npara realizar um teste de Força contra a CD da magia. Se\nobtiver sucesso, ela não estará mais impedida.\n    As teias são inflamáveis. Qualquer cubo de 1,5 metro\nde teia exposto ao fogo, é consumida por ele em 1 rodada,\ncausando 2d4 de dano de fogo a qualquer criatura que\ncomeçar seu turno nas chamas."},{"id":"tranca-arcana","name":"Tranca Arcana","level":2,"school":"abjuração","ritual":false,"classes":["mago"],"pdfPage":286,"time":"1 ação","range":"Toque","components":"V, S, M (pó de ouro valendo, no mínimo, 25 po, consumido pela magia)","duration":"Até ser dissipada","concentration":false,"text":"2° nível de abjuração\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S, M (pó de ouro valendo, no mínimo,\n25 po, consumido pela magia)\nDuração: Até ser dissipada\nVocê toca uma porta, janela, portão, baú ou outra entrada\nfechada e ela ficará trancada pela duração. Você e as\ncriaturas que você designar, quando você conjurar essa\nmagia, podem abrir o objeto normalmente. Você também\npode definir uma senha que, quando falada a 1,5 metro do\nobjeto, suprime a magia por 1 minuto. De outra forma, ele\né intransponível até ser quebrado ou a magia seja\ndissipada ou suprimida. Conjurar arrombar no objeto\nsuprime a tranca arcana por 10 minutos.\n    Enquanto estiver sob efeito dessa magia, o objeto é\nmais difícil de quebrar ou de forçar para abrir; a CD para\nquebra-lo ou de arromba-lo aumenta em 10."},{"id":"truque-de-corda","name":"Truque de Corda","level":2,"school":"transmutação","ritual":false,"classes":["mago"],"pdfPage":286,"time":"1 ação","range":"Toque","components":"V, S, M (pó de extrato de milho e um laço de pergaminho trançado)","duration":"1 hora","concentration":false,"text":"2° nível de transmutação\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S, M (pó de extrato de milho e um laço\n   de pergaminho trançado)\nDuração: 1 hora\nVocê toca um pedaço de corda que tenha até 18 metros de\ncomprimento. Uma ponta da corda então, se ergue no ar\naté toda a corda estar erguida e perpendicular ao solo. Na\nponta de cima da corda, uma entrada invisível se abre\npara um espaço extradimensional que permanece até a\nmagia acabar.\n    O espaço extradimensional pode ser alcançado\nescalando a corda até o topo. O espaço pode abrigar até\noito criaturas Médias ou menores. A corda pode ser\npuxada para dentro do buraco, fazendo-a desaparecer\npara os observadores do lado de fora do espaço.\n    Ataques e magias não podem ultrapassar a entrada,\nentrando ou saindo do espaço extradimensional, mas\nquem está dentro pode ver o lado de fora, como se\nestivesse olhando por uma janela de 0,9 metro por 1,5\nmetro, centrada na corda.\n    Tudo que estiver dentro do espaço extradimensional\ncai quando a magia acabar."},{"id":"ver-o-invisivel","name":"Ver o Invisível","level":2,"school":"adivinhação","ritual":false,"classes":["bardo","feiticeiro","mago"],"pdfPage":287,"time":"1 ação","range":"Pessoal","components":"V, S, M (um pouco de talco e um pó de prata polvilhado)","duration":"1 hora","concentration":false,"text":"2° nível de adivinhação\nTempo de Conjuração: 1 ação\nAlcance: Pessoal\nComponentes: V, S, M (um pouco de talco e um pó de\n   prata polvilhado)\nDuração: 1 hora\nPela duração, você vê criaturas e objetos invisíveis como\nse eles fossem visíveis e você pode ver no Plano Etéreo.\nCriaturas e objetos etéreos parecem espectrais e\ntranslúcidos."},{"id":"visao-no-escuro","name":"Visão no Escuro","level":2,"school":"transmutação","ritual":false,"classes":["druida","feiticeiro","mago","patrulheiro"],"pdfPage":288,"time":"1 ação","range":"Toque","components":"V, S, M (ou um pedaço de cenoura seca ou uma ágata)","duration":"8 horas","concentration":false,"text":"2° nível de transmutação\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S, M (ou um pedaço de cenoura seca\n   ou uma ágata)\nDuração: 8 horas\nVocê toca uma criatura voluntária para conceder a ela a\nhabilidade de ver nas trevas. Pela duração, a criatura\nterá visão no escuro com alcance de 18 metros."},{"id":"vinculo-protetor","name":"Vínculo Protetor","level":2,"school":"abjuração","ritual":false,"classes":["clerigo"],"pdfPage":287,"time":"1 ação","range":"Toque","components":"V, S, M (um par de anéis de platina valendo, no mínimo, 50 po cada, que você e o alvo devem usar pela duração)","duration":"1 hora","concentration":false,"text":"2° nível de abjuração\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S, M (um par de anéis de platina\n   valendo, no mínimo, 50 po cada, que você e o alvo\n   devem usar pela duração)\nDuração: 1 hora\nEssa magia protege uma criatura voluntária que você\ntocar e cria uma conexão mística entre você e o alvo até a\nmagia acabar. Enquanto o alvo estiver a até 18 metros de\nvocê, ele recebe +1 de bônus na CA, nos testes de\nresistência e terá resistência a todos os danos. No\nentanto, a cada vez que ele sofrer dano, você sofrerá a\nmesma quantidade de dano.\n   A magia acaba se você cair a 0 pontos de vida ou se\nvocê e o alvo ficarem separados a mais de 18 metros. Ela\ntambém termina se a magia for conjurada novamente em\nquaisquer das criaturas conectadas. Você também pode\ndissipar a magia com uma ação."},{"id":"zona-da-verdade","name":"Zona da Verdade","level":2,"school":"encantamento","ritual":false,"classes":["bardo","clerigo","paladino"],"pdfPage":288,"time":"1 ação","range":"18 metros","components":"V, S","duration":"10 minutos","concentration":false,"text":"2° nível de encantamento\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, S\nDuração: 10 minutos\nVocê cria uma zona mágica protegida contra enganação,\nnuma esfera com 4,5 metros de raio, centrada num ponto,\nà sua escolha, dentro do alcance. Até a magia acabar,\numa criatura que entrar na área da magia pela primeira\nvez num turno ou começar seu turno nela, deve realizar\num teste de resistência de Carisma. Se falhar na\nresistência, a criatura não poderá mentir\ndeliberadamente enquanto estiver no raio. Você saberá\ncada criatura que passou ou falhou nesse teste de\nresistência.\n    Uma criatura afetada está ciente da magia e pode,\nportanto, evitar responder perguntas as quais ela\nnormalmente responderia com uma mentira. Tais\ncriaturas podem ser evasivas em suas respostas, contanto\nque permaneçam dentro dos limites da verdade."},{"id":"ampliar-plantas","name":"Ampliar Plantas","level":3,"school":"transmutação","ritual":false,"classes":["bardo","druida","patrulheiro"],"pdfPage":215,"time":"1 ação ou 8 horas","range":"45 metros","components":"V, S","duration":"Instantânea","concentration":false,"text":"3° nível de transmutação\nTempo de Conjuração: 1 ação ou 8 horas\nAlcance: 45 metros\nComponentes: V, S\nDuração: Instantânea\nEssa magia canaliza vitalidade nas plantas dentro de\numa área especifica. Existem dois usos possíveis para\nessa magia, concedendo ou benefícios imediatos ou a\nlongo prazo.\n    Se você conjurar essa magia usando 1 ação, escolha\num ponto dentro do alcance. Todas as plantas normais\nnum raio de 30 metros centrado no ponto, tornam-se\nespessas e carregadas. Uma criatura se movendo na área\ndeve gastar 6 metros de movimento para cada 1,5 metro\nque se mover.\n    Você pode excluir uma ou mais áreas de qualquer\ntamanho, dentro da área da magia, para não ser afetada.\n    Se você conjurar essa magia ao longo de 8 horas, você\nfertiliza a terra. Todas as plantas num raio de 800\nmetros, centrado no ponto dentro do alcance, ficam\nenriquecidas por 1 ano. As plantas fornecerão o dobro da\nquantidade normal de comida quando colhidas."},{"id":"andar-na-agua","name":"Andar na Água","level":3,"school":"transmutação","ritual":true,"classes":["clerigo","druida","feiticeiro","patrulheiro"],"pdfPage":215,"time":"1 ação","range":"9 metros","components":"V, S, M (uma rolha)","duration":"1 hora","concentration":false,"text":"3° nível de transmutação (ritual)\nTempo de Conjuração: 1 ação\nAlcance: 9 metros\nComponentes: V, S, M (uma rolha)\nDuração: 1 hora\nEssa magia concede a habilidade de se mover através de\nqualquer superfície líquida – como água, ácido, lama,\nneve, arreia movediça ou lava – como se ela fosse chão\nsólido inofensivo (as criaturas atravessando lava\nderretida ainda podem sofrer dano do calor). Até dez\ncriaturas voluntárias que você possa ver, dentro do\nalcance, ganham essa habilidade pela duração.\n    Se você afetar uma criatura submersa em um líquido,\na magia ergue o alvo para a superfície do líquido a uma\ntaxa de 18 metros por rodada."},{"id":"animar-mortos","name":"Animar mortos","level":3,"school":"necromancia","ritual":false,"classes":["clerigo","mago"],"pdfPage":215,"time":"1 minuto","range":"3 metros","components":"V, S, M (uma gota de sangue, um pedaço de carne e uma punhado de pó de osso)","duration":"Instantânea","concentration":false,"text":"3° nível de necromancia\nTempo de Conjuração: 1 minuto\nAlcance: 3 metros\nComponentes: V, S, M (uma gota de sangue, um pedaço\n   de carne e uma punhado de pó de osso)\nDuração: Instantânea\nEssa magia cria um servo morto-vivo. Escolha uma pilha\nde ossos ou um corpo de um humanoide Médio ou\nPequeno dentro do alcance. Sua magia imbui o alvo com\numa imitação corrompida de vida, erguendo-o como uma\ncriatura morta-viva. O alvo se torna um esqueleto, se você\nescolheu ossos, ou um zumbi, se você escolheu um corpo (o\nMestre tem as estatísticas de jogo da criatura).\n    Em cada um dos seus turnos, você pode usar uma ação\nbônus para comandar mentalmente qualquer criatura que\nvocê criou com essa magia, se a criatura estiver a até 18\nmetros de você (se você controla diversas criaturas, você\npode comandar qualquer uma ou todas elas ao mesmo\ntempo, emitindo o mesmo comando para cada uma). Você\ndecide qual ação a criatura irá fazer e para onde ela irá se\nmover durante o próximo turno dela, ou você pode emitir\num comando geral, como para guardar uma câmara ou\ncorredor especifico. Se você não der nenhum comando, as\ncriaturas apenas se defenderão contra criaturas hostis.\nUma vez que receba uma ordem, a criatura continuará a\nsegui-la até a tarefa estar concluída.\n    A criatura fica sob seu controle por 24 horas, depois\ndisso ela para de obedecer aos seus comandos. Para\n manter o controle da criatura por mais 24 horas, você\n deve conjurar essa magia na criatura novamente, antes\n das 24 horas atuais terminarem. Esse uso da magia\n recupera seu controle sobre até quatro criaturas que você\n tenha animado com essa magia, ao invés de animar uma\n nova.\n    Em Níveis Superiores. Quando você conjurar essa\n magia usando um espaço de magia de 4° nível ou\n superior, você pode animar ou recuperar o controle de\n duas criaturas mortas-vivas para cada nível do espaço\n acima do 3°. Cada uma dessas criaturas deve vir de um\n corpo ou pilha de ossos diferente."},{"id":"arma-elemental","name":"Arma Elemental","level":3,"school":"transmutação","ritual":false,"classes":["paladino"],"pdfPage":218,"time":"1 ação","range":"Toque","components":"V, S","duration":"Concentração, até 1 hora","concentration":true,"text":"3° nível de transmutação\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S\nDuração: Concentração, até 1 hora\nUma arma não-mágica que você tocar se torna uma arma\nmágica. Escolha um dos tipos de dano a seguir: ácido,\nelétrico, frio, fogo ou trovejante. Pela duração, a arma tem\n+1 de bônus nas jogadas de ataque e causa 1d4 de dano\nextra, do tipo de elemento escolhido, ao atingir.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 5° ou 6° nível, o\nbônus nas jogadas de ataque aumenta pra +2 e o dano\nextra aumenta para 2d4. Quando você usar um espaço de\nmagia de 7° nível ou superior, o bônus aumenta para +3 e\no dano extra aumenta para 3d4."},{"id":"aura-de-vitalidade","name":"Aura de Vitalidade","level":3,"school":"evocação","ritual":false,"classes":["paladino"],"pdfPage":220,"time":"1 ação","range":"Pessoal (9 metros de raio)","components":"V","duration":"Concentração, até 1 minuto","concentration":true,"text":"3° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: Pessoal (9 metros de raio)\nComponentes: V\nDuração: Concentração, até 1 minuto\nEnergia curativa irradia de você em uma aura com 9\nmetros de raio. Até a magia acabar, a aura se move\nmantendo-se centrada em você. Você pode usar uma ação\nbônus para fazer com que uma criatura na aura\n(incluindo você) recupere 2d6 pontos de vida."},{"id":"bola-de-fogo","name":"Bola de Fogo","level":3,"school":"evocação","ritual":false,"classes":["feiticeiro","mago"],"pdfPage":221,"time":"1 ação","range":"45 metros","components":"V, S, M (uma minúscula bola de guano de morcego e enxofre)","duration":"Instantânea","concentration":false,"text":"3° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: 45 metros\nComponentes: V, S, M (uma minúscula bola de guano de\n   morcego e enxofre)\nDuração: Instantânea\nUm veio brilhante lampeja na ponta do seu dedo em\ndireção a um ponto que você escolher, dentro do alcance, e\nentão eclode com um estampido baixo, explodindo em\nchamas. Cada criatura em uma esfera de 6 metros de\nraio, centrada no ponto, deve realizar um teste de\nresistência de Destreza. Um alvo sofre 8d6 de dano de\nfogo se falhar na resistência, ou metade desse dano se\nobtiver sucesso.\n   O fogo se espalha, dobrando esquinas. Ele incendeia\nobjetos inflamáveis na área que não estejam sendo\nvestidos ou carregados.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 4° nível ou\nsuperior, o dano aumenta em 1d6 para cada nível do\nespaço acima do 3°."},{"id":"clarividencia","name":"Clarividência","level":3,"school":"adivinhação","ritual":false,"classes":["bardo","clerigo","feiticeiro","mago"],"pdfPage":225,"time":"10 minutos","range":"1,5 quilômetro","components":"V, S, M (um foco valendo, no mínimo, 100 po, também um chifre cravejado de joias para ouvir ou um olho de vidro para ver)","duration":"Concentração, até 10 minutos","concentration":true,"text":"3° nível de adivinhação\nTempo de Conjuração: 10 minutos\nAlcance: 1,5 quilômetro\nComponentes: V, S, M (um foco valendo, no mínimo, 100\n   po, também um chifre cravejado de joias para ouvir ou\n   um olho de vidro para ver)\nDuração: Concentração, até 10 minutos\nVocê cria um sensor invisível, dentro do alcance, em um\nlocal familiar a você (um local que você tenha visitado ou\nvisto antes) ou em um local obvio que não seja familiar a\nvocê (como atrás de uma porta, ao redor de um canto ou\nem um bosque de árvores). O sensor se mantem no local\npela duração e não pode ser atacado ou manipulado de\noutra forma.\n    Quando você conjurar essa magia, escolhe visão ou\naudição. Você pode escolher sentir através do sensor como\nse você estivesse no espaço dele. Com sua ação, você pode\ntrocar entre visão e audição.\n    Uma criatura que puder ver o sensor (como uma\ncriatura beneficiada por ver o invisível ou visão\nverdadeira) vê um globo luminoso e intangível do\ntamanho do seu olho."},{"id":"conjurar-animais","name":"Conjurar Animais","level":3,"school":"conjuração","ritual":false,"classes":["druida","patrulheiro"],"pdfPage":228,"time":"1 ação","range":"18 metros","components":"V, S","duration":"Concentração, até 1 hora","concentration":true,"text":"3° nível de conjuração\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, S\nDuração: Concentração, até 1 hora\nVocê invoca espíritos feéricos, que assumem formas de\nbestas, que aparecem em espaços desocupados, que você\npossa ver dentro do alcance. Escolha uma das opções a\nseguir para aparecer:\n   Uma besta de nível de desafio 2 ou inferior\n   Duas bestas de nível de desafio 1 ou inferior\n   Quatro bestas de nível de desafio 1/2 ou inferior\n   Oito bestas de nível de desafio 1/4 ou inferior\n   Cada besta é também considerada uma fada e\ndesaparece quando cair a 0 pontos de vida ou quando a\nmagia acabar.\n    As criaturas invocadas são amigáveis a você e a seus\ncompanheiros. Role a iniciativa para as criaturas\ninvocadas como um grupo, que age no seu próprio turno.\nEles obedecem a quaisquer comandos verbais que você\nemitir (não requer uma ação sua). Se você não emitir\nnenhum comando a elas, elas se defenderão de criaturas\nhostis, mas no mais, não realizarão nenhuma ação.\n    O Mestre possui as estatísticas das criaturas.\n    Em Níveis Superiores. Se você conjurar essa magia\nusando certos espaços de magia superiores, você escolhe\numa das opções de invocação acima e mais criaturas\naparecem: o dobro delas com um espaço de 5° nível, o\ntriplo delas com um espaço de 7° nível e o quadruplo delas\ncom um espaço de 9° nível."},{"id":"conjurar-rajada","name":"Conjurar Rajada","level":3,"school":"conjuração","ritual":false,"classes":["patrulheiro"],"pdfPage":229,"time":"1 ação","range":"Pessoal (cone de 18 metros)","components":"V, S, M (uma munição ou arma de arremesso)","duration":"Instantânea","concentration":false,"text":"3° nível de conjuração\nTempo de Conjuração: 1 ação\nAlcance: Pessoal (cone de 18 metros)\nComponentes: V, S, M (uma munição ou arma de\n   arremesso)\nDuração: Instantânea\nVocê arremessa uma arma não-mágica ou dispara uma\nmunição não-mágica no ar para criar um cone de armas\nidênticas que se lançam a frente e então desaparecem.\nCada criatura num cone de 18 metros, deve ser bem\nsucedida num teste de resistência de Destreza. Uma\ncriatura sofre 3d8 de dano se falhar na resistência, ou\nmetade desse dano num sucesso. O tipo do dano é o\nmesmo da arma ou munição usada como componente."},{"id":"contramagica","name":"Contramágica","level":3,"school":"bjuração","ritual":false,"classes":["bruxo","feiticeiro","mago"],"pdfPage":230,"time":"1 reação, que você realiza quando vê uma criatura a até 18 metros conjurando uma magia","range":"18 metros","components":"S","duration":"Instantânea","concentration":false,"text":"3° nível de abjuração\nTempo de Conjuração: 1 reação, que você realiza\n   quando vê uma criatura a até 18 metros conjurando\n   uma magia\nAlcance: 18 metros\nComponentes: S\nDuração: Instantânea\nVocê tenta interromper uma criatura no processo de\nconjuração de uma magia. Se a criatura estiver\nconjurando uma magia de 3° nível ou inferior, a magia\nfalha e não gera nenhum efeito. Se ela estiver conjurando\numa magia de 4° nível ou superior, faça um teste de\nhabilidade usando sua habilidade de conjuração. A CD é\nigual a 10 + o nível da magia. Caso seja bem sucedido, a\nmagia da criatura falha e não gera nenhum efeito.\n   Em Níveis Superiores. Se você conjurar essa magia\nusando um espaço de magia de 4° nível ou superior, a\nmagia interrompida não vai gerar efeito se o nível dela for\nmenor ou igual ao nível do espaço de magia que você usar."},{"id":"convocar-relampagos","name":"Convocar Relâmpagos","level":3,"school":"conjuração","ritual":false,"classes":["druida"],"pdfPage":232,"time":"1 ação","range":"36 metros","components":"V, S","duration":"Concentração, até 10 minutos","concentration":true,"text":"3° nível de conjuração\nTempo de Conjuração: 1 ação\nAlcance: 36 metros\nComponentes: V, S\nDuração: Concentração, até 10 minutos\nUma nuvem tempestuosa aparece em formato cilíndrico\ncom 3 metros de altura e 18 metros de raio, centrada num\nponto que você possa ver, 30 metros acima de você. A\nmagia falha se você não puder ver um ponto no ar em que\na nuvem possa aparecer (por exemplo, se você estiver em\numa sala que não possa comportar a nuvem).\n   Quando você conjurar a magia, escolha um ponto que\nvocê possa ver dentro do alcance. Um raio de eletricidade\né disparado da nuvem no ponto. Cada criatura a 1,5\nmetro desse ponto deve realizar um teste de resistência\nde Destreza. Uma criatura sofre 3d10 de dano elétrico se\nfalhar no teste, ou metade desse dano se passar. Em cada\num dos seus turnos, até a magia acabar, você pode usar\nsua ação para convocar um relâmpago dessa forma\nnovamente, afetando o mesmo ponto ou um diferente.\n   Se você estiver a céu aberto em condições\ntempestuosas quando conjurar essa magia, a magia lhe\ndá controle sobre a tempestade existente ao invés de criar\numa nova. Sob tais condições, o dano da magia aumenta\nem 1d10.\n   Em Níveis Superiores. Se você conjurar essa magia\nusando um espaço de magia de 4° nível ou superior, o\ndano aumenta em 1d10 para cada nível do espaço acima\ndo 3°."},{"id":"criar-alimentos","name":"Criar Alimentos","level":3,"school":"conjuração","ritual":false,"classes":["clerigo","paladino"],"pdfPage":233,"time":"1 ação","range":"9 metros","components":"V, S","duration":"Instantânea","concentration":false,"text":"3° nível de conjuração\nTempo de Conjuração: 1 ação\nAlcance: 9 metros\nComponentes: V, S\nDuração: Instantânea\nVocê cria 25 quilos de comida e 100 litros de água no solo\nou em um recipiente dentro do alcance, suficiente para\nsustentar até quinze humanoide ou cinco montarias por\n24 horas. A comida é insossa, porém, nutritiva e estraga\nse não for consumida após 24 horas. A água é limpa e não\nfica ruim."},{"id":"circulo-magico","name":"Círculo Mágico","level":3,"school":"abjuração","ritual":false,"classes":["bruxo","clerigo","mago","paladino"],"pdfPage":225,"time":"1 minuto","range":"3 metros","components":"V, S, M (água benta ou pó de prata e ferro valendo, no mínimo, 100 po, consumidos pela magia)","duration":"1 hora","concentration":false,"text":"3° nível de abjuração\nTempo de Conjuração: 1 minuto\nAlcance: 3 metros\nComponentes: V, S, M (água benta ou pó de prata e\n   ferro valendo, no mínimo, 100 po, consumidos pela\n   magia)\nDuração: 1 hora\nVocê cria um cilindro de energia mágica de 3 metros de\nraio por 6 metros de altura, centrado num ponto no solo\nque você possa ver, dentro do alcance. Runas brilhantes\naparecem toda vez que o cilindro toca o chão ou outra\nsuperfície.\n   Escolha um ou mais dos tipos de criaturas seguintes:\ncelestiais, corruptores, elementais, fadas ou mortos-vivos.\nO círculo afeta uma criatura do tipo escolhido das\nseguintes maneiras:\n   A criatura não consegue entrar no cilindro\n    voluntariamente por meios não-mágicos. Se a criatura\n    tentar usar teletransporte ou viagem interplanar para\n    fazê-lo, ela deve, primeiro, ser bem sucedida num teste\n    de resistência de Carisma.\n   A criatura tem desvantagem nas jogadas de ataque\n    contra alvos dentro do cilindro.\n   Alvos dentro do cilindro não podem ser enfeitiçados,\n    amedrontados ou possuídos pela criatura.\n\n   Quando você conjurar essa magia, você pode decidir\nque a mágica dela opere na direção reversa, prevenindo\nque uma criatura de um tipo especifico saia do cilindro e\nprotegendo os alvos fora dele.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 4° nível ou\nsuperior, a duração aumenta em 1 hora para cada nível\ndo espaço acima do 3°."},{"id":"destruicao-cegante","name":"Destruição Cegante","level":3,"school":"evocação","ritual":false,"classes":["paladino"],"pdfPage":237,"time":"1 ação bônus","range":"Pessoal","components":"V","duration":"Concentração, até 1 minuto","concentration":true,"text":"3° nível de evocação\nTempo de Conjuração: 1 ação bônus\nAlcance: Pessoal\nComponentes: V\nDuração: Concentração, até 1 minuto\nDa próxima vez que você atingir uma criatura com um\nataque com arma, antes do fim da magia, sua arma emite\numa luz intensa, e o ataque causa 3d8 de dano radiante\nextra ao alvo. Além disso, o alvo deve ser bem sucedido\nnum teste de resistência de Constituição ou ficará cego\naté a magia acabar.\n   Uma criatura cega por essa magia realiza outro teste\nde resistência de Constituição no final de cada um dos\nturnos dela. Se obtiver sucesso, não estará mais cega."},{"id":"dificultar-deteccao","name":"Dificultar Detecção","level":3,"school":"abjuração","ritual":false,"classes":["bardo","mago","patrulheiro"],"pdfPage":238,"time":"1 ação","range":"Toque","components":"V, S, M (um pouco de pó de diamante valendo 25 po polvilhado sobre o alvo, consumido pela magia)","duration":"8 horas","concentration":false,"text":"3° nível de abjuração\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S, M (um pouco de pó de diamante\n   valendo 25 po polvilhado sobre o alvo, consumido pela\n   magia)\nDuração: 8 horas\nPela duração, você esconde um alvo que você tocar de\nmagias de adivinhação. O alvo pode ser uma criatura\nvoluntária, um local ou um objeto com não mais de 3\nmetros em qualquer dimensão. O alvo não pode ser alvo\nde magias de adivinhação ou percebido através de\nsensores mágicos de vidência."},{"id":"dissipar-magia","name":"Dissipar Magia","level":3,"school":"abjuração","ritual":false,"classes":["bardo","bruxo","clerigo","druida","feiticeiro","mago","paladino"],"pdfPage":238,"time":"1 ação","range":"36 metros","components":"V, S","duration":"Instantânea","concentration":false,"text":"3° nível de abjuração\nTempo de Conjuração: 1 ação\nAlcance: 36 metros\nComponentes: V, S\nDuração: Instantânea\nEscolha uma criatura, objeto ou efeito mágico dentro do\nalcance. Qualquer magia de 3° nível ou inferior no alvo,\ntermina. Para cada magia de 4° nível ou superior no alvo,\nrealize um teste de habilidade usando sua habilidade de\nconjuração. A CD é igual a 10 + o nível da magia. Se\nobtiver sucesso, a magia termina.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 4° nível ou\nsuperior, você dissipa automaticamente os efeitos de\nmagias no alvo se o nível da magia for igual ou inferior ao\nnível do espaço de magia que você usar."},{"id":"enviar-mensagem","name":"Enviar Mensagem","level":3,"school":"evocação","ritual":false,"classes":["bardo","clerigo","mago"],"pdfPage":241,"time":"1 ação","range":"Ilimitado","components":"V, S, M (um pequeno e fino pedaço de fio de cobre)","duration":"1 rodada","concentration":false,"text":"3° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: Ilimitado\nComponentes: V, S, M (um pequeno e fino pedaço de fio\n   de cobre)\nDuração: 1 rodada\nVocê envia uma mensagem curta, de vinte e cinco\npalavras ou menos, para uma criatura que seja familiar a\nvocê. A criatura ouve a mensagem na sua mente,\nreconhecendo que foi enviada por você, se ela te conhecer,\ne pode responder da mesma maneira, imediatamente. A\nmagia permite que criaturas com valores de Inteligência\nde no mínimo 1, compreendam o sentido da sua\nmensagem.\n   Você pode enviar a mensagem através de qualquer\ndistância e, até mesmo, para outro plano de existência,\nmas se o alvo estiver em um plano diferente do seu, existe\n5 por cento de chance da mensagem não chegar."},{"id":"espiritos-guardioes","name":"Espíritos Guardiões","level":3,"school":"conjuração","ritual":false,"classes":["clerigo"],"pdfPage":243,"time":"1 ação","range":"Pessoal (4,5 metros de raio)","components":"V, S, M (um símbolo sagrado)","duration":"Concentração, até 10 minutos","concentration":true,"text":"3° nível de conjuração\nTempo de Conjuração: 1 ação\nAlcance: Pessoal (4,5 metros de raio)\nComponentes: V, S, M (um símbolo sagrado)\nDuração: Concentração, até 10 minutos\nVocê evoca espíritos para protege-lo. Eles flutuam a seu\nredor, a uma distância de 4,5 metros, pela duração. Se\nvocê for bom ou neutro, as formas espectrais deles\naparenta ser angelical ou feérica (à sua escolha). Se você\nfor mau, eles pareceram demoníacos.\n    Quando você conjura essa magia, você pode designar\nqualquer quantidade de criaturas que você possa ver para\nnão serem afetadas por ela. O deslocamento de uma\ncriatura afetada é reduzido à metade na área e, quando a\ncriatura entrar na área pela primeira vez num turno ou\ncomeçar seu turno nela, ela deve realizar um teste de\nresistência de Sabedoria. Se falhar na resistência, a\ncriatura sofrerá 3d8 de dano radiante (se você for bom ou\nneutro) ou 3d8 de dano necrótico (se você for mau). Com\num sucesso na resistência, a criatura sofre metade desse\ndano.\n    Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 4° nível ou\nsuperior, o dano aumenta em 1d8 para cada nível do\nespaço acima do 3°."},{"id":"falar-com-plantas","name":"Falar com Plantas","level":3,"school":"transmutação","ritual":false,"classes":["bardo","druida","patrulheiro"],"pdfPage":244,"time":"1 ação","range":"Pessoal (9 metros de raio)","components":"V, S","duration":"10 minutos","concentration":false,"text":"1° nível de adivinhação (ritual)\nTempo de Conjuração: 1 ação\nAlcance: Pessoal (9 metros de raio)\nComponentes: V, S\nDuração: 10 minutos\nVocê imbui as plantas a até 9 metros de você com\nconsciência e animação limitadas, dando-lhes a\nhabilidade de se comunicar com você e seguir seus\ncomandos simples. Você pode perguntar as plantas sobre\neventos na área da magia, acontecidos desde o dia\nanterior, recebendo informações sobre criaturas que\npassaram, clima e outras circunstâncias.\n   Você também pode tornar terreno difícil causado pelo\ncrescimento de plantas (como arbustos e vegetação\nrasteira) em terreno normal, permanecendo assim pela\nduração. Ou você pode tornar terreno normal onde as\nplantas estiverem presentes, em terreno difícil,\npermanecendo assim pela duração, fazendo as vinhas e\nramos atrasarem perseguidores, por exemplo.\n   As plantas podem ser capazes de realizar outras\ntarefas em seu favor, à critério do Mestre. A magia não\npermite que as plantas desenraizem-se e se movam, mas\nelas podem mover, livremente, seus ramos, galhos e\ncaules.\n   Se uma criatura planta estiver na área, você pode se\ncomunicar com ela se você partilhar um idioma em\ncomum, mas você não recebe qualquer habilidade mágica\npara influencia-la.\n   Essa magia pode fazer as plantas criadas pela magia\nconstrição soltarem uma criatura impedida."},{"id":"falar-com-os-mortos","name":"Falar com os Mortos","level":3,"school":"necromancia","ritual":false,"classes":["bardo","clerigo"],"pdfPage":244,"time":"1 ação","range":"3 metros","components":"V, S, M (incenso aceso)","duration":"10 minutos","concentration":false,"text":"3° nível de necromancia\nTempo de Conjuração: 1 ação\nAlcance: 3 metros\nComponentes: V, S, M (incenso aceso)\nDuração: 10 minutos\nVocê concede o aspecto de vida e inteligência a um corpo,\nà sua escolha, dentro do alcance, permitindo que ele\nresponda as perguntas que você fizer. O corpo ainda deve\npossuir uma boca e não pode ser um morto-vivo. A magia\nfalha se o corpo já tiver sido alvo dessa magia nos últimos\n10 dias.\n   Até a magia acabar, você pode fazer ao corpo até cinco\nperguntas. O corpo sabe apenas o que ele sabia em vida,\nincluindo o idioma que ele conhecia. As respostas\nnormalmente são breves, enigmáticas ou repetitivas e o\ncorpo não está sob nenhuma compulsão que o obrigue a\noferecer respostas verdadeiras se você for hostil a ele ou\nse ele reconhecer você como um inimigo. Essa magia não\ntraz a alma da criatura de volta ao corpo, apenas anima\nseu espírito. Portanto, o corpo não pode aprender novas\ninformações, não compreende nada que tenha acontecido\ndepois da sua morte e não pode especular sobre eventos\nfuturos."},{"id":"flecha-relampejante","name":"Flecha Relampejante","level":3,"school":"transmutação","ritual":false,"classes":["patrulheiro"],"pdfPage":245,"time":"1 ação bônus","range":"Pessoal","components":"V, S","duration":"Concentração, até 1 minuto","concentration":true,"text":"3° nível de transmutação\nTempo de Conjuração: 1 ação bônus\nAlcance: Pessoal\nComponentes: V, S\nDuração: Concentração, até 1 minuto\nDa próxima vez que você realizar um ataque com uma\narma à distância enquanto a magia durar, a munição da\narma ou a própria arma, se ela for uma arma de\narremesso, se transforma num relâmpago. Realize uma\njogada de ataque normal. O alvo sofre 4d8 de dano\nelétrico se atingir ou metade desse dano se errar, ao invés\ndo dano normal da arma.\n    Independentemente de você acertar ou errar, cada\ncriatura a até 3 metros do alvo deve realizar um teste de\nresistência de Destreza. Cada uma dessas criaturas sofre\n2d8 de dano elétrico se falhar na resistência ou metade\ndesse dano se obtiver sucesso.\n    A munição ou arma então, volta a sua forma normal.\n    Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 4° nível ou\nsuperior, o dano de ambos os efeitos da magia aumenta\nem 1d8 para cada nível do espaço acima do 3°."},{"id":"fome-de-hadar","name":"Fome de Hadar","level":3,"school":"conjuração","ritual":false,"classes":["bruxo"],"pdfPage":245,"time":"1 ação","range":"45 metros","components":"V, S, M (um tentáculo de polvo em conserva)","duration":"Concentração, até 1 minuto","concentration":true,"text":"3° nível de conjuração\nTempo de Conjuração: 1 ação\nAlcance: 45 metros\nComponentes: V, S, M (um tentáculo de polvo em\n   conserva)\nDuração: Concentração, até 1 minuto\nVocê abre um portal para a escuridão entre as estrelas,\numa região infestada de horrores desconhecidos. Uma\nesfera de 6 metros de raio de negritude e frio severo\naparece, centrada num ponto dentro do alcance, e\npermanece pela duração. Esse vazio está preenchido por\numa cacofonia de sussurros suaves e barulhos de rangidos\nque podem ser ouvidos a até 9 metros. Nenhuma luz,\nmágica ou qualquer que seja, pode iluminar a área e as\ncriaturas totalmente dentro da área estarão cegas.\n    O vazio cria uma dobra no tecido do espaço e a área é\nde terreno difícil. Qualquer criatura que começar seu\nturno na área sofre 2d6 de dano de frio. Qualquer\ncriatura que terminar seu turno na área, deve ser bem\nsucedida num teste de resistência de Destreza ou sofrerá\n2d6 de dano de ácido, à medida que tentáculos leitosos\nextraterrestres se esfregam contra ela."},{"id":"forjar-morte","name":"Forjar Morte","level":3,"school":"necromancia","ritual":true,"classes":["bardo","clerigo","druida","mago"],"pdfPage":246,"time":"1 ação","range":"Toque","components":"V, S, M (uma pitada de terra de cemitério)","duration":"1 hora","concentration":false,"text":"3° nível de necromancia (ritual)\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S, M (uma pitada de terra de\n   cemitério)\nDuração: 1 hora\nVocê toca uma criatura voluntária e a coloca em um\nestado catatônico que é indistinguível da morte.\n   Pela duração da magia, ou até você usar uma ação\npara tocar o alvo e dissipar a magia, o alvo aparenta estar\nmorto para todas as inspeções externas e para magias\nusadas para determinar a condição do alvo. O alvo está\ncego e incapacitado e seu deslocamento cai para 0. O alvo\ntem resistência a todos os danos, exceto dano psíquico. Se\no alvo estava doente ou envenenado quando você conjurou\na magia, ou ficou doente ou envenenado durante o período\nem que estava sob efeito da magia, a doença e veneno não\nterá qualquer efeito até a magia terminar."},{"id":"forma-gasosa","name":"Forma Gasosa","level":3,"school":"transmutação","ritual":false,"classes":["bruxo","feiticeiro","mago"],"pdfPage":246,"time":"1 ação","range":"Toque","components":"V, S, M (um pouco de gaze e um pouco de fumaça)","duration":"Concentração, até 1 hora","concentration":true,"text":"3° nível de transmutação\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S, M (um pouco de gaze e um pouco de\n   fumaça)\nDuração: Concentração, até 1 hora\nVocê transforma uma criatura voluntária que você tocar,\njunto com tudo que ela estiver vestindo e carregando, em\numa nuvem nebulosa, pela duração. A magia termina se a\ncriatura cair a 0 pontos de vida. Uma criatura incorpórea\nnão pode ser afetada.\n    Enquanto estiver nessa forma, o único meio de\nmovimentação do alvo é 3 metros de deslocamento de voo.\nO alvo pode entrar e ocupar o espaço de outra criatura. O\nalvo tem resistência a dano não-mágico e tem vantagem\nem testes de resistência de Força, Destreza e\nConstituição. O alvo pode passar através de pequenos\nburacos, aberturas estreitas e, até mesmo, meras\nrachaduras, embora ele trate líquidos como se fossem\nsuperfícies sólidas. O alvo não pode cair e se mantem\nflutuando no ar, mesmo se estiver atordoado ou\nincapacitado de alguma outra forma.\n    Enquanto estiver na forma de uma nuvem nebulosa, o\nalvo não pode falar ou manipular objetos e, quaisquer\nobjetos que ele estava carregando ou segurando não pode\nser derrubado, usado ou, de outra forma, interagido. O\nalvo não pode atacar ou conjurar magias."},{"id":"glifo-de-vigilancia","name":"Glifo de Vigilância","level":3,"school":"abjuração","ritual":false,"classes":["bardo","clerigo","mago"],"pdfPage":247,"time":"1 hora","range":"Toque","components":"V, S, M (incenso e pó de diamante valendo, no mínimo, 200 po, consumidos pela magia)","duration":"Até ser dissipada ou ativada","concentration":false,"text":"3° nível de abjuração\nTempo de Conjuração: 1 hora\nAlcance: Toque\nComponentes: V, S, M (incenso e pó de diamante\n   valendo, no mínimo, 200 po, consumidos pela magia)\nDuração: Até ser dissipada ou ativada\nQuando você conjura essa magia, você inscreve um glifo\nque fere outras criaturas, tanto sobre uma superfície\n(como uma mesa ou uma secção de piso ou parede) quanto\ndentro de um objeto que possa ser fechado (como um livro,\num pergaminho ou um baú de tesouro) para ocultar o\nglifo. Se você escolher uma superfície, o glifo pode cobrir\numa área da superfície não superior a 3 metros de\ndiâmetro. Se você escolher um objeto, o objeto deve\npermanecer no seu local; se ele for movido mais de 3\nmetros de onde você conjurou essa magia, o glifo será\nquebrado e a magia termina sem ser ativada.\n    O glifo é quase invisível e requer um teste de\nInteligência (Investigação) contra a CD da magia para ser\nencontrado.\n    Você define o que ativa o glifo quando você conjura a\nmagia. Para glifos inscritos em uma superfície, os gatilhos\nmais típicos incluem tocar ou ficar sobre o glifo, remover\noutro objeto cobrindo o glifo, aproximar-se a uma certa\ndistância do glifo ou manipular um objeto onde o glifo\nesteja inscrito. Para glifos inscritos dentro de objetos, os\ngatilhos mais comuns incluem abrir o objeto, aproximar-\nse a uma certa distância do objeto ou ver ou ler o glifo.\nUma vez que o glifo seja ativado, a magia termina.\n    Você pode, posteriormente, aperfeiçoar o gatilho para\nque a magia se ative apenas sob certas circunstâncias ou\nde acordo com as características físicas (como altura ou\npeso), tipo de criatura (por exemplo, a proteção poderia\nser definida para afetar aberrações ou drow) ou\ntendência. Você pode, também, definir condições para\ncriaturas não ativarem o glifo, como aqueles que falarem\ndeterminada senha.\n    Quando você inscreve o glifo, escolha runas explosivas\nou glifo de magia.\n    Runas Explosivas. Quando ativado, o glifo irrompe\ncom energia mágica numa esfera com 6 metros de raio,\ncentrada no glifo. A esfera se espalha, dobrando esquinas.\nCada criatura na área deve realizar um teste de\nresistência de Destreza. Uma criatura sofre 5d8 de dano\nde ácido, elétrico, fogo, frio ou trovejante se falhar no\nteste de resistência (você escolhe o tipo quando cria o\nglifo) ou metade desse dano se obtiver sucesso.\n    Glifo de Magia. Você pode armazenar uma magia\npreparada de 3° nível ou inferior no glifo ao conjura-la\ncomo parte da criação do glifo. A magia a ser armazenada\nnão tem efeito imediato quando conjurada dessa forma.\nQuando o glifo for ativado, a magia armazenada é\nconjurada. Se a magia tiver um alvo, esse alvo será a\ncriatura que ativou o glifo. Se a magia afetar uma área, a\nárea será centrada na criatura. Se a magia invocar\ncriaturas hostis ou criar objetos ou armadilhas nocivos,\neles aparecerão o mais próximo possível do intruso e o\natacarão. Se a magia precisar de concentração, ela dura o\nmáximo possível da sua duração.\n    Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 4° nível ou\nsuperior, o dano do glifo de runas explosivas aumenta em\n1d8 para cada nível do espaço acima do 3°. Se você criar\num glifo de magia, você pode armazenar qualquer magia\ndo mesmo nível, ou inferior, do espaço que você usar para\no glifo de vigilância."},{"id":"idiomas","name":"Idiomas","level":3,"school":"adivinhação","ritual":false,"classes":["bardo","bruxo","clerigo","feiticeiro","mago"],"pdfPage":248,"time":"1 ação","range":"Toque","components":"V, M (uma pequena estátua de argila de um zigurate)","duration":"1 hora","concentration":false,"text":"3° nível de adivinhação\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, M (uma pequena estátua de argila de\n   um zigurate)\nDuração: 1 hora\nEssa magia garante a criatura que você tocar a\nhabilidade de compreender e falar o idioma que ela ouvir.\nAlém disso, quando o alvo fala, qualquer criatura que\nsaiba, pelo menos, um idioma pode ouvir o alvo e\ncompreender o que ele diz."},{"id":"imagem-maior","name":"Imagem Maior","level":3,"school":"ilusão","ritual":false,"classes":["bardo","bruxo","feiticeiro","mago"],"pdfPage":250,"time":"1 ação","range":"36 metros","components":"V, S, M (um pedaço de lã)","duration":"Concentração, até 10 minutos","concentration":true,"text":"3° nível de ilusão\nTempo de Conjuração: 1 ação\nAlcance: 36 metros\nComponentes: V, S, M (um pedaço de lã)\nDuração: Concentração, até 10 minutos\nVocê cria uma imagem de um objeto, uma criatura ou\nalgum outro fenômeno visível que não tenha mais de 6\nmetros cúbicos. A imagem aparece em um local que você\npossa ver, dentro do alcance e permanece pela duração.\nEla parece completamente real, incluindo sons, cheiros e\ntemperatura apropriados para a coisa retratada. Você não\npode criar calo ou frio suficiente para causar dano, um\nsom alto o suficiente para causar dano trovejante ou\nensurdecer uma criatura ou um cheiro que poderia\nnausear uma criatura (como o fedor de um troglodita).\n    Enquanto você estiver dentro do alcance da ilusão,\nvocê pode usar sua ação pra fazer a imagem se mover\npara qualquer outro local dentro do alcance. À medida\nque a imagem muda de lugar, você pode alterar a\naparência dela para que seu movimento pareça ser o\nnatural para a imagem. Por exemplo, se você criar uma\nimagem de uma criatura e move-la, você pode alterar a\nimagem para que ela pareça estar andando.\nSimilarmente, você pode fazer a ilusão emitir sons\ndiferentes em momentos diferentes, sendo possível até\nmesmo manter uma conversa, por exemplo.\n    Interação física com a imagem, revelará que ela é uma\nilusão, já que as coisas podem passar através dela. Uma\ncriatura que usar sua ação para examinar a imagem,\npode determinar que ela é uma ilusão com um teste de\nInteligência (Investigação) bem sucedido contra a CD da\nmagia. Se uma criatura discernir a ilusão como sendo\nisso, a criatura verá através da imagem e suas outras\nqualidades sensoriais se tornaram suaves para a criatura.\n    Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 6° nível ou\nsuperior, a magia irá durar até ser dissipada, sem\nnecessitar da sua concentração."},{"id":"lentidao","name":"Lentidão","level":3,"school":"transmutação","ritual":false,"classes":["feiticeiro","mago"],"pdfPage":252,"time":"1 ação","range":"36 metros","components":"V, S, M (uma gota de melaço)","duration":"Concentração, até 1 minuto","concentration":true,"text":"3° nível de transmutação\nTempo de Conjuração: 1 ação\nAlcance: 36 metros\nComponentes: V, S, M (uma gota de melaço)\nDuração: Concentração, até 1 minuto\nVocê altera o tempo ao redor de até seis criaturas, à sua\nescolha, num cubo de 12 metros, dentro do alcance. Cada\ncriatura deve ser bem sucedida num teste de resistência\nde Sabedoria ou será afetada por essa magia pela\nduração.\n    O deslocamento de um alvo afetado é reduzido à\nmetade, ele sofre –2 de penalidade na CA e nos testes de\nresistência de Destreza e não pode usar reações. No turno\ndele, ele pode usar ou uma ação ou uma ação bônus, mas\nnão ambas. Independentemente das habilidades ou itens\nmágicos da criatura, ela não poderá realizar mais de um\nataque corpo-a-corpo ou à distância durante o turno dela.\n    Se a criatura tentar conjurar uma magia com tempo\nde conjuração maior que 1 rodada, jogue um d20. Se cair\n11 ou maior, a magia não surte efeito até o próximo turno\nda criatura e a criatura deve usar sua ação nesse turno\npara completar a magia. Se ela não puder, a magia é\nperdida.\n    Uma criatura afetada por essa magia faz outro teste\nde resistência de Sabedoria no final do turno dela. Se\npassar na resistência, o efeito acaba nela."},{"id":"luz-do-dia","name":"Luz do Dia","level":3,"school":"evocação","ritual":false,"classes":["clerigo","druida","feiticeiro","paladino","patrulheiro"],"pdfPage":253,"time":"1 ação","range":"18 metros","components":"V, S","duration":"1 hora","concentration":false,"text":"3° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, S\nDuração: 1 hora\nUma esfera de luz, com 18 metros de raio, se espalha a\npartir de um ponto, à sua escolha, dentro do alcance. A\nesfera produz luz plena num raio de 18 metros e\npenumbra por 18 metros adicionais.\n    Se você escolher um ponto em um objeto que você\nesteja segurando, ou um que não esteja sendo vestido ou\ncarregado, a luz brilha a partir do objeto e se move com\nele. Cobrir completamente o objeto afetado com um objeto\nopaco, como uma vasilha ou um elmo, bloqueará a luz.\n    Se qualquer área dessa magia sobrepor uma área de\nescuridão criada por uma magia de 3° ou inferior, a magia\nque criou a escuridão será dissipada."},{"id":"manto-do-cruzado","name":"Manto do Cruzado","level":3,"school":"evocação","ritual":false,"classes":["paladino"],"pdfPage":254,"time":"1 ação","range":"Pessoal","components":"V","duration":"Concentração, até 1 minuto","concentration":true,"text":"3° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: Pessoal\nComponentes: V\nDuração: Concentração, até 1 minuto\nPoder sagrado irradia de você em uma aura de 9 metros\nde raio, despertando a audácia nas criaturas amigáveis.\nAté o final da magia, a aura se move, se mantendo\ncentrada em você. Enquanto estiver na aura, cada\ncriatura não-hostil (incluindo você) causa 1d4 de dano\nradiante extra quando atingir com ataques com arma."},{"id":"medo","name":"Medo","level":3,"school":"ilusão","ritual":false,"classes":["bardo","bruxo","feiticeiro","mago"],"pdfPage":256,"time":"1 ação","range":"Pessoal (cone de 9 metros)","components":"V, S, M (uma pena branca ou o coração de uma galinha)","duration":"Concentração, até 1 minuto","concentration":true,"text":"3° nível de ilusão\nTempo de Conjuração: 1 ação\nAlcance: Pessoal (cone de 9 metros)\nComponentes: V, S, M (uma pena branca ou o coração\n   de uma galinha)\nDuração: Concentração, até 1 minuto\nVocê projeta uma imagem fantasmagórica dos piores\nmedos de uma criatura. Cada criatura num cone de 9\nmetros, deve ser bem sucedida num teste de resistência\nde Sabedoria ou largara o que quer que esteja segurando\ne ficará amedrontada pela duração.\n    Enquanto estiver amedrontada por essa magia, uma\ncriatura deve usar a ação de Disparada e fugir de você\npela rota mais curta disponível em cada um dos turnos\ndela, a não ser que não haja lugar para onde se mover. Se\na criatura terminar o turno dela em um local onde ela não\ntenha linha de visão sua, a criatura pode realizar um\nteste de resistência de Sabedoria. Se obtiver sucesso, a\nmagia termina naquela criatura."},{"id":"mesclar-se-as-rochas","name":"Mesclar-se às Rochas","level":3,"school":"transmutação","ritual":true,"classes":["clerigo","druida"],"pdfPage":256,"time":"1 ação","range":"Toque","components":"V, S","duration":"8 horas","concentration":false,"text":"3° nível de transmutação (ritual)\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S\nDuração: 8 horas\nVocê entra em um objeto ou superfície rochoso, grande o\nsuficiente para comportar seu corpo inteiro, mesclando-se,\njunto com todo o equipamento que você esteja carregando,\ncom a rocha pela duração. Usando seu movimento, você\nentra na rocha num ponto que você possa tocar. Nada da\nsua presença ficará visível ou, de outra forma, detectável\npor sentidos não-mágicos.\n    Enquanto estiver imerso na rocha, você não pode ver o\nque está ocorrendo do lado de fora e, qualquer teste de\nSabedoria (Percepção) que você fizer para ouvir os sons do\nlado de fora são feitos com desvantagem. Você continua\nconsciente do tempo transcorrido e pode conjurar magias\nem você enquanto estiver imerso na rocha. Você pode usar\nseu movimento para sair da rocha onde você entrou, o que\ntermina a magia. Do contrário, você não pode se mover.\n    Pequenos danos físicos a rocha não ferem você, mas\ndestruição parcial ou uma mudança no formato (fazendo\nque você já não caiba mais dentro dela) expelirá você\ncausando-lhe 6d6 de dano de concussão. A destruição\ncompleta da rocha (ou transmutação em uma substância\ndiferente) expelirá você causando-lhe 50 de dano de\nconcussão. Se você for expelido, você ficará caído no chão\nem um espaço desocupado perto de onde você entrou da\nprimeira vez."},{"id":"montaria-fantasmagorica","name":"Montaria Fantasmagórica","level":3,"school":"ilusão","ritual":true,"classes":["mago"],"pdfPage":258,"time":"1 minuto","range":"9 metros","components":"V, S","duration":"1 hora","concentration":false,"text":"3° nível de ilusão (ritual)\nTempo de Conjuração: 1 minuto\nAlcance: 9 metros\nComponentes: V, S\nDuração: 1 hora\nUma criatura Grande, quase-real, similar a um cavalo,\naparece no solo em um espaço desocupado, à sua escolha,\ndentro do alcance. Você decide a aparência da criatura,\nmas ela é equipada com sela, estribo e arreio. Qualquer\nequipamento criado por essa magia vira fumaça caso se\nafaste a mais de 3 metros da montaria.\n   Pela duração, você ou a criatura que você escolher,\npode cavalgar a montaria. A criatura usa as estatísticas\nde um cavalo de montaria, exceto por seu deslocamento\nser de 30 metros e poder viajar 15 quilômetros em uma\nhora, ou 20 quilômetros em um ritmo rápido. Quando a\nmagia acaba, a montaria desaparece gradualmente,\ndando ao cavaleiro 1 minuto para desmontar. A magia\nacaba se você usar uma ação para dissipa-la ou se a\nmontaria sofrer qualquer dano."},{"id":"muralha-de-vento","name":"Muralha de Vento","level":3,"school":"evocação","ritual":false,"classes":["druida","patrulheiro"],"pdfPage":261,"time":"1 ação","range":"36 metros","components":"V, S, M (um leque minúsculo e uma pena de origem exótica)","duration":"Concentração, até 1 minuto","concentration":true,"text":"3° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: 36 metros\nComponentes: V, S, M (um leque minúsculo e uma pena\n   de origem exótica)\nDuração: Concentração, até 1 minuto\nUma muralha de ventos fortes ergue-se do chão num\nponto, à sua escolha, dentro do alcance. Você pode fazer a\nmuralha ter até 15 metros de comprimento, 4,5 metros de\naltura e 30 centímetros de espessura. Você pode moldar a\nmuralha em qualquer forma que desejar, contanto que ela\nfaça um caminho contínuo pelo solo. A muralha\npermanece pela duração.\n   Quando a muralha aparece, cada criatura dentro da\nárea dela deve realizar um teste de resistência de Força.\nUma criatura sofre 3d8 de dano de concussão se falhar na\nresistência, ou metade desse dano se obtiver sucesso.\n   Os ventos fortes mantem névoa, fumaça e outros gases\nafastados. Criaturas ou objetos voadores Pequenos ou\nmenores, não podem atravessar a muralha. Materiais\nleves e soltos trazidos para a muralha são arremessados\npara cima. Flechas, virotes e outros projéteis ordinários\ndisparados contra alvos além da muralha são defletidos\npara cima e erram automaticamente. (Pedras\narremessadas por gigantes ou armas de cerco e projéteis\nsimilares, não são afetados.) As criaturas em forma\ngasosa não podem atravessa-la."},{"id":"nevasca","name":"Nevasca","level":3,"school":"conjuração","ritual":false,"classes":["druida","feiticeiro","mago"],"pdfPage":262,"time":"1 ação","range":"45 metros","components":"V, S, M (um punhado de poeira e algumas gotas de água)","duration":"Concentração, até 1 minuto","concentration":true,"text":"3° nível de conjuração\nTempo de Conjuração: 1 ação\nAlcance: 45 metros\nComponentes: V, S, M (um punhado de poeira e\n   algumas gotas de água)\nDuração: Concentração, até 1 minuto\nAté a magia acabar, uma chuva congelante e neve caem\nnum cilindro de 6 metros de altura por 12 metros de raio,\ncentrado num ponto, à sua escolha, dentro do alcance. A\nárea é de escuridão densa e, chamas expostas na área são\nextintas.\n   O solo na área é coberto por gelo escorregadio,\ntornando-o terreno difícil. Quando uma criatura entrar na\nárea da magia pela primeira vez num turno ou começar\nseu turno nela, ela deve realizar um teste de resistência\nde Destreza. Se falhar, cairá no chão.\n   Se um, criatura estiver se concentrando na área da\nmagia, a criatura deve realizar um teste de resistência de\nConstituição contra a CD da magia, ou perderá a\nconcentração."},{"id":"nevoa-fetida","name":"Névoa Fétida","level":3,"school":"conjuração","ritual":false,"classes":["bardo","feiticeiro","mago"],"pdfPage":262,"time":"1 ação","range":"27 metros","components":"V, S, M (um ovo podre ou várias folhas de repolho)","duration":"Concentração, até 1 minuto","concentration":true,"text":"3° nível de conjuração\nTempo de Conjuração: 1 ação\nAlcance: 27 metros\nComponentes: V, S, M (um ovo podre ou várias folhas de\n   repolho)\nDuração: Concentração, até 1 minuto\nVocê cria uma esfera, de 6 metros de raio, de gás\namarelado nauseante, centrada num ponto dentro do\nalcance. A névoa se espalha, dobrando esquinas, e sua\nárea é de escuridão densa. A névoa perdura no ar pela\nduração.\n    Cada criatura que estiver completamente dentro da\nnévoa no início do seu turno deve realizar um teste de\nresistência de Constituição contra veneno. Se falhar na\nresistência, a criatura gastará sua ação nesse turno\ntentando vomitar e cambaleando.\n    Um vento moderado (pelo menos 15 quilômetros por\nhora) dispersará a névoa depois de 4 rodadas. Um vento\nforte (pelo menos 30 quilômetros por hora) dispersará a\nnévoa após 1 rodada."},{"id":"padrao-hipnotico","name":"Padrão Hipnótico","level":3,"school":"ilusão","ritual":false,"classes":["bardo","bruxo","feiticeiro","mago"],"pdfPage":264,"time":"1 ação","range":"36 metros","components":"S, M (uma vareta brilhante de incenso ou um frasco de cristal cheio de material fosforescente)","duration":"Concentração, até 1 minuto","concentration":true,"text":"3° nível de ilusão\nTempo de Conjuração: 1 ação\nAlcance: 36 metros\nComponentes: S, M (uma vareta brilhante de incenso ou\n   um frasco de cristal cheio de material fosforescente)\nDuração: Concentração, até 1 minuto\nVocê cria um padrão retorcido de cores que se entrelaça\natravés do ar dentro de um cubo de 9 metros, dentro do\nalcance. O padrão aparece por um momento depois\ndesaparece. Cada criatura na área que ver o padrão, deve\nrealizar um teste de resistência de Sabedoria. Se falhar\nna resistência, a criatura fica enfeitiçada pela duração.\nEnquanto estiver enfeitiçada por essa magia, a criatura\nestá incapacitada e tem deslocamento 0.\n   A magia acaba em uma criatura afetada se ela sofrer\ndano ou se alguém usar uma ação para agitar a criatura\npara tira-la de seu estupor."},{"id":"palavra-curativa-em-massa","name":"Palavra Curativa em Massa","level":3,"school":"evocação","ritual":false,"classes":["clerigo"],"pdfPage":264,"time":"1 ação bônus","range":"18 metros","components":"V","duration":"Instantânea","concentration":false,"text":"3° nível de evocação\nTempo de Conjuração: 1 ação bônus\nAlcance: 18 metros\nComponentes: V\nDuração: Instantânea\nÀ medida que você brada palavras de restauração, até\nseis criaturas, à sua escolha, que você possa ver, dentro\ndo alcance, recuperam uma quantidade de pontos de vida\nigual a 1d4 + seu modificador de habilidade de\nconjuração. Essa magia não afeta mortos-vivos ou\nconstructos.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 4° nível ou\nsuperior, a cura aumenta em 1d4 para cada nível do\nespaço acima do 3°."},{"id":"pequena-cabana-de-leomund","name":"Pequena Cabana de Leomund","level":3,"school":"evocação","ritual":true,"classes":["bardo","mago"],"pdfPage":266,"time":"1 minuto","range":"Pessoal (hemisfério de 3 metros de raio)","components":"V, S, M (uma pequena conta de cristal)","duration":"8 horas","concentration":false,"text":"3° nível de evocação (ritual)\nTempo de Conjuração: 1 minuto\nAlcance: Pessoal (hemisfério de 3 metros de raio)\nComponentes: V, S, M (uma pequena conta de cristal)\nDuração: 8 horas\nUm domo de energia imóvel, de 3 metros de raio, aparece\ndo nada, ao seu redor e acima de você e permanece parado\npela duração. A magia termina se você deixar a área.\n   Nove criaturas de tamanho Médio ou menor podem\ncaber dentro do domo com você. A magia falha se a área\nincluir criaturas maiores ou mais de nove criaturas.\nCriaturas e objetos dentro do domo quando você conjurou\nessa magia, podem se mover através dele livremente.\nTodas as outras criaturas e objetos são bloqueados ao\ntentarem atravessa-lo. Magias e outros efeitos mágicos\nnão podem se estender através do domo ou serem\nconjurados através dele. A atmosfera dentro do espaço é\nconfortável e seca, independente do clima do lado de fora.\n   Até a magia acabar, você pode comandar o interior\npara que fique mal iluminado ou escuro. O domo é opaco\ndo lado de fora, de qualquer cor que você desejar, mas é\ntransparente do lado de dentro."},{"id":"piscar","name":"Piscar","level":3,"school":"transmutação","ritual":false,"classes":["feiticeiro","mago"],"pdfPage":267,"time":"1 ação","range":"Pessoal","components":"V, S","duration":"1 minuto","concentration":false,"text":"3° nível de transmutação\nTempo de Conjuração: 1 ação\nAlcance: Pessoal\nComponentes: V, S\nDuração: 1 minuto\nRole um d20 no final de cada um dos seus turnos pela\nduração da magia. Com um resultado de 11 ou maior,\nvocê desaparece do seu plano de existência atual e\nreaparece no Plano Etéreo (a magia falha e a conjuração é\nperdida se você já estiver nesse plano). No início do seu\npróximo turno e quando a magia terminar, se você estiver\nno Plano Etéreo, você retorna a um espaço desocupado de\nsua escolha que você possa ver a até 3 metros do espaço\nem que você desapareceu. Se não houver um espaço\ndisponível dentro do alcance, você reaparece no espaço\ndesocupado mais próximo (escolhido aleatoriamente, se\nexistir mais de um espaço a mesma distância). Você pode\ndissipar a magia com uma ação.\n   Quando estiver no Plano Etéreo, você pode ver e ouvir\no plano de onde você veio, que aparece em tons de cinza, e\nvocê não pode ver nada além de 18 metros. Você só pode\nafetar ou ser afetado por outras criaturas no Plano\nEtéreo. As criaturas que não estiverem lá não podem\nnotar você nem interagir com você, a não ser que elas\ntenham uma habilidade que as permita."},{"id":"protecao-contra-energia","name":"Proteção contra Energia","level":3,"school":"abjuração","ritual":false,"classes":["clerigo","druida","feiticeiro","mago","patrulheiro"],"pdfPage":270,"time":"1 ação","range":"Toque","components":"V, S","duration":"Concentração, até 1 hora","concentration":true,"text":"3° nível de abjuração\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S\nDuração: Concentração, até 1 hora\nPela duração, a criatura voluntária que você tocar terá\nresistência a um tipo de dano de sua escolha: ácido,\nelétrico, fogo, frio ou trovejante."},{"id":"relampago","name":"Relâmpago","level":3,"school":"evocação","ritual":false,"classes":["feiticeiro","mago"],"pdfPage":276,"time":"1 ação","range":"Pessoal (linha de 30 metros)","components":"V, S, M (um pouco de pelo e uma haste de âmbar, cristal ou vidro)","duration":"Instantânea","concentration":false,"text":"3° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: Pessoal (linha de 30 metros)\nComponentes: V, S, M (um pouco de pelo e uma haste de\n   âmbar, cristal ou vidro)\nDuração: Instantânea\nUm relâmpago forma uma linha de 30 metros de\ncomprimento e 1,5 metro de largura que é disparado por\nvocê em uma direção, à sua escolha. Cada criatura na\nlinha deve realizar um teste de resistência de Destreza.\nUma criatura sofre 8d6 de dano elétrico se falhar na\nresistência ou metade desse dano se obtiver sucesso.\n   O relâmpago incendeia objetos inflamáveis na área\nque não estejam sendo vestidos ou carregados.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 4° nível ou\nsuperior, o dano aumenta em 1d6 para cada nível do\nespaço acima do 3°."},{"id":"remover-maldicao","name":"Remover Maldição","level":3,"school":"abjuração","ritual":false,"classes":["bruxo","clerigo","mago","paladino"],"pdfPage":276,"time":"1 ação","range":"Toque","components":"V, S","duration":"Instantânea","concentration":false,"text":"3° nível de abjuração\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S\nDuração: Instantânea\nAo seu toque, todas as maldições afetando uma criatura\nou objeto terminam. Se o objeto for um item mágico\namaldiçoado, sua maldição persiste, mas a magia rompe a\nsintonia do portador com o objeto, então permitindo que\nele o remova ou descarte."},{"id":"respirar-na-agua","name":"Respirar na Água","level":3,"school":"transmutação","ritual":true,"classes":["druida","feiticeiro","mago","patrulheiro"],"pdfPage":276,"time":"1 ação","range":"9 metros","components":"V, S, M (um pedaço de cana ou palha)","duration":"24 horas","concentration":false,"text":"3° nível de transmutação (ritual)\nTempo de Conjuração: 1 ação\nAlcance: 9 metros\nComponentes: V, S, M (um pedaço de cana ou palha)\nDuração: 24 horas\nEssa magia concede a até dez criaturas voluntária que\nvocê possa ver, dentro do alcance, a habilidade de respirar\nembaixo d’água até a magia acabar. As criaturas afetadas\ntambém mantem sua forma normal de respiração."},{"id":"revivificar","name":"Revivificar","level":3,"school":"necromancia","ritual":false,"classes":["clerigo","paladino"],"pdfPage":277,"time":"1 ação","range":"Toque","components":"V, S, M (um diamante no valor de 300 po, consumido pela magia)","duration":"Instantânea","concentration":false,"text":"3° nível de necromancia\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S, M (um diamante no valor de 300 po,\n   consumido pela magia)\nDuração: Instantânea\nVocê toca uma criatura que tenha morrido dentro do\núltimo minuto. Essa criatura volta a vida com 1 ponto de\nvida. Essa magia não pode trazer de volta a vida criaturas\nque tenham morrido de velhice nem pode restaurar\nquaisquer partes do corpo perdidas."},{"id":"rogar-maldicao","name":"Rogar Maldição","level":3,"school":"necromancia","ritual":false,"classes":["bardo","clerigo","mago"],"pdfPage":277,"time":"1 ação","range":"Toque","components":"V, S","duration":"Concentração, até 1 minuto","concentration":true,"text":"3° nível de necromancia\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S\nDuração: Concentração, até 1 minuto\nVocê toca uma criatura e a criatura deve ser bem\nsucedida em um teste de resistência de Sabedoria ou será\namaldiçoada pela duração da magia. Quando você conjura\nessa magia, escolha a natureza da maldição dentre as\nseguintes opções:\n   Escolha um valor de habilidade. Enquanto\n    amaldiçoado, o alvo tem desvantagem em testes de\n    habilidade e testes de resistência feitos com esse valor\n    de habilidade,\n   Enquanto amaldiçoado, o alvo tem desvantagem nas\n    jogadas de ataque contra você.\n   Enquanto amaldiçoado, o alvo deve realizar um teste\n    de resistência de Sabedoria no começo de cada um dos\n    turnos dela. Se ela falhar, ela perderá sua ação aquele\n    turno, não fazendo nada.\n   Enquanto o alvo estiver amaldiçoado, seus ataques e\n    magias causam 1d8 de dano necrótico extra a ele.\n\n   Uma magia remover maldição termina esse efeito.\nCom a permissão do Mestre, você pode escolher um efeito\nalternativo de maldição, mas ele não deve ser mais\npoderoso que os descritos acima. O Mestre tem a palavra\nfinal sobre o efeito de uma maldição.\n   Em Níveis Superiores. Se você conjurar essa magia\nusando um espaço de magia de 4° nível, a duração da\nconcentração sobe para 10 minutos. Se você usar um\nespaço de magia de 5° ou 6° nível, a duração será de 8\nhoras. Se você usar um espaço de magia de 7° ou 8° nível,\na duração será de 24 horas. Se você usar um espaço de\nmagia de 9° nível, a magia dura até ser dissipada. Usar\num espaço de magia de 5° nível ou superior faz com que a\nduração não necessite de concentração."},{"id":"sinal-de-esperanca","name":"Sinal de Esperança","level":3,"school":"abjuração","ritual":false,"classes":["clerigo"],"pdfPage":280,"time":"1 ação","range":"9 metros","components":"V, S","duration":"Concentração, até 1 minuto","concentration":true,"text":"3° nível de abjuração\nTempo de Conjuração: 1 ação\nAlcance: 9 metros\nComponentes: V, S\nDuração: Concentração, até 1 minuto\nEssa magia confere esperança e vitalidade. Escolha\nqualquer quantidade de criaturas dentro do alcance. Pela\nduração, cada alvo tem vantagem em testes de resistência\nde Sabedoria e testes de resistência contra a morte e\nrecuperam o máximo de pontos de vida possível em\nqualquer cura."},{"id":"toque-vampirico","name":"Toque Vampírico","level":3,"school":"necromancia","ritual":false,"classes":["bruxo","mago"],"pdfPage":286,"time":"1 ação","range":"Pessoal","components":"V, S","duration":"Concentração, até 1 minuto","concentration":true,"text":"3° nível de necromancia\nTempo de Conjuração: 1 ação\nAlcance: Pessoal\nComponentes: V, S\nDuração: Concentração, até 1 minuto\nO toque da sua mão coberta de sombras pode drenar a\nforça vital dos outros para curar seus ferimentos. Realize\num ataque corpo-a-corpo com magia contra uma criatura\nao seu alcance. Se atingir, o alvo sofre 3d6 de dano\nnecrótico e você recupera pontos de vida igual à metade\ndo dano necrótico causado. Até a magia acabar, você pode\nrealizar o ataque novamente, no seu turno, com uma\nação.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 4° nível ou\nsuperior, o dano aumenta em 1d6 para cada nível do\nespaço acima do 3°."},{"id":"velocidade","name":"Velocidade","level":3,"school":"transmutação","ritual":false,"classes":["feiticeiro","mago"],"pdfPage":287,"time":"1 ação","range":"18 metros","components":"V, S, M (uma raspa de raiz de alcaçuz)","duration":"Concentração, até 1 minuto","concentration":true,"text":"3° nível de transmutação\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, S, M (uma raspa de raiz de alcaçuz)\nDuração: Concentração, até 1 minuto\nEscolha uma criatura voluntária que você possa ver,\ndentro do alcance. Até a magia acabar, o deslocamento do\nalvo é dobrado, ele ganha +2 de bônus na CA, ele tem\nvantagem em testes de resistência de Destreza e ganha\numa ação adicional em cada um dos turnos dele. A ação\npode ser usada apenas para realizar as ações de Ataque\n(um ataque com arma, apenas), Disparada, Desengajar,\nEsconder ou Usar um Objeto.\n   Quando a magia acabar, o alvo não poderá se mover\nou realizar ações até depois do seu próximo turno, à\nmedida que uma onda de letargia toma conta dele."},{"id":"voo","name":"Voo","level":3,"school":"transmutação","ritual":false,"classes":["bruxo","feiticeiro","mago"],"pdfPage":288,"time":"1 ação","range":"Toque","components":"V, S, M (uma pena da asa de qualquer pássaro)","duration":"Concentração, até 10 minutos","concentration":true,"text":"3° nível de transmutação\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S, M (uma pena da asa de qualquer\n   pássaro)\nDuração: Concentração, até 10 minutos\nVocê toca uma criatura voluntária. O alvo ganha\ndeslocamento de voo de 18 metros, pela duração. Quando\na magia acabar, o alvo cai se ainda estiver no ar, a não\nser que ele possa impedir a queda.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 4° nível ou\nsuperior, você pode afetar uma criatura adicional para\ncada nível do espaço acima do 3°."},{"id":"adivinhacao","name":"Adivinhação","level":4,"school":"adivinhação","ritual":true,"classes":["clerigo"],"pdfPage":213,"time":"1 ação","range":"Pessoal","components":"V, S, M (incenso e uma oferenda apropriada para sacrifício à sua religião, juntos valendo, no mínimo, 25 po, consumidos pela magia)","duration":"Instantânea","concentration":false,"text":"4° nível de adivinhação (ritual)\nTempo de Conjuração: 1 ação\nAlcance: Pessoal\nComponentes: V, S, M (incenso e uma oferenda\n   apropriada para sacrifício à sua religião, juntos\n   valendo, no mínimo, 25 po, consumidos pela magia)\nDuração: Instantânea\nSua magia e uma oferenda colocam você em contato com\num deus ou servo divino. Você faz uma única pergunta a\nrespeito de um objetivo, evento ou atividade específico\nque irá ocorrer dentro de 7 dias. O Mestre oferece uma\nresposta confiável. A resposta deve ser uma frase curta,\numa rima enigmática ou um presságio.\n    A magia não leva em consideração qualquer possível\ncircunstância que possa mudar o que está por vir, como a\nconjuração de magias adicionais ou a perda ou ganho de\num companheiro.\n    Se você conjurar a magia duas ou mais vezes antes de\ncompletar seu próximo descanso longo, existe uma chance\ncumulativa de 25 por cento de cada conjuração, depois da\nprimeira que você fez, ter um resultado aleatório. O\nMestre faz essa jogada secretamente."},{"id":"arca-secreta-de-leomund","name":"Arca Secreta de Leomund","level":4,"school":"conjuração","ritual":false,"classes":["mago"],"pdfPage":217,"time":"1 ação","range":"Toque","components":"V, S, M (um baú requintado, de 90 cm por 60 cm por 60 cm, construído com materiais raros valendo, no mínimo, 5.000 po e uma réplica Miúda feita do mesmo material valendo, no mínimo, 50 po)","duration":"Instantânea","concentration":false,"text":"4° nível de conjuração\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S, M (um baú requintado, de 90 cm\n   por 60 cm por 60 cm, construído com materiais raros\n   valendo, no mínimo, 5.000 po e uma réplica Miúda\n   feita do mesmo material valendo, no mínimo, 50 po)\nDuração: Instantânea\nVocê esconde um baú, e todo o seu conteúdo, no Plano\nEtéreo. Você deve tocar o baú e a réplica em miniatura\nque serve como componente material para a magia. O baú\npode acomodar até 3,6 metros cúbicos de matéria\ninorgânica (90 cm por 60 cm por 60 cm).\n    Enquanto o baú permanecer no Plano Etéreo, você\npode usar uma ação e tocar a réplica para revocar o baú.\nEle aparece em um espaço desocupado no chão a 1,5\nmetro de você. Você pode enviar o baú de volta ao Plano\nEtéreo usando uma ação e tocando tanto no baú quanto\nna réplica.\n    Após 60 dias, existe 5 por cento de chance, cumulativa,\npor dia do efeito da magia terminar. Esse efeito termina\nse você conjurar essa magia novamente, se a pequena\nréplica do baú for destruída ou se você decidir terminar a\nmagia usando uma ação. Se a magia terminar enquanto o\nbaú maior estiver no Plano Etéreo, ele estará\nirremediavelmente perdido."},{"id":"assassino-fantasmagorico","name":"Assassino Fantasmagórico","level":4,"school":"ilusão","ritual":false,"classes":["mago"],"pdfPage":218,"time":"1 ação","range":"36 metros","components":"V, S","duration":"Concentração, até 1 minuto","concentration":true,"text":"4° nível de ilusão\nTempo de Conjuração: 1 ação\nAlcance: 36 metros\nComponentes: V, S\nDuração: Concentração, até 1 minuto\nVocê mexe com os pesadelos de uma criatura que você\npossa ver, dentro do alcance, e cria uma manifestação\nilusória dos seus medos mais profundos, visível apenas\npara a criatura. O alvo deve realizar um teste de\nresistência de Sabedoria. Se falhar na resistência, ele\nficará amedrontado pela duração. No final de cada turno\ndo alvo, antes da magia acabar, ele deve ser bem sucedido\nnum teste de resistência de Sabedoria ou sofrerá 4d10 de\ndano psíquico. Se passar na resistência, a magia acaba.\n    Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 5° nível ou\nsuperior, o dano aumenta em 1d10 para cada nível do\nespaço acima do 4°."},{"id":"aura-de-pureza","name":"Aura de Pureza","level":4,"school":"abjuração","ritual":false,"classes":["paladino"],"pdfPage":219,"time":"1 ação","range":"Pessoal (9 metros de raio)","components":"V","duration":"Concentração, até 10 minutos","concentration":true,"text":"4° nível de abjuração\nTempo de Conjuração: 1 ação\nAlcance: Pessoal (9 metros de raio)\nComponentes: V\nDuração: Concentração, até 10 minutos\nEnergia purificante irradia de você em uma aura com 9\nmetros de raio. Até a magia acabar, a aura se move\nmantendo-se centrada em você. Todas as criaturas não-\nhostis na aura (incluindo você) não podem ficar doentes,\ntem resistência a dano de veneno e tem vantagem em\ntestes de resistência contra efeitos que deixem ela com\nqualquer das condições a seguir: amedrontado, atordoado,\ncego, enfeitiçado, envenenado, paralisado e surdo."},{"id":"aura-de-vida","name":"Aura de Vida","level":4,"school":"bjuração","ritual":false,"classes":["paladino"],"pdfPage":220,"time":"1 ação","range":"Pessoal (9 metros de raio)","components":"V","duration":"Concentração, até 10 minutos","concentration":true,"text":"4° nível de abjuração\nTempo de Conjuração: 1 ação\nAlcance: Pessoal (9 metros de raio)\nComponentes: V\nDuração: Concentração, até 10 minutos\nEnergia de prevenção vital irradia de você em uma aura\ncom 9 metros de raio. Até a magia acabar, a aura se move\nmantendo-se centrada em você. Todas as criaturas não-\nhostis na aura (incluindo você) tem resistência a dano\nnecrótico e seu máximo de pontos de vida não pode ser\nreduzido. Além disso, uma criatura viva não-hostil,\nrecupera 1 ponto de vida quando começa seu turno na\naura com 0 pontos de vida."},{"id":"banimento","name":"Banimento","level":4,"school":"abjuração","ritual":false,"classes":["bruxo","clerigo","feiticeiro","mago","paladino"],"pdfPage":220,"time":"1 ação","range":"9 metros","components":"V, S, M (um item desagradável ao alvo)","duration":"Concentração, até 1 minuto","concentration":true,"text":"4° nível de abjuração\nTempo de Conjuração: 1 ação\nAlcance: 9 metros\nComponentes: V, S, M (um item desagradável ao alvo)\nDuração: Concentração, até 1 minuto\nVocê tenta enviar uma criatura que você pode ver dentro\ndo alcance, para outro plano de existência. O alvo deve\nser bem sucedido num teste de resistência de Carisma ou\nserá banido.\n   Se o alvo for nativo do plano de existência que você\nestá, você bane o alvo para um semiplano inofensivo.\nEnquanto estiver lá, a criatura estará incapacitada. Ela\npermanece lá até a magia acabar, a partir desse ponto, o\nalvo reaparece no espaço em que ela deixou ou no espaço\ndesocupado mais próximo, se o espaço dela estiver\nocupado.\n   Se o alvo for nativo de um plano de existência\ndiferente do que você está, o alvo é banido em um lampejo\nsutil, retornando para o seu plano natal. Se a magia\nacabar antes de 1 minuto se passar, o alvo reaparece no\nlugar em que estava ou no espaço desocupado mais\npróximo, se o espaço dela estiver ocupado. Do contrário, o\nalvo não retorna.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 5° nível ou\nsuperior, você pode afetar uma criatura adicional para\ncada nível do espaço acima do 4°."},{"id":"compulsao","name":"Compulsão","level":4,"school":"encantamento","ritual":false,"classes":["bardo"],"pdfPage":226,"time":"1 ação","range":"9 metros","components":"V, S","duration":"Concentração, até 1 minuto","concentration":true,"text":"4° nível de encantamento\nTempo de Conjuração: 1 ação\nAlcance: 9 metros\nComponentes: V, S\nDuração: Concentração, até 1 minuto\nCriaturas, à sua escolha, que você puder ver dentro do\nalcance e que puderem ouvir você, devem realizar um\nteste de resistência de Sabedoria. Um alvo passa\nautomaticamente nesse teste de resistência se ele não\npuder ser enfeitiçado. Se falhar no teste, um alvo é\nafetado por essa magia. Até a magia acabar, você pode\nusar uma ação bônus em cada um dos seus turnos, para\ndesignar uma direção horizontal a você. Cada criatura\nafetada deve se mover, da melhor forma possível, para\nessa direção no próximo turno dela. Ela pode realizar sua\nação antes de se mover. Depois de se mover dessa forma,\nela pode realizar outra resistência de Sabedoria para\ntentar acabar com o efeito.\n   Um alvo não é obrigado a se mover em direção de um\nperigo obviamente mortal, como uma fogueira ou abismo,\nmas ele vai provocar ataques de oportunidade por se\nmover na direção designada."},{"id":"confusao","name":"Confusão","level":4,"school":"encantamento","ritual":false,"classes":["bardo","druida","feiticeiro","mago"],"pdfPage":227,"time":"1 ação","range":"27 metros","components":"V, S, M (três cascas de noz)","duration":"Concentração, até 1 minuto","concentration":true,"text":"4° nível de encantamento\nTempo de Conjuração: 1 ação\nAlcance: 27 metros\nComponentes: V, S, M (três cascas de noz)\nDuração: Concentração, até 1 minuto\nEssa magia ataca e embaralha as mentes das criaturas,\ngerando delírios e provocando ações descontroladas. Cada\ncriatura em uma esfera com 3 metros de raio, centrada\nnum ponto, à sua escolha, dentro do alcance, deve ser bem\nsucedida num teste de resistência de Sabedoria, quando\nvocê conjurar essa magia ou for afetada por ela.\n    Um alvo afetado não pode realizar reações e deve rolar\num d10 no início de cada um dos seus turnos para\ndeterminar seu comportamento nesse turno.\n\nd10  Comportamento\n 1   A criatura usa todo seu deslocamento para se mover em\n     uma direção aleatória. Para determinar a direção, role\n     um d8 e atribua uma direção a cada face do dado. A\n     criatura não realiza uma ação nesse turno.\n2–6 A criatura não se move ou realiza ações nesse turno.\n7–8 A criatura usa sua ação para realizar um ataque corpo-a-\n     corpo contra uma criatura, determinada aleatoriamente,\n     ao seu alcance. Se não houver criaturas dentro do\n     alcance, a criatura não faz nada nesse turno.\n9–10 A criatura pode agir e se mover normalmente.\n\n   Ao final de cada um dos seus turnos, um alvo afetado\npode realizar um teste de resistência de Sabedoria. Se for\nbem sucedido, esse efeito acaba nesse alvo.\n   Em Níveis Superiores. Se você conjurar essa magia\nusando um espaço de magia de 5° nível ou superior, o raio\nda esfera aumenta em 1,5 metro para cada nível do\nespaço acima do 4°."},{"id":"conjurar-elementais-menores","name":"Conjurar Elementais Menores","level":4,"school":"conjuração","ritual":false,"classes":["druida","mago"],"pdfPage":228,"time":"1 minuto","range":"27 metros","components":"V, S","duration":"Concentração, até 1 hora","concentration":true,"text":"4° nível de conjuração\nTempo de Conjuração: 1 minuto\nAlcance: 27 metros\nComponentes: V, S\nDuração: Concentração, até 1 hora\nVocê invoca elementais que aparecem em espaços\ndesocupados, que você possa ver dentro do alcance. Você\nescolhe uma das opções a seguir para aparecer:\n   Um elemental de nível de desafio 2 ou inferior\n   Dois elementais de nível de desafio 1 ou inferior\n   Quatro elementais de nível de desafio 1/2 ou inferior\n   Oito elementais de nível de desafio 1/4 ou inferior\n   Um elemental invocado através dessa magia\ndesaparece quando cair a 0 pontos de vida ou quando a\nmagia acabar.\n    As criaturas invocadas são amigáveis a você e a seus\ncompanheiros. Role a iniciativa para as criaturas\ninvocadas como um grupo, que age no seu próprio turno.\nEles obedecem a quaisquer comandos verbais que você\nemitir (não requer uma ação sua). Se você não emitir\nnenhum comando a elas, elas se defenderão de criaturas\nhostis, mas no mais, não realizarão nenhuma ação.\n    O Mestre possui as estatísticas das criaturas.\n    Em Níveis Superiores. Se você conjurar essa magia\nusando certos espaços de magia superiores, você escolhe\numa das opções de invocação acima e mais criaturas\naparecem: o dobro delas com um espaço de 6° nível e o\ntriplo delas com um espaço de 8° nível."},{"id":"conjurar-seres-da-floresta","name":"Conjurar Seres da Floresta","level":4,"school":"conjuração","ritual":false,"classes":["druida","patrulheiro"],"pdfPage":229,"time":"1 ação","range":"18 metros","components":"V, S, M (um fruto sagrado por criatura invocada)","duration":"Concentração, até 1 hora","concentration":true,"text":"4° nível de conjuração\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, S, M (um fruto sagrado por criatura\n   invocada)\nDuração: Concentração, até 1 hora\nVocê invoca criaturas feéricas que aparecem em espaços\ndesocupados, que você possa ver dentro do alcance.\nEscolha uma das opções a seguir para aparecer:\n   Uma criatura feérica de nível de desafio 2 ou inferior\n   Duas criaturas feéricas de nível de desafio 1 ou\n    inferior\n   Quatro criaturas feéricas de nível de desafio 1/2 ou\n    inferior\n   Oito criaturas feéricas de nível de desafio 1/4 ou\n    inferior\n   Uma criatura invocado desaparece quando cair a 0\npontos de vida ou quando a magia acabar.\n    As criaturas invocadas são amigáveis a você e a seus\ncompanheiros. Role a iniciativa para as criaturas\ninvocadas como um grupo, que age no seu próprio turno.\nEles obedecem a quaisquer comandos verbais que você\nemitir (não requer uma ação sua). Se você não emitir\nnenhum comando a elas, elas se defenderão de criaturas\nhostis, mas no mais, não realizarão nenhuma ação.\n    O Mestre possui as estatísticas das criaturas.\n    Em Níveis Superiores. Se você conjurar essa magia\nusando certos espaços de magia superiores, você escolhe\numa das opções de invocação acima e mais criaturas\naparecem: o dobro delas com um espaço de 6° nível e o\ntriplo delas com um espaço de 8° nível."},{"id":"controlar-a-agua","name":"Controlar a Água","level":4,"school":"transmutação","ritual":false,"classes":["clerigo","druida","mago"],"pdfPage":231,"time":"1 ação","range":"90 metros","components":"V, S, M (uma gota de água e uma pitada de poeira)","duration":"Concentração, até 10 minutos","concentration":true,"text":"4° nível de transmutação\nTempo de Conjuração: 1 ação\nAlcance: 90 metros\nComponentes: V, S, M (uma gota de água e uma pitada\n   de poeira)\nDuração: Concentração, até 10 minutos\nAté o fim da magia, você controla qualquer corpo de água\ndentro da área que você escolher, que é um cubo de 30\nmetros quadrados. Você pode escolher dentre quaisquer\ndos efeitos seguintes, quando você conjurar essa magia.\nCom uma ação no seu turno, você pode repetir o mesmo\nefeito ou escolher um diferente.\n    Inundação. Você faz com que o nível da água de toda\nárea afetada suba até 6 metros. Se a área incluir uma\nmargem, a inundação ira transbordar para a terra seca.\n    Se você escolher uma área em um extenso corpo de\nágua, ao invés disso, você cria uma onda com 6 metros de\naltura que irá de um lado ao outro da área e então\ndesaba. Qualquer veículo Enorme ou menor no caminho\nda onda será carregado por ela até o outro lado. Qualquer\nveículo Enorme ou menor atingido pela onda tem uma\nchance de 25 por cento de emborcar.\n    O nível da água se mantem elevado até a magia\nacabar ou você escolher um efeito diferente. Se esse efeito\nproduzir uma onda, a onda se repete no início do seu\npróximo turno enquanto o efeito de inundação durar.\n    Dividir Água. Você faz com que a água na área se\ndivida e crie uma trincheira. A trincheira se estende por\ntoda área da magia e a água separada forma uma parede\nde cada lado. A trincheira permanece até a magia acabar\nou você escolher um efeito diferente. A água, então,\nlentamente preenche a trincheira ao longo do curso da\npróxima rodada até o nível normal da água ser\nrestaurado.\n    Redirecionar Fluxo. Você faz com que o fluxo da\nágua na área se mova na direção que você escolher,\nmesmo que a água tenha que fluir através de obstáculos,\nsubir muros ou em outra direção improvável. A água na\nárea se move na direção ordenada, mas uma vez que\ntenha se movido além da área da magia, ela conclui seu\nfluxo baseado nas condições do terreno. A água continua a\nse mover na direção que você escolheu até a magia acabar\nou você escolher um efeito diferente.\n    Redemoinho. Esse efeito requer um corpo de água de,\npelo menos, 15 metros quadrados e 7,5 metros de\nprofundidade. Você faz com que um redemoinho se forme\nno centro da área. O redemoinho forma um vórtice com\n1,5 metro de largura na base, chegando a 15 metros de\nlargura no topo e 7,5 metros de altura. Qualquer criatura\nou objeto na água a até 7,5 metros do vórtice é puxado 3\nmetros na direção dele. Uma criatura pode tentar nadar\npara longe do vórtice com um teste de Força (Atletismo)\ncontra a CD da magia.\n    Quando uma criatura entrar no vórtice pela primeira\nvez no turno dela ou começar seu turno dentro dele, ela\ndeve realizar um teste de resistência de Força. Se falhar,\na criatura sofre 2d8 de dano de concussão e estará presa\nno vórtice até a magia acabar. Se passar na resistência, a\ncriatura sofre metade do dano e não estará presa no\nvórtice. Uma criatura presa no vórtice pode usar sua ação\npara tentar nadar para fora do vórtice como descrito\nacima, mas terá desvantagem no teste de Força\n(Atletismo) para fazer isso.\n     A primeira vez a cada turno que um objeto entrar no\n vórtice, o objeto sofre 2d8 de dano de concussão; esse dano\n se repete a cada rodada que ele permanecer no vórtice."},{"id":"cao-fiel-de-mordenkainen","name":"Cão Fiel de Mordenkainen","level":4,"school":"conjuração","ritual":false,"classes":["mago"],"pdfPage":224,"time":"1 ação","range":"9 metros","components":"V, S, M (um minúsculo apito de prata, um pedaço de osso e um fio)","duration":"8 horas","concentration":false,"text":"4° nível de conjuração\nTempo de Conjuração: 1 ação\nAlcance: 9 metros\nComponentes: V, S, M (um minúsculo apito de prata,\n   um pedaço de osso e um fio)\nDuração: 8 horas\nVocê conjura um cão de guarda fantasma em um espaço\ndesocupado que você possa ver, dentro do alcance, que\npermanece pela duração, até você dissipa-lo com uma\nação ou até você se mover para mais de 30 metros dele.\n    O cão é invisível para todas as criaturas, exceto para\nvocê, e não pode ser ferido. Quando uma criatura\nPequena ou maior se aproximar a 9 metros sem,\nprimeiramente, falar a senha que você especifica quando\nconjura a magia, o cão começa a latir muito alto. O cão vê\ncriaturas invisíveis e pode ver no Plano Etéreo. Ele ignora\nilusões.\n    No começo de cada um dos seus turnos, o cão tenta\nmorder uma criatura a 1,5 metro dele que seja hostil a\nvocê. O bônus de ataque do cão é igual ao seu modificador\nde habilidade de conjuração + seu bônus de proficiência.\nSe atingir, ele causa 4d8 de dano perfurante."},{"id":"destruicao-estonteante","name":"Destruição Estonteante","level":4,"school":"evocação","ritual":false,"classes":["paladino"],"pdfPage":237,"time":"1 ação bônus","range":"Pessoal","components":"V","duration":"Concentração, até 1 minuto","concentration":true,"text":"4° nível de evocação\nTempo de Conjuração: 1 ação bônus\nAlcance: Pessoal\nComponentes: V\nDuração: Concentração, até 1 minuto\nDa próxima vez que você atingir uma criatura com um\nataque corpo-a-corpo com arma, antes do fim da magia,\nsua arma penetra tanto no corpo quanto na mente e o\nataque causa 4d6 de dano psíquico adicional ao alvo. O\nalvo deve realizar um teste de resistência de Sabedoria.\nSe falhar na resistência, ele terá desvantagem nas\njogadas de ataque e testes de habilidade e não poderá\nefetuar reações até o final do próximo turno dele."},{"id":"dominar-besta","name":"Dominar Besta","level":4,"school":"encantamento","ritual":false,"classes":["druida","feiticeiro"],"pdfPage":239,"time":"1 ação","range":"18 metros","components":"V, S","duration":"Concentração, até 1 minuto","concentration":true,"text":"4° nível de encantamento\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, S\nDuração: Concentração, até 1 minuto\nVocê tenta seduzir uma besta que você possa ver dentro\ndo alcance. Ela deve ser bem sucedida num teste de\nresistência de Sabedoria ou ficará enfeitiçada por você\npela duração. Se você ou criaturas amigáveis a você\nestiverem lutando com ela, ela terá vantagem no teste de\nresistência.\n    Enquanto a besta estiver enfeitiçada, você terá uma\nligação telepática com ela, contanto que ambos estejam no\nmesmo plano de existência. Você pode usar essa ligação\ntelepática para emitir comandos para a criatura enquanto\nvocê estiver consciente (não requer uma ação), aos quais\nela obedece da melhor forma possível. Você pode\nespecificar um curso de ação simples e genérico, como\n“Ataque aquela criatura”, “Corra até ali”, ou “Traga\naquele objeto”. Se a criatura completar a ordem e não\nreceber direções posteriores de você, ela se defenderá e se\nauto preservará da melhor forma que puder.\n    Você pode usar sua ação para tomar controle total e\npreciso do alvo. Até o final do seu próximo turno, a\ncriatura realiza apenas as ações que você escolher e não\nfaz nada que você não permita que ela faça. Durante esse\nperíodo, você também pode fazer com que a criatura use\numa reação, mas isso requer que você usa sua própria\nreação também.\n    Cada vez que o alvo sofrer dano, ele realiza um novo\nteste de resistência de Sabedoria contra a magia. Se\nobtiver sucesso no teste de resistência, a magia termina.\n    Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 5° nível, a duração\nserá concentração, até 10 minutos. Quando você usar um\nespaço de magia de 6° nível, a duração será concentração,\naté 1 hora. Quando você usar um espaço de magia de 7°\nnível, a duração será concentração, até 8 horas."},{"id":"escudo-de-fogo","name":"Escudo de Fogo","level":4,"school":"evocação","ritual":false,"classes":["mago"],"pdfPage":242,"time":"1 ação","range":"Pessoal","components":"V, S, M (um pouco de fósforo ou um vaga- lume)","duration":"10 minutos","concentration":false,"text":"4° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: Pessoal\nComponentes: V, S, M (um pouco de fósforo ou um vaga-\n   lume)\nDuração: 10 minutos\nFinas e discretas chamas rodeiam seu corpo pela duração,\nemitindo luz plena em 3 metros de raio e penumbra por\nmais 3 metros adicionais. Você pode terminar a magia\nprematuramente usando sua ação para dissipa-la.\n   As chamas lhe conferem um escudo quente ou um\nescudo frio, à sua escolha. O escudo quente lhe garante\nresistência a dano de frio e o escudo frio lhe concede\nresistência a dano de fogo.\n   Além disso, sempre que uma criatura a 1,5 metro de\nvocê atingir você com um ataque corpo-a-corpo, o escudo\nexpele chamas. O atacante sofre 2d8 de dano de fogo do\nescudo quente ou 2d8 de dano de frio do escudo frio."},{"id":"esfera-resiliente-de-otiluke","name":"Esfera Resiliente de Otiluke","level":4,"school":"evocação","ritual":false,"classes":["mago"],"pdfPage":242,"time":"1 ação","range":"9 metros","components":"V, S, M (uma peça hemisférica de cristal transparente e uma peça hemisférica que combine de goma arábica)","duration":"Concentração, até 1 minuto","concentration":true,"text":"4° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: 9 metros\nComponentes: V, S, M (uma peça hemisférica de cristal\n   transparente e uma peça hemisférica que combine de\n   goma arábica)\nDuração: Concentração, até 1 minuto\nUma esfera de energia brilhante engloba uma criatura ou\nobjeto de tamanho Grande ou menor, dentro do alcance.\nUma criatura involuntária deve realizar um teste de\nresistência de Destreza. Se falhar na resistência, a\ncriatura estará enclausurada pela duração.\nNada – nem objetos físicos, energia ou outros efeitos\nmágicos – pode passar através da barreira, para dentro\nou para fora, apesar da criatura na esfera poder respirar\nlá dentro. A esfera é imune a todos os danos e a criatura\nou objeto dentro não pode sofrer dano de ataques ou\nefeitos originados de fora, nem a criatura dentro da\nesfera, pode causar dano a nada fora dela.\n   A esfera não tem peso e é grande o suficiente apenas\npara conter a criatura ou objeto dentro. Uma criatura\nenclausurada pode usar sua ação para empurrar a parede\nda esfera e, assim, rolar a esfera a metade do\ndeslocamento da criatura. Similarmente, o globo pode ser\nerguido e movido por outras criaturas.\n   A magia desintegrar lançada no globo o destruirá sem\ncausar ferimentos a nada dentro dele."},{"id":"fabricar","name":"Fabricar","level":4,"school":"transmutação","ritual":false,"classes":["mago"],"pdfPage":244,"time":"10 minutos","range":"36 metros","components":"V, S","duration":"Instantânea","concentration":false,"text":"4° nível de transmutação\nTempo de Conjuração: 10 minutos\nAlcance: 36 metros\nComponentes: V, S\nDuração: Instantânea\nVocê converte matéria-prima em produtos do mesmo\nmaterial. Por exemplo, você pode construir uma ponte de\nmadeira usando um amontoado de árvores, uma corda de\num pedaço de cânhamo e roupas usando linho ou lã.\n    Escolha matérias-primas que você possa ver, dentro do\nalcance. Você pode fabricar um objeto Grande ou menor\n(contido em 3 metros cúbicos ou em oito cubos de 1,5\nmetro conectados), tendo uma quantidade suficiente de\nmatéria-prima. Se você estiver trabalhando com metal,\npedra ou outra substância mineral, no entanto, o objeto\nfabricado não pode ser maior que Médio (contido em\napenas 1,5 metro cúbico). A quantidade de objetos feitos\npor essa magia é proporcional com a quantidade de\nmatéria-prima.\n    Criaturas ou itens mágicos não podem ser criados ou\ntransmutados por essa magia. Você também não pode\nusá-la para criar itens que, geralmente, requerem um alto\ngrau de perícia, como joalheria, armas, vidros ou\narmaduras, a não ser que você tenha proficiência com o\ntipo de ferramenta de artesanato usada para construir\ntais objetos."},{"id":"guardiao-da-fe","name":"Guardião da Fé","level":4,"school":"conjuração","ritual":false,"classes":["clerigo"],"pdfPage":248,"time":"1 ação","range":"9 metros","components":"V","duration":"8 horas","concentration":false,"text":"4° nível de conjuração\nTempo de Conjuração: 1 ação\nAlcance: 9 metros\nComponentes: V\nDuração: 8 horas\nUm guardião espectral Grande aparece e flutua, pela\nduração, em um espaço desocupado, à sua escolha, que\nvocê possa ver dentro do alcance. O guardião ocupa esse\nespaço e é indistinto, exceto por uma espada reluzente e\num escudo brasonado com o símbolo da sua divindade.\n   Qualquer criatura hostil a você que se mover para um\nespaço a até 3 metros do guardião pela primeira vez em\num turno, deve ser bem sucedida num teste de resistência\nde Destreza. A criatura sofre 20 de dano radiante se\nfalhar na resistência ou metade desse dano se obtiver\nsucesso. O guardião desaparece após ter causado um total\nde 60 de dano."},{"id":"inseto-gigante","name":"Inseto Gigante","level":4,"school":"transmutação","ritual":false,"classes":["druida"],"pdfPage":250,"time":"1 ação","range":"9 metros","components":"V, S","duration":"Concentração, até 10 minutos","concentration":true,"text":"4° nível de transmutação\nTempo de Conjuração: 1 ação\nAlcance: 9 metros\nComponentes: V, S\nDuração: Concentração, até 10 minutos\nVocê transforma até dez centopeias, três aranhas, cinco\nvespas ou um escorpião, dentro do alcance, em versões\ngigantes das suas formas naturais, pela duração. Uma\ncentopeia se torna uma centopeia gigante, uma aranha se\ntorna uma aranha gigante, uma vespa se torna uma\nvespa gigante e um escorpião se torna um escorpião\ngigante.\n   Cada criatura obedece aos seus comando verbais e, em\ncombate, elas agem no seu turno a cada rodada. O Mestre\npossui as estatísticas dessas criaturas e determina suas\nações e movimentação.\n    Uma criatura permanece no tamanho gigante pela\nduração, ou até cair a 0 pontos de vida ou até você usar\nsua ação para dissipar o efeito nela.\n    O Mestre pode permitir que você escolha alvos\ndiferentes. Por exemplo, se você transformar uma abelha,\nsua versão gigante poderia ter as mesmas estatísticas da\nvespa gigante."},{"id":"invisibilidade-maior","name":"Invisibilidade Maior","level":4,"school":"ilusão","ritual":false,"classes":["bardo","feiticeiro","mago"],"pdfPage":251,"time":"1 ação","range":"Toque","components":"V, S","duration":"Concentração, até 1 minuto","concentration":true,"text":"4° nível de ilusão\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S\nDuração: Concentração, até 1 minuto\nVocê ou uma criatura que você possa tocar, se torna\ninvisível até a magia acabar. Qualquer coisa que o alvo\nestiver vestindo ou carregando fica invisível enquanto\nestiver de posse do alvo."},{"id":"localizar-criatura","name":"Localizar Criatura","level":4,"school":"adivinhação","ritual":false,"classes":["bardo","clerigo","druida","mago","paladino","patrulheiro"],"pdfPage":253,"time":"1 ação","range":"Pessoal","components":"V, S, M (um pouco de pelo de um cão de caça)","duration":"Concentração, até 1 hora","concentration":true,"text":"4° nível de adivinhação\nTempo de Conjuração: 1 ação\nAlcance: Pessoal\nComponentes: V, S, M (um pouco de pelo de um cão de\n   caça)\nDuração: Concentração, até 1 hora\nDescreva ou nomeie uma criatura que seja familiar a\nvocê. Você sente a direção da localização da criatura,\ncontanto que a criatura esteja a até 300 metros de você.\nSe a criatura se mover, você saberá a direção do\nmovimento dela.\n   A magia pode localizar uma criatura especifica que\nvocê conheça ou a criatura mais próxima de um tipo\nespecifico (como um humano ou um unicórnio), desde que\nvocê já tenha visto tal criatura de perto – a até 9 metros –\npelo menos uma vez. Se a criatura que você descreveu ou\nnomeou estiver em uma forma diferente, como se estiver\nsob efeito da magia metamorfose, essa magia não\nlocalizará a criatura.\n   Essa magia não pode localizar uma criatura se água\ncorrente de, pelo menos 3 metros de largura, bloquear o\ncaminho direito entre você e a criatura."},{"id":"malogro","name":"Malogro","level":4,"school":"necromancia","ritual":false,"classes":["bruxo","druida","feiticeiro","mago"],"pdfPage":253,"time":"1 ação","range":"9 metros","components":"V, S","duration":"Instantânea","concentration":false,"text":"4° nível de necromancia\nTempo de Conjuração: 1 ação\nAlcance: 9 metros\nComponentes: V, S\nDuração: Instantânea\nEnergia necromântica inunda uma criatura, à sua\nescolha, que você possa ver dentro do alcance, drenando\nsua umidade e vitalidade. O alvo deve realizar um teste\nde resistência de Concentração. O alvo sofre 8d8 de dano\nnecrótico se falhar no teste, ou metade desse dano se\nobtiver sucesso. Essa magia não surte efeito em mortos-\nvivos ou constructos.\n   Se você afetar uma criatura planta ou planta mágica,\nela faz seu teste de resistência com desvantagem e a\nmagia causa o máximo de dano a ela.\n   Se você afetar uma planta não-mágica que não seja\numa criatura, como uma árvore ou arbusto, ele não faz\num teste de resistência; ela simplesmente seca e morre.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 5° nível ou\nsuperior, o dano aumenta em 1d8 para cada nível do\nespaço acima do 4°."},{"id":"metamorfose","name":"Metamorfose","level":4,"school":"transmutação","ritual":false,"classes":["bardo","druida","feiticeiro","mago"],"pdfPage":256,"time":"1 ação","range":"18 metros","components":"V, S, M (um casulo de lagarta)","duration":"Concentração, até 1 hora","concentration":true,"text":"4° nível de transmutação\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, S, M (um casulo de lagarta)\nDuração: Concentração, até 1 hora\nEssa magia transforma uma criatura que você possa ver,\ndentro do alcance, em uma nova forma. Uma criatura\ninvoluntária deve realizar um teste de resistência de\nSabedoria para evitar o efeito. Um metamorfo obtém\nsucesso automaticamente nesse teste de resistência.\n    A transformação permanece pela duração, ou até o\nalvo cair a 0 pontos de vida ou morrer. A nova forma pode\nser qualquer besta a qual o nível de desafio seja igual ou\nmenor que o do alvo (ou o nível do alvo, se ele não possuir\num nível de desafio). As estatísticas de jogo do alvo,\nincluindo seus valores de habilidades mentais, são\nsubstituídas pelas estatísticas da besta escolhida. Ele\nmantem sua tendência e personalidade.\n    O alvo assume os pontos de vida da sua nova forma.\nQuando ele reverter a sua forma normal, a criatura\nretorna à quantidade de pontos de vida que ela tinha\nantes da transformação. Se ela reverter como resultado de\nter caído a 0 pontos de vida, qualquer dano excedente é\nrecebido pela sua forma normal. Contanto que o dano\nexcedente não reduza os pontos de vida da forma normal\nda criatura a 0, ela não cairá inconsciente. Essa magia\nnão pode afetar um alvo com 0 pontos de vida.\n    A criatura é limitada em suas ações pela natureza da\nsua nova forma e ela não pode falar, conjurar magias ou\nrealizar qualquer outra ação que precise de mãos ou de\nvocalização.\n    O equipamento do alvo mescla-se a sua nova forma. O\nalvo não pode ativar, empunhar ou, de outra forma, se\nbeneficiar de qualquer de seus equipamentos."},{"id":"moldar-rochas","name":"Moldar Rochas","level":4,"school":"transmutação","ritual":false,"classes":["clerigo","druida","mago"],"pdfPage":258,"time":"1 ação","range":"Toque","components":"V, S, M (barro mole, que deve ser trabalhado aproximadamente com a forma desejada para o objeto de pedra)","duration":"Instantânea","concentration":false,"text":"4° nível de transmutação\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S, M (barro mole, que deve ser\n   trabalhado aproximadamente com a forma desejada\n   para o objeto de pedra)\nDuração: Instantânea\nVocê toca um objeto de pedra de tamanho Médio ou\nmenor, ou uma seção de rocha com não mais de 1,5 metro\nem qualquer dimensão e modela-a em qualquer forma que\nsirva aos seus propósitos. Então, por exemplo, você\npoderia modelar uma pedra grande em uma arma, ídolo\nou caixão, ou fazer uma pequena passagem através de um\nmuro, contanto que o muro não tenha mais de 1,5 metro\nde espessura. Você poderia, também, modelar uma porta\nde pedra ou sua moldura para selar a porta. O objeto que\nvocê cria pode ter até duas dobradiças e um trinco, mas\ndetalhes mecânicos mais complexos não são possíveis."},{"id":"movimentacao-livre","name":"Movimentação Livre","level":4,"school":"abjuração","ritual":false,"classes":["bardo","clerigo","druida","patrulheiro"],"pdfPage":259,"time":"1 ação","range":"Toque","components":"V, S, M (uma fita de couro, enrolada no braço ou apêndice similar)","duration":"1 hora","concentration":false,"text":"4° nível de abjuração\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S, M (uma fita de couro, enrolada no\n   braço ou apêndice similar)\nDuração: 1 hora\nVocê toca uma criatura voluntária. Pela duração, os\nmovimentos do alvo não são afetados por terreno difícil e\nmagias e outros efeitos mágicos também não podem\nreduzir o deslocamento do alvo ou fazer com que o alvo\nfique paralisado ou impedido.\n   O alvo também pode gastar 1,5 metro de deslocamento\npara escapar, automaticamente, de impedimentos não-\nmágicos, como algemas ou o agarrão de uma criatura.\nFinalmente, estar submerso não impõe penalidades no\ndeslocamento ou ataques do alvo."},{"id":"muralha-de-fogo","name":"Muralha de Fogo","level":4,"school":"evocação","ritual":false,"classes":["druida","feiticeiro","mago"],"pdfPage":259,"time":"1 ação","range":"36 metros","components":"V, S, M (um pequeno pedaço de fósforo)","duration":"Concentração, até 1 minuto","concentration":true,"text":"4° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: 36 metros\nComponentes: V, S, M (um pequeno pedaço de fósforo)\nDuração: Concentração, até 1 minuto\nVocê cria uma muralha de fogo numa superfície sólida\ndentro do alcance. Você pode fazer uma muralha de até\n18 metros de comprimento, 6 metros de altura e 30\ncentímetros de espessura ou uma muralha anelar de até 6\nmetros de diâmetro, 6 metros de altura e 30 centímetros\nde espessura. A muralha é opaca e permanece pela\nduração.\n    Quando a muralha aparece, cada criatura dentro da\nárea dela deve realizar um teste de resistência de\nDestreza. Se falhar na resistência, uma criatura sofrerá\n5d8 de dano, ou metade desse dano se passar na\nresistência.\n    Um lado da muralha, escolhido por você no momento\nda conjuração da magia, causa 5d8 de dano de fogo a cada\ncriatura que terminar o turno dela a até 3 metros desse\nlado ou dentro da muralha. Uma criatura sofre o mesmo\ndano quando entra na muralha pela primeira vez num\nturno ou termina seu turno nela. O outro lado da muralha\nnão causa dano algum.\n    Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 5° nível ou\nsuperior, o dano aumenta em 1d8 para cada nível do\nespaço acima do 4°."},{"id":"olho-arcano","name":"Olho Arcano","level":4,"school":"adivinhação","ritual":false,"classes":["mago"],"pdfPage":263,"time":"1 ação","range":"9 metros","components":"V, S, M (um punhado de pelo de morcego)","duration":"Concentração, até 1 hora","concentration":true,"text":"4° nível de adivinhação\nTempo de Conjuração: 1 ação\nAlcance: 9 metros\nComponentes: V, S, M (um punhado de pelo de morcego)\nDuração: Concentração, até 1 hora\nVocê cria um olho mágico invisível, dentro do alcance, que\nflutua no ar pela duração.\n    Você mentalmente recebe informações visuais do olho,\nque possui visão normal e visão no escuro com alcance de\n9 metros. O olho pode ver em todas as direções.\n    Com uma ação, você pode mover o olho até 9 metros\nem qualquer direção. Não existe limite de quão longe de\nvocê o olho pode se mover, mas ele não pode entrar em\noutro plano de existência. Uma barreira solida bloqueia o\nmovimento do olho, mas o olho pode passar através de\naberturas de até 3 centímetros de diâmetro."},{"id":"pele-de-pedra","name":"Pele de Pedra","level":4,"school":"abjuração","ritual":false,"classes":["druida","feiticeiro","mago","patrulheiro"],"pdfPage":266,"time":"1 ação","range":"Toque","components":"V, S, M (pó de diamante no valor de 100 po, consumido pela magia)","duration":"Concentração, até 1 hora","concentration":true,"text":"4° nível de abjuração\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S, M (pó de diamante no valor de 100\n   po, consumido pela magia)\nDuração: Concentração, até 1 hora\nEssa magia transforma a pele de uma criatura voluntária\nque você tocar em rocha sólida. Até a magia acabar, o alvo\ntem resistência a dano de concussão, cortante e\nperfurante não-mágico."},{"id":"porta-dimensional","name":"Porta Dimensional","level":4,"school":"conjuração","ritual":false,"classes":["bardo","bruxo","feiticeiro","mago"],"pdfPage":267,"time":"1 ação","range":"150 metros","components":"V","duration":"Instantânea","concentration":false,"text":"4° nível de conjuração\nTempo de Conjuração: 1 ação\nAlcance: 150 metros\nComponentes: V\nDuração: Instantânea\nVocê se teletransporte da sua posição atual para qualquer\nlocal dentro do alcance. Você aparece exatamente no local\ndesejado. Pode ser um lugar que você possa ver, um que\nvocê possa visualizar ou um que você possa descrever\nindicando a distância e direção, como “60 metros\ndiretamente pra baixo” ou “90 metros, subindo para\nnoroeste num ângulo de 45 graus”.\n   Você pode levar objetos com você, contanto que o peso\ndeles não exceda o que você pode carregar. Você também\npode levar uma criatura voluntária do seu tamanho ou\nmenor, que esteja carregando equipamento até o limite da\ncapacidade de carga dela. A criatura deve estar a 1,5\nmetro de você quando você conjurar a magia.\n   Se você aparecer em um lugar que já esteja ocupado\npor um objeto ou uma criatura, você e qualquer criatura\nviajando com você, sofrem 4d6 de dano de energia cada\num e a magia falha em teletransportar vocês."},{"id":"protecao-contra-a-morte","name":"Proteção contra a Morte","level":4,"school":"abjuração","ritual":false,"classes":["clerigo","paladino"],"pdfPage":270,"time":"1 ação","range":"Toque","components":"V, S","duration":"8 horas","concentration":false,"text":"4° nível de abjuração\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S\nDuração: 8 horas\nVocê toca uma criatura e concede a ela uma certa\nproteção contra a morte.\n    A primeira vez que o alvo cair a 0 pontos de vida, como\nresultado de ter sofrido dano, o alvo, ao invés disso, cai a\n1 ponto de vida e a magia termina.\n    Se a magia ainda estiver funcionando quando o alvo\nfor afetado por um efeito que poderia mata-lo\ninstantaneamente sem causar dano, o efeito, ao invés\ndisso, não funciona no alvo e a magia termina."},{"id":"santuario-particular-de-mordenkainen","name":"Santuário Particular de Mordenkainen","level":4,"school":"abjuração","ritual":false,"classes":["mago"],"pdfPage":278,"time":"10 minutos","range":"36 metros","components":"V, S, M (uma folha de chumbo, um pedaço de vidro opaco, um chumaço de algodão ou pano e pó de crisólita)","duration":"24 horas","concentration":false,"text":"4° nível de abjuração\nTempo de Conjuração: 10 minutos\nAlcance: 36 metros\nComponentes: V, S, M (uma folha de chumbo, um\n   pedaço de vidro opaco, um chumaço de algodão ou\n   pano e pó de crisólita)\nDuração: 24 horas\nVocê deixa uma área, dentro do alcance, magicamente\nsegura. A área é um cubo que pode ser tão pequeno\nquanto 1,5 metro ou tão grande quanto 30 metros de cada\nlado. A magia permanece pela duração ou até você usar\numa ação para dissipa-la.\n   Quando você conjura essa magia, você decide que tipo\nde segurança ela fornecerá, escolhendo qualquer ou todas\nas propriedades a seguir:\n   Sons não podem atravessar a barreira na fronteira da\n    área protegida.\n   A barreira da área protegida escura e nebulosa,\n    impedindo visão (inclusive visão no escuro) através\n    dela.\n   Sensores criados por magia de adivinhação não podem\n    aparecer dentro da área protegida ou atravessar a\n    barreira no perímetro.\n   As criaturas na área não podem ser alvo de magias de\n    adivinhação.\n   Nada pode se teletransportar para dentro ou para fora\n    da área protegida.\n   Viagem planar está bloqueada para dentro da área\n    protegida.\n    Conjurar essa magia no mesmo lugar, a cada dia, por\num ano, torna o efeito permanente.\n    Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 5° nível ou\nsuperior, você pode aumentar o tamanho do cubo em 30\nmetros de cada lado para cada nível do espaço acima do\n4°. Então, você poderia proteger um cubo de até 60 metros\nde lado usando um espaço de magia de 5° nível."},{"id":"tempestade-de-gelo","name":"Tempestade de Gelo","level":4,"school":"evocação","ritual":false,"classes":["druida","feiticeiro","mago"],"pdfPage":285,"time":"1 ação","range":"90 metros","components":"V, S, M (um pouco de poeira e algumas gotas de água)","duration":"Instantânea","concentration":false,"text":"4° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: 90 metros\nComponentes: V, S, M (um pouco de poeira e algumas\n   gotas de água)\nDuração: Instantânea\nUma rajada de pedras de gelo batem no chão em um\ncilindro de 6 metros de raio por 12 metros de altura,\ncentrado num ponto dentro do alcance. Cada criatura no\ncilindro deve realizar um teste de resistência de Destreza.\nUma criatura sofre 2d8 de dano de concussão e 4d6 de\ndano de frio se falhar na resistência ou metade desse\ndano se obtiver sucesso.\n    O granizo torna a área da tempestade em terreno\ndifícil até o final do seu próximo turno.\n    Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 5° nível ou\nsuperior, o dano de concussão aumenta em 1d8 para cada\nnível do espaço acima do 4°."},{"id":"tentaculos-negros-de-evard","name":"Tentáculos Negros de Evard","level":4,"school":"conjuração","ritual":false,"classes":["mago"],"pdfPage":285,"time":"1 ação","range":"27 metros","components":"V, S, M (um pedaço de tentáculo de um polvo gigante ou lula gigante)","duration":"Concentração, até 1 minuto","concentration":true,"text":"4° nível de conjuração\nTempo de Conjuração: 1 ação\nAlcance: 27 metros\nComponentes: V, S, M (um pedaço de tentáculo de um\n   polvo gigante ou lula gigante)\nDuração: Concentração, até 1 minuto\nTentáculos negros retorcidos preenchem um quadrado de\n6 metros no chão, que você possa ver dentro do alcance.\nPela duração, esses tentáculos transformam o solo na\nárea em terreno difícil.\n    Quando uma criatura adentrar a área afetada pela\nprimeira vez em um turno ou começar o turno dela lá, a\ncriatura deve ser bem sucedida num teste de resistência\nde Destreza ou sofrerá 3d6 de dano de concussão e estará\nimpedida pelos tentáculos até o fim da magia. Uma\ncriatura que começar seu turno na área e já estiver\nimpedida pelos tentáculos sofre 3d6 de dano de concussão.\n    Uma criatura impedida pelos tentáculos pode usar sua\nação para realizar um teste de Força ou Destreza (à\nescolha dela) contra a CD da sua magia. Se ela obtiver\nsucesso, ela se libertará."},{"id":"terreno-alucinogeno","name":"Terreno Alucinógeno","level":4,"school":"ilusão","ritual":false,"classes":["bardo","bruxo","druida","mago"],"pdfPage":285,"time":"10 minutos","range":"90 metros","components":"V, S, M (uma pedra, um galho e um pouco de planta verde)","duration":"24 horas","concentration":false,"text":"4° nível de ilusão\nTempo de Conjuração: 10 minutos\nAlcance: 90 metros\nComponentes: V, S, M (uma pedra, um galho e um\n   pouco de planta verde)\nDuração: 24 horas\nVocê faz com que um terreno natural num cubo de 45\nmetros dentro do alcance, pareça, soe e cheire com outro\ntipo de terreno natural. Portanto, campos abertos ou uma\nestrada podem ser modificados para se assemelharem a\num pântano, colina, fenda ou algum outro tipo de terreno\ndifícil ou intransponível. Uma lagoa pode ser modificada\npara se parecer com um prado, um precipício com um\ndeclive suave ou um barranco pedregoso com uma estrada\nlarga e lisa. Estruturas manufaturadas, equipamentos e\ncriaturas dentro da área não tem suas aparências\nmodificadas.\nAs características táteis do terreno são inalteradas,\nportanto, as criaturas que adentrarem na área estão\nsusceptíveis de ver através da ilusão. Se a diferença não\nfor obvia ao toque, uma criatura que examine a ilusão\ncuidadosamente, pode realizar um teste de Inteligência\n(Investigação) contra a CD da magia para desacredita-la.\nUma criatura que discernir a ilusão do que ela é, a\nenxerga como uma imagem vaga sobrepondo o terreno."},{"id":"vinha-esmagadora","name":"Vinha Esmagadora","level":4,"school":"conjuração","ritual":false,"classes":["druida","patrulheiro"],"pdfPage":288,"time":"1 ação bônus","range":"9 metros","components":"V, S","duration":"Concentração, até 1 minuto","concentration":true,"text":"4° nível de conjuração\nTempo de Conjuração: 1 ação bônus\nAlcance: 9 metros\nComponentes: V, S\nDuração: Concentração, até 1 minuto\nVocê conjura uma vinha que brota do chão em um espaço\ndesocupado, à sua escolha, que você possa ver dentro do\nalcance. Quando você conjura essa magia, você pode\ndirecionar a vinha para que ela enlace uma criatura a até\n9 metros dela que você possa ver. Essa criatura deve ser\nbem sucedida num teste de resistência de Destreza ou\nserá arrastada 6 metros na direção da vinha.\n   Até o fim da magia, você pode direcionar a vinha para\nenlaçar a mesma criatura ou uma diferente, com uma\nação bônus, em cada um dos seus turnos."},{"id":"aljava-veloz","name":"Aljava Veloz","level":5,"school":"transmutação","ritual":false,"classes":["patrulheiro"],"pdfPage":214,"time":"1 ação bônus","range":"Toque","components":"V, S, M (uma aljava contendo, pelo menos, uma munição)","duration":"Concentração, até 1 minuto","concentration":true,"text":"5° nível de transmutação\nTempo de Conjuração: 1 ação bônus\nAlcance: Toque\nComponentes: V, S, M (uma aljava contendo, pelo\n   menos, uma munição)\nDuração: Concentração, até 1 minuto\nVocê transmuta sua aljava para que ela produza um\nsuprimento interminável de munições não-mágicas, que\nparecem saltar na sua mão quando você tenta pega-las.\n    Em cada um dos seus turnos, até a magia acabar, você\npode usar uma ação bônus para realizar dois ataques com\numa arma que use munição de uma aljava. Cada vez que\nvocê fizer tais ataques à distância, sua aljava,\nmagicamente, repõe a munição que você usou com uma\nmunição não-mágica similar. Qualquer munição criada\npor essa magia se desintegra quando a magia acaba. Se a\naljava não estiver mais com você, a magia acaba."},{"id":"animar-objetos","name":"Animar Objetos","level":5,"school":"transmutação","ritual":false,"classes":["bardo","feiticeiro","mago"],"pdfPage":216,"time":"1 ação","range":"36 metros","components":"V, S","duration":"Concentração, até 1 minuto","concentration":true,"text":"5° nível de transmutação\n Tempo de Conjuração: 1 ação\n Alcance: 36 metros\n Componentes: V, S\n Duração: Concentração, até 1 minuto\n Objetos ganham vida ao seu comando. Escolha até dez\n objetos não-mágicos dentro do alcance, que não estejam\n sendo vestidos ou carregados. Alvos Médios contam como\n dois objetos, alvos Grandes contam como quatro objetos e\n alvos Enormes contam como oito objetos. Você não pode\n animar um objeto maior que Enorme. Cada alvo se anima\n e torna-se uma criatura sob seu controle até o final da\n magia ou até ser reduzido a 0 pontos de vida.\n     Com uma ação bônus, você pode comandar\n mentalmente qualquer criatura que você criar com essa\n magia se a criatura estiver a até 150 metros de você (se\n você controla várias criaturas, você pode comandar\n qualquer ou todas elas ao mesmo tempo, emitindo o\n mesmo comando para cada uma). Você decide qual ação a\n criatura irá fazer e para onde ela irá se mover durante o\n próximo turno dela, ou você pode emitir um comando\n geral, como para guardar uma câmara ou corredor\n especifico. Se você não der nenhum comando, as criaturas\n apenas se defenderão contra criaturas hostis. Uma vez\n que receba uma ordem, a criatura continuará a segui-la\n até a tarefa estar concluída.\n\nESTATÍSTICAS DE OBJETO ANIMADO\n Tamanho     PV   CA   Ataque                           For   Des\n Miúdo       20   18   +8 para atingir, 1d4 + 4 dano     4    18\n Pequeno     25   16   +6 para atingir, 1d8 + 2 dano     6    14\n Médio       40   13   +5 para atingir, 2d6 + 1 dano    10    12\n Grande      50   10   +6 para atingir, 2d10 + 2 dano   14    10\n Enorme      80   10   +8 para atingir, 2d12 + 4 dano   18     6\n\n     Um objeto animado é um constructo com CA, pontos\n de vida, ataques, Força e Destreza determinados pelo seu\n tamanho. Sua Constituição é 10 e sua Inteligência e\n Sabedoria são 3 e seu Carisma é 1. Seu deslocamento é 9\n metros; se o objeto não tiver pernas ou outros apêndices\n que ele possa usar para locomoção, ao invés, ele terá\n deslocamento de voo 9 metros e poderá planar. Se o objeto\n estiver firmemente preso a uma superfície ou objeto\n maior, como uma corrente presa a uma parede, seu\n deslocamento será 0. Ele tem percepção às cegas num raio\n de 9 metros e é cego além dessa distância. Quando o\n objeto animado cair a 0 pontos de vida, ele reverte a sua\n forma normal de objeto e qualquer dano restante é\n transferido para sua forma de objeto original.\n     Se você ordenar a um objeto que ataque, ele pode\n realizar um único ataque corpo-a-corpo contra uma\n criatura a até 1,5 metro dele. Ele realiza um ataque de\n pancada com um bônus de ataque e dano de concussão\n determinado pelo seu tamanho. O Mestre pode definir que\num objeto especifico inflige dano cortante ou perfurante,\nbaseado na forma dele.\n   Em Níveis Superiores. Se você conjurar essa magia\nusando um espaço de magia de 6° nível ou superior, você\npode animar dois objetos adicionais para cada nível do\nespaço acima do 5°."},{"id":"caminhar-em-arvores","name":"Caminhar em Árvores","level":5,"school":"conjuração","ritual":false,"classes":["druida","patrulheiro"],"pdfPage":223,"time":"1 ação","range":"Pessoal","components":"V, S","duration":"Concentração, até 1 minuto","concentration":true,"text":"5° nível de conjuração\nTempo de Conjuração: 1 ação\nAlcance: Pessoal\nComponentes: V, S\nDuração: Concentração, até 1 minuto\nVocê adquire a habilidade de entrar em uma árvore e se\nmover de dentro dela para dentro de outra árvore de\nmesmo tipo à até 150 metros. Ambas as árvores devem\nestar vivas e ter, pelo menos, o mesmo tamanho que você.\nVocê deve usar 1,5 metro de deslocamento para entrar\nnuma árvore. Você, instantaneamente, sabe a localização\nde todas as outras árvores de mesmo tipo à 150 metros e,\ncomo parte do movimento usado para entrar na árvore,\npode tanto passar por uma dessas árvores quanto sair da\nárvore em que você está. Você aparece no espaço que você\nquiser a 1,5 metro da árvore destino, usando outro\nmovimento de 1,5 metro. Se você não tiver movimento\nrestante, você aparece a 1,5 metro da árvore que você\nterminou seu movimento.\n   Você pode usar esse habilidade de transporte uma vez\npor rodada pela duração. Você deve terminar cada turno\nfora da árvore."},{"id":"coluna-de-chamas","name":"Coluna de Chamas","level":5,"school":"evocação","ritual":false,"classes":["clerigo"],"pdfPage":226,"time":"1 ação","range":"18 metros","components":"V, S, M (uma pitada de enxofre)","duration":"Instantânea","concentration":false,"text":"5° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, S, M (uma pitada de enxofre)\nDuração: Instantânea\nUma coluna vertical de fogo divino emerge de baixo para\nos céus, no local que você especificar. Cada criatura num\ncilindro de 3 metros de raio por 12 metros de altura,\ncentrado num ponto dentro do alcance, deve realizar um\nteste de resistência de Destreza. Uma criatura sofre 4d6\nde dano de fogo e 4d6 de dano radiante se falhar na\nresistência, ou metade desse dano se obtiver sucesso.\n    Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 6° nível ou\nsuperior, o dano de fogo ou o dano radiante (à sua\nescolha) aumenta em 1d6 por nível do espaço acima do 5°."},{"id":"comunhao","name":"Comunhão","level":5,"school":"adivinhação","ritual":true,"classes":["clerigo"],"pdfPage":227,"time":"1 minuto","range":"Pessoal","components":"V, S, M (incenso e um frasco de água benta ou profana)","duration":"1 minuto","concentration":false,"text":"5° nível de adivinhação (ritual)\nTempo de Conjuração: 1 minuto\nAlcance: Pessoal\nComponentes: V, S, M (incenso e um frasco de água\n   benta ou profana)\nDuração: 1 minuto\nVocê contata sua divindade ou um representante divino e\nfaz até três perguntas que podem ser respondidas com um\nsim ou não. Você deve fazer suas perguntas antes da\nmagia terminar. Você recebe uma resposta correta para\ncada pergunta.\n   Seres divinos não são necessariamente oniscientes,\nportanto, você pode receber “incerto” como uma resposta\nse uma pergunta que diga respeito a uma informação\nalém do conhecimento da divindade. Em caso de uma\nresposta de única palavra puder levar ao engano ou\ncontrariar os interesses da divindade, o Mestre pode\noferecer uma frase curta como resposta, no lugar.\n   Se você conjurar essa magia duas ou mais vezes antes\nde terminar um descanso longo, existe uma chance\ncumulativa de 25 por cento de cada conjuração, depois da\nprimeira que você fez, ter um resultado aleatório. O\nMestre faz essa jogada secretamente."},{"id":"comunhao-com-a-natureza","name":"Comunhão com a Natureza","level":5,"school":"adivinhação","ritual":true,"classes":["druida","patrulheiro"],"pdfPage":227,"time":"1 minuto","range":"Pessoal","components":"V, S","duration":"Instantânea","concentration":false,"text":"5° nível de adivinhação (ritual)\nTempo de Conjuração: 1 minuto\nAlcance: Pessoal\nComponentes: V, S\nDuração: Instantânea\nVocê, momentaneamente, se torna uno com a natureza e\nganha conhecimento do território ao seu redor. Ao ar\nlivre, a magia lhe oferece conhecimento do terreno a até\n4,5 quilômetros de você. Em cavernas e outros formações\nsubterrâneas naturais, o raio é limitado a 150 metros. A\nmagia não funciona onde a natureza foi substituída por\nconstruções, como em masmorras ou cidades.\n    Você, instantaneamente, adquire conhecimento de até\ntrês fatos, à sua escolha, sobre qualquer dos assuntos a\nseguir, relacionados a área:\n   Terrenos e corpos de água\n   Plantas, minérios, animais e povo predominante\n   Celestiais, fadas, corruptores, elementais ou mortos-\n    vivos mais poderosos\n   Influência de outros planos de existência\n   Construções\n   Por exemplo, você poderia determinar a localização de\num morto-vivo poderoso na área, a localização da maior\nfonte de água potável e a localização de quaisquer cidades\npróximas."},{"id":"cone-de-frio","name":"Cone de Frio","level":5,"school":"evocação","ritual":false,"classes":["feiticeiro","mago"],"pdfPage":227,"time":"1 ação","range":"Pessoal (cone de 18 metros)","components":"V, S, M (um pequeno cristal ou cone de vidro)","duration":"Instantânea","concentration":false,"text":"5° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: Pessoal (cone de 18 metros)\nComponentes: V, S, M (um pequeno cristal ou cone de\n  vidro)\nDuração: Instantânea\nUma explosão de ar gelado irrompe das suas mãos. Cada\ncriatura dentro do cone de 18 metros, deve realizar um\nteste de resistência de Constituição. Uma criatura sofre\n8d8 de dano de frio se falhar na resistência, ou metade\ndesse dano se passar.\n    Uma criatura morta por essa magia se torna uma\nestátua congelada até derreter.\n    Em Níveis Superiores. Se você conjurar essa magia\nusando um espaço de magia de 6° nível ou superior, o\ndano aumenta em 1d8 para cada nível do espaço acima do\n5°."},{"id":"conhecimento-lendario","name":"Conhecimento Lendário","level":5,"school":"adivinhação","ritual":false,"classes":["bardo","clerigo","mago"],"pdfPage":227,"time":"10 minutos","range":"Pessoal","components":"V, S, M (incenso valendo, no mínimo, 250 po, consumido pela magia e quatro tiras de marfim valendo, no mínimo, 50 po cada)","duration":"Instantânea","concentration":false,"text":"5° nível de adivinhação\nTempo de Conjuração: 10 minutos\nAlcance: Pessoal\nComponentes: V, S, M (incenso valendo, no mínimo, 250\n   po, consumido pela magia e quatro tiras de marfim\n   valendo, no mínimo, 50 po cada)\nDuração: Instantânea\nNomeie ou descreva uma pessoa, local ou objeto. A magia\ntraz a sua mente um breve resumo do conhecimento\nsignificativo sobre a coisa que você nomeou. O\nconhecimento deve consistir em contos atuais, histórias\nesquecidas ou, até mesmo, conhecimento secreto que\nnunca foi amplamente divulgado. Se a coisa que você\nnomeou não for de importância lendária, você não recebe\nqualquer informação sofre ela. Quanto mais informação\nvocê possuir sobre a coisa, mais precisa e detalhada será\na informação que você receberá.\n    A informação que você aprende é precisa, mas pode ser\nredigida em linguagem figurada. Por exemplo, se você\npossuir um misterioso machado mágico na mão, a magia\npode proporcionar essa informação: “Ai do malfeitor cuja\nmão toca o machado, até mesmo seu cabo corta a mão dos\nmalignos. Só um verdadeiro Filho da Pedra, adorador e\nadorado de Moradin, pode despertar os verdadeiros\npoderes do machado e apenas com a palavra sagrada\nRudnogg nos lábios.”"},{"id":"conjurar-elemental","name":"Conjurar Elemental","level":5,"school":"conjuração","ritual":false,"classes":["druida","mago"],"pdfPage":228,"time":"1 minuto","range":"27 metros","components":"V, S, M (incenso aceso para ar, argila mole para terra, enxofre e fósforo para fogo ou água e areia para água)","duration":"Concentração, até 1 hora","concentration":true,"text":"5° nível de conjuração\nTempo de Conjuração: 1 minuto\nAlcance: 27 metros\nComponentes: V, S, M (incenso aceso para ar, argila\n   mole para terra, enxofre e fósforo para fogo ou água e\n   areia para água)\nDuração: Concentração, até 1 hora\nVocê invoca um servo elemental. Escolha uma área de ar,\nágua, fogo ou terra que preencha 3 metros cúbicos, dentro\ndo alcance. Um elemental de nível de desafio 5 ou\ninferior, adequado a área que você escolheu, aparece em\num espaço desocupado a até 3 metros dela. Por exemplo,\num elemental do fogo emergiria de uma fogueira e um\nelemental da terra erguer-se-ia do solo. O elemental\ndesaparece quando cair a 0 pontos de vida ou quando a\nmagia acabar.\n   O elemental é amigável a você e a seus companheiros\npela duração. Role a iniciativa para o elemental, que age\nno seu próprio turno. Ele obedece a quaisquer comandos\nverbais que você emitir (não requer uma ação sua). Se\nvocê não emitir nenhum comando a ele, ele se defenderá\nde criaturas hostis, mas no mais, não realizará nenhuma\nação.\n    Se sua concentração for interrompida, o elemental\nnão desaparece. Ao invés disso, você perde o controle\nsobre o elemental e ele se torna hostil a você e aos seus\ncompanheiros, e irá atacar. Um elemental fora de controle\nnão pode ser dispensado e desaparece 1 hora depois de\nvocê ter o invocado."},{"id":"conjurar-saraivada","name":"Conjurar Saraivada","level":5,"school":"conjuração","ritual":false,"classes":["patrulheiro"],"pdfPage":229,"time":"1 ação","range":"45 metros","components":"V, S, M (uma munição ou arma de arremesso)","duration":"Instantânea","concentration":false,"text":"5° nível de conjuração\nTempo de Conjuração: 1 ação\nAlcance: 45 metros\nComponentes: V, S, M (uma munição ou arma de\n   arremesso)\nDuração: Instantânea\nVocê dispara uma munição não-mágica de uma arma à\ndistância ou arremessa uma arma não-mágica no ar e\nescolhe um ponto dentro do alcance. Centenas de\nduplicatas da munição ou arma caem em uma saraivada\nvinda de cima e então desaparecem. Cada criatura num\ncilindro com 12 metros de raio e 6 metros de altura\ncentrado no ponto, deve realizar um teste de resistência\nde Destreza. Uma criatura sofre 8d8 de dano se falhar na\nresistência, ou metade desse dano num sucesso. O tipo do\ndano é o mesmo da munição ou arma."},{"id":"consagrar","name":"Consagrar","level":5,"school":"evocação","ritual":false,"classes":["clerigo"],"pdfPage":229,"time":"24 horas","range":"Toque","components":"V, S, M (ervas, óleos e incenso valendo, no mínimo, 1.000 po, consumidos pela magia)","duration":"Até ser dissipada","concentration":false,"text":"5° nível de evocação\nTempo de Conjuração: 24 horas\nAlcance: Toque\nComponentes: V, S, M (ervas, óleos e incenso valendo,\n   no mínimo, 1.000 po, consumidos pela magia)\nDuração: Até ser dissipada\nVocê toca um ponto e infunde uma área ao redor com\npoder sagrado (ou profano). A área pode ter até 18 metros\nde raio e a magia falha se o raio incluir uma área já sob\nefeito da magia consagrar. A área afetada está sujeita aos\nseguintes efeitos.\n    Primeiro, celestiais, corruptores, elementais, fadas e\nmortos-vivos não conseguem entrar na área, nem, tais\ncriaturas, podem enfeitiçar, amedrontar ou possuir\ncriaturas dentro da área. Qualquer criatura enfeitiçada,\namedrontada ou possuída por uma criatura dessas, não\nestará mais enfeitiçada, amedrontada ou possuída ao\nadentrar a área. Você pode excluir um ou mais desses\ntipos de criaturas desse efeito.\n    Segundo, você pode vincular um efeito extra a área.\nEscolha o efeito da lista a seguir, ou escolha um efeito\noferecido pelo Mestre. Alguns desses efeitos se aplicam a\ncriaturas na área; você pode definir seu o efeito se aplica\na todas as criaturas, criaturas que seguem uma divindade\nou líder especifico ou criaturas de uma espécie especifica,\ncomo orcs ou trolls. Quando uma criatura que seria\nafetada entrar na área da magia pela primeira vez em um\nturno, ou começar seu turno nela, ela pode fazer um teste\nde resistência de Carisma. Se obtiver sucesso, a criatura\nignora o efeito extra até sair da área.\n    Coragem. As criaturas afetadas não podem ser\namedrontadas enquanto estiverem na área.\n    Descanso Eterno. Cadáveres enterrados na área não\npodem ser transformados em mortos-vivos.\n    Escuridão. Escuridão preenche a área. Luz normal,\nassim como luz mágica criada por magias de nível inferior\nao nível do espaço usado para conjurar essa magia, não\npodem iluminar a área.\n    Idiomas. As criaturas afetadas podem se comunicar\ncom qualquer outra criatura na área, mesmo que elas não\npartilhem um idioma em comum.\n    Interferência Extradimensional. As criaturas\nafetadas não podem se mover ou viajar usando\nteletransporte ou por meios extradimensionais ou\ninterplanares.\n    Luz do Dia. Luz plena preenche a área. Escuridão\nmágica criada por magias de nível inferior ao nível do\nespaço usado para conjurar essa magia, não podem\nextinguir a luz.\n    Medo. As criaturas afetadas ficam amedrontadas\nenquanto estiverem na área.\n    Proteção contra Energia. As criaturas afetadas na\nárea tem resistência a um tipo de dano, à sua escolha,\nexceto de concussão, cortante ou perfurante.\n    Silêncio. Nenhum som pode ser emitido de dentro da\nárea e nenhum som pode adentra-la.\n    Vulnerabilidade à Energia. As criaturas afetadas\nna área tem vulnerabilidade a um tipo de dano, à sua\nescolha, exceto de concussão, cortante ou perfurante."},{"id":"contato-extraplanar","name":"Contato Extraplanar","level":5,"school":"adivinhação","ritual":true,"classes":["bruxo","mago"],"pdfPage":230,"time":"1 minuto","range":"Pessoal","components":"V","duration":"1 minuto","concentration":false,"text":"5° nível de adivinhação (ritual)\nTempo de Conjuração: 1 minuto\nAlcance: Pessoal\nComponentes: V\nDuração: 1 minuto\nVocê contata mentalmente um semideus, o espírito de um\nsábio morto há muito tempo ou alguma outra entidade\nmisteriosa de outro plano. Contatar esse extraplanar\ninteligente pode distorcer ou até mesmo arruinar com sua\nmente. Quando você conjurar essa magia, faça um teste\nde resistência de Inteligência CD 15. Se falhar, você sofre\n6d6 de dano psíquico e fica insano até terminar um\ndescanso longo. Enquanto estiver insano, você não pode\nrealizar ações, não entende o que as outras criaturas\ndizem, não pode ler e fala apenas coisas sem sentido.\nConjurar a magia restauração maior em você acaba com\nesse efeito.\n   Se obtiver sucesso no teste de resistência, você pode\nfazer até cinco perguntas à entidade. Você deve fazer suas\nperguntas antes da magia acabar. O Mestre responde\ncada pergunta com uma única palavra, como “sim”, “não”,\n“talvez”, “nunca”, “irrelevante” ou “incerto” (se a entidade\nnão souber a resposta para a pergunta). Em caso de uma\nresposta de única palavra puder levar ao engano, o\nMestre pode, ao invés disso, oferecer uma frase curta\ncomo resposta."},{"id":"criar-passagem","name":"Criar Passagem","level":5,"school":"transmutação","ritual":false,"classes":["mago"],"pdfPage":234,"time":"1 ação","range":"9 metros","components":"V, S, M (algumas sementes de gergelim)","duration":"1 hora","concentration":false,"text":"5° nível de transmutação\nTempo de Conjuração: 1 ação\nAlcance: 9 metros\nComponentes: V, S, M (algumas sementes de gergelim)\nDuração: 1 hora\nUma passagem aparece em um ponto, à sua escolha, que\nvocê possa ver em uma superfície de madeira, gesso ou\nrocha (como um muro, um teto ou um piso) dentro do\nalcance e permanece pela duração. Você escolhe as\ndimensões da passagem: até 1,5 metro de largura, 2,10 de\naltura e 6 metros de profundidade. A passagem não\nprovoca instabilidade na estrutura ao seu redor.\n   Quando a abertura desaparecer, qualquer criatura ou\nobjeto que ainda estiver dentro da passagem criada pela\nmagia é ejetada em segurança para o espaço desocupado\nmais próximo da superfície onde a magia foi conjurada."},{"id":"criacao","name":"Criação","level":5,"school":"ilusão","ritual":false,"classes":["feiticeiro","mago"],"pdfPage":233,"time":"1 minuto","range":"9 metros","components":"V, S, M (um pequeno pedaço de material do mesmo tipo do item que você planeja criar)","duration":"Especial","concentration":false,"text":"5° nível de ilusão\nTempo de Conjuração: 1 minuto\nAlcance: 9 metros\nComponentes: V, S, M (um pequeno pedaço de material\n   do mesmo tipo do item que você planeja criar)\nDuração: Especial\nVocê puxa mechas de matéria sombria da Umbra para\ncriar objetos inanimados de matéria vegetal dentro do\nalcance: bens finos, cordas, madeira ou algo similar. Você\ntambém pode usar a magia para criar objetos minerais\ncomo pedra, cristal ou metal. O objeto criado não pode ser\nmaior que um cubo de 1,5 metro e o objeto deve ser de um\nformado e material que você já tenha visto antes.\n    A duração depende do material do objeto. Se o objeto\nfor composto por diversos materiais, use o de menor\nduração.\n\nMaterial                 Duração\nMatéria vegetal          1 dia\nPedra ou cristal         12 horas\nMetais preciosos         1 hora\nGemas                    10 minutos\nAdamante ou mitral       1 minuto\n\n   Usar qualquer material criado por essa magia como\ncomponente material de outra magia faz com que a magia\nfalhe.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 6° nível ou\nsuperior, o tamanho do cubo aumenta em 1,5 metro para\ncada nível do espaço de magia acima do 5°."},{"id":"curar-ferimentos-em-massa","name":"Curar Ferimentos em Massa","level":5,"school":"evocação","ritual":false,"classes":["bardo","clerigo","druida"],"pdfPage":235,"time":"1 ação","range":"18 metros","components":"V, S","duration":"Instantânea","concentration":false,"text":"5° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, S\nDuração: Instantânea\nUma onda de energia curativa emerge de um ponto, à sua\nescolha, dentro do alcance. Escolha até seis criaturas\nnuma esfera de 9 metros de raio, centrada nesse ponto.\nCada alvo recupera uma quantidade de pontos de vida\nigual a 3d8 + seu modificador de habilidade de\nconjuração. A magia não afeta mortos-vivos ou\nconstructos.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 6° nível ou\nsuperior, a cura aumenta em 1d8 para cada nível do\nespaço acima do 5°."},{"id":"circulo-de-poder","name":"Círculo de Poder","level":5,"school":"abjuração","ritual":false,"classes":["paladino"],"pdfPage":225,"time":"1 ação","range":"Pessoal (9 metros de raio)","components":"V","duration":"Concentração, até 10 minutos","concentration":true,"text":"5° nível de abjuração\nTempo de Conjuração: 1 ação\nAlcance: Pessoal (9 metros de raio)\nComponentes: V\nDuração: Concentração, até 10 minutos\nEnergia divina irradia de você, distorcendo e espalhando\nenergia mágica a até 9 metros de você. Até a magia\nacabar, a esfera se move com você, centrada em você. Pela\nduração, cada criatura amigável na área (incluindo você)\ntem vantagem em testes de resistência contra magias e\noutros efeitos mágicos. Além disso, quando uma criatura\nafetada for bem sucedida num teste de resistência contra\numa magia ou efeito mágico realizado para sofrer apenas\nmetade do dano, ao invés disso, ela não sofrerá dano\nnenhum se passar na resistência."},{"id":"circulo-de-teletransporte","name":"Círculo de Teletransporte","level":5,"school":"conjuração","ritual":false,"classes":["bardo","feiticeiro","mago"],"pdfPage":225,"time":"1 minuto","range":"3 metros","components":"V, M (giz e tintas raros infundidos com pedras preciosas no valor de 50 po, consumidos pela magia)","duration":"1 rodada","concentration":false,"text":"5° nível de conjuração\nTempo de Conjuração: 1 minuto\nAlcance: 3 metros\nComponentes: V, M (giz e tintas raros infundidos com\n   pedras preciosas no valor de 50 po, consumidos pela\n   magia)\nDuração: 1 rodada\nÀ medida que você conjura essa magia, você desenha um\ncírculo de 3 metros de diâmetro no chão, inscrevendo\nselos que conectam sua localização a um círculo de\nteletransporte permanente, à sua escolha, cuja sequência\nde selos você conheça e esteja no mesmo plano de\nexistência que você. Um portal cintilante se abre dentro\ndo círculo que você desenhou e permanece aberto até o\nfinal do seu próximo turno. Qualquer criatura que entrar\nno portal, instantaneamente, aparecerá a 1,5 metro do\ncírculo de destino ou no espaço desocupado mais próximo,\nse o espaço estiver ocupado.\n    Muitos templos principais, guildas e outros locais\nimportantes possuem círculos de teletransporte\npermanentes inscritos em algum lugar dos seus confins.\nCada círculo desse inclui uma sequência única de selos –\numa sequência de runas mágicas dispostas em um padrão\nespecífico. Quando você adquire a capacidade de conjurar\nessa magia pela primeira vez, você aprende a sequência\nde selos de dois destinos no Plano Material, determinadas\npelo Mestre. Você pode aprender sequências de selos\nadicionais durante suas aventuras. Você pode consignar\numa nova sequência de selos a memória após estuda-la\npor 1 minuto.\n    Você pode criar um círculo de teletransporte\npermanente ao conjurar essa magia no mesmo local a\ncada dia por um ano. Você não precisa usar o círculo para\nse teletransportar quando você conjurar a magia desse\nmodo."},{"id":"cupula-antivida","name":"Cúpula Antivida","level":5,"school":"abjuração","ritual":false,"classes":["druida"],"pdfPage":234,"time":"1 ação","range":"Pessoal (3 metros de raio)","components":"V, S","duration":"Concentração, até 1 hora","concentration":true,"text":"5° nível de abjuração\nTempo de Conjuração: 1 ação\nAlcance: Pessoal (3 metros de raio)\nComponentes: V, S\nDuração: Concentração, até 1 hora\nUma barreira cintilante se estende de você até 3 metros\nde raio, e se move com você, permanecendo centrada em\nvocê e restringindo criaturas diferentes de mortos-vivos e\nconstructos. A barreira mantem-se pela duração.\n    A barreira previna uma criatura afetada de atravessa-\nla ou alcançar através dela. Uma criatura afetada pode\nconjurar magias ou realizar ataques à distância ou\nataques com armas de haste através da barreira.\n    Se você se mover forçando uma criatura afetada a\natravessar a barreira, a magia termina."},{"id":"despertar","name":"Despertar","level":5,"school":"transmutação","ritual":false,"classes":["bardo","druida"],"pdfPage":236,"time":"8 horas","range":"Toque","components":"V, S, M (uma ágata valendo, no mínimo, 1.000 po que será consumida pela magia)","duration":"Instantânea","concentration":false,"text":"5° nível de transmutação\nTempo de Conjuração: 8 horas\nAlcance: Toque\nComponentes: V, S, M (uma ágata valendo, no mínimo,\n   1.000 po que será consumida pela magia)\nDuração: Instantânea\nDepois de gastar o tempo de conjuração traçando runas\nmágicas com uma gema preciosa, você toca uma besta ou\nplanta Enorme ou menor. O alvo deve ter ou um valor de\nInteligência nulo, ou Inteligência 3 ou menor. O alvo\nganha Inteligência 10. O alvo também ganha a\ncapacidade de falar um idioma que você conheça. Se o\nalvo for uma planta, ela ganha a habilidade de mover\nseus membros, raízes, vinhas, trepadeiras e assim por\ndiante, e ganha sentidos similares ao de um humano. Seu\nMestre escolhe as estatísticas apropriadas para o arbusto\ndesperto ou árvore desperta.\n   A besta ou planta desperta estará enfeitiçada por você\npor 30 dias ou até você ou seus companheiros fazerem\nqualquer coisa nociva contra ela. Quando a condição\nenfeitiçado terminar, a criatura desperta pode escolher\npermanecer amigável a você, baseado em como ela foi\ntratada enquanto estava enfeitiçada."},{"id":"despistar","name":"Despistar","level":5,"school":"ilusão","ritual":false,"classes":["bardo","mago"],"pdfPage":236,"time":"1 ação","range":"Pessoal","components":"S","duration":"Concentração, até 1 hora","concentration":true,"text":"5° nível de ilusão\nTempo de Conjuração: 1 ação\nAlcance: Pessoal\nComponentes: S\nDuração: Concentração, até 1 hora\nVocê fica invisível ao mesmo tempo que uma cópia\nilusória sua aparece onde você estava. A cópia permanece\npela duração, mas a invisibilidade acaba se você atacar ou\nconjurar uma magia.\n    Você pode usar sua ação para mover a cópia ilusória\naté o dobro do seu deslocamento e fazê-la gesticular, falar\ne se comportar da forma que você quiser.\nVocê pode ver através dos olhos e ouvir através dos\nouvidos da cópia como se você estivesse localizado onde\nela está. Em cada um dos seus turnos, com uma ação\nbônus, você pode trocar o uso dos sentidos dela pelo seu\nou voltar novamente. Enquanto você está usando os\nsentidos dela, você fica cego e surdo ao que está a sua\nvolta."},{"id":"destruicao-banidora","name":"Destruição Banidora","level":5,"school":"abjuração","ritual":false,"classes":["paladino"],"pdfPage":236,"time":"1 ação bônus","range":"Pessoal","components":"V","duration":"Concentração, até 1 minuto","concentration":true,"text":"5° nível de abjuração\nTempo de Conjuração: 1 ação bônus\nAlcance: Pessoal\nComponentes: V\nDuração: Concentração, até 1 minuto\nDa próxima vez que você atingir uma criatura com um\nataque com arma, antes do fim da magia, seu ataque\ncrepita com energia e o ataque causa 5d6 de dano de\nenergia extra ao alvo. Além disso, se esse ataque reduzir o\nalvo a 50 pontos de vida ou menos, você a bane. Se o alvo\nfor nativo de um plano de existência diferente do que você\nestá, o alvo desaparece, retornando ao seu plano natal. Se\no alvo for nativo do plano que você está, a criatura é\nenviada para um semiplano inofensivo. Enquanto estiver\nlá, a criatura estará incapacitada. Ela permanece lá até a\nmagia acabar, a partir desse ponto, o alvo reaparece no\nespaço em que ela deixou ou no espaço desocupado mais\npróximo, se o espaço dela estiver ocupado."},{"id":"dissipar-o-bem-e-mal","name":"Dissipar o Bem e Mal","level":5,"school":"abjuração","ritual":false,"classes":["clerigo","paladino"],"pdfPage":239,"time":"1 ação","range":"Pessoal","components":"V, S, M (água benta ou pó de prata e ferro)","duration":"Concentração, até 1 minuto","concentration":true,"text":"5° nível de abjuração\nTempo de Conjuração: 1 ação\nAlcance: Pessoal\nComponentes: V, S, M (água benta ou pó de prata e\n   ferro)\nDuração: Concentração, até 1 minuto\nEnergia cintilante envolve e protege você de fadas,\nmortos-vivos e criaturas originarias além do Plano\nMaterial. Pela duração, celestiais, corruptores,\nelementais, fadas e mortos-vivos tem desvantagem nas\njogadas de ataque contra você.\n   Você pode terminar a magia prematuramente usando\numa das funções especiais a seguir.\n   Cancelar Encantamento. Com sua ação, você toca\numa criatura que você possa alcançar que esteja\nenfeitiçada, amedrontada ou possuída por um celestial,\ncorruptor, elemental, fada ou morto-vivo. A criatura\ntocada não estará mais enfeitiçada, amedrontada ou\npossuída por tais criaturas.\n   Demissão. Com sua ação, faça um ataque corpo-a-\ncorpo com magia contra um celestial, corruptor,\nelemental, fada ou morto-vivo que você possa alcançar. Se\natingir, você pode tentar guiar a criatura de volta ao seu\nplano natal. A criatura deve ser bem sucedida num teste\nde resistência de Carisma ou será enviada de volta ao seu\nplano natal (se já não for aqui). Se elas não estiverem em\nseus planos de origem, mortos-vivos serão enviados para\nUmbra e fadas serão enviadas para Faéria."},{"id":"dominar-pessoa","name":"Dominar Pessoa","level":5,"school":"encantamento","ritual":false,"classes":["bardo","feiticeiro","mago"],"pdfPage":240,"time":"1 ação","range":"18 metros","components":"V, S","duration":"Concentração, até 1 minuto","concentration":true,"text":"5° nível de encantamento\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, S\nDuração: Concentração, até 1 minuto\nVocê tenta seduzir um humanoide que você possa ver\ndentro do alcance. Ele deve ser bem sucedido num teste\nde resistência de Sabedoria ou ficará enfeitiçado por você\npela duração. Se você ou criaturas amigáveis a você\nestiverem lutando com ele, ele terá vantagem no teste de\nresistência.\n    Enquanto o alvo estiver enfeitiçado, você terá uma\nligação telepática com ela, contanto que ambos estejam no\nmesmo plano de existência. Você pode usar essa ligação\ntelepática para emitir comandos para a criatura enquanto\nvocê estiver consciente (não requer uma ação), aos quais\nela obedece da melhor forma possível. Você pode\nespecificar um curso de ação simples e genérico, como\n“Ataque aquela criatura”, “Corra até ali”, ou “Traga\naquele objeto”. Se a criatura completar a ordem e não\nreceber direções posteriores de você, ela se defenderá e se\nauto preservará da melhor forma que puder.\n    Você pode usar sua ação para tomar controle total e\npreciso do alvo. Até o final do seu próximo turno, a\ncriatura realiza apenas as ações que você escolher e não\nfaz nada que você não permita que ela faça. Durante esse\nperíodo, você também pode fazer com que a criatura use\numa reação, mas isso requer que você usa sua própria\nreação também.\n    Cada vez que o alvo sofrer dano, ele realiza um novo\nteste de resistência de Sabedoria contra a magia. Se\nobtiver sucesso no teste de resistência, a magia termina.\n    Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 6° nível, a duração\nserá concentração, até 10 minutos. Quando você usar um\nespaço de magia de 7° nível, a duração será concentração,\naté 1 hora. Quando você usar um espaço de magia de 8°\nnível, a duração será concentração, até 8 horas."},{"id":"imobilizar-monstro","name":"Imobilizar Monstro","level":5,"school":"encantamento","ritual":false,"classes":["bardo","bruxo","feiticeiro","mago"],"pdfPage":250,"time":"1 ação","range":"27 metros","components":"V, S, M (uma pequena peça de ferro reta)","duration":"Concentração, até 1 minuto","concentration":true,"text":"5° nível de encantamento\nTempo de Conjuração: 1 ação\nAlcance: 27 metros\nComponentes: V, S, M (uma pequena peça de ferro reta)\nDuração: Concentração, até 1 minuto\nEscolha uma criatura que você possa ver, dentro do\nalcance. O alvo deve ser bem sucedido num teste de\nresistência de Sabedoria ou ficará paralisado pela\nduração. Essa magia não tem efeito em mortos-vivos. No\nfinal de cada um dos turnos dele, o alvo pode realizar\noutro teste de resistência de Sabedoria. Se obtiver\nsucesso, a magia termina no alvo.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 6° nível ou\nsuperior, você pode afetar uma criatura adicional para\ncada nível de magia acima do 5°. As criaturas devem\nestar a 9 metros entre si para serem afetadas."},{"id":"ligacao-telepatica-de-rary","name":"Ligação Telepática de Rary","level":5,"school":"adivinhação","ritual":true,"classes":["mago"],"pdfPage":252,"time":"1 ação","range":"9 metros","components":"V, S, M (pedaços de cascas de ovos de dois tipos diferentes de criatura)","duration":"1 hora","concentration":false,"text":"5° nível de adivinhação (ritual)\nTempo de Conjuração: 1 ação\nAlcance: 9 metros\nComponentes: V, S, M (pedaços de cascas de ovos de\n   dois tipos diferentes de criatura)\nDuração: 1 hora\nVocê forja uma ligação telepática entre até oito criaturas\nvoluntárias, à sua escolha, dentro do alcance, ligando\npsiquicamente cada criatura a todas as outras, pela\nduração. Criaturas com valores de Inteligência 2 ou\nmenos não são afetadas por essa magia.\n    Até a magia acabar, os alvos podem se comunicar\ntelepaticamente através do elo, independentemente de\nterem ou não um idioma em comum. A comunicação é\npossível a qualquer distância, apesar de não se estender a\noutros planos de existência."},{"id":"missao","name":"Missão","level":5,"school":"encantamento","ritual":false,"classes":["bardo","clerigo","druida","mago","paladino"],"pdfPage":257,"time":"1 minuto","range":"18 metros","components":"V","duration":"30 dias","concentration":false,"text":"5° nível de encantamento\nTempo de Conjuração: 1 minuto\nAlcance: 18 metros\nComponentes: V\nDuração: 30 dias\nVocê impõe um comando mágico a uma criatura que você\npossa ver, dentro do alcance, forçando-a a fazer algum\nserviço ou reprimindo-a por alguma ação ou curso de\natividade, como você decidir. Se a criatura puder\ncompreender você, ela deve ser bem sucedida num teste\nde resistência de Sabedoria ou ficará enfeitiçada por você\npela duração. Enquanto a criatura estiver enfeitiçada por\nvocê, ela sofrerá 5d6 de dano psíquico toda vez que ela\nagir de maneira diretamente contrária às suas instruções,\nmas não mais de uma vez por dia. Uma criatura que não\npuder compreender você não é afetada por essa magia.\n   Você pode emitir qualquer comando que escolher,\nexceto uma atividade que resulte em morte certa. Se você\nemitir um comando suicida, a magia termina.\n   Você pode terminar a magia prematuramente usando\numa ação para dissipa-la. As magias remover maldição,\nrestauração maior ou desejo também podem termina-la.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 7° ou 8° nível, a\nduração será 1 ano. Quando você conjurar essa magia\nusando um espaço de magia de 9° nível, a magia dura até\nser terminada por uma das magias mencionadas acima."},{"id":"modificar-memoria","name":"Modificar Memória","level":5,"school":"encantamento","ritual":false,"classes":["bardo","mago"],"pdfPage":258,"time":"1 ação","range":"9 metros","components":"V, S","duration":"Concentração, até 1 minuto","concentration":true,"text":"5° nível de encantamento\nTempo de Conjuração: 1 ação\nAlcance: 9 metros\nComponentes: V, S\nDuração: Concentração, até 1 minuto\nVocê tenta modelar as memórias de outra criatura. Uma\ncriatura que você possa ver, deve realizar um teste de\nresistência de Sabedoria. Se você estiver lutando com a\ncriatura, ela terá vantagem no teste de resistência. Se\nfalhar na resistência, o alvo fica enfeitiçado por você pela\nduração. O alvo enfeitiçado está incapacitado e não sabe o\nque está acontecendo seu redor, apesar de ainda poder\nouvir você. Se ele sofrer qualquer dano ou for alvo de\noutra magia, essa magia acaba, e nenhuma das memórias\ndo alvo é modificada.\n    Enquanto esse feitiço durar, você pode afetar a\nmemória sobre um evento que o alvo participou nas\núltimas 24 horas e que não tenha durado mais de 10\nminutos. Você pode, permanentemente, eliminar todas as\nmemórias desse evento, permitir que o alvo relembre do\nevento com perfeita clareza e riqueza de detalhes, mudar\nsua memória sobre os detalhes do evento ou criar uma\nmemória de outro evento qualquer.\n    Você deve falar ao alvo para descrever como sua\nmemória é afetada e ele deve ser capaz de compreender\nseu idioma para que as memórias modificadas se\nenraízem. A mente dele preenche qualquer lacuna nos\ndetalhes da sua descrição. Se a magia terminar antes de\nvocê ter finalizado a descrição das memórias modificadas,\na memória da criatura não será alterada. Do contrário, as\nmemórias modificadas tomam lugar quando a magia\nacabar.\n    Uma memória modificada não afeta, necessariamente,\ncomo uma criatura se comporta, particularmente se a\nmemória contradiz as inclinações, tendência ou crenças\nnaturais da criatura. Uma modificação ilógica na\nmemória, como implantar uma memória de como a\ncriatura gosta de se encharcar de ácido, é repudiada,\ntalvez como um sonho ruim. O Mestre pode considerar\numa modificação na memória muito absurda para afetar\numa criatura de uma forma significativa.\n    Uma magia remover maldição ou restauração maior,\nconjurada no alvo, restaura a verdadeira memória da\ncriatura.\n    Em Níveis Superiores. Se você conjurar essa magia\nusando um espaço de magia de 6° nível ou superior, você\npode alterar a memória do alvo de um evento que\naconteceu a até 7 dias atrás (6° nível), 30 dias atrás (7°\nnível), 1 ano atrás (8° nível) ou em qualquer momento do\npassado da criatura (9° nível)."},{"id":"muralha-de-energia","name":"Muralha de Energia","level":5,"school":"evocação","ritual":false,"classes":["mago"],"pdfPage":259,"time":"1 ação","range":"36 metros","components":"V, S, M (um pouco de pó feito de uma gema transparente esmagada)","duration":"Concentração, até 10 minutos","concentration":true,"text":"5° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: 36 metros\nComponentes: V, S, M (um pouco de pó feito de uma\n   gema transparente esmagada)\nDuração: Concentração, até 10 minutos\nUma muralha invisível de energia aparece do nada num\nponto, à sua escolha, dentro do alcance. A muralha\naparece em qualquer orientação que você escolher, como\numa barreira horizontal ou vertical ou em uma\nangulação. Ela pode estar flutuando no ar ou apoiada em\numa superfície sólida. Você pode molda-la em uma cúpula\nhemisférica ou uma esfera com um raio de até dez painéis\nde 3 metros por 3 metros. Cada painel deve ser contíguo\ncom outro painel. Em qualquer formato, a muralha terá\n0,6 centímetros de espessura. Ela permanece pela\nduração. Se a muralha passar pelo espaço ocupado por\numa criatura quando ela surgir, a criatura será\nempurrada para um dos lados da muralha (você escolhe\nqual lado).\n   Nada pode passar fisicamente através da muralha.\nEla é imune a todos os danos e não pode ser dissipada por\ndissipar magia. A magia desintegrar destrói a muralha\ninstantaneamente, no entanto. A muralha também se\nestende ao Plano Etéreo, bloqueando a viagem etérea\natravés dela."},{"id":"muralha-de-pedra","name":"Muralha de Pedra","level":5,"school":"evocação","ritual":false,"classes":["druida","feiticeiro","mago"],"pdfPage":261,"time":"1 ação","range":"36 metros","components":"V, S, M (um pequeno bloco de granito)","duration":"Concentração, até 10 minutos","concentration":true,"text":"5° nível de conjuração\nTempo de Conjuração: 1 ação\nAlcance: 36 metros\nComponentes: V, S, M (um pequeno bloco de granito)\nDuração: Concentração, até 10 minutos\nUma muralha não-mágica de rocha sólida surge do nada\nnum ponto, à sua escolha, dentro do alcance. A muralha\ntem 15 centímetros de espessura e é composta por dez\npainéis de 3 metros por 3 metros. Cada painel deve ser\ncontíguo com, pelo menos, outro painel.\nAlternativamente, você pode criar painéis de 3 metros por\n6 metros com apenas 7,5 centímetros de espessura.\n    Se a muralha passar pelo espaço ocupado por uma\ncriatura quando ela surgir, a criatura será empurrada\npara um dos lados da muralha (você escolhe qual lado). Se\na criatura fosse ser rodeada por todos os lados da\nmuralha (ou pela muralha e outra superfície sólida), a\ncriatura pode realizar um teste de resistência de\nDestreza. Se obtiver sucesso, ela pode usar sua reação\npara se mover até seu deslocamento, assim não ficando\nmais cercada pela muralha.\n    A muralha pode ter qualquer formato que você\ndesejar, no entanto, ela não pode ocupar o mesmo espaço\nde uma criatura ou objeto. A muralha não precisa ser\nvertical ou se apoiar em qualquer fundação estável. Ela\ndeve, no entanto, se fundir e estar solidamente suportada\npor rocha existente. Então, você pode usar essa magia\npara criar uma ponte sobre um abismo ou criar uma\nrampa.\n    Se você criar um vão com mais de 6 metros de\ncomprimento, você deve reduzir o tamanho de cada painel\nà metade para criar suportes. Você pode moldar\ngrosseiramente a parede para criar merlões, ameias e\nassim por diante.\n    A muralha é um objeto feito de pedra que pode ser\ndanificado e então, partido. Cada painel tem CA 15 e 30\npontos de vida para cada 2,5 centímetros de espessura.\nReduzir os pontos de vida de um painel a 0, o destruirá e\npode fazer painéis conectados desmoronarem, à critério do\nMestre.\n    Se você mantiver sua concentração nessa magia por\ntoda a duração, a muralha se tornará permanente e não\npoderá ser dissipada. Do contrário, a muralha desaparece\nquando a magia acabar."},{"id":"mao-de-bigby","name":"Mão de Bigby","level":5,"school":"evocação","ritual":false,"classes":["mago"],"pdfPage":254,"time":"1 ação","range":"36 metros","components":"V, S, M (uma casca de ovo e uma luva de couro de cobra)","duration":"Concentração, até 1 minuto","concentration":true,"text":"5° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: 36 metros\nComponentes: V, S, M (uma casca de ovo e uma luva de\n   couro de cobra)\nDuração: Concentração, até 1 minuto\nVocê cria uma mão Grande de energia cintilante e\ntranslucida em um espaço desocupado que você possa ver\ndentro do alcance. A mão permanece pela duração da\nmagia e ela se move ao seu comando, imitando os\nmovimentos da sua própria mão.\n    A mão é um objeto com CA 20 e pontos de vida igual\nao seu máximo de pontos de vida. Se ela cair a 0 pontos de\nvida, a magia termina. Ela tem Força 26 (+8) e Destreza\n10 (+0). A mão não preenche o espaço dela.\n    Quando você conjura essa magia você pode, com uma\nação bônus, nos seus turnos subsequentes, mover a mão\naté 18 metros e então causar um dos seguintes efeitos\ncom ela.\n    Mão Esmagadora. A mão tenta agarrar uma\ncriatura Enorme ou menor a 1,5 metro dela. Você usa o\nvalor de Força da mão para determinar o agarrão. Se o\nalvo for Médio ou menor, você terá vantagem no teste.\nEnquanto a mão estiver agarrando o alvo, você pode usar\numa ação bônus para fazer a mão esmaga-lo. Quando o\nfizer, o alvo sofre dano de concussão igual a 2d6 + seu\nmodificador de habilidade de conjuração.\n    Mão Interposta. A mão se interpõem entre você e\numa criatura a sua escolha até você lhe dar um comando\ndiferente. A mão se move para ficar entre você e o alvo,\nconcedendo a você meia-cobertura contra o alvo. O alvo\nnão pode se mover através do espaço da mão se o valor de\nForça dele for menor ou igual ao valor de Força da mão.\nSe o valor de Força dele for maior que o valor de Força da\nmão, o alvo pode se mover até você através do espaço da\nmão, mas aquele espaço será considerado terreno difícil\npara o alvo.\n    Mão Poderosa. A mão tenta empurrar uma criatura\na 1,5 metro dela em uma direção a sua escolha. Realize\num teste com a Força da mão, resistido por um teste de\nForça (Atletismo) do alvo. Se o alvo for Médio ou menor,\nvocê tem vantagem no teste. Se você for bem sucedido, a\nmão empurra o alvo até 1,5 metro mais uma quantidade\nde metros igual ao modificador da sua habilidade de\nconjuração multiplicado por 1,5. A mão se move com o\nalvo, permanecendo a 1,5 metro dele.\n    Punho Cerrado. A mão golpeia uma criatura ou\nobjeto a 1,5 metro dela. Realize uma jogada de ataque\ncorpo-a-corpo com magia para a mão usando suas\nestatísticas de jogo. Se atingir, o alvo sofre 4d8 de dano de\nenergia.\n    Em Níveis Superiores. Se você conjurar essa magia\nusando um espaço de magia de 6° nível ou superior, o\ndano da opção punho cerrado aumenta em 2d8 e o dano\nda mão esmagadora aumenta em 2d6 para cada nível do\nespaço acima do 5°."},{"id":"nevoa-mortal","name":"Névoa Mortal","level":5,"school":"conjuração","ritual":false,"classes":["feiticeiro","mago"],"pdfPage":262,"time":"1 ação","range":"36 metros","components":"V, S","duration":"Concentração, até 10 minutos","concentration":true,"text":"5° nível de conjuração\nTempo de Conjuração: 1 ação\nAlcance: 36 metros\nComponentes: V, S\nDuração: Concentração, até 10 minutos\nVocê cria uma esfera de nevoeiro venenoso de cor\namarelo-esverdeado, com 6 metros de raio, centrado em\num ponto, à sua escolha, dentro do alcance. O nevoeiro se\nespalha, dobrando esquinas. Ele permanece pela duração\nou até um vento forte dispersar o nevoeiro, terminando a\nmagia. Sua área é de escuridão densa.\n    Quando uma criatura entra na área da magia pela\nprimeira vez no turno dela ou começa seu turno lá, essa\ncriatura deve realizar um teste de resistência de\nConstituição. A criatura sofre 5d8 de dano de veneno, ou\nmetade desse dano, se passar no teste. As criaturas serão\nafetadas mesmo se prenderem a respiração ou não\nprecisarem respirar.\n    O nevoeiro se afasta 3 metros de você no começo de\ncada um dos seus turnos, deslizando pela superfície do\nsolo. Os vapores são mais pesados que o ar, mantendo-se\nnos níveis mais baixos do terreno, até mesmo caindo em\naberturas.\n    Em Níveis Superiores. Se você conjurar essa magia\nusando um espaço de magia de 6° nível ou superior, o\ndano aumenta em 1d8 para cada nível do espaço acima do\n5°."},{"id":"onda-destrutiva","name":"Onda Destrutiva","level":5,"school":"evocação","ritual":false,"classes":["paladino"],"pdfPage":264,"time":"1 ação","range":"Pessoal (9 metros de raio)","components":"V","duration":"Instantânea","concentration":false,"text":"5° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: Pessoal (9 metros de raio)\nComponentes: V\nDuração: Instantânea\nVocê golpeia o chão, criando uma explosão de energia\ndivina que se propaga de você. Cada criatura, à sua\nescolha, a até 9 metros de você, deve ser bem sucedida em\num teste de resistência de Constituição ou sofrerá 5d6 de\ndano trovejante, assim como 5d6 de dano radiante ou\nnecrótico (à sua escolha), e será derrubada no chão. Uma\ncriatura que obtenha sucesso no teste de resistência sofre\nmetade desse dano e não é derrubada no chão.","sourceNote":"Correção editorial do CritCall: o PDF local imprime 5d5 trovejante; o catálogo usa 5d6, conforme Destructive Wave de 2014 (PHB, p. 231). O PDF original foi preservado."},{"id":"praga","name":"Praga","level":5,"school":"necromancia","ritual":false,"classes":["clerigo","druida"],"pdfPage":268,"time":"1 ação","range":"Toque","components":"V, S","duration":"7 dias","concentration":false,"text":"5° nível de necromancia\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S\nDuração: 7 dias\nSeu toque inflige uma doença. Faça um ataque de magia\ncorpo-a-corpo contra uma criatura ao seu alcance. Se\natingir, você aflige a criatura com uma doença, de sua\nescolha, entre qualquer um das descritas abaixo.\n    No final de cada turno do alvo, ele deve realizar um\nteste de resistência de Constituição. Após obter três\nfalhas nesses testes de resistência, o efeito da doença\npermanece pela duração e a criatura para de fazer testes\nde resistência. Após obter três sucessos nesses testes de\nresistência, a criatura se recupera da doença e a magia\ntermina.\n    Já que essa magia induz uma doença natural no alvo,\nqualquer efeito que remova uma doença, ou de outra\nforma, melhore os efeitos de uma doença, se aplica a ela.\n    Ardência Mental. A mente da criatura fica febril. A\ncriatura tem desvantagem em testes de Inteligência,\ntestes de resistência de Inteligência e a criatura age como\nse estivesse sob efeito da magia confusão durante um\ncombate.\n    Enjoo Cegante. A dor se agarra a mente da criatura e\nseus olhos ficam branco-leitosos. A criatura tem\ndesvantagem em testes de Sabedoria e testes de\nresistência de Sabedoria e está cega.\n    Febre do Esgoto. Uma febre voraz se espalha pelo\ncorpo da criatura. A criatura tem desvantagem em testes\nde Força, testes de resistência de Força e jogadas de\nataque que usem Força.\n    Necrose da Carne. A carne da criatura se decompõe.\nA criatura tem desvantagem em testes de Carisma e\nvulnerabilidade a todos os danos.\n    Perdição Pegajosa. A criatura começa a sangrar\nincontrolavelmente. A criatura tem desvantagem em\ntestes de Constituição e testes de resistência de\nConstituição. Além disso, sempre que a criatura sofrer\ndano, ela ficará atordoada até o fim do seu próximo turno.\n    Tremedeira. A criatura é acometida por espasmos. A\ncriatura tem desvantagem em testes de Destreza, testes\nde resistência de Destreza e jogadas de ataque que usem\nDestreza."},{"id":"praga-de-insetos","name":"Praga de Insetos","level":5,"school":"conjuração","ritual":false,"classes":["clerigo","druida","feiticeiro"],"pdfPage":268,"time":"1 ação","range":"90 metros","components":"V, S, M (alguns grãos de açúcar, alguns miolos de grão e uma mancha de gordura)","duration":"Concentração, até 10 minutos","concentration":true,"text":"5° nível de conjuração\nTempo de Conjuração: 1 ação\nAlcance: 90 metros\nComponentes: V, S, M (alguns grãos de açúcar, alguns\n   miolos de grão e uma mancha de gordura)\nDuração: Concentração, até 10 minutos\nUm enxame voraz de gafanhotos preenche uma esfera de\n6 metros de raio, centrada no ponto que você escolher,\ndentro do alcance. A esfera se espalha dobrando esquinas.\nA esfera permanece pela duração e sua área é de\nescuridão leve. A área da esfera é de terreno difícil.\n    Quando a área aparece, cada criatura dentro dela deve\nrealizar um teste de resistência de Constituição. Uma\ncriatura sofre 4d10 de dano perfurante se falhar na\nresistência ou metade desse dano se passar. Uma criatura\ndeve, também, realizar um teste de resistência quando\nentrar na área da magia pela primeira vez num turno ou\nterminar seu turno nela.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 6° nível ou\nsuperior, o dano aumenta em 1d10 para cada nível do\nespaço acima do 5°."},{"id":"reencarnacao","name":"Reencarnação","level":5,"school":"transmutação","ritual":false,"classes":["druida"],"pdfPage":275,"time":"1 hora","range":"Toque","components":"V, S, M (óleos e unguentos raros valendo, no mínimo, 1.000 po, consumidos pela magia)","duration":"Instantânea","concentration":false,"text":"5° nível de transmutação\nTempo de Conjuração: 1 hora\nAlcance: Toque\nComponentes: V, S, M (óleos e unguentos raros valendo,\n   no mínimo, 1.000 po, consumidos pela magia)\nDuração: Instantânea\nVocê toca um humanoide morto ou um pedaço de um\nhumanoide morto. Considerando que a criatura não esteja\nmorta a mais de 10 dias, a magia forma um novo corpo\nadulto para ele e então, chama a alma para entrar no\ncorpo. Se a alam do alvo não estiver livre ou deseje fazê-\nlo, a magia falha.\n    A magia forma um novo corpo para que a criatura\nhabite, o que, provavelmente, fará com que a raça da\ncriatura mude. O Mestre rola um d100 e consulta a tabela\nseguinte para determinar qual forma a criatura terá\nquando voltar a vida, ou o Mestre pode escolher uma\nforma.\n\n  d100       Raça\n  01–04      Draconato\n  05–13      Anão, colina\n  14–21      Anão, montanha\n  22–25      Elfo, negro\n  26–34      Elfo, alto\n  35–42      Elfo, floresta\n  43–46      Gnomo, floresta\n  47–52      Gnomo, rochas\n  53–56      Meio-elfo\n  57–60      Meio-orc\n  61–68      Halfling, pés leves\n  69–76      Halfling, robusto\n  77–96      Humano\n  97–00      Tiefling\n\nA criatura reencarnada lembra-se da sua vida e\nexperiências anteriores. Ela mantem as capacidades que\na sua forma original tinha, exceto por trocar sua raça\noriginal pela nova e mudar suas características raciais\nadequadamente."},{"id":"restauracao-maior","name":"Restauração Maior","level":5,"school":"abjuração","ritual":false,"classes":["bardo","clerigo","druida"],"pdfPage":277,"time":"1 ação","range":"Toque","components":"V, S, M (pó de diamante valendo, no mínimo, 100 po, consumido pela magia)","duration":"Instantânea","concentration":false,"text":"5° nível de abjuração\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S, M (pó de diamante valendo, no\n   mínimo, 100 po, consumido pela magia)\nDuração: Instantânea\nVocê imbui uma criatura que você toca, com energia\npositiva para desfazer um efeito debilitante. Você pode\nreduzir a exaustão do alvo em um nível ou remover um\ndos seguintes do alvo:\n   Um efeito que enfeitice ou petrifique o alvo\n   Uma maldição, incluindo a sintonização do alvo com\n    um item mágico amaldiçoado\n   Qualquer redução a um dos valores de habilidade do\n    alvo\n   Um efeito que esteja reduzindo o máximo de pontos de\n    vida do alvo"},{"id":"reviver-os-mortos","name":"Reviver os Mortos","level":5,"school":"necromancia","ritual":false,"classes":["bardo","clerigo","paladino"],"pdfPage":277,"time":"1 hora","range":"Toque","components":"V, S, M (um diamante valendo, no mínimo, 500 po, consumido pela magia)","duration":"Instantânea","concentration":false,"text":"5° nível de necromancia\nTempo de Conjuração: 1 hora\nAlcance: Toque\nComponentes: V, S, M (um diamante valendo, no\n   mínimo, 500 po, consumido pela magia)\nDuração: Instantânea\nVocê traz uma criatura morta que você tocar de volta a\nvida, considerando que ela não esteja morta a mais de 10\ndias. Se a alma da criatura estiver tanto disposta quando\nlivre para juntar-se ao corpo dela, a criatura volta a vida\ncom 1 ponto de vida.\n    Essa magia também neutraliza quaisquer venenos e\ncura doenças não-mágicas que afetavam a criatura no\nmomento da morte. Essa magia, no entanto, não remove\ndoenças mágicas, maldições ou efeitos similares; se eles\nnão tiverem sido removidos antes da conjuração da\nmagia, eles voltam a afetar a criatura quando ela volta a\nviver. A magia não pode trazer uma criatura morta-viva\nde volta à vida.\n    Essa magia fecha todos os ferimentos mortais, mas ela\nnão restaura partes do corpo perdidas. Se a criatura não\ntiver uma parte do corpo ou órgão fundamental para sua\nsobrevivência – sua cabeça, por exemplo – a magia falha\nautomaticamente.\n    Voltar dos mortos é um calvário. O alvo sofre –4 de\npenalidade em todas as suas jogadas de ataque, testes de\nresistência e testes de habilidade. A cada vez que o alvo\nterminar um descanso longo, as penalidades são\nreduzidas em 1, até desaparecerem."},{"id":"similaridade","name":"Similaridade","level":5,"school":"ilusão","ritual":false,"classes":["bardo","feiticeiro","mago"],"pdfPage":280,"time":"1 ação","range":"9 metros","components":"V, S","duration":"8 horas","concentration":false,"text":"5° nível de ilusão\nTempo de Conjuração: 1 ação\nAlcance: 9 metros\nComponentes: V, S\nDuração: 8 horas\nEssa magia permite que você mude a aparência de\nqualquer quantidade de criaturas que você possa ver,\ndentro do alcance. Você dá a cada alvo que você escolheu\numa nova aparência ilusória. Um alvo involuntário pode\nrealizar um teste de resistência de Carisma, se for bem\nsucedido, a magia não o afetará.\n    A magia disfarça a aparência física, assim como roupa,\narmadura, armas e equipamentos. Você pode fazer com\nque cada criatura pareça 30 centímetros mais baixa ou\nalta e aparente ser magra, gorda ou entre. Você não pode\nmudar o tipo do seu corpo, portanto, você deve adotar\numa forma que tenha a mesma disposição básica de\nmembros. No mais, a extensão da sua ilusão cabe a você.\nA magia permanece pela duração, a menos que você usa\nsua ação para dissipa-la precocemente.\n    As mudanças criadas por essa magia não conseguem\nse sustentar perante uma inspeção física. Por exemplo, se\nvocê usar essa magia para adicionar um chapéu ao seu\nvisual, objetos que passarem pelo chapéu e qualquer um\nque tocá-lo não sentirá nada ou sentirá sua cabeça e\ncabelo. Se você usar essa magia para aparentar ser mais\nmagro do que é, a mão de alguém que a erguer para tocar\nem você, irá esbarrar em você enquanto ainda está,\naparentemente, está no ar.\n    Uma criatura pode usar a ação dela para inspecionar\num alvo e fazer um teste de Inteligência (Investigação)\ncontra a CD da sua magia. Se for bem sucedido, ele estará\nciente de que o alvo está disfarçado."},{"id":"sonho","name":"Sonho","level":5,"school":"ilusão","ritual":false,"classes":["bardo","bruxo","mago"],"pdfPage":280,"time":"1 minuto","range":"Especial","components":"V, S, M (um punhado de areia, um pouco de tinta e uma pena de escrita arrancada de um pássaro adormecido)","duration":"8 horas","concentration":false,"text":"5° nível de ilusão\nTempo de Conjuração: 1 minuto\nAlcance: Especial\nComponentes: V, S, M (um punhado de areia, um pouco\n   de tinta e uma pena de escrita arrancada de um\n   pássaro adormecido)\nDuração: 8 horas\nEssa magia molda os sonhos de uma criatura. Escolha\numa criatura que você conheça como alvo dessa magia. O\nalvo deve estar no mesmo plano de existência que você.\nCriaturas que não dormem, como elfos, não podem ser\ncontatados por essa magia. Você, ou uma criatura\nvoluntária que você tocar, entram em um estado de\ntranse. Enquanto estiver me transe, o mensageiro está\nciente dos seus arredores, mas não pode realizar ações ou\nse mover.\n    Se o alvo estiver dormindo, o mensageiro aparece no\nsonho do alvo e pode conversar com o alvo enquanto ele\nestiver dormindo, até o limite da duração da magia. O\nmensageiro também pode modificar o meio ambiente do\nsonho, criando paisagens, objetos e outras imagens. O\nmensageiro pode sair do transe a qualquer momento,\nterminando o efeito da magia prematuramente. O alvo se\nlembra do sonho perfeitamente quando acorda. Se o alvo\nestiver acordado quando a magia for conjurada, o\nmensageiro saberá disso e pode, tanto terminar o transe\n(e a magia) quando esperar o alvo cair no sono, no\nmomento em que o mensageiro aparecerá nos sonhos do\nalvo.\n    Você pode fazer o mensageiro parecer monstruoso e\naterrorizante para o alvo. Se o fizer, o mensageiro pode\nenviar uma mensagem de não mais que dez palavras,\nentão o alvo deve realizar um teste de resistência de\nSabedoria. Se falhar na resistência, ecos da\nmonstruosidade fantasmagórica criarão um pesadelo que\npermanecerá pela duração do sono do alvo e impede o alvo\nde ganhar qualquer benefício do descanso. Além disso,\nquando o alvo acordar, ele sofrerá 3d6 de dano psíquico.\n    Se você tiver uma parte do corpo, mecha de cabelo,\nrecorte de unha ou porção similar do corpo do alvo, o alvo\nrealiza seu teste de resistência com desvantagem."},{"id":"telecinesia","name":"Telecinésia","level":5,"school":"transmutação","ritual":false,"classes":["feiticeiro","mago"],"pdfPage":282,"time":"1 ação","range":"18 metros","components":"V, S","duration":"Concentração, até 10 minutos","concentration":true,"text":"5° nível de transmutação\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, S\nDuração: Concentração, até 10 minutos\nVocê adquire a habilidade de mover ou manipular\ncriaturas ou objetos através do pensamento. Quando você\nconjura a magia e, com sua ação a cada turno, pela\nduração, você pode exercer sua vontade sobre uma\ncriatura ou objeto que você possa ver, dentro do alcance,\ncausando os efeitos apropriados abaixo. Você pode afetar\no mesmo alvo rodada após rodada, ou escolher um novo a\nqualquer momento. Se você mudar de alvos, o alvo\nanterior não será mais afetado pela magia.\n    Criatura. Você pode tentar mover uma criatura\nEnorme ou menor. Faça um teste de habilidade com sua\nhabilidade de conjuração resistido por um teste Força da\ncriatura. Se você vencer a disputa, você move a criatura\naté 9 metros em qualquer direção, incluindo para cima,\nmas não além do alcance da magia. Até o final do seu\npróximo turno, a criatura estará impedida pelo seu\nagarrão telecinético. Uma criatura erguida para cima\nestará suspensa no ar.\n    Em rodadas subsequente, você pode usar sua ação\npara tentar manter seu agarrão telecinético na criatura\nrepetindo o teste resistido.\n    Objeto. Você pode tentar mover um objeto pesando até\n500 quilos. Se o objeto não estiver sendo vestido ou\ncarregado, você o move, automaticamente, até 9 metros\nem qualquer direção, mas não além do alcance dessa\nmagia.\n    Se o objeto estiver sendo vestido ou carregado por uma\ncriatura, você deve realizar um teste de habilidade com\nsua habilidade de conjuração resistido por um teste de\nForça da criatura. Se você for bem sucedido, você arranca\no objeto da criatura e o move até 9 metros, em qualquer\ndireção, mas não além do alcance dessa magia.\n    Você pode exercer um controle refinado sobre os\nobjetos com seu agarrão telecinético, como manipular\nferramentas simples, abrir uma porta ou um recipiente,\nguardar ou recuperar um item de um recipiente aberto ou\nderramar o conteúdo de um frasco."},{"id":"videncia","name":"Vidência","level":5,"school":"adivinhação","ritual":false,"classes":["bardo","bruxo","clerigo","druida","mago"],"pdfPage":287,"time":"10 minutos","range":"Pessoal","components":"V, S, M (um foco valendo, no mínimo, 1.000 po, como uma bola de cristal, espelho de prata ou fonte cheia de água benta)","duration":"Concentração, até 10 minutos","concentration":true,"text":"5° nível de adivinhação\nTempo de Conjuração: 10 minutos\nAlcance: Pessoal\nComponentes: V, S, M (um foco valendo, no mínimo,\n   1.000 po, como uma bola de cristal, espelho de prata\n   ou fonte cheia de água benta)\nDuração: Concentração, até 10 minutos\nVocê pode ver e ouvir uma criatura em particular, à sua\nescolha, que esteja no mesmo plano de existência que\nvocê. O alvo deve realizar um teste de resistência de\nSabedoria, que é modificador de acordo com o quão bem\nvocê conhece o alvo e o tipo de conexão física que você tem\ncom ele. Se um alvo souber que você está conjurando essa\nmagia, ele pode falhar no teste de resistência\nvoluntariamente, se ele quiser ser observado.\n   Com um sucesso na resistência, o alvo não é afetado e\nvocê não pode usar essa magia contra ele novamente por\n24 horas.\n   Se falhar na resistência, a magia cria um sensor\ninvisível a até 3 metros do alvo. Você pode ver e ouvir\natravés do sensor, como se você estivesse onde ele está. O\nsensor se move com o alvo, permanecendo a 3 metros dele\npela duração. Uma criatura que puder ver objetos\ninvisíveis verá o sensor como um globo luminoso do\ntamanho de um punho.\n   Ao invés de focar em uma criatura, você pode escolher\num local que você já tenha visto antes como alvo dessa\nmagia. Quando fizer isso, o sensor aparece no local e não\nse move.\n\n                                              Modificador de\nConhecimento                                   Resistência\nSegunda mão (você ouviu falar do alvo)              +5\nPrimeira mão (você foi apresentado ao alvo)         +0\nFamiliar (você conhece bem o alvo)                  –5\n\n                                              Modificador de\nConexão                                        Resistência\nDescrição ou foto                                   –2\nPertences ou roupas                                 –4\nParte do corpo, mexa de cabelo, recorte de         –10\nunha ou simular"},{"id":"ancora-planar","name":"Âncora Planar","level":5,"school":"abjuração","ritual":false,"classes":["bardo","clerigo","druida","mago"],"pdfPage":215,"time":"1 hora","range":"18 metros","components":"V, S, M (uma joia valendo, no mínimo, 1.000 po, consumida pela magia)","duration":"24 horas","concentration":false,"text":"5° nível de abjuração\nTempo de Conjuração: 1 hora\nAlcance: 18 metros\nComponentes: V, S, M (uma joia valendo, no mínimo,\n   1.000 po, consumida pela magia)\nDuração: 24 horas\nCom essa magia, você tenta obrigar um celestial,\ncorruptor, elemental ou fada a servi-lo. A criatura deve\nestar dentro do alcance durante toda a conjuração da\nmagia. (Tipicamente, a criatura, primeiramente, é\ninvocada dentro de um círculo mágico invertido para\nmantê-la presa enquanto a magia é conjurada.) Ao\ncompletar a conjuração, o alvo deve realizar um teste de\nresistência de Carisma. Se falhar na resistência, ela é\nobrigada a servir você pela duração. Se a criatura foi\ninvocada ou criada por outra magia, a duração da magia é\nestendida para se equiparar a dessa magia.\n    Uma criatura obrigada deve seguir suas instruções da\nmelhor forma que puder. Você poderia comandar a\ncriatura a acompanhar você em uma aventura, a guardar\num local ou a enviar uma mensagem. A criatura obedece\nao pé da letra suas instruções, mas se a criatura for hostil\na você, ela se esforçará para distorcer suas palavras para\natingir seus próprios objetivos. Se a criatura atender suas\ninstruções completamente antes da magia acabar, ela\nviajará até você para relatar esse fato se você estiver no\nmesmo plano de existência. Se você estiver em um plano\nde existência diferente, ela retornará para o lugar onde\nvocê a contatou e permanecerá lá até a magia acabar.\n    Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de nível superior, a\nduração aumenta para 10 dias com um espaço de 6° nível,\npara 30 dias com um espaço de 7° nível, para 180 dias\ncom um espaço de 8° nível e para um ano com um espaço\nde magia de 9° nível."},{"id":"aliado-planar","name":"Aliado Planar","level":6,"school":"conjuração","ritual":false,"classes":["clerigo"],"pdfPage":213,"time":"10 minutos","range":"18 metros","components":"V, S","duration":"Instantânea","concentration":false,"text":"6° nível de conjuração\nTempo de Conjuração: 10 minutos\nAlcance: 18 metros\nComponentes: V, S\nDuração: Instantânea\nVocê suplica a uma entidade transcendental por ajuda. O\nser deve ser conhecido por você: seu deus, um primordial,\num príncipe demônio ou algum outro ser de poder\ncósmico. Essa entidade envia um celestial, um corruptor\nou um elemental leal a ela para ajudar você, fazendo a\ncriatura aparecer em um espaço desocupado dentro do\nalcance. Se você conhecer o nome de uma criatura\nespecifica, você pode falar o nome quando conjurar essa\nmagia para requisitar essa criatura, do contrário, você\npode receber uma criatura diferente de qualquer forma (à\nescolha do Mestre).\n    Quando a criatura aparecer, ela não está sob nenhuma\ncompulsão para se comportar de um modo em particular.\nVocê pode pedir a criatura que realize um serviço em\ntroca de um pagamento, mas ela não é obrigada a fazê-lo.\nA tarefa solicitada pode variar de simples (carregue-nos\nvoando para o outro lado do abismo ou nos ajude a lutar\nessa batalha) a complexa (espione nossos inimigos ou nos\nproteja durante nossa incursão na masmorra). Você deve\nser capaz de se comunicar com a criatura para barganhar\nos serviços dela.\n    O pagamento pode ser feito de várias formas. Um\ncelestial pode requerer uma generosa doação de ouro ou\nitens mágicos para um templo aliado, enquanto que um\ncorruptor pode exigir um sacrifício vivo ou uma parte dos\nespólios. Algumas criaturas podem trocar seus serviços\npor uma missão feita por você.\n    Como regra geral, uma tarefa que possa ser medida\nem minutos, exigirá um pagamento de 100 po por minuto.\nUma tarefa medida em horas exigirá 1.000 po por hora. E\numa tarefa medida em dias (até 10 dias) exigirá 10.000 po\npor dia. O Mestre pode ajustar esses pagamentos baseado\nnas circunstâncias pelas quais a magia foi conjurada. Se a\ntarefa estiver de acordo com o caráter da criatura, o\npagamento pode ser reduzido à metade, ou mesmo\ndispensado. Tarefas que não proporcionem perigo,\ntipicamente requerem apenas metade do pagamento\nsugerido, enquanto que tarefas especialmente perigosas\npodem exigir um grande presente. As criaturas\nraramente aceitarão tarefas que pareçam suicidas.\n   Após a criatura completar a tarefa ou quando a\nduração acordada para o serviço expirar, a criatura\nretornará para seu plano natal depois de relatar sua\npartida a você, se apropriado para a tarefa e se possível.\nSe você não for capaz de acertar um preço para os serviços\nda criatura, ela imediatamente voltará para o seu plano\nnatal.\n   Uma criatura convidada para se juntar ao seu grupo,\nconta como um membro dele, recebendo sua parte total na\npremiação de pontos de experiência."},{"id":"ataque-visual","name":"Ataque Visual","level":6,"school":"necromancia","ritual":false,"classes":["bardo","bruxo","feiticeiro","mago"],"pdfPage":219,"time":"1 ação","range":"Pessoal","components":"V, S","duration":"Concentração, até 1 minuto","concentration":true,"text":"6° nível de necromancia\nTempo de Conjuração: 1 ação\nAlcance: Pessoal\nComponentes: V, S\nDuração: Concentração, até 1 minuto\nPela duração da magia, seus olhos tornam-se manchas\nvazias imbuídas com poder terrível. Uma criatura, à sua\nescolha, a até de 18 metros de você que você puder ver,\ndeve ser bem sucedida num teste de resistência de\nSabedoria ou será afetada por um dos efeitos a seguir, à\nsua escolha, pela duração. A cada um dos seus turnos, até\na magia acabar, você pode usar sua ação para afetar\noutra criatura, mas não pode afetar uma criatura\nnovamente se ela tiver sido bem sucedida no teste de\nresistência contra essa conjuração de ataque visual.\n   Adormecer. O alvo cai inconsciente. Ele acorda se\nsofrer qualquer dano ou se outra criatura usar sua ação\npara sacudir o adormecido até acordá-lo.\n   Apavorar. O alvo está amedrontado. Em cada um dos\nturnos dele, a criatura amedrontada deve realizar a ação\nde Disparada e se mover para longe de você pela rota\nsegura mais curta disponível, a não ser que não haja\nlugar para se mover. Se o alvo se mover para um local a,\npelo menos, 18 metros de distância de você onde ela não\npossa mais te ver, esse efeito termina.\n   Adoecer. O alvo tem desvantagem nas jogadas de\nataque e testes de habilidade. No final de cada um dos\nturnos dele, ele pode realizar outro teste de resistência de\nSabedoria. Se for bem sucedido, o efeito termina."},{"id":"banquete-de-herois","name":"Banquete dos Heróis","level":6,"school":"conjuração","ritual":false,"classes":["clerigo","druida"],"pdfPage":220,"time":"10 minutos","range":"9 metros","components":"V, S, M (uma tigela encrustada de gemas valendo, no mínimo, 1.000 po, que é consumida pela magia)","duration":"Instantânea","concentration":false,"text":"6° nível de conjuração\nTempo de Conjuração: 10 minutos\nAlcance: 9 metros\nComponentes: V, S, M (uma tigela encrustada de gemas\n  valendo, no mínimo, 1.000 po, que é consumida pela\n  magia)\nDuração: Instantânea\nVocê traz um grande banquete, incluindo comida e bebida\nmagnificas. O banquete leva 1 hora para ser consumido e\ndesaparece ao final desse tempo e os efeitos benéficos não\nse aplicam até essa hora terminar. Até doze criaturas\npodem participar do banquete.\n   Uma criatura que participe do banquete ganha\ndiversos benefícios. A criatura é curada de todas as\ndoenças e venenos, torna-se imune a veneno e a ser\namedrontada e faz todos os seus testes de resistência de\nSabedoria com vantagem. Seu máximo de pontos de vida\ntambém aumenta em 2d10 e ela ganha a mesma\nquantidade de pontos de vida. Esses benefícios duram por\n24 horas."},{"id":"barreira-de-laminas","name":"Barreira de Lâminas","level":6,"school":"evocação","ritual":false,"classes":["clerigo"],"pdfPage":221,"time":"1 ação","range":"24 metros","components":"V, S","duration":"Concentração, até 10 minutos","concentration":true,"text":"6° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: 24 metros\nComponentes: V, S\nDuração: Concentração, até 10 minutos\nVocê cria uma muralha vertical de lâminas giratórias,\nafiadas como navalhas, feitas de energia mágica. A\nmuralha aparece dentro do alcance e permanece pela\nduração. Você pode fazer uma muralha reta de até 30\nmetros de comprimento por 6 metros de altura e 1,5\nmetro de largura ou uma muralha anelar com até 18\nmetros de diâmetro, 6 metros de altura e 1,5 metro de\nlargura. A muralha confere três-quartos de cobertura a\ncriaturas atrás dela e seu espaço é terreno difícil.\n    Quando uma criatura entrar a área da muralha pela\nprimeira vez em um turno, ou começar seu turno nela, a\ncriatura deve realizar um teste de resistência de\nDestreza. Se falhar, a criatura sofrerá 6d10 de dano\ncortante. Em um sucesso, a criatura sofre metade desse\ndano."},{"id":"caminhar-no-vento","name":"Caminhar no Vento","level":6,"school":"transmutação","ritual":false,"classes":["druida"],"pdfPage":223,"time":"1 minuto","range":"9 metros","components":"V, S, M (fogo e água benta)","duration":"8 horas","concentration":false,"text":"6° nível de transmutação\nTempo de Conjuração: 1 minuto\nAlcance: 9 metros\nComponentes: V, S, M (fogo e água benta)\nDuração: 8 horas\nVocê e até dez criaturas voluntária que você possa ver,\ndentro do alcance, assumem uma forma gasosa pela\nduração, parecidas com pedaços de nuvem. Enquanto\nestiver na forma de nuvem, uma criatura tem\ndeslocamento de voo de 90 metros e tem resistência a\ndano de concussão, cortante e perfurante de ataques não-\nmágicos. As únicas ações que uma criatura pode realizar\nnessa forma são a ação de Disparada ou para reverter a\nsua forma normal. Reverter leva 1 minuto, período pelo\nqual a criatura estará incapacitada e não poderá se\nmover. Até a magia acabar, uma criatura pode reverter\npara a forma de nuvem, o que também requer a\ntransformação de 1 minuto.\n   Se uma criatura estiver na forma de nuvem e voando\nquando o efeito acabar, a criatura descerá a 18 metros por\nrodada por 1 minuto, até aterrissar na solo, o que é feito\ncom segurança. Se ela não puder aterrissar em 1 minuto,\na criatura cairá a distância restante."},{"id":"carne-para-pedra","name":"Carne para Pedra","level":6,"school":"transmutação","ritual":false,"classes":["bruxo","mago"],"pdfPage":224,"time":"1 ação","range":"18 metros","components":"V, S, M (uma pitada de cal, água e terra)","duration":"Concentração, até 1 minuto","concentration":true,"text":"6° nível de transmutação\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, S, M (uma pitada de cal, água e terra)\nDuração: Concentração, até 1 minuto\nVocê tenta transformar uma criatura que você possa ver,\ndentro do alcance, em pedra. Se o corpo do alvo for feito\nde carne, a criatura deve realizar um teste de resistência\nde Constituição. Em caso de falha, ela ficará impedida, à\nmedida que sua carne começa a endurecer. Se obtiver\nsucesso, a criatura não é afetada.\n   Uma criatura impedida por essa magia deve realizar\noutro teste de resistência de Constituição no final de cada\num dos turnos dela. Se obtiver sucesso na resistência\ncontra essa magia três vezes, a magia termina. Se ela\nfalhar no teste de resistência três vezes, ela se torna\npedra é afetada pela condição petrificado pela duração. Os\nsucessos e falhas não precisam ser consecutivos; anote\nambos os resultados até o alvo acumular três de mesmo\ntipo.\n   Se a criatura for quebrada fisicamente enquanto\npetrificada, ela sofre deformidades similares se for\nrevertida ao seu estado original.\n   Se você mantiver sua concentração nessa magia\ndurante toda a duração possível, a criatura é\ntransformada em pedra até o efeito ser removido."},{"id":"conjurar-fada","name":"Conjurar Fada","level":6,"school":"conjuração","ritual":false,"classes":["bruxo","druida"],"pdfPage":228,"time":"1 minuto","range":"27 metros","components":"V, S","duration":"Concentração, até 1 hora","concentration":true,"text":"6° nível de conjuração\nTempo de Conjuração: 1 minuto\nAlcance: 27 metros\nComponentes: V, S\nDuração: Concentração, até 1 hora\nVocê invoca uma criatura feérica de nível de desafio 6 ou\ninferior ou um espírito feérico que assume a forma de\numa besta de nível de desafio 6 ou inferior. Ela aparece\nnum espaço desocupado, que você possa ver dentro do\nalcance. A criatura feérica desaparece se cair a 0 pontos\nde vida ou quando a magia acabar.\n    A criatura feérica é amigável a você e a seus\ncompanheiros pela duração. Role a iniciativa para a\ncriatura, que age no seu próprio turno. Ela obedece a\nquaisquer comandos verbais que você emitir (não requer\numa ação sua), contanto que não violem sua tendência. Se\nvocê não emitir nenhum comando a ela, ela se defenderá\nde criaturas hostis, mas no mais, não realizará nenhuma\nação.\n    Se sua concentração for interrompida, a criatura\nfeérica não desaparece. Ao invés disso, você perde o\ncontrole sobre o elemental e ele se torna hostil a você e\naos seus companheiros, e irá atacar. Uma criatura feérica\nfora de controle não pode ser dispensada e desaparece 1\nhora depois de você ter a invocado.\n    O Mestre possui as estatísticas da criatura feérica.\n    Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 7° nível ou\nsuperior, o nível de desafio aumenta em 1 para cada nível\ndo espaço acima do 6°."},{"id":"contingencia","name":"Contingência","level":6,"school":"evocação","ritual":false,"classes":["mago"],"pdfPage":230,"time":"10 minutos","range":"Pessoal","components":"V, S, M (uma estátua sua esculpida em marfim e decorada com gemas valendo, no mínimo, 1.500 po)","duration":"10 dias","concentration":false,"text":"6° nível de evocação\nTempo de Conjuração: 10 minutos\nAlcance: Pessoal\nComponentes: V, S, M (uma estátua sua esculpida em\n   marfim e decorada com gemas valendo, no mínimo,\n   1.500 po)\nDuração: 10 dias\nEscolha uma magia de 5° nível ou inferior que você possa\nconjurar, que tenha um tempo de conjuração de 1 ação e\nque possa ter você como alvo. Você conjura essa magia –\nchamada de magia contingente – como parte da\nconjuração de contingência, gastando espaços de magia\npara ambas, mas a magia contingente não tem efeito\nimediato. Ao invés disso, ela se ativa quando uma certa\ncircunstância ocorre. Você descreve a circunstância\nquando conjura as duas magias. Por exemplo, uma\ncontingência conjurada com respirar na água pode\nestipular que respirar na água se ative quando você\nestiver imerso em água ou um líquido similar.\n    A magia contingente se ativa imediatamente depois da\ncircunstância ser satisfeita pela primeira vez, quer você\nqueira, quer não, e a contingência termina.\n    A magia contingente afeta apenas você, mesmo que ela\nnormalmente possa afetar outros alvos. Você pode ter\napenas uma contingência ativa por vez. Se você conjurar\nessa magia novamente, o efeito da outra magia\ncontingência termina. Além disso, a contingência também\ntermina em você se os componentes materiais dela não\nestiverem mais com você."},{"id":"corrente-de-relampagos","name":"Corrente de Relâmpagos","level":6,"school":"evocação","ritual":false,"classes":["feiticeiro","mago"],"pdfPage":233,"time":"1 ação","range":"45 metros","components":"V, S, M (um pouco de pelo; um pedaço de âmbar, vidro ou um bastão de cristal; e três pinos de prata)","duration":"Instantânea","concentration":false,"text":"6° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: 45 metros\nComponentes: V, S, M (um pouco de pelo; um pedaço de\n   âmbar, vidro ou um bastão de cristal; e três pinos de\n   prata)\nDuração: Instantânea\nVocê cria um raio elétrico que atinge um alvo, à sua\nescolha, que você possa ver dentro do alcance. Três raios\nsaltam do alvo para até três outros alvos, cada um a não\nmais de 9 metros do alvo primário. Um alvo pode ser uma\ncriatura ou um objeto e só pode ser alvo de um único\ndesses raios.\n    Um alvo deve realizar um teste de resistência de\nDestreza. O alvo sofre 10d8 de dano elétrico se falhar no\nteste ou metade desse dano se for bem sucedido.\n    Em Níveis Superiores. Se você conjurar essa magia\nusando um espaço de magia de 7° nível ou superior, um\nraio adicional salta do alvo primário para outro alvo para\ncada nível do espaço acima do 6°."},{"id":"criar-mortos-vivos","name":"Criar Mortos-Vivos","level":6,"school":"necromancia","ritual":false,"classes":["bruxo","clerigo","mago"],"pdfPage":233,"time":"1 minuto","range":"3 metros","components":"V, S, M (um pote de barro cheio de terra de sepultura, um pote de barro cheio de água salobra, e uma ônix negra no valor de 150 po, para cada corpo)","duration":"Instantânea","concentration":false,"text":"6° nível de necromancia\nTempo de Conjuração: 1 minuto\nAlcance: 3 metros\nComponentes: V, S, M (um pote de barro cheio de terra\n   de sepultura, um pote de barro cheio de água salobra,\n   e uma ônix negra no valor de 150 po, para cada corpo)\nDuração: Instantânea\nVocê só pode conjurar essa magia durante a noite.\nEscolha até três corpos de humanoides Médios ou\nPequenos dentro do alcance. Cada corpo se torna um\ncarniçal sob seu controle. (O Mestre tem as estatísticas de\njogo das criaturas.)\n   Com uma ação bônus, em cada um dos seus turnos,\nvocê pode comandar mentalmente qualquer criatura que\nvocê animou com essa magia, se a criatura estiver a até\n36 metros de você (se você controla diversas criaturas,\nvocê pode comandar qualquer uma ou todas elas ao\nmesmo tempo, emitindo o mesmo comando para cada\numa). Você decide qual ação a criatura irá fazer e para\nonde ela irá se mover durante o próximo turno dela, ou\nvocê pode emitir um comando geral, como para guardar\numa câmara ou corredor especifico. Se você não der\nnenhum comando, as criaturas apenas se defenderão\ncontra criaturas hostis. Uma vez que receba uma ordem,\na criatura continuará a segui-la até a tarefa estar\nconcluída.\n   A criatura fica sob seu controle por 24 horas, depois\ndisso ela para de obedecer aos seus comandos. Para\nmanter o controle da criatura por mais 24 horas, você\ndeve conjurar essa magia na criatura novamente, antes\ndas 24 horas atuais terminarem. Esse uso da magia\nrecupera seu controle sobre até três criaturas que você\ntenha animado com essa magia, ao invés de animar\nnovas.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 7° nível, você pode\nanimar ou recuperar o controle de quatro carniçais.\nQuando você conjura essa magia usando um espaço de\nmagia de 8° nível, você pode animar ou recuperar o\ncontrole de cinco carniçais ou dois lívidos ou aparições.\nQuando você conjurar essa magia usando um espaço de\nmagia de 9° nível, você pode animar ou recuperar o\ncontrole de seis carniçais, três lívidos ou aparições ou\nduas múmias."},{"id":"cura-completa","name":"Cura Completa","level":6,"school":"evocação","ritual":false,"classes":["clerigo","druida"],"pdfPage":234,"time":"1 ação","range":"18 metros","components":"V, S","duration":"Instantânea","concentration":false,"text":"6° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, S\nDuração: Instantânea\nEscolha uma criatura que você possa ver, dentro do\nalcance. Um surto de energia positiva banha a criatura,\nfazendo-a recuperar 70 pontos de vida. Essa magia\ntambém acaba com efeitos de cegueira, surdez e qualquer\ndoença que estejam afetando o alvo. Essa magia não tem\nefeito em constructos ou mortos-vivos.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 7° nível ou\nsuperior, a quantidade de cura aumenta em 10 para cada\nnível do espaço acima do 6°."},{"id":"circulo-da-morte","name":"Círculo da Morte","level":6,"school":"necromancia","ritual":false,"classes":["bruxo","feiticeiro","mago"],"pdfPage":225,"time":"1 ação","range":"45 metros","components":"V, S, M (o pó de uma pérola negra esmagada valendo, no mínimo, 500 po)","duration":"Instantânea","concentration":false,"text":"6° nível de necromancia\nTempo de Conjuração: 1 ação\nAlcance: 45 metros\nComponentes: V, S, M (o pó de uma pérola negra\n   esmagada valendo, no mínimo, 500 po)\nDuração: Instantânea\nUma esfera de energia negativa ondula em um raio de 18\nmetros de um ponto ao alcance. Cada criatura na área\ndeve realizar um teste de resistência de Constituição. Um\nalvo sofre 8d6 de dano necrótico se falhar no seu teste de\nresistência, ou metade desse dano se passar.\n    Em Níveis Superiores. Se você conjurar essa magia\nusando um espaço de magia de 7° nível ou superior, o\ndano aumenta em 2d6 para cada nível do espaço acima do\n6°."},{"id":"danca-irresistivel-de-otto","name":"Dança Irresistível de Otto","level":6,"school":"encantamento","ritual":false,"classes":["bardo","mago"],"pdfPage":235,"time":"1 ação","range":"9 metros","components":"V","duration":"Concentração, até 1 minuto","concentration":true,"text":"6° nível de encantamento\nTempo de Conjuração: 1 ação\nAlcance: 9 metros\nComponentes: V\nDuração: Concentração, até 1 minuto\nEscolha uma criatura que você possa ver, dentro do\nalcance. O alvo começa a dançar comicamente no lugar:\nrodopiando, batendo os pés e saltitando pela duração. As\ncriaturas que não podem ser enfeitiçadas são imunes a\nessa magia.\n    Uma criatura dançando deve usar todo o seu\nmovimento para dançar sem abandonar seu espaço e tem\ndesvantagem nos testes de resistência de Destreza e nas\njogadas de ataque. Enquanto o alvo estiver sob efeito\ndessa magia, as outras criaturas terão vantagem nas\njogadas de ataque contra ele. Com uma ação, uma\ncriatura dançando pode realizar um teste de resistência\nde Sabedoria para recuperar controle sobre si mesmo.\nNum sucesso na resistência, a magia acaba."},{"id":"desintegrar","name":"Desintegrar","level":6,"school":"transmutação","ritual":false,"classes":["feiticeiro","mago"],"pdfPage":236,"time":"1 ação","range":"18 metros","components":"V, S, M (um ímã e uma pitada de poeira)","duration":"Instantânea","concentration":false,"text":"6° nível de transmutação\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, S, M (um ímã e uma pitada de poeira)\nDuração: Instantânea\nUm fino raio esverdeado é lançado da ponta do seu dedo\nem um alvo que você possa ver dentro do alcance. O alvo\npode ser uma criatura, um objeto ou uma criação de\nenergia mágica, como uma muralha criada por muralha\nde energia.\n    Uma criatura afetada por essa magia deve realizar um\nteste de resistência de Destreza. Se falhar na resistência,\no alvo sofrerá 10d6 + 40 de dano de energia. Se esse dano\nreduzir os pontos de vida do alvo a 0, ele será\ndesintegrado.\n    Uma criatura desintegrada e tudo que ela está\nvestindo ou carregando, exceto itens mágicos, são\nreduzidos a uma pilha de um fino pó acinzentado. A\ncriatura só pode ser trazida de volta a vida por meio das\nmagias ressurreição verdadeira ou desejo.\n    Essa magia desintegra, automaticamente, um objeto\nnão-mágico Grande ou menor ou uma criação de energia\nmágica. Se o alvo for um objeto ou criação de energia\nEnorme ou maior, a magia desintegra uma porção de 3\nmetros cúbicos dele. Um item mágico não pode ser afetado\npor essa magia.\n    Em Níveis Superiores. Se você conjurar essa magia\nusando um espaço de magia de 7° nível ou superior, o\ndano aumenta em 3d6 para cada nível do espaço acima do\n6°."},{"id":"doenca-plena","name":"Doença Plena","level":6,"school":"necromancia","ritual":false,"classes":["clerigo"],"pdfPage":239,"time":"1 ação","range":"18 metros","components":"V, S","duration":"Instantânea","concentration":false,"text":"6° nível de necromancia\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, S\nDuração: Instantânea\nVocê introduz uma doença virulenta em uma criatura que\nvocê puder ver, dentro do alcance. O alvo deve realizar\num teste de resistência de Constituição. Se falhar na\nresistência, ele sofre 14d6 de dano necrótico ou metade\ndesse dano se obtiver sucesso na resistência. O dano não\npode reduzir os pontos de vida do alvo abaixo de 1. Se o\nalvo falhar no teste de resistência, seu máximo de pontos\nde vida é reduzidos por 1 hora em uma quantidade igual\nao dano necrótico causado. Qualquer efeito que remova\numa doença permitirá que o máximo de pontos de vida do\nalvo volte ao normal antes do período indicado."},{"id":"encontrar-o-caminho","name":"Encontrar o Caminho","level":6,"school":"adivinhação","ritual":false,"classes":["bardo","clerigo","druida"],"pdfPage":240,"time":"1 minuto","range":"Pessoal","components":"V, S, M (um conjunto de ferramentas de adivinhação – como ossos, bastões de marfim, dentes ou runas esculpidas – no valor de 100 po e um objeto do lugar que você deseja encontrar)","duration":"Concentração, até 1 dia","concentration":true,"text":"6° nível de adivinhação\nTempo de Conjuração: 1 minuto\nAlcance: Pessoal\nComponentes: V, S, M (um conjunto de ferramentas de\n  adivinhação – como ossos, bastões de marfim, dentes\n  ou runas esculpidas – no valor de 100 po e um objeto\n  do lugar que você deseja encontrar)\nDuração: Concentração, até 1 dia\nEssa magia permite que você encontre a rota física mais\ncurta e direta para um local especifico estático, que você\nseja familiar, no mesmo plano de existência. Se você\ndenominar um destino em outro plano de existência, um\nlocal que se mova (como uma fortaleza andante) ou um\ndestino que não seja especifico (como “o covil do dragão\nverde”), a magia falha.\n    Pela duração, contanto que você esteja no mesmo\nplano de existência do destino, você saberá o quão longe\nele está e em que direção ele se encontra. Enquanto\nestiver viajando, sempre que você se deparar com uma\nescolha de trajetória no caminho, você automaticamente\ndetermina qual trajetória tem a rota mais curta e direta\n(mas não necessariamente a rota mais segura) para o\ndestino."},{"id":"esfera-congelante-de-otiluke","name":"Esfera Congelante de Otiluke","level":6,"school":"evocação","ritual":false,"classes":["mago"],"pdfPage":242,"time":"1 ação","range":"90 metros","components":"V, S, M (uma pequena esfera de cristal)","duration":"Instantânea","concentration":false,"text":"6° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: 90 metros\nComponentes: V, S, M (uma pequena esfera de cristal)\nDuração: Instantânea\nUm globo frigido de energia gelada é arremessado das\npontas dos seus dedos para um ponto, à sua escolha,\ndentro do alcance, onde ele explode numa esfera de 18\nmetros de raio. Cada criatura dentro da área deve\nrealizar um teste de resistência de Constituição. Se falhar\nna resistência, uma criatura sofre 10d6 de dano de frio.\nSe obtiver sucesso na resistência, ela sofre metade desse\ndano.\n    Se o globo atingir um corpo de água ou liquido\ncomposto principalmente de água (não incluindo criaturas\nfeitas de água), ele congela o líquido até uma\nprofundidade de 15 centímetros numa área de 9 metros\nquadrados. Esse gelo dura por 1 minuto. Criaturas que\nestiverem nadando na superfície de água congelada\nestarão presas no gelo. Uma criatura presa pode usar sua\nação para realizar um teste de Força contra a CD da\nmagia para se libertar.\n   Você pode evitar de disparar o globo após completar a\nmagia, se desejar. Um pequeno globo, do tamanho de uma\npedra de funda, frio ao toque, aparece em sua mão. A\nqualquer momento, você ou uma criatura a quem você\nentregar o globo, pode arremessa-lo (a uma distância de\n12 metros) ou atira-lo com uma funda (ao alcance normal\nda funda). Ele se despedaça no impacto, produzindo o\nmesmo efeito da conjuração normal da magia. Você pode,\ntambém, soltar o globo no chão sem despedaça-lo. Após 1\nminuto, se o globo ainda não tiver se despedaçado, ele\nexplode.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 7° nível ou\nsuperior, o dano aumenta em 1d6 para cada nível do\nespaço acima do 6°."},{"id":"globo-de-invulnerabilidade","name":"Globo de Invulnerabilidade","level":6,"school":"abjuração","ritual":false,"classes":["feiticeiro","mago"],"pdfPage":247,"time":"1 ação","range":"Pessoal (3 metros de raio)","components":"V, S, M (uma perola de vidro ou cristal que se despedaça quando a magia termina)","duration":"Concentração, até 1 minuto","concentration":true,"text":"6° nível de abjuração\nTempo de Conjuração: 1 ação\nAlcance: Pessoal (3 metros de raio)\nComponentes: V, S, M (uma perola de vidro ou cristal\n   que se despedaça quando a magia termina)\nDuração: Concentração, até 1 minuto\nUma barreira imóvel, levemente cintilante, surge do nada\nnum raio de 3 metros centrado em você e permanece pela\nduração.\n    Qualquer magia de 5° nível ou inferior conjurada de\nfora da barreira não poderá afetar as criaturas ou objetos\ndentro dela, mesmo que a magia seja conjurada usando\num espaço de magia de nível superior. Tais magias podem\nter como alvo criaturas e objetos dentro da barreira, mas\na magia não produz nenhum efeito neles. Similarmente, a\nárea dentro da barreira é excluída das áreas afetadas por\ntais magias.\n    Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 7° nível ou\nsuperior, a barreira bloqueia magias de um nível superior\npara cada nível do espaço acima do 6°."},{"id":"ilusao-programada","name":"Ilusão Programada","level":6,"school":"ilusão","ritual":false,"classes":["bardo","mago"],"pdfPage":248,"time":"1 ação","range":"36 metros","components":"V, S, M (um pouco de lã e pó de jade valendo, no mínimo, 25 po)","duration":"Até ser dissipada","concentration":false,"text":"6° nível de ilusão\nTempo de Conjuração: 1 ação\nAlcance: 36 metros\nComponentes: V, S, M (um pouco de lã e pó de jade\n   valendo, no mínimo, 25 po)\nDuração: Até ser dissipada\nVocê cria uma ilusão de um objeto, uma criatura ou de\nalgum outro fenômeno visível, dentro do alcance, que se\nativa quando uma condição especifica ocorre. A ilusão é\nimperceptível até esse momento. Ela não pode ter mais de\n9 metros cúbicos e você decide, quando conjura a magia,\ncomo a ilusão se comporta e quais sons ela faz. Essa\nperformance roteirizada por durar até 5 minutos.\n    Quando a condição que você especificou ocorrer, a\nilusão surge do nada e age da maneira que você\ndescreveu. Uma vez que a ilusão tenha acabado de agir,\nela desaparece e permanece dormente por 10 minutos.\nApós desse período, a ilusão pode se ativar novamente.\n    A condição de ativação pode ser tão genérica ou tão\ndetalhada quando você quiser, apesar de ela precisar ser\nbaseada em condições visuais ou audíveis que ocorram a\naté 9 metros da área. Por exemplo, você poderia criar uma\nilusão, de si mesmo, que aparecerá e avisará a outros que\ntentarem abrir a porta com armadilha ou você pode\nprogramar a ilusão para se ativar apenas quando uma\ncriatura disser a palavra ou frase correta.\n    Interação física com a imagem revelará ela como sendo\numa ilusão, já que as coisas podem atravessa-la. Uma\ncriatura que usar sua ação para examinar a imagem,\npode determinar que ela é uma ilusão sendo bem sucedida\nnum teste de Inteligência (Investigação) contra a CD da\nmagia para desacredita-la. Se a criatura discernir a\nilusão como ela é, a criatura poderá ver através da\nimagem e qualquer barulho que ela fizer soará oco para a\ncriatura."},{"id":"invocacao-instantanea-de-drawmij","name":"Invocação Instantânea de Drawmij","level":6,"school":"conjuração","ritual":true,"classes":["mago"],"pdfPage":251,"time":"1 minuto","range":"Toque","components":"V, S, M (uma safira no valor de 1.000 po)","duration":"Até ser dissipada","concentration":false,"text":"6° nível de conjuração (ritual)\nTempo de Conjuração: 1 minuto\nAlcance: Toque\nComponentes: V, S, M (uma safira no valor de 1.000 po)\nDuração: Até ser dissipada\nVocê toca um objeto pesando 5 quilos ou menos com maior\ndimensão de 1,8 metro ou menos. A magia deixa uma\nmarca invisível na sua superfície e grava invisivelmente o\nnome do item na safira que você usou como componente\nmaterial. A cada vez que você conjurar essa magia, você\ndeve usar uma safira diferente.\n   A qualquer momento, posteriormente, você pode usar\nsua ação para falar o nome do item e esmagar a safira. O\nitem aparece instantaneamente em suas mãos,\nindependentemente de distâncias físicas ou planares, e a\nmagia termina.\n   Se outra criatura estiver segurando ou carregando o\nitem, esmagar a safira não irá transportar o item até\nvocê, ao invés disso, você descobre quem é a criatura\npossuindo o objeto e onde, vagamente, a criatura está\nlocalizada no momento.\n   Dissipar magia ou um efeito similar aplicado com\nsucesso na safira, termina o efeito da magia."},{"id":"mover-terra","name":"Mover Terra","level":6,"school":"transmutação","ritual":false,"classes":["druida","feiticeiro","mago"],"pdfPage":258,"time":"1 ação","range":"36 metros","components":"V, S, M (uma lâmina de ferro e uma pequena sacola contendo uma mistura de solos – argila, barro e areia)","duration":"Concentração, até 2 horas","concentration":true,"text":"6° nível de transmutação\nTempo de Conjuração: 1 ação\nAlcance: 36 metros\nComponentes: V, S, M (uma lâmina de ferro e uma\n   pequena sacola contendo uma mistura de solos –\n   argila, barro e areia)\nDuração: Concentração, até 2 horas\nEscolha uma área de terreno não maior que 12 metros de\nlado, dentro do alcance. Você pode remodelar terra, areia\nou barro na área da maneira que quiser, pera duração.\nVocê pode erguer ou abaixar a elevação da área, criar ou\npreencher valas, levantar ou deitar um muro ou formar\numa coluna. A extensão de tais mudanças não pode\nexceder metade da maior dimensão da área. Portanto, se\nvocê afetar um quadrado de 12 metros, você poderá criar\num pilar de até 6 metros de altura, erguer ou abaixar a\nelevação do quadrado em até 6 metros ou cavar uma vala\nde até 6 metros de profundidade e assim por diante. Leva\n10 minutos para completar essas modificações.\n    Ao final de cada 10 minutos que você gastar se\nconcentrando nessa magia, você pode escolher uma nova\nárea de terreno para afetar.\n    Devido às transformações no terreno ocorrerem\nlentamente, as criaturas na área normalmente não podem\nficar presas ou sofrer dano pela movimentação do solo.\n    Essa magia pode manipular rocha natural ou\nconstruções de pedra. Pedra e estruturas deslocam-se\npara acomodar o novo terreno. Se a forma pela qual você\nmodela o terreno poderia tornar uma estrutura instável,\nela poderá desmoronar.\n    Similarmente, essa magia não afeta diretamente o\ncrescimento da vegetação. A terra movida carrega\nquaisquer plantas no caminho junto com ela."},{"id":"muralha-de-espinhos","name":"Muralha de Espinhos","level":6,"school":"conjuração","ritual":false,"classes":["druida"],"pdfPage":259,"time":"1 ação","range":"36 metros","components":"V, S, M (um punhado de espinhos)","duration":"Concentração, até 10 minutos","concentration":true,"text":"6° nível de conjuração\nTempo de Conjuração: 1 ação\nAlcance: 36 metros\nComponentes: V, S, M (um punhado de espinhos)\nDuração: Concentração, até 10 minutos\nVocê cria uma muralha de arbustos robustos, flexíveis,\nemaranhados e eriçados com espinhos pontudos. A\nmuralha aparece, dentro do alcance, em uma superfície\nsólida e permanece pela duração. Você escolher fazer a\nmuralha com até 18 metros de comprimento, 3 metros de\naltura e 1,5 metro de espessura ou um círculo com 6\nmetros de diâmetro e até 6 metros de altura com 1,5\nmetro de espessura. A muralha bloqueia a visão.\n    Quando a muralha aparece, cada criatura dentro da\nárea deve realizar um teste de resistência de Destreza. Se\nfalhar na resistência, uma criatura sofrerá 7d8 de dano\nperfurante ou metade desse dano se obtiver sucesso.\n    Uma criatura pode se mover através da muralha,\nembora lentamente e dolorosamente. Para cada 1,5 metro\nque a criatura atravesse da muralha, ela deve gastar 6\nmetros de movimento. Além disso, a primeira vez que a\ncriatura entrar na muralha num turno ou termina o\nturno nela, ela deve fazer um teste de resistência de\nDestreza. Ela sofre 7d8 de dano cortante se falhar na\nresistência ou metade desse dano se obtiver sucesso.\n    Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 7° nível ou\nsuperior, ambos os tipos de dano aumentam em 1d8 para\ncada nível do espaço acima do 6°."},{"id":"muralha-de-gelo","name":"Muralha de Gelo","level":6,"school":"evocação","ritual":false,"classes":["mago"],"pdfPage":259,"time":"1 ação","range":"36 metros","components":"V, S, M (um pequeno pedaço de quartzo)","duration":"Concentração, até 10 minutos","concentration":true,"text":"6° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: 36 metros\nComponentes: V, S, M (um pequeno pedaço de quartzo)\nDuração: Concentração, até 10 minutos\nVocê cria uma muralha de gelo numa superfície sólida\ndentro do alcance. Você pode molda-la em uma cúpula\nhemisférica ou uma esfera com um raio de até dez painéis\nde 3 metros por 3 metros. Cada painel deve ser contíguo\ncom outro painel. Em qualquer formato, a muralha terá\n0,6 centímetros de espessura. Ela permanece pela\nduração.\n    Se a muralha passar pelo espaço ocupado por uma\ncriatura quando ela surgir, a criatura na área será\nempurrada para um dos lados da muralha (você escolhe\nqual lado) e deve realizar um teste de resistência de\nDestreza. Se falhar na resistência, a criatura sofrerá 10d6\nde dano de frio ou metade desse dano se passar na\nresistência.\n    A muralha é um objeto que pode ser danificado e\nentão, partido. Ela tem CA 12, 30 pontos de vida por\nseção de 3 metros e é vulnerável a dano de fogo. Reduzir\nos pontos de vida de uma seção de 3 metros da muralha a\n0 destruirá essa seção, deixando para trás uma camada\nde ar gelado no espaço ocupado pela muralha. Uma\ncriatura que atravesse a camada de ar gelado pela\nprimeira vez num turno, deve realizar um teste de\nresistência de Constituição. Essa criatura sofrerá 5d6 de\ndano de frio se fracassar na resistência, ou metade desse\ndano se obtiver sucesso.\n   Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 7° nível ou\nsuperior, o dano causado quando ela aparece aumenta em\n2d6 e o dano por atravessar através da camada de ar\ngelado aumenta em 1d6 para cada nível do espaço acima\ndo 6°."},{"id":"palavra-de-recordacao","name":"Palavra de Recordação","level":6,"school":"conjuração","ritual":false,"classes":["clerigo"],"pdfPage":265,"time":"1 ação","range":"1,5 metro","components":"V","duration":"Instantânea","concentration":false,"text":"6° nível de conjuração\nTempo de Conjuração: 1 ação\nAlcance: 1,5 metro\nComponentes: V\nDuração: Instantânea\nVocê e até cinco criaturas voluntária a 1,5 metro de você,\ninstantaneamente são teletransportadas para um\nsantuário previamente designado. Você e qualquer\ncriatura que se teletransportar com você, aparece no\nespaço desocupado mais próximo do ponto que você\ndesignou quando preparou seu santuário (veja abaixo). Se\nvocê conjurar essa magia sem ter preparado um santuário\nprimeiro, a magia não funciona.\n    Você deve designar um santuário na conjuração dessa\nmagia dentro de um local, como um templo dedicado ou\nfortemente ligado a sua divindade. Se você tentar\nconjurar essa magia dessa forma em uma área que não\nseja dedicada à sua divindade, a magia não funciona."},{"id":"portal-arcano","name":"Portal Arcano","level":6,"school":"conjuração","ritual":false,"classes":["bruxo","feiticeiro","mago"],"pdfPage":267,"time":"1 ação","range":"150 metros","components":"V, S","duration":"Concentração, até 10 minutos","concentration":true,"text":"6° nível de conjuração\nTempo de Conjuração: 1 ação\nAlcance: 150 metros\nComponentes: V, S\nDuração: Concentração, até 10 minutos\nVocê cria portais de teletransporte conectados que\npermanecem abertos pela duração. Escolha dois pontos no\nsolo que você possa ver, um ponto a até 3 metros de você e\noutro a até 150 metros de você. Um portal circular, com 3\nmetros de diâmetro, se abre em cada ponto. Se o portal se\nabriria num local ocupado por uma criatura, a magia\nfalha e a conjuração é perdida.\n   Os portais são dois anéis dimensionais brilhantes\ncheios de névoa, flutuando a centímetros do chão,\nperpendicular a ele no ponto escolhido. Um anel é visível\napenas de um lado (à sua escolha), que é o lado que\nfunciona como portal.\n   Qualquer criatura ou objeto que adentrar o portal,\nsairá pelo outro portal, como se ambos estivessem\nadjacentes um ao outro; atravessar um portal do lado que\nnão é um portal não tem efeito. A névoa que preenche\ncada portal é opaca e bloqueia a visão através dele. No\nseu turno, você pode girar os anéis, com uma ação bônus,\nfazendo o lado ativo ficar em uma direção diferente."},{"id":"proibicao","name":"Proibição","level":6,"school":"abjuração","ritual":true,"classes":["clerigo"],"pdfPage":269,"time":"10 minutos","range":"Toque","components":"V, S, M (uma borrifada de água benta, incensos raros e pó de rubi valendo, no mínimo, 1.000 po)","duration":"1 dia","concentration":false,"text":"6° nível de abjuração (ritual)\nTempo de Conjuração: 10 minutos\nAlcance: Toque\nComponentes: V, S, M (uma borrifada de água benta,\n   incensos raros e pó de rubi valendo, no mínimo,\n   1.000 po)\nDuração: 1 dia\nVocê cria uma defesa contra viagem mágica que protege\naté 12.000 metros quadrados de solo até 9 metros de\naltura do solo. Pela duração, criaturas não conseguem se\nteletransportar para dentro da área ou usar portais, como\nos criados pela magia portal, para entrar na área. A\nmagia protege a área contra viagem planar e, portanto,\nimpede criaturas de acessarem a área por meio do Plano\nAstra, Plano Etéreo, Faéria, Umbra ou pela magia viagem\nplanar.\n    Além disso, a magia causa dano a certos tipos de\ncriatura, à sua escolha, quando a conjurar. Escolha um ou\nmais dentre os seguintes: celestiais, corruptores,\nelementais, fadas ou mortos-vivos. Quando uma criatura\nescolhida entrar na área da magia pela primeira vez em\num turno ou começa seu turno nela, a criatura sofre 5d6\nde dano radiante ou necrótico (à sua escolha, quando você\nconjura a magia).\n    Quando você conjura essa magia, você pode definir\numa senha. Uma criatura que falar a senha quando\nentrar na área não sofrerá dano dessa magia.\n    A área da magia não pode sobrepor a área de outra\nmagia proibição. Se você conjurar proibição a cada dia por\n30 dias no mesmo local, a magia durará até ser dissipada,\ne os componentes materiais serão consumidos apenas na\núltima conjuração."},{"id":"proteger-fortaleza","name":"Proteger Fortaleza","level":6,"school":"abjuração","ritual":false,"classes":["bardo","mago"],"pdfPage":271,"time":"10 minutos","range":"Toque","components":"V, S, M (incenso aceso, uma porção de enxofre e óleo, uma corda amarrada, uma porção de sangue de tribulo brutal e um pequeno bastão de prata valendo, no mínimo, 10 po)","duration":"24 horas","concentration":false,"text":"6° nível de abjuração\nTempo de Conjuração: 10 minutos\nAlcance: Toque\nComponentes: V, S, M (incenso aceso, uma porção de\n   enxofre e óleo, uma corda amarrada, uma porção de\n   sangue de tribulo brutal e um pequeno bastão de prata\n   valendo, no mínimo, 10 po)\nDuração: 24 horas\nVocê cria uma defesa que protege até 225 metros\nquadrados de espaço (uma área de um quadrado de 15\nmetros ou cem quadrados de 1,5 metro ou vinte e cinco\nquadrados de 3 metros). A área protegida pode ter até 6\nmetros de altura, no formado que você desejar. Você pode\nproteger diversos armazéns de uma fortaleza dividindo a\nárea entre eles, contanto que você possa andar em cada\nárea contígua enquanto estiver conjurando a magia.\n    Quando você conjura essa magia, você pode especificar\nindivíduos que não serão afetados por qualquer dos\nefeitos que você escolher. Você também pode especificar\numa senha que, ao ser falada em voz alta, deixa o orador\nimune aos efeitos.\n    Proteger fortaleza cria os seguintes efeitos dentro da\nárea protegida.\n    Corredores. Névoa preenche todos os corredores\nprotegidos, tornando-os área de escuridão densa. Além\ndisso, cada interseção ou passagem ramificada oferecendo\numa escolha de direção, há 50 por cento de chance de uma\ncriatura diferente de você acredite que está indo na\ndireção oposta à que escolheu.\n    Portas. Todas as portas na área protegida estão\ntrancadas magicamente, como se estivessem seladas pela\nmagia tranca arcana. Além disso, você pode cobrir até dez\nportas com uma ilusão (equivalente a função de objeto\nilusório da magia ilusão menor) para fazê-las parecer\nseções simples da parede.\n    Escadas. Teias preenchem todas as escadas na área\nprotegida do topo ao solo, como a magia teia. Esses fios\nvoltam a crescer em 10 minutos se forem queimados ou\npartidos enquanto proteger fortaleza durar.\n    Outros Efeitos de Magia. Você pode colocar, à sua\nescolha, um dos seguintes efeitos mágicos dentro da área\nprotegida de uma fortaleza.\n   Colocar globos de luz em quatro corredores. Você pode\n    designar uma programação simples que as luzes\n    repetem enquanto proteger fortaleza durar.\n   Colocar boca encantada em duas localizações.\n   Colocar névoa fétida em duas localizações. Os vapores\n    aparecem nos locais que você designar; eles retornam\n    dentro de 10 minutos, se forem dispersados por um\n    vento, enquanto proteger fortaleza durar.\n   Colocar uma lufada de vento constante em um\n    corredor ou aposento.\n   Colocar uma sugestão em uma localização. Você\n    seleciona uma área de um quadrado de 1,5 metro e,\n    qualquer criatura que entrar ou passar através dessa\n    área recebe a sugestão mentalmente.\n\n   A área protegida inteira irradia magia. Uma dissipar\nmagia conjurada em uma área especifica, se for bem\nsucedida, remove apenas aquele efeito.\n   Você pode criar uma estrutura, permanentemente,\nafetada por proteger fortaleza ao conjurar essa magia nela\na cada dia por um ano."},{"id":"raio-solar","name":"Raio Solar","level":6,"school":"evocação","ritual":false,"classes":["druida","feiticeiro","mago"],"pdfPage":273,"time":"1 ação","range":"Pessoal (linha de 18 metros)","components":"V, S, M (uma lente de aumento)","duration":"Concentração, até 1 minuto","concentration":true,"text":"6° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: Pessoal (linha de 18 metros)\nComponentes: V, S, M (uma lente de aumento)\nDuração: Concentração, até 1 minuto\nUm raio de luz brilhante surge da sua mão em uma linha\nde 18 metros de comprimento por 1,5 metro de largura.\nCada criatura na linha deve realizar um teste de\nresistência de Constituição. Se falhar na resistência, uma\ncriatura sofrerá 6d8 de dano radiante e ficará cega até\nseu próximo turno. Se passar na resistência, ela sofrerá\nmetade desse dano e não ficará cega pela magia. Mortos-\nvivos e limos tem desvantagem nos seus testes de\nresistência.\n    Você pode criar uma linha de radiação com sua ação\nem qualquer turno, até a magia acabar.\n    Pela duração, uma fagulha de radiação luminosa\nbrilha na sua mão. Ela emite luz plena num raio de 9\nmetros e penumbra por 9 metros adicionais. Essa luz é\nluz do sol."},{"id":"recipiente-arcano","name":"Recipiente Arcano","level":6,"school":"necromancia","ritual":false,"classes":["mago"],"pdfPage":275,"time":"1 minuto","range":"Pessoal","components":"V, S, M (uma gema, cristal, relicário ou algum outro tipo de recipiente ornamental valendo, no mínimo, 500 po)","duration":"Até ser dissipada","concentration":false,"text":"6° nível de necromancia\nTempo de Conjuração: 1 minuto\nAlcance: Pessoal\nComponentes: V, S, M (uma gema, cristal, relicário ou\n   algum outro tipo de recipiente ornamental valendo, no\n   mínimo, 500 po)\nDuração: Até ser dissipada\nSeu corpo entra em um estado catatônico, enquanto sua\nalma o abandona e entra num recipiente que você usa\ncomo componente material da magia. Enquanto sua alma\npermanecer no recipiente, você estará ciente do seu\nentorno como se você estivesse no espaço do recipiente.\nVocê não pode se mover ou usar reações. A única ação que\nvocê pode realizar é projetar sua alma a até 30 metros do\nrecipiente, tanto para retornar para o seu corpo\n(terminando a magia) ou para tentar possuir um corpo\nhumanoide.\n    Você pode tentar possuir qualquer humanoide a até 30\nmetros de você que você possa ver (criaturas protegidas\npelas magias proteção contra o bem e mal ou círculo\nmágico não podem ser possuídas). O alvo deve realizar\num teste de resistência de Carisma. Se falhar, sua alma\nse move para o corpo do alvo e a alma do alvo fica\naprisionada no recipiente. Se obtiver sucesso, o alvo\nresiste aos seus esforços em possuí-lo e você não poderá\ntentar possuí-lo novamente por 24 horas.\n    Uma vez que tenha possuído o corpo de uma criatura,\nvocê a controla. Suas estatísticas de jogo são substituídas\npelas estatísticas da criatura, no entanto, você mantem\nsua tendência e seus valores de Inteligência, Sabedoria e\nCarisma. Você mantem os benefícios das suas\ncaracterísticas de classe. Se o alvo tiver quaisquer níveis\nde classe, você não pode usar quaisquer das\ncaracterísticas de classe dele.\n    Nesse período, a alma da criatura possuída pode\nperceber do recipiente usando os sentidos dela, mas, no\nmais, não pode se mover ou realizar quaisquer ações.\n    Enquanto estiver possuindo um corpo, você pode usar\nsua ação para retornar do corpo do hospedeiro para o\nrecipiente se ele estiver a até 30 metros de você,\ndevolvendo a alma da criatura hospedeira para o corpo\ndela. Se o corpo do hospedeiro morrer enquanto você\nestiver dentro dele, a criatura morre e você deve realizar\num teste de resistência de Carisma contra a sua CD de\nconjuração. Se obtiver sucesso, você retorna ao recipiente\nse ele estiver a até 30 metros de você. Caso contrário, você\nmorre.\n    Se o recipiente for destruído ou a magia acabar, sua\nalma, imediatamente, retorna para o seu corpo. Se seu\ncorpo estiver a mais de 30 metros de você ou se seu corpo\nestiver morto quando você tentar retornar para ele, você\nmorre. Se a alma de outra criatura estiver no recipiente\nquando ele for destruído, a alma da criatura volta para o\ncorpo dela se o corpo estiver vivo e a até 30 metros dela.\nCaso contrário, a criatura morre.\n    Quando a magia acabar, o recipiente é destruído."},{"id":"sugestao-em-massa","name":"Sugestão em Massa","level":6,"school":"encantamento","ritual":false,"classes":["bardo","bruxo","feiticeiro","mago"],"pdfPage":281,"time":"1 ação","range":"18 metros","components":"V, M (uma língua de cobra e, ou um pedaço de favo de mel ou uma gota de azeite doce)","duration":"24 horas","concentration":false,"text":"6° nível de encantamento\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, M (uma língua de cobra e, ou um\n   pedaço de favo de mel ou uma gota de azeite doce)\nDuração: 24 horas\nVocê sugere um curso de atividade (limitado a uma ou\nduas sentenças) e, magicamente, influencia até dozes\ncriaturas, à sua escolha, que você possa ver dentro do\nalcance e que possam ouvir e compreender você.\nCriaturas que não podem ser enfeitiçadas são imunes a\nesse efeito. A sugestão deve ser formulada de modo que o\ncurso de ação soe razoável. Dizer para a criatura se\nesfaquear, se arremessar em uma lança, tocar fogo em si\nmesma ou fazer algum outro ato obviamente nocivo\nanulará o efeito da magia.\n    Cada alvo deve realizar um teste de resistência de\nSabedoria. Se falhar na resistência, ele seguirá o curso de\nação que você descreveu, da melhor forma possível. O\ncurso de ação sugerido pode continuar por toda a duração.\nPor exemplo, você poderia sugeria a um grupo de soldados\nque deem todo o seu dinheiro para o primeiro mendigo\nque encontrarem. Se a condição não for atingida antes da\nmagia acabar, a atividade não é realizada.\n    Se você ou um dos seus companheiros causar dano a\numa criatura afetada por essa magia, a magia termina\npara aquela criatura.\n    Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 7° nível, a duração\nserá de 10 dias. Quando você usar um espaço de magia de\n8° nível, a duração será de 30 dias. Quando você usar um\nespaço de magia de 9° nível, a duração será de 1 ano e 1\ndia."},{"id":"teletransporte-por-arvores","name":"Teletransporte por Árvores","level":6,"school":"conjuração","ritual":false,"classes":["druida"],"pdfPage":284,"time":"1 ação","range":"3 metros","components":"V, S","duration":"1 rodada","concentration":false,"text":"6° nível de conjuração\nTempo de Conjuração: 1 ação\nAlcance: 3 metros\nComponentes: V, S\nDuração: 1 rodada\nEssa magia cria uma ligação mágica entre uma planta\ninanimada Grande ou maior, dentro do alcance, e outra\nplanta a qualquer distância, no mesmo plano de\nexistência. Você deve ter visto ou tocado a planta de\ndestino, pelo menos uma vez antes. Pela duração,\nqualquer criatura pode entrar na planta alvo e sair da\nplanta destino usando 1,5 metro de movimento."},{"id":"visao-da-verdade","name":"Visão da Verdade","level":6,"school":"adivinhação","ritual":false,"classes":["bardo","bruxo","clerigo","feiticeiro","mago"],"pdfPage":288,"time":"1 ação","range":"Toque","components":"V, S, M (unguento para os olhos no valor de 25 po; ele é feito de pó de cogumelo, açafrão e gordura; e é consumido pela magia)","duration":"1 hora","concentration":false,"text":"6° nível de adivinhação\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S, M (unguento para os olhos no valor\n   de 25 po; ele é feito de pó de cogumelo, açafrão e\n   gordura; e é consumido pela magia)\nDuração: 1 hora\nEssa magia concede a uma criatura voluntária tocada a\nhabilidade de ver as coisas como elas realmente são. Pela\nduração, a criatura terá visão verdadeira, percebendo\nportas secretas escondidas por magia e podendo ver no\nPlano Etéreo, tudo num alcance de até 36 metros."},{"id":"bola-de-fogo-controlavel","name":"Bola de Fogo Controlável","level":7,"school":"evocação","ritual":false,"classes":["feiticeiro","mago"],"pdfPage":221,"time":"1 ação","range":"45 metros","components":"V, S, M (uma minúscula bola de guano de morcego e enxofre)","duration":"Concentração, até 1 minuto","concentration":true,"text":"7° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: 45 metros\nComponentes: V, S, M (uma minúscula bola de guano de\n   morcego e enxofre)\nDuração: Concentração, até 1 minuto\nUm feixe de luz amarelada é disparado da ponta do seu\ndedo, então se condensa e aguarda no ponto escolhido,\ndentro do alcance, como uma conta brilhante, pela\nduração. Quando a magia termina, seja por sua\nconcentração ter sido interrompida ou por você ter\ndecidido termina-la, a conta eclode com um estampido\nbaixo, explodindo em chamas que se espalhando,\ndobrando esquinas. Cada criatura numa esfera, com 6\nmetros de raio, centrada na conta, deve realizar um teste\nde resistência de Destreza. Uma criatura sofre dano igual\nao total de dano acumulado se falhar na resistência, ou\nmetade do total se obtiver sucesso.\n    O dano base da magia é 12d6. Se até o final do seu\nturno, a conta ainda não tiver sido detonada, o dano\naumenta em 1d6.\n    Se a conta brilhante for tocada antes do intervalo\nexpirar, a criatura que a tocou deve realizar um teste de\nresistência de Destreza. Se falhar na resistência, a magia\ntermina imediatamente, fazendo a conta explodir em\nchamas. Se obtiver sucesso na resistência, a criatura pode\narremessar a conta a até 12 metros. Quando ela atinge\numa criatura ou objeto solido, a magia termina e a conta\nexplode.\n    O fogo danifica objetos na área e incendeia objetos\ninflamáveis que não estejam sendo vestidos ou\ncarregados.\n    Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 8° nível ou\nsuperior, o dano base aumenta e 1d6 para cada nível do\nespaço acima do 7°."},{"id":"conjurar-celestial","name":"Conjurar Celestial","level":7,"school":"conjuração","ritual":false,"classes":["clerigo"],"pdfPage":228,"time":"1 minuto","range":"27 metros","components":"V, S","duration":"Concentração, até 1 hora","concentration":true,"text":"7° nível de conjuração\nTempo de Conjuração: 1 minuto\nAlcance: 27 metros\nComponentes: V, S\nDuração: Concentração, até 1 hora\nVocê invoca um celestial de nível de desafio 4 ou inferior,\nque aparece num espaço desocupado, que você possa ver\ndentro do alcance. O celestial desaparece se cair a 0\npontos de vida ou quando a magia acabar.\n    O celestial é amigável a você e a seus companheiros\npela duração. Role a iniciativa para o celestial, que age no\nseu próprio turno. Ele obedece a quaisquer comandos\nverbais que você emitir (não requer uma ação sua),\ncontanto que não violem sua tendência. Se você não\nemitir nenhum comando a ele, ele se defenderá de\ncriaturas hostis, mas no mais, não realizará nenhuma\nação.\n    O Mestre possui as estatísticas do celestial.\n    Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 9° nível, você\ninvoca um celestial de nível de desafio 5 ou inferior."},{"id":"dedo-da-morte","name":"Dedo da Morte","level":7,"school":"necromancia","ritual":false,"classes":["bruxo","feiticeiro","mago"],"pdfPage":235,"time":"1 ação","range":"18 metros","components":"V, S","duration":"Instantânea","concentration":false,"text":"7° nível de necromancia\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, S\nDuração: Instantânea\nVocê envia energia negativa na direção de uma criatura\nque você possa ver, dentro do alcance, causando dores\nseveras nela. O alvo deve realizar um teste de resistência\nde Constituição. Ele sofre 7d8 + 30 de dano necrótico se\nfalhar na resistência, ou metade desse dano se obtiver\nsucesso.\n    Um humanoide morto por essa magia, se ergue no\ninício do seu próximo turno como um zumbi que está\npermanentemente sob seu controle, seguindo suas ordens\nverbais da melhor forma possível."},{"id":"espada-de-mordenkainen","name":"Espada de Mordenkainen","level":7,"school":"evocação","ritual":false,"classes":["bardo","mago"],"pdfPage":243,"time":"1 ação","range":"18 metros","components":"V, S, M (espada de platina em miniatura com cabo e pomo de cobre e zinco valendo, no mínimo, 250 po)","duration":"Concentração, até 1 minuto","concentration":true,"text":"7° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, S, M (espada de platina em miniatura\n   com cabo e pomo de cobre e zinco valendo, no mínimo,\n   250 po)\nDuração: Concentração, até 1 minuto\n\nVocê cria um plano de energia em formato de espada que\nflutua dentro do alcance. Ela permanece pela duração.\n    Quando a espada aparece, você realiza um ataque com\nmagia contra um alvo, à sua escolha, a 1,5 metro da\nespada. Se atingir, o alvo sofre 3d10 de dano de energia.\nAté a magia acabar, você pode usar uma ação bônus, em\ncada um dos seus turnos, para mover a espada até 6\nmetros para um local que você possa ver e repetir esse\nataque contra o mesmo alvo ou um diferente."},{"id":"forma-eterea","name":"Forma Etérea","level":7,"school":"transmutação","ritual":false,"classes":["bardo","bruxo","clerigo","feiticeiro","mago"],"pdfPage":246,"time":"1 ação","range":"Pessoal","components":"V, S","duration":"até 8 horas","concentration":false,"text":"7° nível de transmutação\nTempo de Conjuração: 1 ação\nAlcance: Pessoal\nComponentes: V, S\nDuração: até 8 horas\nVocê dá um passo para dentro das fronteiras do Plano\nEtéreo, na área em que ele se sobrepõem com o seu plano\natual. Você se mantem na Fronteira Etérea pela duração\nou até você usar sua ação para dissipar a magia. Durante\nesse período, você pode se mover para qualquer direção.\nSe você se mover para cima ou para baixo, cada passo de\ndeslocamento custa um passo extra. Você pode ver e ouvir\no plano que você se originou, mas tudo parece cinzento e\nvocê não pode ver nada além de 18 metros de você.\n   Enquanto estiver no Plano Etéreo, você pode afetar e\nser afetado apenas por criaturas nesse plano. As criaturas\nque não estiverem no Plano Etéreo não podem notar sua\npresença e não podem interagir com você, a menos que\numa habilidade especial ou magia dê a elas a capacidade\nde fazê-lo.\n   Você ignora todos os objetos e efeitos que não\nestiverem no Plano Etéreo, permitindo que você se mova\natravés de objetos que você perceba no plano de onde você\nveio.\n   Quando a magia acabar, você imediatamente retorna\npara o plano de onde você se originou, no lugar que você\nestá ocupando atualmente. Se você estiver ocupando o\nmesmo espaço de um objeto sólido ou de uma criatura\nquando isso ocorrer, você é, imediatamente, desviado para\no espaço desocupado mais próximo que você puder ocupar\ne sofre dano de energia igual a dez vezes a quantidade de\nquadrados de 1,5 metro que você foi movido.\n    Essa magia não tem efeito se você conjura-la enquanto\nestiver no Plano Etéreo ou um plano que não faça\nfronteira com ele, como um dos Planos Exteriores.\n    Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 8° nível ou\nsuperior, você pode afetar até três criaturas voluntária\n(incluindo você) para cada nível do espaço acima do 7°. As\ncriaturas devem estar a até 3 metros de você quando você\nconjurar a magia."},{"id":"inverter-a-gravidade","name":"Inverter a Gravidade","level":7,"school":"transmutação","ritual":false,"classes":["druida","feiticeiro","mago"],"pdfPage":251,"time":"1 ação","range":"30 metros","components":"V, S, M (um ímã e limalhas de ferro)","duration":"Concentração, até 1 minuto","concentration":true,"text":"7° nível de transmutação\nTempo de Conjuração: 1 ação\nAlcance: 30 metros\nComponentes: V, S, M (um ímã e limalhas de ferro)\nDuração: Concentração, até 1 minuto\nEssa magia inverte a gravidade num cilindro de 15\nmetros de raio por 30 metros de altura, centrado num\nponto dentro do alcance. Todas as criaturas e objetos que\nnão esteja, de alguma forma, presos ao solo na área, caem\npara cima e alcançam o topo da área, quando você conjura\nessa magia. Uma criatura pode fazer um teste de\nresistência de Destreza para se agarrar em algum objeto\nfixo que ela possa alcançar, assim, evitando a queda.\n    Se algum objeto sólido (como um teto) for encontrado\ndurante essa queda, objetos e criaturas caindo atingem\nele, exatamente como fariam durante uma queda normal.\nSe um objeto ou criatura alcançar o topo da área sem\natingir nada, ele permanecerá lá, oscilando ligeiramente,\npela duração\n    No final da duração, objetos e criaturas afetadas caem\nde volta para baixo."},{"id":"isolamento","name":"Isolamento","level":7,"school":"transmutação","ritual":false,"classes":["mago"],"pdfPage":251,"time":"1 ação","range":"Toque","components":"V, S, M (um composto de pós de diamante, esmeralda, rubi e safira valendo, no mínimo, 5.000 po, consumidos pela magia)","duration":"Até ser dissipada","concentration":false,"text":"7° nível de transmutação\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S, M (um composto de pós de\n   diamante, esmeralda, rubi e safira valendo, no\n   mínimo, 5.000 po, consumidos pela magia)\nDuração: Até ser dissipada\nAtravés dessa magia, uma criatura voluntária ou um\nobjeto, pode ser escondido, seguro contra detecção pela\nduração. Quando você conjura essa magia e toca o alvo,\nele fica invisível e não pode ser alvo de magias de\nadivinhação ou percebido através de sensores de vidência\ncriados por magias de adivinhação.\n    Se o alvo for uma criatura, ela entra num estado de\nanimação suspensa. O tempo para de fluir para ela e ela\nnão envelhece.\n    Você pode determinar uma condição para que a magia\ntermine prematuramente. A condição pode ser qualquer\ncoisa, à sua escolha, mas deve ocorrer ou ser visível a até\n1,5 quilômetro do alvo. Exemplos incluem “depois de\n1.000 anos” ou “quando o tarrasque despertar”. Essa\nmagia também acaba se o alvo sofrer qualquer dano."},{"id":"mansao-magnifica-de-mordenkainen","name":"Mansão Magnifica de Mordenkainen","level":7,"school":"conjuração","ritual":false,"classes":["bardo","mago"],"pdfPage":254,"time":"1 minuto","range":"90 metros","components":"V, S, M (um portal em miniatura esculpido em marfim, um pedaço de mármore polido e uma pequena colher de prata, cada item valendo, no mínimo, 5 po)","duration":"24 horas","concentration":false,"text":"7° nível de conjuração\nTempo de Conjuração: 1 minuto\nAlcance: 90 metros\nComponentes: V, S, M (um portal em miniatura\n   esculpido em marfim, um pedaço de mármore polido e\n   uma pequena colher de prata, cada item valendo, no\n   mínimo, 5 po)\nDuração: 24 horas\nVocê conjura uma residência extradimensional, dentro do\nalcance, que permanece pela duração. Você escolhe onde\nsua única entrada é localizada. A entrada brilha\ndiscretamente e tem 1,5 metro de largura por 3 metros de\naltura. Você e qualquer criatura que você designou,\nquando conjurou a magia, pode entrar na residência\nextradimensional enquanto o portal permanecer aberto.\nVocê pode abrir ou fechar o portal se estiver a até 9\nmetros dele. Enquanto estiver fechado, o portal é\ninvisível.\n    Além do portal existe um magnifico salão com\ninúmeros aposentos. A atmosfera é limpa, fresca e morna.\n    Você pode criar qualquer projeto de piso que quiser,\nmas o espaço não pode exceder 50 cubos, cada cubo tendo\n3 metros de cada lado. O local é mobiliado e decorado\ncomo você desejar. Ele contém comida suficiente para\nservir nove banquetes para até 100 pessoas. Uma equipe\nde 100 servos quase-transparentes atende todos que\nentrarem. Você decide a aparência visual dos servos e o\nvestuário deles. Eles são completamente obedientes as\nsuas ordens. Cada servo pode realizar qualquer tarefa\nque um servo humano comum poderia fazer, mas eles não\npodem atacar ou realizar qualquer ação que poderia\ncausar maleficio direto a outra criatura. Portanto, os\nservos podem buscar coisas, limpar, remendar, dobrar\nroupas, acender lareiras, servir comida, despejar vinho e\nassim por diante. Os servos podem ir a qualquer lugar na\nmansão, mas não podem deixa-la. Mobília e outros objetos\ncriados por essa magia viram fumaça se forem removidos\nda mansão. Quando a magia acabar, qualquer criatura\ndentro do espaço extradimensional é expelida para o\nespaço vago mais próximo da entrada."},{"id":"miragem","name":"Miragem","level":7,"school":"ilusão","ritual":false,"classes":["bardo","druida","mago"],"pdfPage":257,"time":"10 minutos","range":"Visão","components":"V, S","duration":"10 dias","concentration":false,"text":"7° nível de ilusão\nTempo de Conjuração: 10 minutos\nAlcance: Visão\nComponentes: V, S\nDuração: 10 dias\nVocê faz um terreno em uma área de até 1,5 quilômetro\nquadrados pareça, soe, cheire e, até, sinta com outro tipo\nde terreno natural. Os formatos gerais do terreno\npermanecem os mesmos, no entanto. Campos abertos ou\numa estrada podem ser modificados para se\nassemelharem a um pântano, colina, fenda ou algum\noutro tipo de terreno difícil ou intransponível. Uma lagoa\npode ser modificada para se parecer com um prado, um\nprecipício com um declive suave ou um barranco\npedregoso com uma estrada larga e lisa.\n    Similarmente, você pode alterar a aparência de\nestruturas ou adiciona-las onde nenhuma existia. A\nmagia não disfarça, esconde ou adiciona criaturas.\n    A ilusão inclui elementos audíveis, visuais, táteis e\nolfativos, portanto, ela pode transformar solo limpo em\nterreno difícil (ou vice-versa) ou, de outra forma, impedir\no movimento através da área. Qualquer porção de terreno\nilusório (como uma rocha ou galho) que seja removida da\nárea da magia desaparece imediatamente.\n    Criaturas com visão verdadeira podem ver através da\nilusão a verdadeira forma do terreno; porém, todos os\noutros elementos da ilusão permanecem, então, mesmo\nque a criatura esteja ciente da presença da ilusão, ela\nainda interage fisicamente com a ilusão."},{"id":"palavra-divina","name":"Palavra Divina","level":7,"school":"evocação","ritual":false,"classes":["clerigo"],"pdfPage":265,"time":"1 ação bônus","range":"9 metros","components":"V","duration":"Instantânea","concentration":false,"text":"7° nível de evocação\nTempo de Conjuração: 1 ação bônus\nAlcance: 9 metros\nComponentes: V\nDuração: Instantânea\nVocê profere uma palavra divina, imbuída com o poder\nque moldou o mundo na aurora da criação. Escolha\nqualquer quantidade de criaturas que você possa ver\ndentro do alcance. Cada criatura que puder ouvir você\ndeve realizar um teste de resistência de Carisma. Ao\nfalhar na resistência, uma criatura sofre um efeito\nbaseado nos seus pontos de vida atuais:\n   50 pontos de vida ou menos: surda por 1 minuto\n   40 pontos de vida ou menos: surda e cega por 10\n    minutos\n   30 pontos de vida ou menos: surda, cega e atordoada\n    por 1 hora\n   20 pontos de vida ou menos: morta instantaneamente\n   Independentemente dos seus pontos de vida atuais,\num celestial, corruptor, elemental ou fada que falhar na\nsua resistência é obrigado a voltar para o plano de origem\ndele (se já não for aqui) e não pode retornar para o plano\natual por 24 horas através de nenhum meio inferior à\nmagia desejo."},{"id":"prisao-de-energia","name":"Prisão de Energia","level":7,"school":"evocação","ritual":false,"classes":["bardo","bruxo","mago"],"pdfPage":269,"time":"1 ação","range":"30 metros","components":"V, S, M (pó de rubi no valor de 1.500 po)","duration":"1 hora","concentration":false,"text":"7° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: 30 metros\nComponentes: V, S, M (pó de rubi no valor de 1.500 po)\nDuração: 1 hora\nUma prisão em formato cúbico, imóvel e invisível,\ncomposta de energia mágica brota do nada, em volta de\numa área, à sua escolha, dentro do alcance. A prisão pode\nser uma cela ou uma caixa sólida, à sua escolha.\n    Uma prisão em formato de cela pode ter até 6 metros\nquadrados e é feita de barras com 1,5 centímetro de\ndiâmetro espaçadas a 1,5 centímetro umas das outras.\n    Uma prisão em formato de caixa pode ter até 3 metros\nquadrados, criando uma barreira sólida que impede\nqualquer matéria de atravessa-la e bloqueia qualquer\nmagia conjurada de entrar ou sair da área.\n    Quando você conjura a magia, qualquer criatura que\nestiver completamente dentro da área da prisão ficará\npresa. As criaturas que estiverem apenas parcialmente\nna área, ou as grandes demais para caber dentro da área,\nsão empurradas do centro da área, até estarem\ncompletamente fora dela.\n    Uma criatura dentro da prisão não pode sair dela por\nmeios não-mágicos. Se a criatura tentar usar\nteletransporte ou viagem entre planos para abandonar a\nprisão, ela deve, primeiro, realizar um teste de resistência\nde Carisma. Se obtiver sucesso, a criatura pode usar a\nmagia e sair da prisão. Se falhar, a criatura não pode sair\nda prisão e desperdiça o uso da magia ou efeito. A prisão\ntambém se estende ao Plano Etéreo, bloqueando viagem\netérea.\n   Essa magia não pode ser dissipada por dissipar magia."},{"id":"projetar-imagem","name":"Projetar Imagem","level":7,"school":"ilusão","ritual":false,"classes":["bardo","mago"],"pdfPage":270,"time":"1 ação","range":"750 quilômetros","components":"V, S, M (uma pequena réplica sua feita com materiais valendo, no mínimo, 5 po)","duration":"Concentração, até 1 dia","concentration":true,"text":"7° nível de ilusão\nTempo de Conjuração: 1 ação\nAlcance: 750 quilômetros\nComponentes: V, S, M (uma pequena réplica sua feita\n   com materiais valendo, no mínimo, 5 po)\nDuração: Concentração, até 1 dia\n\nVocê cria uma cópia ilusória de si mesmo, que permanece\npela duração. A cópia pode aparecer em qualquer lugar,\ndentro do alcance, que você já tenha visto antes,\nindependentemente da intervenção de obstáculos. A\nilusão se parece e fala como você, mas é intangível. Se a\nilusão sofrer qualquer dano, ela desaparece e a magia\nacaba.\n    Você pode ver através dos olhos e ouvir através dos\nouvidos da cópia como se você estivesse no lugar dela. Em\ncada um dos seus turnos, com uma ação bônus, você pode\ntrocar o uso dos sentidos dela pelo seu ou voltar\nnovamente. Enquanto você está usando os sentidos dela,\nvocê fica cego e surdo ao que está a sua volta.\n    Interação física com a imagem revelará ela como sendo\numa ilusão, já que as coisas podem atravessa-la. Uma\ncriatura que usar sua ação para examinar a imagem,\npode determinar que ela é uma ilusão sendo bem sucedida\nnum teste de Inteligência (Investigação) contra a CD da\nmagia para desacredita-la. Se a criatura discernir a\nilusão como ela é, a criatura poderá ver através da\nimagem e qualquer barulho que ela fizer soará oco para a\ncriatura."},{"id":"rajada-prismatica","name":"Rajada Prismática","level":7,"school":"evocação","ritual":false,"classes":["feiticeiro","mago"],"pdfPage":273,"time":"1 ação","range":"Pessoal (cone de 18 metros)","components":"V, S","duration":"Instantânea","concentration":false,"text":"7° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: Pessoal (cone de 18 metros)\nComponentes: V, S\nDuração: Instantânea\nOito raios de luz multicoloridos lampejam da sua mão.\nCada raio é uma cor diferente e tem poderes e propósitos\ndiferentes. Cada criatura em um cone de 18 metros deve\nrealizar um teste de resistência de Destreza. Para cada\nalvo, role um d8 para determinar qual cor de raio afetou\nele.\n    1. Vermelho. O alvo sofre 10d6 de dano de fogo se\nfalhar na resistência ou metade desse dano se obtiver\nsucesso.\n    2. Laranja. O alvo sofre 10d6 de dano de ácido se\nfalhar na resistência ou metade desse dano se obtiver\nsucesso.\n    3. Amarelo. O alvo sofre 10d6 de dano elétrico se\nfalhar na resistência ou metade desse dano se obtiver\nsucesso.\n    4. Verde. O alvo sofre 10d6 de dano de veneno se\nfalhar na resistência ou metade desse dano se obtiver\nsucesso.\n    5. Azul. O alvo sofre 10d6 de dano de frio se falhar na\nresistência ou metade desse dano se obtiver sucesso.\n    6. Anil. Se falhar na resistência, o alvo ficará\nimpedido. Ele deve então, fazer um teste de resistência de\nConstituição ao final de cada um dos turnos dele. Se\nobtiver sucesso três vezes, a magia termina. Se falhar na\nresistência três vezes, ela se torna pedra é afetada pela\ncondição petrificado. Os sucessos e falhas não precisam\nser consecutivos; anote ambos os resultados até o alvo\nacumular três de mesmo tipo.\n    7. Violeta. Se falhar na resistência, o alvo ficará cego.\nEle deve realizar um teste de resistência de Sabedoria no\ninício do seu próximo turno. Um sucesso na resistência\nacaba com a cegueira. Se falhar na resistência, a criatura\né transportada para outro plano de existência, escolhido\npelo Mestre, e não estará mais cego. (Tipicamente, uma\ncriatura que esteja em um plano que não seja o seu plano\nnatal é banida para lá, enquanto que outras criaturas\ngeralmente são enviadas para os Planos Astral ou\nEtéreo.)\n    8. Especial. O alvo é atingido por dois raios. Role\nmais duas vezes e jogue novamente qualquer 8."},{"id":"regeneracao","name":"Regeneração","level":7,"school":"transmutação","ritual":false,"classes":["bardo","clerigo","druida"],"pdfPage":276,"time":"1 minuto","range":"Toque","components":"V, S, M (uma conta de oração e água benta)","duration":"1 hora","concentration":false,"text":"7° nível de transmutação\nTempo de Conjuração: 1 minuto\nAlcance: Toque\nComponentes: V, S, M (uma conta de oração e água\n   benta)\nDuração: 1 hora\nVocê toca uma criatura e estimula sua habilidade de cura\nnatural. O alvo recupera 4d8 + 15 pontos de vida. Pela\nduração da magia o alvo recupera 1 ponto de vida no\ninício de cada turno dela (10 pontos de vida por minuto).\n    Os membro decepados do corpo do alvo (dedos, pernas,\nrabos e assim por diante), se tiver algum, são restaurados\napós 2 minutos. Se você tiver a parte decepada e segura-\nla contra o topo, a magia, instantaneamente, faz com que\no membro se grude ao toco."},{"id":"ressurreicao","name":"Ressurreição","level":7,"school":"necromancia","ritual":false,"classes":["bardo","clerigo"],"pdfPage":276,"time":"1 hora","range":"Toque","components":"V, S, M (um diamante valendo, no mínimo, 1.000 po, consumido pela magia)","duration":"Instantânea","concentration":false,"text":"7° nível de necromancia\nTempo de Conjuração: 1 hora\nAlcance: Toque\nComponentes: V, S, M (um diamante valendo, no\n   mínimo, 1.000 po, consumido pela magia)\nDuração: Instantânea\nVocê toca uma criatura morta que não esteja assim a\nmais de um século, que não tenha morrido por velhice e\nque não seja um morto-vivo. Se a alma da criatura estiver\ndisposta e livre, o alvo volta a vida com todos os seus\npontos de vida.\n    Essa magia neutraliza quaisquer venenos e cura\ndoenças normais que afetavam a criatura no momento da\nmorte. Essa magia, no entanto, não remove doenças\nmágicas, maldições ou efeitos similares; se eles não\ntiverem sido removidos antes da conjuração da magia,\neles voltam a afetar a criatura quando ela volta a viver.\n    Essa magia fecha todos os ferimentos mortais e\nrestaura partes do corpo perdidas.\n    Voltar dos mortos é um calvário. O alvo sofre –4 de\npenalidade em todas as suas jogadas de ataque, testes de\nresistência e testes de habilidade. A cada vez que o alvo\nterminar um descanso longo, as penalidades são\nreduzidas em 1, até desaparecerem.\n    Conjurar essa magia para trazer de volta a vida uma\ncriatura que tenha morrido a um ano ou mais tempo é\nextremamente desgastante para você. Até você terminar\num descanso longo, você não pode conjurar magias\nnovamente e terá desvantagem em todas as jogadas de\nataque, testes de habilidade e testes de resistência."},{"id":"simulacro","name":"Simulacro","level":7,"school":"ilusão","ritual":false,"classes":["mago"],"pdfPage":280,"time":"12 horas","range":"Toque","components":"V, S, M (neve ou gelo em quantidade suficiente para fazer uma cópia em tamanho real da criatura duplicada; algum cabelo, recortes de unha ou outro pedaço do corpo da criatura, colocado dentro da neve ou gelo; e pó de rubi no valor de 1.500 po, polvilhado sobre a duplicata e consumido pela magia)","duration":"Até ser dissipada","concentration":false,"text":"7° nível de ilusão\nTempo de Conjuração: 12 horas\nAlcance: Toque\nComponentes: V, S, M (neve ou gelo em quantidade\n   suficiente para fazer uma cópia em tamanho real da\n   criatura duplicada; algum cabelo, recortes de unha ou\n   outro pedaço do corpo da criatura, colocado dentro da\n   neve ou gelo; e pó de rubi no valor de 1.500 po,\n   polvilhado sobre a duplicata e consumido pela magia)\nDuração: Até ser dissipada\nVocê modela uma duplicata ilusória de uma besta ou\nhumanoide, dentro do alcance, durante todo tempo de\nconjuração da magia. A duplicada é uma criatura,\nparcialmente real, formada de gelo ou neve e pode\nrealizar ações e, no mais, ser tratada como uma criatura\nnormal. Ela aparenta ser igual a original, mas tem\nmetade do máximo de pontos de vida da criatura e é\nformada sem qualquer equipamento. No mais, a ilusão\nusa todas as estatísticas da criatura que ela copiou.\n   O simulacro é amigável a você e às criaturas que você\ndesignar. Ele obedece aos seus comandos verbais, se\nmovendo e agindo de acordo com seus desejos, agindo no\nseu turno em combate. O simulacro não possui capacidade\nde aprender ou de se tornar mais poderoso, portanto, ele\nnunca subirá de nível ou ganhará outras habilidades,\nnem poderá recuperar espaços de magia gastos.\n   Se o simulacro sofrer dano, você pode repara-lo em um\nlaboratório alquímico, usando ervas e minerais raros no\nvalor de 100 po por ponto de vida recuperado. O simulacro\ndura até cair a 0 pontos de vida, no momento em que ele\nvolta a ser neve e derrete instantaneamente.\n   Se você conjurar essa magia novamente, qualquer\nduplicata atualmente ativa, que você criou com essa\nmagia, é instantaneamente destruída."},{"id":"simbolo","name":"Símbolo","level":7,"school":"abjuração","ritual":false,"classes":["bardo","clerigo","mago"],"pdfPage":279,"time":"1 minuto","range":"Toque","components":"V, S, M (mercúrio, fósforo e pó de diamante e opala, com um valor total de, no mínimo, 1.000 po, consumidos pela magia)","duration":"Até ser dissipada ou ativada","concentration":false,"text":"7° nível de abjuração\nTempo de Conjuração: 1 minuto\nAlcance: Toque\nComponentes: V, S, M (mercúrio, fósforo e pó de\n   diamante e opala, com um valor total de, no mínimo,\n   1.000 po, consumidos pela magia)\nDuração: Até ser dissipada ou ativada\nQuando você conjura essa magia, você inscreve um glifo\nnocivo, tanto sobre uma superfície (como uma secção de\npiso, uma parede ou mesa) quanto dentro de um objeto\nque possa ser fechado (como um livro, um pergaminho ou\num baú de tesouro). Se você escolher uma superfície, o\nglifo pode cobrir uma área da superfície não superior a 3\nmetros de diâmetro. Se você escolher um objeto, o objeto\ndeve permanecer no seu local; se ele for movido mais de 3\nmetros de onde você conjurou essa magia, o glifo será\nquebrado e a magia termina sem ser ativada.\n    O glifo é quase invisível e requer um teste de\nInteligência (Investigação) contra a CD da magia para ser\nencontrado.\n    Você define o que ativa o glifo quando você conjura a\nmagia. Para glifos inscritos em uma superfície, os gatilhos\nmais típicos incluem tocar ou ficar sobre o glifo, remover\noutro objeto cobrindo o glifo, aproximar-se a uma certa\ndistância do glifo ou manipular um objeto onde o glifo\nesteja inscrito. Para glifos inscritos dentro de objetos, os\ngatilhos mais comuns incluem abrir o objeto, aproximar-\nse a uma certa distância do objeto ou ver ou ler o glifo.\n    Você pode, posteriormente, aperfeiçoar o gatilho para\nque a magia se ative apenas sob certas circunstâncias ou\nde acordo com as características físicas (como altura ou\npeso), tipo de criatura (por exemplo, a proteção poderia\nser definida para afetar aberrações ou drow) ou\ntendência. Você pode, também, definir condições para\ncriaturas não ativarem o glifo, como aqueles que falarem\ndeterminada senha.\n    Quando você inscreve o glifo, escolha uma das opções\nabaixo para seu efeito. Uma vez ativado, o glifo brilha,\npreenchendo uma esfera de 18 metros de raio com\npenumbra por 10 minutos, após esse tempo, a magia\ntermina. Cada criatura na esfera, quando o glifo é\nativado, é afetada por seu efeito, assim como uma\ncriatura que entrar na esfera a primeira vez num turno\nou termina seu turno nela.\n    Atordoamento. Cada alvo deve realizar um teste de\nresistência de Sabedoria e ficará atordoada por 1 minuto\nse falhar na resistência.\n    Desespero. Cada alvo deve realizar um teste de\nresistência de Carisma. Com uma falha na resistência, o\nalvo será consumido pelo desespero por 1 minuto.\nDurante esse período, ele não poderá atacar ou afetar\nqualquer criatura com habilidades, magias ou outros\nefeitos mágicos nocivos.\n    Discórdia. Cada alvo deve realizar um teste de\nresistência de Sabedoria. Com uma falha na resistência,\num alvo irá brigar e discutir com outras criaturas por 1\nminuto. Durante esse período, ele será incapaz de se\ncomunicar compreensivamente e terá desvantagem nas\njogadas de ataque e testes de habilidade.\n    Dor. Cada alvo deve realizar um teste de resistência\nde Constituição e ficará incapacitada com dores\nexcruciantes por 1 minuto se falhar na resistência.\n    Insanidade. Cada alvo deve realizar um teste de\nresistência de Inteligência. Com uma falha na resistência,\no alvo é levado a loucura por 1 minuto. Uma criatura\ninsana, não pode realizar ações, não entende o que as\noutras criaturas dizem, não pode ler e fala apenas coisas\nsem sentido. O Mestre controla seus movimentos, que\nserão erráticos.\n    Medo. Cada alvo deve realizar um teste de resistência\nde Sabedoria e ficará amedrontado por 1 minuto se falhar\nna resistência. Enquanto estiver amedrontado, o alvo\nlargará o que quer que esteja segurando e deve se afastar,\npelo menos 9 metros do glifo em cada um dos seus turnos,\nse for capaz.\n    Morte. Cada alvo deve realizar um teste de resistência\nde Constituição, sofrendo 10d10 de dano necrótico se\nfalhar na resistência ou metade desse dano se passar na\nresistência.\n    Sono. Cada alvo deve realizar um teste de resistência\nde Sabedoria e cairá inconsciente por 10 minutos se\nfalhar na resistência. Uma criatura acorda se sofrer dano\nou se alguém usar sua ação para sacudi-la e estapeá-la\naté ela acordar."},{"id":"teletransporte","name":"Teletransporte","level":7,"school":"conjuração","ritual":false,"classes":["bardo","feiticeiro","mago"],"pdfPage":284,"time":"1 ação","range":"3 metros","components":"V","duration":"Instantânea","concentration":false,"text":"7° nível de conjuração\nTempo de Conjuração: 1 ação\nAlcance: 3 metros\nComponentes: V\nDuração: Instantânea\nEssa magia, instantaneamente, transporta você e até oito\ncriaturas voluntárias, à sua escolha, que você possa ver\ndentro do alcance ou um único objeto que você possa ver\nno alcance, para um destino que você selecionou. Se você\nfor afetar um objeto, ele deve ser capaz de caber inteiro\ndentro de um cubo de 3 metros e não pode estar sendo\nempunhado ou carregado por uma criatura involuntária.\n    O destino que você escolher deve ser conhecido por\nvocê e deve ser no mesmo plano de existência que você\nestá. Sua familiaridade com o destino determina se você\nchegará nele com sucesso. O Mestre rola um d100 e\nconsulta a tabela.\n\n                                Área    Fora do\nFamiliaridade        Fiasco   Similar     Alvo    No Alvo\nCírculo permanente      –        –         –      01–100\nObjeto associado        –        –         –      01–100\nMuito familiar       01–05     06–13     14–24    25–100\nVisto casualmente    01–33     34–43     44–53    54–100\nVisto uma vez        01–43     44–53     54–73    74–100\nDescrição            01–43     44–53     54–73    74–100\nDescrição falsa      01–50    51–100       –         –\n\n    Familiaridade. “Círculo permanente” significa um\ncírculo de teletransporte permanente o qual você conhece\na sequência de selos. “Objeto associado” significa que você\npossui um objeto retirado do destino desejado nos últimos\nseis meses, como um livro da biblioteca do mago, roupa de\ncama de uma suíte real ou um pedaço de mármore da\ntumba secreta do lich.\n    “Muito familiar” é um lugar que você já tenha ido\nmuitas vezes, um lugar que você estudou cuidadosamente\nou um local que você possa ver enquanto conjura a magia.\n“Visto casualmente” é algum lugar que você tenha visto\nmais de uma vez, mas que não seja muito familiar. “Visto\numa vez” é um lugar que você só viu uma vez,\npossivelmente através de magia. “Descrição” é um lugar\ncuja localização e aparência você conhece através da\ndescrição de outrem, talvez através de um mapa.\n    “Destino falso” é um local que não existe. Talvez você\ntenha tentado espionar o santuário de um inimigo, mas,\nao invés, viu uma ilusão ou você está tentando se\nteletransportar para um local familiar que não existe\nmais.\n    No Alvo. Você e seu grupo (ou objeto alvo) aparecem\nonde você queria.\n    Fora do Alvo. Você e seu grupo (ou objeto alvo)\naparecem a uma distância aleatória fora do destino em\numa direção aleatória. A distância do alvo é 1d10 x 1d10\npor cento da distância que você viajou. Por exemplo, se\nvocê tentou viajar 180 quilômetros, mas apareceu fora do\nalvo e rolou um 5 e um 3 nos dois d10s, então você saiu do\nalvo 15 por cento ou 27 quilômetros. O Mestre determina\na direção de fora do alvo aleatoriamente rolando um d8 e\ndesignando 1 como norte, 2 como nordeste, 3 como leste e\nassim por diante ao redor dos pontos cardeais. Se você\nseria teletransportado para uma cidade costeira, podendo\ncair a 27 quilômetros dela, no mar, você poderia ter\nproblemas.\n    Área Similar. Você e seu grupo (ou objeto alvo)\naparecem em uma área diferente que, visualmente ou\ntematicamente, é similar a área alvo. Se você estava indo\npara o laboratório na sua casa, por exemplo, você pode\nparar em outro laboratório de mago ou em uma loja de\nsuprimentos alquímicos que terá muitas ferramentas\niguais às encontradas no seu laboratório. Geralmente,\nvocê aparecerá no local similar mais próximo, mas já que\na magia não tem limite de alcance, você pode,\nconcebivelmente, viajar para qualquer lugar no plano.\n    Fiasco. A mágica imprevisível da magia resulta em\numa jornada difícil. Cada criatura teletransportada (ou o\nobjeto alvo) sofrem 3d10 de dano de energia e o Mestre\nrola novamente a tabela para ver onde você foi parar\n(fiascos múltiplos podem ocorrer, causando dano a cada\nvez)."},{"id":"tempestade-de-fogo","name":"Tempestade de Fogo","level":7,"school":"evocação","ritual":false,"classes":["clerigo","druida","feiticeiro"],"pdfPage":285,"time":"1 ação","range":"45 metros","components":"V, S","duration":"Instantânea","concentration":false,"text":"7° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: 45 metros\nComponentes: V, S\nDuração: Instantânea\nUma tempestade feita de camadas de chamas crepitantes\naparece num local, à sua escolha, dentro do alcance. A\nárea da tempestade consiste de até dez cubos de 3 metros,\nque você pode organizar como desejar. Cada cubo deve\nter, pelo menos, uma face adjacente a face de outro cubo.\nCada criatura na área deve realizar um teste de\nresistência de Destreza. Ela sofre 7d10 de dano de fogo se\nfalhar na resistência, ou metade desse dano se obtiver\nsucesso.\n    O fogo causa dano aos objetos na área e incendeia\nobjetos inflamáveis que não estejam sendo vestidos ou\ncarregados. Se desejar, a vida vegetal na área pode não\nser afetada por essa magia."},{"id":"viagem-planar","name":"Viagem Planar","level":7,"school":"conjuração","ritual":false,"classes":["bruxo","clerigo","druida","feiticeiro","mago"],"pdfPage":287,"time":"1 ação","range":"Toque","components":"V, S, M (uma haste metálica bifurcada valendo, no mínimo, 250 po, sintonizada com um plano de existência em particular)","duration":"Instantânea","concentration":false,"text":"7° nível de conjuração\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S, M (uma haste metálica bifurcada\n   valendo, no mínimo, 250 po, sintonizada com um plano\n   de existência em particular)\nDuração: Instantânea\nVocê e até oito criaturas voluntárias, que estejam de mãos\ndadas em um círculo, são transportadas para um plano de\nexistência diferente. Você pode especificar o destino alvo\nem termos gerais, como a Cidade de Bronze do Plano\nElemental do Fogo ou o palácio de Dispater na segunda\ncamada dos Nove Infernos e você aparece no ou perto do\ndestino. Se você estiver tentando chegar a Cidade de\nBronze, por exemplo, você poderia chegar na Estrada de\nAço dela, em frente aos Portões de Cinzas ou\ncontemplando a cidade do outro lado do Mar de Fogo, à\ncritério do Mestre.\n    Alternativamente, se você conhecer a sequência de\nselos do círculo de teletransporte em outro plano de\nexistência, essa magia pode leva-lo para esse círculo. Se o\ncírculo de teletransporte for muito pequeno para\ncomportar as criaturas que você está transportando, elas\naparecerão no espaço desocupado mais próximo do\ncírculo.\n   Você pode usar essa magia para banir uma criatura\ninvoluntária para outro plano. Escolha uma criatura ao\nseu alcance e realize um ataque corpo-a-corpo com magia\ncontra ela. Se atingir, a criatura deve realizar um teste de\nresistência de Carisma. Se a criatura falhar na\nresistência, ela é transportada para um local aleatório no\nplano de existência que você especificou. Uma criatura,\numa vez transportada, deve encontrar seu próprio meio\nde retornar para seu plano de existência atual."},{"id":"antipatia-simpatia","name":"Antipatia/Simpatia","level":8,"school":"encantamento","ritual":false,"classes":["druida","mago"],"pdfPage":216,"time":"1 hora","range":"18 metros","components":"V, S, M (ou um pedaço de alume embebido em vinagre para o efeito de antipatia, ou uma gota de mel para o efeito de simpatia)","duration":"10 dias","concentration":false,"text":"8° nível de encantamento\nTempo de Conjuração: 1 hora\nAlcance: 18 metros\nComponentes: V, S, M (ou um pedaço de alume\nembebido em vinagre para o efeito de antipatia, ou uma\ngota de mel para o efeito de simpatia)\nDuração: 10 dias\nEssa magia atrai ou repele as criaturas de sua escolha.\nVocê escolhe um alvo dentro do alcance, tanto um objeto\nou criatura Enorme ou menor ou uma área que não seja\nmaior que 60 metros cúbicos. Então, especifica um tipo de\ncriatura inteligente, como dragões vermelhos, goblins ou\nvampiros. Você envolve o alvo com uma aura que pode\natrair ou repelir as criaturas especificas pela duração.\nEscolha antipatia ou simpatia como efeito da aura.\n    Antipatia. O encantamento faz com que criaturas do\ntipo designado por você sintam-se fortemente impelidos\nem deixar a área e evitar o alvo. Quando uma dessas\ncriaturas puder ver o alvo ou ficar a 18 metros dele, a\ncriatura deve ser bem sucedida num teste de resistência\nde Sabedoria ou ficará amedrontada. A criatura\ncontinuará amedrontada enquanto puder ver o alvo ou\npermanecer a 18 metros dele. Enquanto estiver\namedrontada pelo alvo, a criatura deve usar seu\ndeslocamento para se mover para o local seguro mais\npróximo o qual ela não possa ver o alvo. Se a criatura se\nmover para mais de 18 metros do alvo e não puder vê-lo, a\ncriatura não estará mais amedrontada, mas ela ficará\namedrontada novamente se voltar a ver o alvo ou ficar a\n18 metros dele.\n    Simpatia. O encantamento faz com que as criaturas\nespecificadas sintam-se fortemente impelidos a se\naproximar do alvo enquanto estiverem a 18 metros dele\nou puderem vê-lo. Quando uma dessas criaturas puder\nver o alvo ou ficar a 18 metros dele, a criatura deve ser\nbem sucedida num teste de resistência de Vontade ou\nusará seu deslocamento em cada um dos seus turnos para\nentrar na área ou se mover até o alcance do alvo. Quando\na criatura tiver feito isso, ela não poderá se afastar do\nalvo voluntariamente.\n    Se o alvo causar dano ou ferir a criatura afetada de\nalguma forma, a criatura afetada pode realizar um novo\nteste de resistência de Sabedoria para terminar o efeito,\ncomo descrito abaixo.\n    Terminando o Efeito. Se uma criatura afetada\nterminar se turno enquanto não estiver a até 18 metros\ndo alvo ou não for capaz de vê-lo, a criatura faz um teste\nde resistência de Sabedoria. Em um sucesso, a criatura\nnão estará mais afetada pelo alvo e reconhecerá o\nsentimento de repugnância ou atração como mágico. Além\ndisso, uma criatura afetada pela magia tem direito a\noutro teste de resistência de Sabedoria a cada 24 horas\nenquanto a magia durar.\n    Uma criatura que obtenha sucesso na resistência\ncontra esse efeito ficará imune a ele por 1 minuto, depois\ndesse tempo, ela pode ser afetada novamente."},{"id":"aura-sagrada","name":"Aura Sagrada","level":8,"school":"abjuração","ritual":false,"classes":["clerigo"],"pdfPage":220,"time":"1 ação","range":"Pessoal","components":"V, S, M (um minúsculo relicário valendo, no mínimo, 1.000 po, contendo uma relíquia sagrada, como um pedaço de tecido do robe de um santo ou um pedaço de pergaminho de um texto religioso)","duration":"Concentração, até 1 minuto","concentration":true,"text":"8° nível de abjuração\nTempo de Conjuração: 1 ação\nAlcance: Pessoal\nComponentes: V, S, M (um minúsculo relicário valendo,\n   no mínimo, 1.000 po, contendo uma relíquia sagrada,\n   como um pedaço de tecido do robe de um santo ou um\n   pedaço de pergaminho de um texto religioso)\nDuração: Concentração, até 1 minuto\nLuz divina emana de você e adere em uma aureola suave\nnum raio de 9 metros, em volta de você. As criaturas de\nsua escolha, no raio, quando você conjurar essa magia,\nemitem penumbra num raio de 1,5 metro e tem vantagem\nem todos os testes de resistência e as outras criaturas tem\ndesvantagem nas jogadas de ataque contra elas, até a\nmagia acabar. Além disso, quando um corruptor ou\nmorto-vivo atingir uma criatura afetada com um ataque\ncorpo-a-corpo, a aura lampeja com luz plena. O atacante\ndeve ser bem sucedido num teste de resistência de\nConstituição ou ficara cego até a magia acabar."},{"id":"campo-antimagia","name":"Campo Antimagia","level":8,"school":"abjuração","ritual":false,"classes":["clerigo","mago"],"pdfPage":223,"time":"1 ação","range":"Pessoal (3 metros de raio)","components":"V, S, M (um punhado de pó de ferro ou limalhas de ferro)","duration":"Concentração, até 1 hora","concentration":true,"text":"8° nível de abjuração\nTempo de Conjuração: 1 ação\nAlcance: Pessoal (3 metros de raio)\nComponentes: V, S, M (um punhado de pó de ferro ou\n   limalhas de ferro)\nDuração: Concentração, até 1 hora\nUma esfera invisível, de 3 metros de raio, de antimagia\nenvolve você. Essa área é separada da energia mágica que\nse espalha pelo multiverso. Dentro da esfera, magias não\npodem ser conjuradas, criaturas invocadas desaparecem\ne, até mesmo itens mágicos, se tornam mundanos. Até o\nfim da magia, a esfera se move com você, centrada em\nvocê.\n    Magias e outros efeitos mágicos, exceto os criados por\nartefatos ou divindades, são suprimidos na esfera e não\npodem adentra-la. Um espaço gasto para conjurar uma\nmagia suprimida é consumido. Enquanto o efeito estiver\nsuprimido, ela não funciona, mas o tempo que ela\npermanecer suprimida é descontado da sua duração.\n    Efeitos de Alvo. Magias e outros efeitos mágicos,\ncomo mísseis mágicos e enfeitiçar pessoa, que forem\nusados em uma criatura ou objeto dentro da esfera, não\nsurtem efeito no alvo.\n    Áreas de Magia. A área de outra magia ou efeito\nmágico, como uma bola de fogo, não se estende para\ndentro da esfera. Se a esfera sobrepor um área mágica, a\nparte da área que for coberta pela espera é suprimida.\nPor exemplo, as chás criadas por uma muralha de fogo\nserão suprimidas dentro da esfera, criando um abertura\nna muralha se a sobreposição por grande o suficiente.\n    Magias. Qualquer magia ativa ou outro efeito mágico\nem uma criatura ou objeto dentro da esfera é suprimido\nenquanto a criatura ou objeto permanecer dentro dela.\n    Itens Mágicos. As propriedades e poderes de itens\nmágicos são suprimidas dentro da esfera. Por exemplo,\numa espada longa +1 dentro da esfera funciona como uma\nespada não-mágica.\n    As propriedades e poderes de uma arma mágica são\nsuprimidos se ela for usada contra um alvo dentro da\nesfera ou empunhada por um atacante dentro da esfera.\nSe uma arma mágica ou munição mágica deixar a esfera\ncompletamente (por exemplo, se você disparar uma flecha\nmágica ou arremessar uma lança mágica e um alvo fora\nda esfera), a magia do item deixa de ser suprimida tão\nlogo ele deixe a esfera.\n    Viagem Mágica. Teletransporte e viagem planar não\nfunciona dentro da esfera, tanto se a esfera for o destino\nquando o ponto de partida para tais viagens mágicas. Um\nportal para outro lugar, mundo ou plano de existência,\nassim como um espaço extradimensional aberto, como o\ncriado pela magia truque de corda, é temporariamente\nfechado enquanto estiver dentro da esfera.\n    Criaturas e Objetos. Uma criatura ou objeto\ninvocado ou criado através de magia, temporariamente\ndesaparece da existência dentro da esfera. Tais criaturas\nreaparecem instantaneamente quando o espaço ocupado\npela criatura não estiver mais dentro da esfera.\n    Dissipar Magia. Magias e efeitos mágicos como\ndissipar magia, não surtem efeito sob esfera. Da mesma\nforma, esferas criadas por magias de campo antimagia\ndiferentes não se anulam."},{"id":"clone","name":"Clone","level":8,"school":"necromancia","ritual":false,"classes":["mago"],"pdfPage":226,"time":"1 hora","range":"Toque","components":"V, S, M (um diamante valendo, no mínimo, 1.000 po e, no mínimo 3 centímetros cúbicos de carne da criatura que será clonada, consumida pela magia, e um receptáculo valendo, no mínimo, 2.000 po que tenha uma tampa selada e seja grande o suficiente para comportar uma criatura Média, como uma urna enorme, um caixão, um cisto cheio de lama no solo ou um recipiente de cristal cheio de água salgada)","duration":"Instantânea","concentration":false,"text":"8° nível de necromancia\nTempo de Conjuração: 1 hora\nAlcance: Toque\nComponentes: V, S, M (um diamante valendo, no\n   mínimo, 1.000 po e, no mínimo 3 centímetros cúbicos\n   de carne da criatura que será clonada, consumida pela\n   magia, e um receptáculo valendo, no mínimo, 2.000 po\n   que tenha uma tampa selada e seja grande o suficiente\n   para comportar uma criatura Média, como uma urna\n   enorme, um caixão, um cisto cheio de lama no solo ou\n   um recipiente de cristal cheio de água salgada)\nDuração: Instantânea\nEssa magia produz uma duplicata inerte de uma criatura\nviva como uma garantia contra a morte. Esse clone é\nformado dentro de um receptáculo selado e cresce ao seu\ntamanho total, atingindo a maturidade após 120 dias;\nVocê também pode escolher que o clone seja uma versão\nmais jovem da mesma criatura. Ele permanece inerte e\ndura indefinidamente, enquanto seu receptáculo\npermanecer intocado.\n    A qualquer momento, após o clone amadurecer, se a\ncriatura original morrer, sua alma é transferida para o\nclone, considerando que a alma está livre e deseje\nretornar. O clone é fisicamente idêntico ao original e tem\na mesma personalidade, memórias e habilidades, mas não\npossui qualquer equipamento do original. O físico da\ncriatura original permanece, se ainda existir, se tornando\ninerte e não podendo, consequentemente, ser trazido de\nvolta à vida, já que a alma da criatura está em outro\nlugar."},{"id":"controlar-o-clima","name":"Controlar o Clima","level":8,"school":"transmutação","ritual":false,"classes":["clerigo","druida","mago"],"pdfPage":231,"time":"10 minutos","range":"Pessoal (7,5 quilômetros de raio)","components":"V, S, M (incenso aceso e pedaços de terra e madeira misturados em água)","duration":"Concentração, até 8 horas","concentration":true,"text":"8° nível de transmutação\n Tempo de Conjuração: 10 minutos\n Alcance: Pessoal (7,5 quilômetros de raio)\n Componentes: V, S, M (incenso aceso e pedaços de terra\n    e madeira misturados em água)\n Duração: Concentração, até 8 horas\n Você toma controle do clima numa área de 7,5\n quilômetros de você pela duração. Você deve estar ao ar\n livre para conjurar essa magia. Se mover para um lugar\n onde você não tenha uma visão clara do céu termina a\n magia prematuramente.\n     Quando você conjurar essa magia, você muda as\n condições climáticas atuais, que são determinadas pelo\n Mestre baseado no ambiente e estação. Você pode mudar\n a precipitação, temperatura e vento. Leva 1d4 x 10\n minutos para as novas condições fazerem efeito. Quando\n a magia terminar, o clima, gradualmente, volta ao\n normal.\n     Quando você altera as condições climáticas, encontre a\n condição atual nas tabelas a seguir e mude em um\n estágio, para cima ou para baixo. Quando mudar o vento,\n você pode mudar a direção do mesmo.\n\nPRECIPITAÇÃO\n Estágio   Condição\n    1      Céu claro\n    2      Parcialmente encoberto\n    3      Céu escuro ou nublado\n    4      Chuva, granizo ou neve\n    5      Chuva torrencial, tempestade de granizo ou nevasca\n\nTEMPERATURA                      VENTO\n Estágio   Condição                Estágio   Condição\n    1      Calor insuportável         1      Calmo\n    2      Quente                     2      Vento moderado\n    3      Morno                      3      Vento forte\n    4      Frio                       4      Ventania\n    5      Gelado                     5      Temporal\n    6      Frio ártico"},{"id":"dominar-monstro","name":"Dominar Monstro","level":8,"school":"encantamento","ritual":false,"classes":["bardo","bruxo","feiticeiro","mago"],"pdfPage":239,"time":"1 ação","range":"18 metros","components":"V, S","duration":"Concentração, até 1 hora","concentration":true,"text":"8° nível de encantamento\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, S\nDuração: Concentração, até 1 hora\nVocê tenta seduzir uma criatura que você possa ver\ndentro do alcance. Ela deve ser bem sucedida num teste\nde resistência de Sabedoria ou ficará enfeitiçada por você\npela duração. Se você ou criaturas amigáveis a você\nestiverem lutando com ela, ela terá vantagem no teste de\nresistência.\n    Enquanto a criatura estiver enfeitiçada, você terá uma\nligação telepática com ela, contanto que ambos estejam no\nmesmo plano de existência. Você pode usar essa ligação\ntelepática para emitir comandos para a criatura enquanto\nvocê estiver consciente (não requer uma ação), aos quais\nela obedece da melhor forma possível. Você pode\nespecificar um curso de ação simples e genérico, como\n“Ataque aquela criatura”, “Corra até ali”, ou “Traga\naquele objeto”. Se a criatura completar a ordem e não\nreceber direções posteriores de você, ela se defenderá e se\nauto preservará da melhor forma que puder.\n    Você pode usar sua ação para tomar controle total e\npreciso do alvo. Até o final do seu próximo turno, a\ncriatura realiza apenas as ações que você escolher e não\nfaz nada que você não permita que ela faça. Durante esse\nperíodo, você também pode fazer com que a criatura use\numa reação, mas isso requer que você usa sua própria\nreação também.\n    Cada vez que o alvo sofrer dano, ele realiza um novo\nteste de resistência de Sabedoria contra a magia. Se\nobtiver sucesso no teste de resistência, a magia termina.\n    Em Níveis Superiores. Quando você conjurar essa\nmagia usando um espaço de magia de 9° nível, a duração\nserá concentração, até 8 horas."},{"id":"enfraquecer-intelecto","name":"Enfraquecer Intelecto","level":8,"school":"encantamento","ritual":false,"classes":["bardo","bruxo","druida","mago"],"pdfPage":241,"time":"1 ação","range":"45 metros","components":"V, S, M (um punhado de barro, cristal, vidro ou esferas minerais)","duration":"Instantânea","concentration":false,"text":"8° nível de encantamento\nTempo de Conjuração: 1 ação\nAlcance: 45 metros\nComponentes: V, S, M (um punhado de barro, cristal,\n   vidro ou esferas minerais)\nDuração: Instantânea\nVocê ataca a mente de uma criatura que você possa ver,\ndentro do alcance, tentando despedaçar seu intelecto e\npersonalidade. O alvo sofre 4d6 de dano psíquico e deve\nrealizar um teste de resistência de Inteligência.\n    Se falhar na resistência, os valores de Inteligência e\nCarisma da criatura se tornam 1. A criatura não pode\nconjurar magias, ativar itens mágicos, compreender\nidiomas ou se comunicar de qualquer forma inteligível. A\ncriatura pode, no entanto, identificar seus amigos, segui-\nlos e, até mesmo, protege-los.\n    Ao final de cada 30 dias, a criatura pode repetir seu\nteste de resistência contra essa magia. Se ela obtiver\nsucesso no teste de resistência, a magia termina.\n    Essa magia também pode ser terminada através de\nrestauração maior, cura completa ou desejo."},{"id":"explosao-solar","name":"Explosão Solar","level":8,"school":"evocação","ritual":false,"classes":["druida","feiticeiro","mago"],"pdfPage":244,"time":"1 ação","range":"45 metros","components":"V, S, M (fogo e um pedaço de pedra do sol)","duration":"Instantânea","concentration":false,"text":"8° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: 45 metros\nComponentes: V, S, M (fogo e um pedaço de pedra do\n   sol)\nDuração: Instantânea\nLuz solar brilhante lampeja num raio de 18 metros,\ncentrada num ponto, à sua escolha, dentro do alcance.\nCada criatura nessa luz, deve realizar um teste de\nresistência de Constituição. Com uma falha na\nresistência, uma criatura sofrerá 12d6 de dano radiante e\nficará cega por 1 minuto. Se obtiver sucesso na\nresistência, ela sofrerá metade desse dano e não ficará\ncega por essa magia. Mortos-vivos e limos tem\ndesvantagem nos seus testes de resistência.\n    Uma criatura cega por essa magia faz outro teste de\nresistência de Constituição no final de cada um dos\nturnos dela. Se obtiver sucesso, ela não estará mais cega.\n    Essa magia dissipa qualquer escuridão na área dela\nque tenha sido criada por um magia."},{"id":"formas-animais","name":"Formas Animais","level":8,"school":"transmutação","ritual":false,"classes":["druida"],"pdfPage":246,"time":"1 ação","range":"9 metros","components":"V, S","duration":"Concentração, até 24 horas","concentration":true,"text":"8° nível de transmutação\nTempo de Conjuração: 1 ação\nAlcance: 9 metros\nComponentes: V, S\nDuração: Concentração, até 24 horas\nSua magia transforma você em bestas. Escolha qualquer\nquantidade de criaturas voluntárias que você possa ver, o\nalcance. Você muda cada alvo para a forma de uma besta\nGrande ou menor, com um nível de desafio de 4 ou\ninferior. Nos turnos subsequentes, você pode usar sua\nação para mudar uma criatura afetada para uma nova\nforma.\n    A transformação permanece pela duração para cada\nalvo, ou até o alvo cair para 0 pontos de vida ou morrer.\nVocê pode escolher uma forma diferente para cada alvo.\nAs estatísticas de jogo do alvo são substituídas pelas\nestatísticas da besta escolhida, mas o alvo mantem sua\ntendência e valores de Inteligência, Sabedoria e Carisma.\nO alvo adquire os pontos de vida da sua nova forma, e\nquando ele reverte para sua forma normal, ele volta aos\npontos de vida que tinha antes de ser transformado. Se\nele reverter como resultado de ter caído a 0 pontos de\nvida, todo dano excedente é recebido pela sua forma\nnormal. Contanto que o dano excedente não reduza os\npontos de vida da forma normal da criatura a 0, ela não\ncairá inconsciente. A criatura é limitada em suas ações\npela natureza da sua nova forma e ela não pode falar nem\nconjurar magias.\n   O equipamento do alvo mescla-se a sua nova forma. O\nalvo não pode ativar, empunhar ou, de outra forma, se\nbeneficiar de qualquer de seus equipamentos."},{"id":"labirinto","name":"Labirinto","level":8,"school":"conjuração","ritual":false,"classes":["mago"],"pdfPage":251,"time":"1 ação","range":"18 metros","components":"V, S","duration":"Concentração, até 10 minutos","concentration":true,"text":"8° nível de conjuração\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, S\nDuração: Concentração, até 10 minutos\nVocê bane uma criatura que você possa ver, dentro do\nalcance, para um semiplano labiríntico. O alvo permanece\nlá pela duração ou até escapar do labirinto.\n    O alvo pode usar sua ação para tentar escapar.\nQuando o fizer, ele realiza um teste de Inteligência com\nCD 20. Se for bem sucedido, ele escapa e a magia termina\n(um minotauro ou um demônio goristro, obtém sucesso\nautomaticamente).\n    Quando a magia termina, o alvo reaparece no espaço\nque ela estava ou, se o espaço estiver ocupado, no espaço\ndesocupado mais próximo."},{"id":"limpar-a-mente","name":"Limpar a Mente","level":8,"school":"abjuração","ritual":false,"classes":["bardo","mago"],"pdfPage":252,"time":"1 ação","range":"Toque","components":"V, S","duration":"24 horas","concentration":false,"text":"8° nível de abjuração\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S\nDuração: 24 horas\nAté a magia acabar, uma criatura voluntária que você\ntocar fica imune a dano psíquico, a qualquer efeito que\npoderia sentir suas emoções ou ler seus pensamentos, a\nmagias de adivinhação e a condição enfeitiçado. A magia\npode até mesmo evitar a magia desejo e magias ou efeitos\nde poder similar usados para afetar a mente do alvo ou\npara adquirir informações sobre ele."},{"id":"loquacidade","name":"Loquacidade","level":8,"school":"transmutação","ritual":false,"classes":["bardo","bruxo"],"pdfPage":253,"time":"1 ação","range":"Pessoal","components":"V","duration":"1 hora","concentration":false,"text":"8° nível de transmutação\nTempo de Conjuração: 1 ação\nAlcance: Pessoal\nComponentes: V\nDuração: 1 hora\nAté o fim da magia, quando você realizar um teste de\nCarisma, você pode substituir o número rolado por você\npor um 15. Além disso, não importa o que você diga,\nmagias que determinam se você está dizendo a verdade\nindicarão que você está sendo sincero."},{"id":"nuvem-incendiaria","name":"Nuvem Incendiária","level":8,"school":"conjuração","ritual":false,"classes":["feiticeiro","mago"],"pdfPage":263,"time":"1 ação","range":"45 metros","components":"V, S","duration":"Concentração, até 1 minuto","concentration":true,"text":"8° nível de conjuração\nTempo de Conjuração: 1 ação\nAlcance: 45 metros\nComponentes: V, S\nDuração: Concentração, até 1 minuto\nUma nuvem de fumaça rodopiante que dispara brasas\nincandescentes aparece numa esfera de 6 metros centrada\nnum ponto, dentro do alcance. A nuvem se espalha,\ndobrando esquinas, e gera escuridão densa. Ela\npermanece pela duração ou até que um vento de\nvelocidade moderada ou mais forte (pelo menos 15\nquilômetros por hora) a disperse.\n   Quando a nuvem aparece, cada criatura deve realizar\num teste de resistência de Destreza. Uma criatura sofre\n10d8 de dano de fogo se falhar na resistência ou metade\ndesse dano se passar. Uma criatura deve, também,\nrealizar um teste de resistência quando entrar na área da\nmagia pela primeira vez num turno ou terminar seu\nturno nela.\n   A nuvem se afasta 3 metros de você numa direção, que\nvocê escolheu, no começo de cada um dos seus turnos."},{"id":"palavra-de-poder-atordoar","name":"Palavra de Poder Atordoar","level":8,"school":"encantamento","ritual":false,"classes":["bardo","bruxo","feiticeiro","mago"],"pdfPage":265,"time":"1 ação","range":"18 metros","components":"V","duration":"Instantânea","concentration":false,"text":"8° nível de encantamento\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V\nDuração: Instantânea\nVocê pronuncia uma palavra de poder que pode oprimir a\nmente de uma criatura que você possa ver, dentro do\nalcance, deixando-a estupefata. Se o alvo escolhido estiver\ncom 150 pontos de vida ou menos, ele ficará atordoado. Do\ncontrário, essa magia não produz efeito.\n   O alvo atordoado deve realizar um teste de resistência\nde Constituição no final de cada um dos turnos dele. Se\nobtiver sucesso na resistência, o efeito de atordoamento\ntermina."},{"id":"semiplano","name":"Semiplano","level":8,"school":"conjuração","ritual":false,"classes":["bruxo","mago"],"pdfPage":278,"time":"1 ação","range":"18 metros","components":"V","duration":"1 hora","concentration":false,"text":"8° nível de conjuração\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V\nDuração: 1 hora\nVocê cria uma porta umbral em uma superfície sólida e\nlisa que você possa ver, dentro do alcance. A porta é\ngrande o suficiente para permitir a passagem de criaturas\nMédias sem dificuldade. Quando aberta, a porta levará a\num semiplano que parece uma sala vazia de 9 metros\nquadrados de dimensão, feita de madeira ou pedra.\nQuando a magia termina, a porta desaparece e, qualquer\ncriatura ou objeto dentro do semiplano, permanecerá\npreso lá, a medida que a porta desaparece do outro lado.\nCada vez que você conjura essa magia, você pode criar um\nnovo semiplano ou fazer a porta umbral se conectar a um\nsemiplano que você tenha criado em uma conjuração\nanterior dessa magia. Além disso, se você conhecer a\nnatureza e conteúdo do semiplano criado através da\nconjuração dessa magia por outra criatura, você pode\nfazer com que a porta umbral se conecte a esse semiplano."},{"id":"telepatia","name":"Telepatia","level":8,"school":"evocação","ritual":false,"classes":["mago"],"pdfPage":282,"time":"1 ação","range":"Ilimitado","components":"V, S, M (um par de anéis de prata unidos)","duration":"24 horas","concentration":false,"text":"8° nível de adivinhação\nTempo de Conjuração: 1 ação\nAlcance: Ilimitado\nComponentes: V, S, M (um par de anéis de prata\n   unidos)\nDuração: 24 horas\nVocê cria uma ligação telepática entre você e uma\ncriatura voluntária com a qual você seja familiarizado. A\ncriatura pode estar em qualquer lugar no mesmo plano de\nexistência que você. A magia termina se você ou o alvo\nnão estiver mais no mesmo plano.\n    Até a magia acabar, você e o alvo podem,\ninstantaneamente, compartilhar palavras, imagens, sons\ne outras mensagens sensoriais uma com a outra através\nda ligação e o alvo reconhece que é você a criatura que\nestá se comunicando com ele. A magia permite que uma\ncriatura com valor de Inteligência mínimo de 1\ncompreenda o sentido das suas palavras e capta o sentido\ngeral de qualquer mensagem sensorial que você enviar."},{"id":"terremoto","name":"Terremoto","level":8,"school":"evocação","ritual":false,"classes":["clerigo","druida","feiticeiro"],"pdfPage":285,"time":"1 ação","range":"150 metros","components":"V, S, M (um pouco de poeira, uma pedra e um pedaço de barro)","duration":"Concentração, até 1 minuto","concentration":true,"text":"8° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: 150 metros\nComponentes: V, S, M (um pouco de poeira, uma pedra\n   e um pedaço de barro)\nDuração: Concentração, até 1 minuto\nVocê cria um distúrbio sísmico num ponto no solo, que\nvocê possa ver dentro do alcance. Pela duração, um\ntremor intenso rompe o solo em um círculo com 30 metros\nde raio centrado no ponto e sacode criaturas e estruturas\nem contato com o chão na área.\n    O solo na área torna-se terreno difícil. Cada criatura\nno solo que estiver se concentrando, deve realizar um\nteste de resistência de Constituição. Se falha na\nresistência, a concentração da criatura é interrompida.\n    Quando você conjura essa magia, e ao final de cada\nturno que você gastar se concentrando nela, cada criatura\nno solo na área deve realizar um teste de resistência de\nDestreza. Se falhar na resistência, a criatura será\nderrubada no chão.\n    Essa magia pode ter efeitos adicionais a depender do\nterreno na área, como determinado pelo Mestre.\n    Fissuras. Fissuras se abrem por toda área da magia,\nno começo do seu próximo turno, após você conjurar a\nmagia. Um total de 1d6 dessas fissuras se abrem em\nlocais escolhidos pelo Mestre. Cada um tem 1d10 x 3\nmetros de profundidade, 3 metros de largura e se estende\nde uma extremidade até o lado oposto da área da magia.\nUma criatura que estiver em um ponto onde uma fissura\nse abriu deve ser bem sucedido num teste de resistência\nde Destreza ou cairá dentro dela. Uma criatura que\nobtenha sucesso na resistência se move com a margem da\nfissura, à medida que ela se abre.\n    Uma fissura que se abra abaixo de uma estrutura faz\ncom que ela, automaticamente, desmorone (veja abaixo).\n    Estruturas. O tremor causa 50 de dano de concussão\na qualquer estrutura em contato com o solo na área,\nquando você conjurar a magia e, no início de cada turno\naté a magia terminar. Se a estrutura cair a 0 pontos de\nvida, ela desmorona e, potencialmente, fere criaturas\npróximas. Uma criatura a uma distância inferior a\nmetade da altura da estrutura deve realizar um teste de\nresistência de Destreza. Se falhar na resistência, a\ncriatura sofrerá 5d6 de dano de concussão, cairá no chão e\nestará soterrada nos escombros, precisando de um teste\nde Força (Atletismo) com CD 20, usando uma ação, para\nescapar. O Mestre pode ajustar a CD para cima ou para\nbaixo, dependendo da natureza dos escombros. Se obtiver\nsucesso na resistência, a criatura sofre metade do dano e\nnão estará caída ou soterrada."},{"id":"tsunami","name":"Tsunami","level":8,"school":"conjuração","ritual":false,"classes":["druida"],"pdfPage":286,"time":"1 minuto","range":"Visão","components":"V, S","duration":"Concentração, até 6 rodadas","concentration":true,"text":"8° nível de conjuração\nTempo de Conjuração: 1 minuto\nAlcance: Visão\nComponentes: V, S\nDuração: Concentração, até 6 rodadas\nUma muralha de água aparece do nada num ponto, à sua\nescolha, dentro do alcance. Você pode fazer a muralha ter\naté 90 metros de comprimento, 90 metro de altura e 15\nmetros de espessura. A muralha permanece pela duração.\n   Quando a muralha aparece, cada criatura dentro da\nárea deve realizar um teste de resistência de Força. Se\nfalhar na resistência, uma criatura sofrerá 6d10 de dano\nde concussão ou metade desse dano se passar na\nresistência.\n   No início de cada um dos seus turnos, após a muralha\naparecer, ela, junto com qualquer criatura nela, se afasta\n15 metros de você. Qualquer criatura Enorme ou menor\ndentro da muralha ou no espaço que a muralha entrar\nquando ela se mover, deve ser bem sucedida num teste de\nresistência de Força ou sofrerá 5d6 de dano de concussão.\nUma criatura pode sofrer esse dano apenas uma vez por\nrodada. No final do turno, a altura da muralha é reduzida\nem 15 metros e o dano que as criaturas sofrem da magia\nnas rodadas subsequentes é reduzido em 1d10. Quando a\nmuralha chegar a 0 metro de altura, a magia acaba.\n   Uma criatura pega pela muralha, pode se mover\nnadando. Devido à força da onda, no entanto, a criatura\ndeve realizar um teste de Força (Atletismo) contra a CD\nda magia para conseguir se mover. Se ela falhar no teste,\nnão conseguirá se mover. Uma criatura que se mova para\nfora da área, cairá no chão."},{"id":"alterar-forma","name":"Alterar Forma","level":9,"school":"transmutação","ritual":false,"classes":["druida","mago"],"pdfPage":214,"time":"1 ação","range":"Pessoal","components":"V, S, M (uma argola de jade valendo, no mínimo, 1.500 po, que você deve colocar na sua cabeça antes de conjurar a magia)","duration":"Concentração, até 1 hora","concentration":true,"text":"9° nível de transmutação\nTempo de Conjuração: 1 ação\nAlcance: Pessoal\nComponentes: V, S, M (uma argola de jade valendo, no\n   mínimo, 1.500 po, que você deve colocar na sua cabeça\n   antes de conjurar a magia)\nDuração: Concentração, até 1 hora\nVocê assume a forma de uma criatura diferente, pela\nduração. A nova forma pode ser qualquer criatura com\num nível de desafio igual ao seu nível ou menor. A\ncriatura não pode ser nem um constructo nem um morto-\nvivo e você deve ter visto esse tipo de criatura pelo menos\numa vez. Você se transforma num exemplar médio da\ncriatura, um sem quaisquer níveis de classe nem\ncaracterística Conjuração.\n    Suas estatísticas de jogo são substituídas pelas\nestatísticas da forma escolhida, no entanto, você mantem\nsua tendência e valores de Inteligência, Sabedoria e\nCarisma. Você também mantem suas proficiências em\ntestes de resistência, além de ganhar as da nova criatura.\nSe a criatura tiver a mesma proficiência que você e o\nbônus listado nas estatísticas dela for maior que o seu,\nuse os bônus da criatura no lugar do seu. Você não pode\nusar qualquer ação lendária ou de covil da nova forma.\n    Você assume os pontos de vida e Dados de Vida da sua\nnova forma. Quando você reverter a sua forma normal,\nvocê retorna à quantidade de pontos de vida que tinha\nantes da transformação. Se você reverter como resultado\nde ter caído a 0 pontos de vida, qualquer dano excedente é\nrecebido pela sua forma normal. Contanto que o dano\nexcedente não reduza os pontos de vida da sua forma\nnormal a 0, você não cairá inconsciente.\n    Você mantem os benefícios de qualquer característica\nda sua classe, raça ou outra fonte e pode usa-las,\nconsiderando que sua nova forma é fisicamente capaz de\nfazê-lo. Você não pode usar quaisquer sentidos especiais\nque você possua (por exemplo, visão no escuro) a não ser\nque a nova forma também possua o sentido. Você só\npoderá falar se a nova forma, normalmente, puder falar.\n    Quando você se transforma, você pode escolher se o\nseu equipamento cai no chão, é assimilado a sua nova\nforma ou é usado por ela. Equipamentos vestidos e\ncarregados funcionam normalmente. O Mestre decide\nqual equipamento é viável para a nova forma vestir ou\nusar, baseado na forma e tamanho da criatura. O seu\nequipamento não muda de forma ou tamanho para se\nadaptar à nova forma e, qualquer equipamento que a\nnova forma não possa vestir deve, ou cair no chão ou ser\nassimilado por ela. Equipamentos assimilados não terão\nefeito nesse estado.\n    Pela duração da magia, você pode usar sua ação para\nassumir uma forma diferente, seguindo as mesmas\nrestrições e regras da forma anterior, com uma exceção:\nse sua nova forma tiver mais pontos de vida que sua\nforma atual, seus pontos de vida mantem o valor atual."},{"id":"aprisionamento","name":"Aprisionamento","level":9,"school":"abjuração","ritual":false,"classes":["bruxo","mago"],"pdfPage":217,"time":"1 minuto","range":"9 metros","components":"V, S, M (um pergaminho de representação ou uma estatueta esculpida para se parecer com o alvo e um componente especial, que varia de acordo com a versão da magia que você escolher, valendo, no mínimo, 500 po por Dado de Vida)","duration":"Até ser dissipada","concentration":false,"text":"9° nível de abjuração\nTempo de Conjuração: 1 minuto\nAlcance: 9 metros\nComponentes: V, S, M (um pergaminho de\n   representação ou uma estatueta esculpida para se\n   parecer com o alvo e um componente especial, que\n   varia de acordo com a versão da magia que você\n   escolher, valendo, no mínimo, 500 po por Dado de\n   Vida)\nDuração: Até ser dissipada\nVocê cria um impedimento mágico para imobilizar uma\ncriatura que você possa ver, dentro do alcance. O alvo\ndeve ser bem sucedido num teste de resistência de\nSabedoria ou será vinculado à magia; se ele for bem\nsucedido, ele será imune a essa magia se você conjura-la\nnovamente. Enquanto estiver sob efeito dessa magia, a\ncriatura não precisará respirar, comer ou beber e não\nenvelhece. Magias de adivinhação não podem localizar ou\nperceber o alvo.\n    Quando você conjura essa magia, você escolhe uma\ndas seguintes formas de aprisionamento.\n    Enterrar. O alvo é sepultado bem fundo na terra em\numa esfera de energia mágica que é grande o suficiente\npara conter o alvo. Nada pode atravessar a esfera e\nnenhuma criatura pode se teletransportar ou usar viagem\nplantar para entrar ou sair dela.\n    O componente especial para essa versão da magia é\num pequeno globo de mitral.\n    Acorrentar. Pesadas correntes, firmemente presas ao\nsolo, matem o alvo no lugar. O alvo está impedido até a\nmagia acabar e ele não pode se mover ou ser movido por\nnenhum meio, até lá.\n    O componente especial para essa versão da magia é\numa fina corrente de metal precioso.\n    Prisão Cercada. A magia transporta o alvo para\ndentro de um pequeno semiplano que é protegido contra\nteletransporte e viagem planar. O semiplano pode ser um\nlabirinto, uma jaula, uma torre ou qualquer estrutura ou\nárea confinada similar, à sua escolha.\n   O componente material especial para essa versão da\nmagia é uma representação em miniatura da prisão, feita\nde jade.\n   Contenção Reduzida. O alvo é reduzido até o\ntamanho de 30 centímetros e é aprisionado dentro de uma\ngema ou objeto similar. A luz pode passar através da\ngema normalmente (permitindo que o alvo veja o exterior\ne outras criaturas vejam o interior), mas nada mais pode\natravessa-la, mesmo por meios de teletransporte ou\nviagem planar. A gema não pode ser partida ou quebrada\nenquanto a magia estiver efetiva.\n   O componente especial para essa versão da magia é\numa gema transparente grande, como um coríndon,\ndiamante ou rubi.\n   Torpor. O alvo cai no sono e não pode ser acordado.\n   O componente especial para essa versão da magia\nconsiste em ervas soporíferas raras.\n   Terminando a Magia. Durante a conjuração da\nmagia, em quaisquer das versões, você pode especificar\numa condição que irá fazer a magia terminar e libertará o\nalvo. A condição pode ser o quão especifica ou elaborada\nquanto você quiser, mas o Mestre deve concordar que a\ncondição é razoável e tem uma probabilidade de\nacontecer. As condições podem ser baseadas no nome,\nidentidade ou divindade da criatura mas, no mais, devem\nser baseadas em ações ou qualidades observáveis e não\nem valores intangíveis tais como nível, classe e pontos de\nvida.\n   A magia dissipar magia pode terminar a magia\napenas se for conjurada como uma magia de 9° nível,\ntendo como alvo ou a prisão ou o componente especial\nusado para cria-la.\n   Você pode usar um componente especial em particular\npara criar apenas uma prisão por vez. Se você conjurar\nessa magia novamente usando o mesmo componente, o\nalvo da primeira conjuração é, imediatamente, liberado do\nvínculo."},{"id":"chuva-de-meteoros","name":"Chuva de Meteoros","level":9,"school":"evocação","ritual":false,"classes":["feiticeiro","mago"],"pdfPage":225,"time":"1 ação","range":"1,5 quilômetro","components":"V, S","duration":"Instantânea","concentration":false,"text":"9° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: 1,5 quilômetro\nComponentes: V, S\nDuração: Instantânea\nEsferas de fogo incandescentes atingem o solo em quatro\npontos diferentes que você possa ver, dentro do alcance.\nCada criatura numa esfera de 12 metros de raio, centrada\nem cada ponto escolhido por você, deve realizar um teste\nde resistência de Destreza. A esfera se espalha, dobrando\nesquinas. Uma criatura sofre 20d6 de dano de fogo e 20d6\nde dano de concussão se falhar na resistência ou metade\ndesse dano se obtiver sucesso. Uma criatura na área de\nmais de uma explosão de chamas é afetada apenas uma\nvez.\n   A magia causa dano aos objetos na área e incendeia\nobjetos inflamáveis que não estejam sendo vestidos ou\ncarregados."},{"id":"cura-completa-em-massa","name":"Cura Completa em Massa","level":9,"school":"evocação","ritual":false,"classes":["clerigo"],"pdfPage":234,"time":"1 ação","range":"18 metros","components":"V, S","duration":"Instantânea","concentration":false,"text":"9° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, S\nDuração: Instantânea\nUma inundação de energia curativa emerge de você para\nas criaturas feridas ao seu redor. Você restaura até 700\npontos de vida, divididos, à sua escolha, entre qualquer\nquantidade de criaturas que você possa ver, dentro do\nalcance. As criaturas curadas por essa magia também são\ncuradas de todas as doenças e qualquer efeito que as\ndeixou cegas ou surdas. Essa magia não afeta mortos-\nvivos ou constructos."},{"id":"desejo","name":"Desejo","level":9,"school":"conjuração","ritual":false,"classes":["feiticeiro","mago"],"pdfPage":235,"time":"1 ação","range":"Pessoal","components":"V","duration":"Instantânea","concentration":false,"text":"9° nível de conjuração\nTempo de Conjuração: 1 ação\nAlcance: Pessoal\nComponentes: V\nDuração: Instantânea\nDesejo é a magia mais poderosa que uma criatura mortal\npode conjurar. Apenas ao falar em voz alta, você pode\nalterar os próprios fundamentos da realidade, de acordo\ncom seus desejos.\n   O uso básico dessa magia é de copiar qualquer magia\nde 8° nível ou inferior. Você não precisa atender a\nqualquer pré-requisito da magia copiada, incluindo os\ncomponentes dispendiosos. A magia simplesmente\nacontece.\n   Alternativamente, você pode criar um dos seguintes\nefeitos, à sua escolha:\n   Você cria um objeto no valor de até 25.000 po, que não\n    seja mágico. O objeto não pode ter dimensões maiores\n    que 90 metros e ele aparece em um espaço desocupado\n    que você possa ver, no chão.\n   Você permite que até doze criaturas que você possa\n    ver, recuperem todos os seus pontos de vida e você\n    acaba com todos os efeitos descritos na magia\n    restauração maior.\n   Você concede a até dez criaturas que você possa ver,\n    resistência a um tipo de dano, à sua escolha.\n   Você concede a até dez criaturas que você possa ver,\n    imunidade a uma única magia ou outro efeito mágico\n    por 8 horas. Por exemplo, você poderia deixar você e\n    todos os seus companheiros imunes ao ataque de\n    dreno de vida de um lich.\n   Você desfaz um único evento recente forçando uma\n    nova jogada de qualquer jogada feita na última rodada\n    (incluindo seu último turno). A realidade remodela-se\n    para acomodar o novo resultado. Por exemplo, uma\n    magia desejo poderia desfazer o teste de resistência\n    bem sucedido de um oponente, um acerto crítico de um\n    inimigo ou o teste de resistência fracassado de um\n    amigo. Você pode forçar que a nova jogada seja feita\n    com vantagem ou desvantagem e você pode escolher se\n    irá usar o resultado da nova jogada ou da jogada\n    original.\n\n   Você é capaz de fazer coisas além do alcance dos\nexemplos acima. Apresente seu desejo ao Mestre o mais\nprecisamente possível. O Mestre tem grande amplitude\nem definir o que ocorre em tais circunstâncias; quanto\nmaior o desejo, maior será a possibilidade de que algo dê\nerrado. Essa magia pode simplesmente falhar, o efeito do\nseu desejo pode ser apenas parcialmente atendido ou você\npode sofrer consequências imprevistas como resultado da\nforma que você formulou o desejo. Por exemplo, desejar\nque um vilão esteja morto pode impulsionar você para um\nperíodo no tempo em que o vilão não esteja mais vivo,\nefetivamente removendo você do jogo. Similarmente,\ndesejar um item mágico lendário ou um artefato poderia,\ninstantaneamente, transportar você para a presença do\ndono atual do item.\n    O estresse da conjuração dessa magia para produzir\nqualquer efeito diferente de copiar outra magia\nenfraquece você. Após enfrentar esse estresse, a cada vez\nque você conjurar uma magia, antes de terminar um\ndescanso longo, você sofrerá 1d10 de dano necrótico por\nnível da magia. Esse dano não pode ser reduzido ou\nprevenido de forma alguma. Além disso, sua Força cai\npara 3, se ela já não for 3 ou inferior, por 2d4 dias. Para\ncada dia desses que você permanecer descansando e não\nfizer nada além de atividades leves, seu tempo de\nrecuperação é reduzido em 2 dias. Finalmente, existe 33\npor cento de chance de você se tornar incapaz de conjurar\ndesejo novamente se você sofrer esse estresse."},{"id":"encarnacao-fantasmagorica","name":"Encarnação Fantasmagórica","level":9,"school":"ilusão","ritual":false,"classes":["mago"],"pdfPage":240,"time":"1 ação","range":"36 metros","components":"V, S","duration":"Concentração, até 1 minuto","concentration":true,"text":"9° nível de ilusão\nTempo de Conjuração: 1 ação\nAlcance: 36 metros\nComponentes: V, S\nDuração: Concentração, até 1 minuto\nBaseado nos mais profundos medos de um grupo de\ncriaturas, você cria criaturas ilusórias nas mentes delas,\nvisíveis apenas por elas. Cada criatura numa esfera com 9\nmetros de raio centrada num ponto, à sua escolha, dentro\ndo alcance, deve realizar um teste de resistência de\nSabedoria. Se falhar na resistência, uma criatura ficará\namedrontada pela duração. A ilusão invoca os medos mais\nprofundos da criatura, manifestando seus piores\npesadelos como uma ameaça implacável. No final de cada\nturno da criatura amedrontada, ela deve ser bem\nsucedida num teste de resistência de Sabedoria ou sofrerá\n4d10 de dano psíquico. Se obtiver sucesso na resistência,\na magia termina para essa criatura."},{"id":"metamorfose-verdadeira","name":"Metamorfose Verdadeira","level":9,"school":"transmutação","ritual":false,"classes":["bardo","bruxo","mago"],"pdfPage":257,"time":"1 ação","range":"9 metros","components":"V, S, M (uma gota de mercúrio, uma porção de goma arábica e um pouco de fumaça)","duration":"Concentração, até 1 hora","concentration":true,"text":"9° nível de transmutação\nTempo de Conjuração: 1 ação\nAlcance: 9 metros\nComponentes: V, S, M (uma gota de mercúrio, uma\n   porção de goma arábica e um pouco de fumaça)\nDuração: Concentração, até 1 hora\nEscolha uma criatura ou objeto não-mágico que você\npossa ver, dentro do alcance. Você transforma a criatura\nem uma criatura diferente, a criatura em um objeto ou o\nobjeto em uma criatura (o objeto não pode nem estar\nsendo vestido nem carregado por outra criatura). A\ntransformação permanece pela duração ou até o alvo cair\na 0 pontos de vida ou morrer. Se você se concentrar nessa\nmagia por toda a duração, a transformação será\npermanente.\n    Metamorfos não são afetados por essa magia. Uma\ncriatura involuntária pode realizar um teste de\nresistência de Constituição e, se for bem sucedida, não\nserá afetada por essa magia.\n    Criatura em Criatura. Se você transformar uma\ncriatura em outro tipo de criatura, a nova forma pode ser\nde qualquer tipo que você desejar, contanto que o nível de\ndesafio seja igual ou menor que o do alvo (ou o nível dele,\ncaso o alvo não possua nível de desafio). As estatísticas de\njogo do alvo, incluindo seus valores de habilidades\nmentais, são substituídas pelas estatísticas da nova\nforma. Ele mantem sua tendência e personalidade.\n    O alvo assume os pontos de vida da sua nova forma e,\nquando ela reverter a sua forma normal, a criatura\nretorna à quantidade de pontos de vida que ela tinha\nantes da transformação. Se ela reverter como resultado de\nter caído a 0 pontos de vida, qualquer dano excedente é\nrecebido pela sua forma normal. Contanto que o dano\nexcedente não reduza os pontos de vida da forma normal\nda criatura a 0, ela não cairá inconsciente. Essa magia\nnão pode afetar um alvo com 0 pontos de vida.\n    A criatura é limitada em suas ações pela natureza da\nsua nova forma e ela não pode falar, conjurar magias ou\nrealizar qualquer outra ação que precise de mãos ou de\nvocalização, a não ser que a nova forma seja capaz de tais\nações.\n    O equipamento do alvo mescla-se a sua nova forma. O\nalvo não pode ativar, empunhar ou, de outra forma, se\nbeneficiar de qualquer de seus equipamentos.\n    Objeto em Criatura. Você pode transformar um\nobjeto em um tipo de criatura, contanto que o tamanho da\ncriatura não seja maior que o tamanho do objeto e, o nível\nde desafio da criatura será 9 ou menor. A criatura é\namigável a você e aos seus companheiros. Ela age em\ncada um dos seus turnos. Você decide qual ação ela\nrealizará e como ela se move. O Mestre tem as\nestatísticas da criatura e resolve todas as ações e\nmovimentos dela.\n    Se a magia se tornar permanente, você não terá mais\ncontrole sobre a criatura. Ele pode continuar amigável a\nvocê, dependendo da forma como você a tratou.\n    Criatura em Objeto. Se você transformar uma\ncriatura em um objeto, ela se transformará, junto com\ntudo que estiver vestindo ou carregando, nessa forma. As\nestatísticas da criatura tornam-se as do objeto e a\ncriatura não se lembrará do tempo que passou nessa\nforma, depois da magia acabar e ela retornar a sua forma\nnormal."},{"id":"muralha-prismatica","name":"Muralha Prismática","level":9,"school":"abjuração","ritual":false,"classes":["mago"],"pdfPage":261,"time":"1 ação","range":"18 metros","components":"V, S","duration":"10 minutos","concentration":false,"text":"9° nível de abjuração\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, S\nDuração: 10 minutos\nUma plano cintilante multicolorido de luzes forma uma\nparece vertical opaca – de até 27 metros de comprimento,\n9 metros de altura e 2,5 centímetros de espessura –\ncentrada num ponto que você possa ver, dentro do\nalcance. Alternativamente, você pode moldar a muralha\nnuma esfera de 9 metros de diâmetro centrada num\nponto, à sua escolha, dentro do alcance. A muralha\npermanece no lugar pela duração. Se você posicionar a\nmuralha de forma que ela passaria através do espaço\nocupado por uma criatura, a magia falha e sua ação e o\nespaço de magia são desperdiçados.\n   A muralha emite luz plena num raio de 30 metros e\npenumbra por 30 metros adicionais. Você e as criaturas\ndesignadas, no momento que você conjurou a magia,\npodem passar através e permanecer perto da muralha\nsem se ferirem. Se outra criatura que puder ver a\nmuralha se aproximar mais de 6 metros dela ou começar\nseu turno lá, a criatura deve realizar um teste de\nresistência de Constituição ou ficará cega por 1 minuto.\n   A muralha consiste em sete camadas, cada uma de\numa cor diferente. Quando uma criatura tenta tocar ou\npassar através da muralha, ela atravessa uma camada de\ncada vez, até atravessar todas as camadas da muralha. À\nmedida que ela passa ou toca cada camada, a criatura\nrealiza um teste de resistência de Destreza ou será\nafetada pelas propriedades daquela camada, como\ndescrito abaixo.\n   A muralha pode ser destruída, também, uma camada\npor vez, em ordem de vermelho à violeta, pelos meios\nespecificados em cada camada. Quando uma camada é\ndestruída, ela permanece assim pela duração da magia.\nUm bastão do cancelamento destrói uma muralha\nprismática, mas um campo antimagia não produz efeito\nnela.\n   1. Vermelho. O alvo sofre 10d6 de dano de fogo se\nfalhar na resistência ou metade desse dano se obtiver\nsucesso. Enquanto essa camada estiver no lugar, ataques\nà distância não-mágicos não podem atravessar a muralha.\nA camada pode ser destruída causando, pelo menos, 25 de\ndano de frio a ela.\n   2. Laranja. O alvo sofre 10d6 de dano de ácido se\nfalhar na resistência ou metade desse dano se obtiver\nsucesso. Enquanto essa camada estiver no lugar, ataques\nà distância mágicos não podem atravessar a muralha. A\ncamada pode ser destruída por um vento forte.\n    3. Amarelo. O alvo sofre 10d6 de dano elétrico se\nfalhar na resistência ou metade desse dano se obtiver\nsucesso. A camada pode ser destruída causando, pelo\nmenos, 60 de dano de energia a ela.\n    4. Verde. O alvo sofre 10d6 de dano de veneno se\nfalhar na resistência ou metade desse dano se obtiver\nsucesso. A magia criar passagem ou outra magia de nível\nigual ou superior que possam abrir um portal em uma\nsuperfície sólida, destroem essa camada.\n    5. Azul. O alvo sofre 10d6 de dano de frio se falhar na\nresistência ou metade desse dano se obtiver sucesso. A\ncamada pode ser destruída causando, pelo menos, 25 de\ndano de fogo a ela.\n    6. Anil. Se falhar na resistência, o alvo ficará\nimpedido. Ele deve então, fazer um teste de resistência de\nConstituição ao final de cada um dos turnos dele. Se\nobtiver sucesso três vezes, a magia termina. Se falhar na\nresistência três vezes, ela se torna pedra é afetada pela\ncondição petrificado. Os sucessos e falhas não precisam\nser consecutivos; anote ambos os resultados até o alvo\nacumular três de mesmo tipo.\n    Enquanto essa camada estiver no lugar, magias não\npodem ser conjuradas através da muralha. A camada\npode ser destruída por luz plena emitida pela magia luz\ndo dia ou uma magia similar de nível equivalente ou\nsuperior.\n    7. Violeta. Se falhar na resistência, o alvo ficará cego.\nEle deve realizar um teste de resistência de Sabedoria no\ninício do seu próximo turno. Um sucesso na resistência\nacaba com a cegueira. Se falhar na resistência, a criatura\né transportada para outro plano de existência, escolhido\npelo Mestre, e não estará mais cego. (Tipicamente, uma\ncriatura que esteja em um plano que não seja o seu plano\nnatal é banida para lá, enquanto que outras criaturas\ngeralmente são enviadas para os Planos Astral ou\nEtéreo.) Essa camada é destruída pela magia dissipar\nmagia ou por uma magia similar de nível equivalente ou\nsuperior que possa acabar com magias e efeitos mágicos."},{"id":"palavra-de-poder-curar","name":"Palavra de Poder Curar","level":9,"school":"evocação","ritual":false,"classes":["bardo"],"pdfPage":265,"time":"1 ação","range":"Toque","components":"V, S","duration":"Instantânea","concentration":false,"text":"9° nível de evocação\nTempo de Conjuração: 1 ação\nAlcance: Toque\nComponentes: V, S\nDuração: Instantânea\nUma onda de energia curativa inunda a criatura tocada.\nO alvo recupera todos os seus pontos de vida. Se a\ncriatura estiver enfeitiçada, amedrontada, paralisada ou\natordoada, a condição termina. Se a criatura estiver\ncaída, ela pode usar a reação dela para se levantar. Essa\nmagia não afeta mortos-vivos ou constructos."},{"id":"palavra-de-poder-matar","name":"Palavra de Poder Matar","level":9,"school":"encantamento","ritual":false,"classes":["bardo","bruxo","feiticeiro","mago"],"pdfPage":265,"time":"1 ação","range":"18 metros","components":"V","duration":"Instantânea","concentration":false,"text":"9° nível de encantamento\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V\nDuração: Instantânea\nVocê profere uma palavra de poder que pode compelir\numa criatura que você possa ver, dentro do alcance, a\nmorrer instantaneamente. Se o alvo escolhido estiver com\n100 pontos de vida ou menos, ele morre. Do contrário,\nessa magia não produz efeito."},{"id":"parar-o-tempo","name":"Parar o Tempo","level":9,"school":"transmutação","ritual":false,"classes":["feiticeiro","mago"],"pdfPage":265,"time":"1 ação","range":"Pessoal","components":"V","duration":"Instantânea","concentration":false,"text":"9° nível de transmutação\nTempo de Conjuração: 1 ação\nAlcance: Pessoal\nComponentes: V\nDuração: Instantânea\nVocê, por um breve momento, para o fluxo do tempo pra\ntudo, menos pra você. Nenhum tempo se passa para as\noutras criaturas, enquanto você realiza 1d4 + 1 turnos de\numa vez, durante os quais você pode usar ações e se\nmover normalmente.\n   Essa magia termina se uma das ações que você fizer\ndurante esse período ou qualquer efeito que você criar,\nafetar uma criatura diferente de você ou um objeto que\nesteja sendo vestido ou carregado por outro que não você.\nAlém disso, a magia termina se você se mover para um\nlugar a mais de 300 metros do local onde você conjurou\nessa magia."},{"id":"portal","name":"Portal","level":9,"school":"conjuração","ritual":false,"classes":["clerigo","feiticeiro","mago"],"pdfPage":267,"time":"1 ação","range":"18 metros","components":"V, S, M (um diamante valendo, no mínimo, 5.000 po)","duration":"Concentração, até 1 minuto","concentration":true,"text":"9° nível de conjuração\nTempo de Conjuração: 1 ação\nAlcance: 18 metros\nComponentes: V, S, M (um diamante valendo, no\n   mínimo, 5.000 po)\nDuração: Concentração, até 1 minuto\nVocê conjura um portal conectando um espaço desocupado\nque você possa ver, dentro do alcance, a uma localização\nprecisa em um plano de existência diferente. O portal é\numa abertura circular, que você pode fazer ter de 1,5 a 6\nmetros de diâmetro. Você pode orientar o portal em\nqualquer direção, à sua escolha. O portal permanece pela\nduração.\n    O portal terá uma frente e um fundo em cada plano\nque ele aparecer. Viajar pelo portal só é possível ao\natravessa-lo pela frente. Qualquer coisa que o fizer, é\ninstantaneamente transportado para o outro plano,\naparecendo no espaço desocupado mais próximo do portal.\n    Divindades e outros soberanos planares podem\nimpedir que portais criados através dessa magia se abram\nna presença deles ou em qualquer parte dos seus\ndomínios.\n    Quando você conjurar essa magia, você pode falar o\nnome de uma criatura especifica (um pseudônimo, título\nou apelido não funcionará). Se essa criatura estiver em\num plano diferente do que você está, o portal se abre na\nvizinhança imediata da criatura nomeada e suga a\ncriatura para dentro do portal, fazendo-a aparecer no\nespaço desocupado mais próximo do seu lado do portal.\nVocê não adquire qualquer poder especial sobre a criatura\ne ela está livre para agir como o Mestre julgar apropriado.\nEla pode ir embora, atacar você ou ajudar você."},{"id":"projecao-astral","name":"Projeção Astral","level":9,"school":"necromancia","ritual":false,"classes":["bruxo","clerigo","mago"],"pdfPage":269,"time":"1 hora","range":"3 metros","components":"V, S, M (para cada criatura que você afetar com essa magia, você deve fornecer um jacinto valendo, no mínimo, 1.000 po e uma barra de prata com ornamentos esculpidos valendo, no mínimo, 100 po, todos consumidos pela magia)","duration":"Especial","concentration":false,"text":"9° nível de necromancia\nTempo de Conjuração: 1 hora\nAlcance: 3 metros\nComponentes: V, S, M (para cada criatura que você\n   afetar com essa magia, você deve fornecer um jacinto\n   valendo, no mínimo, 1.000 po e uma barra de prata\n   com ornamentos esculpidos valendo, no mínimo, 100\n   po, todos consumidos pela magia)\nDuração: Especial\n\nVocê e até oito criaturas voluntárias dentro do alcance,\nprojetam seus corpos astrais para o Plano Astral (a magia\nfalha e a conjuração é perdida se você já estiver no plano).\nO corpo material que você deixa para trás ficará\ninconsciente e em estado de animação suspensa; ele não\nprecisa de comida ou ar e não envelhece.\n   Seu corpo astral assemelhasse à sua forma mortal em\npraticamente tudo, copiando suas estatísticas de jogo e\nposses. A principal diferença é a adição de um cordão\nprateado que se estende de trás da sua omoplata e traça\num caminho atrás de você, sumindo após 30 centímetros.\nEsse cordão é a sua corrente com o seu corpo material.\nEnquanto sua corrente permanecer intacta, você pode\nencontrar seu caminho de volta pra casa. Se o cordão for\ncortado – algo que só pode acontecer se um efeito dizer\nespecificamente que faz isso – sua alma e corpo estão\nseparados, matando você instantaneamente.\n    Sua forma astral pode viajar livremente dentro do\nPlano Astral e pode passar através de portais que levam a\nqualquer outro plano. Se você entrar em um novo portal\nou retornar para o plano que você estava quando conjurou\na magia, seu corpo e posses são transportados ao longo do\ncordão de prata, permitindo que você reentre no seu corpo\nao entrar no novo plano. Sua forma astral é uma\nencarnação separada. Qualquer dano ou outros efeitos\nque se aplicarem a ela, não terão efeito no seu corpo\nfísico, nem persistem quando você voltar.\n    A magia termina para você e seus companheiros\nquando você usar sua ação para dissipa-la. Quando a\nmagia termina, as criaturas afetadas voltam para seus\ncorpos físicos e acordam.\n    A magia também pode terminar prematuramente para\nvocê ou um dos seus companheiros. Uma magia dissipar\nmagia, bem sucedida, usada contra um corpo astral ou\nfísico termina a magia para a criatura. Se o corpo original\nde uma criatura ou sua forma astral caírem a 0 pontos de\nvida, a magia termina para essa criatura. Se a magia\nterminar e o cordão prateado estiver intacto, o cordão\npuxa a forma astral da criatura de volta para seu corpo,\nterminando seu estado de animação suspensa.\n    Se você retornar para o seu corpo prematuramente,\nseus companheiros permanecem nas suas formas astrais\ne devem encontrar seus próprios meios de voltar para\nseus corpos, geralmente caindo a 0 pontos de vida."},{"id":"ressurreicao-verdadeira","name":"Ressurreição Verdadeira","level":9,"school":"necromancia","ritual":false,"classes":["clerigo","druida"],"pdfPage":277,"time":"1 hora","range":"Toque","components":"V, S, M (um borrifo de água benta e diamantes valendo, no mínimo, 25.000 po, consumidos pela magia)","duration":"Instantânea","concentration":false,"text":"9° nível de necromancia\nTempo de Conjuração: 1 hora\nAlcance: Toque\nComponentes: V, S, M (um borrifo de água benta e\n   diamantes valendo, no mínimo, 25.000 po, consumidos\n   pela magia)\nDuração: Instantânea\nVocê toca uma criatura morta que não esteja assim a\nmais de 200 anos e que tenha morrido por qualquer\nmotivo, exceto velhice. Se a alma da criatura estiver\ndisposta e livre, o alvo volta a vida com todos os seus\npontos de vida.\n   Essa magia fecha todos os ferimentos, neutraliza\nquaisquer venenos, cura todas as doenças e suspende\nquaisquer maldições que afligiam a criatura quando ela\nmorreu. A magia recupera órgão e membros danificados\nou perdidos.\n   Essa magia pode, até mesmo, prover um novo corpo, se\no original não existir mais, nesse caso, você deve falar o\nnome da criatura. Ela aparece em um espaço desocupado,\nà sua escolha, a até 3 metros de você."},{"id":"sexto-sentido","name":"Sexto Sentido","level":9,"school":"adivinhação","ritual":false,"classes":["bardo","bruxo","druida","mago"],"pdfPage":279,"time":"1 minuto","range":"Toque","components":"V, S, M (uma pena de colibri)","duration":"8 horas","concentration":false,"text":"9° nível de adivinhação\nTempo de Conjuração: 1 minuto\nAlcance: Toque\nComponentes: V, S, M (uma pena de colibri)\nDuração: 8 horas\nVocê toca uma criatura voluntária e a abençoa com uma\nhabilidade limitada de ver o futuro iminente. Pela\nduração, o alvo não pode ser surpreendido e tem\nvantagem nas jogadas de ataque, testes de habilidade e\ntestes de resistência. Além disso, outras criaturas tem\ndesvantagem nas jogadas de ataque contra o alvo, pela\nduração.\n   Essa magia termina imediatamente, se você conjura-la\nnovamente antes da duração acabar."},{"id":"tempestade-da-vinganca","name":"Tempestade da Vingança","level":9,"school":"conjuração","ritual":false,"classes":["druida"],"pdfPage":284,"time":"1 ação","range":"Visão","components":"V, S","duration":"Concentração, até 1 minuto","concentration":true,"text":"9° nível de conjuração\nTempo de Conjuração: 1 ação\nAlcance: Visão\nComponentes: V, S\nDuração: Concentração, até 1 minuto\nUma agitada nuvem tempestuosa se forma, centrada num\nponto que você possa ver e se espalha num raio de 108\nmetros. Relâmpagos riscam a área, trovões ressoam e\nventos fortes silvam. Cada criatura embaixo da nuvem (a\nnão mais de 1.500 metros abaixo da nuvem) quando ela\naparece deve realizar um teste de resistência de\nConstituição. Com uma falha na resistência, uma criatura\nsofre 2d6 de dano trovejante e ficará surda por 5 minutos.\n   A cada rodada que você mantiver a concentração nessa\nmagia, a tempestade produzirá efeitos adicionais no seu\nturno.\n   Rodada 2. Chuva ácida cai da nuvem. Cada criatura\ne objeto abaixo dela nuvem sofre 1d6 de dano ácido.\n   Rodada 3. Você convoca seis relâmpagos da nuvem\npara atingir seis criaturas ou objetos, à sua escolha,\nabaixo da nuvem. Uma mesma criatura ou objeto não\npode ser atingido por mais de um raio. Uma criatura\natingida deve realizar um teste de resistência de\nDestreza. A criatura sofrerá 10d6 de dano elétrico se\nfalhar na resistência ou metade desse dano se passar.\n   Rodada 4. Granizo chove da nuvem. Cada criatura\nabaixo da nuvem sofre 2d6 de dano de concussão.\n   Rodada 5–10. Ventos e chuva gelados atacam a área\nabaixo da nuvem. A área se torna terreno difícil e de\nescuridão densa. Cada criatura sofre 1d6 de dano de frio.\nAtaques com armas à distância na área são impossíveis.\nO vento e chuva contam como uma distração grave com os\npropósitos de manter a concentração em magias.\nFinalmente, ventos fortes (entre 30 e 75 quilômetros por\nhora) automaticamente dispersam nevoa, neblina e\nfenômenos similares na área, independentemente de\nserem mundanos ou mágicos."}];if(typeof module!=="undefined")module.exports=data;else root.PHB_SPELLS=data;})(globalThis);
